i32 wrapCoordinate(i32 v, i32 size) {
    // SRD R19: 1-based coordinates wrap into 1..size.
    if (size <= 0) return v;
    i32 r = (v - 1) % size;
    if (r < 0) r += size;
    return r + 1;
}

