i32 refillGuildCrests(Ctx& ctx, Inventory& inv, const Str& ownerName, bool inParty) {
    i32 refilled = 0;
    for (i32 l = kCrestScanFirst; l <= kCrestScanLast; ++l) {
        Item& slot = inv.pack[static_cast<u32>(l)];
        if (slot.id <= 0) {
            continue;  // Pack(l).Ref must be above 0
        }
        if (!slot.isGuildItem()) {
            continue;
        }
        const i32 guildIdx = slot.guildIndex();
        if (guildIdx < 0 || guildIdx >= kGuildCount) {
            continue;
        }
        const i32 full = kCrestCharges[guildIdx];
        if (slot.charges < full) {
            slot.charges = full;
            ++refilled;
        }
    }

    if (refilled > 0) {
        // R5 step 2: trim the owner name for the in-party message.
        i32 b = 0;
        i32 e = static_cast<i32>(ownerName.size());
        while (b < e && ownerName[static_cast<u32>(b)] == ' ') {
            ++b;
        }
        while (e > b && ownerName[static_cast<u32>(e - 1)] == ' ') {
            --e;
        }
        const Str trimmed = ownerName.substr(static_cast<u32>(b), static_cast<u32>(e - b));
        if (inParty) {
            ctx.say("city.crestRecharged", "Crest recharged for \"" + trimmed + "\"",
                    {static_cast<i64>(refilled)}, {trimmed});
        } else {
            ctx.say("city.crestRecharged", "Crest recharged",
                    {static_cast<i64>(refilled)}, {});
        }
    }
    return refilled;
}

Vec<TownSection> townSwitchOrder(const Party& party) {
    Vec<TownSection> order;
    if (party.size <= 0) {
        return order;
    }
    const Character& leader = party.members[0];
    if (party.dungeonLevel > 0 || leader.isDead()) {
        return order;
    }
    order.push_back(TownSection::Store);
    order.push_back(TownSection::Confinement);
    order.push_back(TownSection::Morgue);
    order.push_back(TownSection::Guild);
    order.push_back(TownSection::Bank);
    return order;
}

void createInitialStore(Ctx& ctx, Vec<Item>& store) {
    store.clear();
    const i32 n = static_cast<i32>(ctx.data.items.size());
    for (i32 i = 0; i < n; ++i) {
        const ItemDef& def = ctx.data.items[static_cast<u32>(i)];
        const i32 id = def.id;

        // R7 artifact branch: artifacts 356..361 with fixed alignment and count.
        i32 artIdx = -1;
        for (i32 k = 0; k < 6; ++k) {
            if (kStartingArtifacts[k].itemId == id) {
                artIdx = k;
            }
        }
        if (artIdx >= 0) {
            const StartingArtifact& art = kStartingArtifacts[artIdx];
            Item unit{};
            unit.id = id;
            unit.alignment = art.alignment;
            unit.aligned = art.alignment != ItemAlign::Unaligned;
            for (i32 c = 0; c < art.count; ++c) {
                store.push_back(unit);
            }
            continue;
        }

        // R7 skip: Floor > 1, Price > 200000, Price == 0, or Cursed.
        if (def.floor > 1 || def.price > 200000 || def.price == 0 || def.cursed) {
            continue;
        }

        Item unit{};
        unit.id = id;
        if (def.alignmentFlags > 1) {
            // R7: AlignmentFlags > 1 is a numeric test (quirk kept). One each of G, N, E.
            const ItemAlign aligns[3] = {ItemAlign::Good, ItemAlign::Neutral, ItemAlign::Evil};
            for (i32 a = 0; a < 3; ++a) {
                unit.alignment = aligns[a];
                unit.aligned = true;
                store.push_back(unit);
            }
        } else {
            // R7: Unaligned = (Floor == 0) ? 99 : 5.
            unit.alignment = ItemAlign::Unaligned;
            unit.aligned = false;
            const i32 count = (def.floor == 0) ? 99 : 5;
            for (i32 c = 0; c < count; ++c) {
                store.push_back(unit);
            }
        }
    }
}

void replenishStore(Ctx& ctx, Vec<Item>& store, i64 daysAged, i32 deepestReached) {
    i32 deepest = deepestReached;
    if (deepest < 1) {
        deepest = 1;
    }
    if (deepest > kTownDeepestFloor) {
        deepest = kTownDeepestFloor;
    }

    i64 chance = daysAged;
    if (chance < kRestockChanceMin) {
        chance = kRestockChanceMin;
    }
    if (chance > kRestockChanceMax) {
        chance = kRestockChanceMax;
    }

    while (true) {
        if (ctx.rng.nextDouble() * 100.0 > static_cast<double>(chance)) {
            break;
        }
        const bool adding = ctx.rng.nextDouble() * 100.0 < static_cast<double>(kAddProbabilityPct);
        const i32 roll = static_cast<i32>(vbInt(ctx.rng.nextDouble() * 100.0)) + 1;

        i32 pickFloor = 0;
        for (i32 f = 1; f <= deepest; ++f) {
            const double threshold =
                100.0 - (static_cast<double>(f) / static_cast<double>(deepest + 1)) * 100.0;
            if (static_cast<double>(roll) < threshold) {
                pickFloor = f;
            } else {
                break;
            }
        }
        if (pickFloor < 1) {
            pickFloor = 1;
        }
        if (pickFloor > deepest) {
            pickFloor = deepest;
        }

        if (adding) {
            // Reference StoreStock.Replenish / AddOne: draw until an uncursed floor>0 item; Unaligned unless its alignment flags
            // exceed 1, then a random allowed alignment (bits 0-3); one copy is shelved unless that alignment already holds 9.
            for (i32 guard = 0; guard < 100000; ++guard) {
                const i32 idx = drawItemIndex(ctx, pickFloor);
                if (idx <= 0) continue;
                const ItemDef& d = ctx.data.items[static_cast<u32>(idx)];
                if (d.cursed != 0 || d.floor <= 0) continue;
                ItemAlign al = Unaligned;
                if (d.alignmentFlags > 1) {
                    if ((d.alignmentFlags & 0xF) == 0) break;      // the original would spin here; nothing is shelved
                    do {
                        al = static_cast<ItemAlign>(static_cast<i32>(vbInt(ctx.rng.nextDouble() * 4.0)));
                    } while ((d.alignmentFlags & (1 << static_cast<i32>(al))) == 0);
                }
                i32 same = 0;
                for (const Item& o : store) {
                    if (o.id == d.id && o.alignment == al) ++same;
                }
                if (same < 9) {                                       // ShelfCap
                    Item unit{};
                    unit.id = d.id;                                   // the item's id, not its table index
                    unit.alignment = al;
                    unit.level = pickFloor;
                    store.push_back(unit);
                }
                break;
            }
        } else {
            // Reference RemoveOne: up to 100 tries for an uncursed floor>0 item with Unaligned stock (the original only looks at the
            // Unaligned count), then one copy leaves from a random alignment that has stock.
            for (i32 t = 0; t < 100; ++t) {
                const i32 idx = drawItemIndex(ctx, pickFloor);
                if (idx <= 0) continue;
                const ItemDef& d = ctx.data.items[static_cast<u32>(idx)];
                if (d.cursed != 0 || d.floor <= 0) continue;
                auto countOf = [&](ItemAlign a2) { i32 n = 0; for (const Item& o : store) if (o.id == d.id && o.alignment == a2) ++n; return n; };
                if (countOf(Unaligned) <= 0) continue;
                ItemAlign al = Unaligned;
                do {
                    al = static_cast<ItemAlign>(static_cast<i32>(vbInt(ctx.rng.nextDouble() * 4.0)));
                } while (countOf(al) <= 0);
                for (u32 j = 0; j < store.size(); ++j) {
                    if (store[j].id == d.id && store[j].alignment == al) {
                        store.erase(store.begin() + static_cast<i64>(j));
                        break;
                    }
                }
                break;
            }
        }
    }
}

i32 drawItemIndex(Ctx& ctx, i32 floor) {
    // The reference draws the kind over NumItemTypes (the item-type table, 35 entries in the shipped data), not 9.
    const i32 kItemKindCount = ctx.data.itemTypes.empty() ? 9 : static_cast<i32>(ctx.data.itemTypes.size());
    const i32 count = static_cast<i32>(ctx.data.items.size());
    const i32 kind = roundedIndex(ctx, kItemKindCount);

    // first = first i with Type == kind and Floor <= floor.
    // Index 0 is not found, whether nothing matched or item 0 matched
    // (StoreStock.cs:423 Reachable: "if (first == 0) continue;", "an index of 0 is not found").
    i32 first = -1;
    for (i32 i = 0; i < count; ++i) {
        const ItemDef& d = ctx.data.items[static_cast<u32>(i)];
        if (static_cast<i32>(d.type) == kind && d.floor <= floor) {
            first = i;
            break;
        }
    }
    if (first <= 0) {
        return 0;
    }

    // last = (first i from first with Floor > floor or Type != kind) - 1
    i32 last = count - 1;  // CONFLICT: stale-value quirk, see note above
    for (i32 i = first; i < count; ++i) {
        const ItemDef& d = ctx.data.items[static_cast<u32>(i)];
        if (d.floor > floor || static_cast<i32>(d.type) != kind) {
            last = i - 1;
            break;
        }
    }
    if (last < first) {
        last = first;
    }

    double total = 0.0;
    for (i32 i = first; i <= last; ++i) {
        total += static_cast<double>(ctx.data.items[static_cast<u32>(i)].rarity);
    }
    if (total <= 0.0) {
        return 0;  // UNKNOWN: zero total; original would divide by zero
    }

    const double pick = ctx.rng.nextDouble() * 100.0;
    i64 acc = 0;
    for (i32 i = first; i <= last; ++i) {
        const double rarity =
            static_cast<double>(ctx.data.items[static_cast<u32>(i)].rarity);
        const i64 weight = (rarity > 0.0) ? roundHalfEven(rarity / total * 100.0) : 0;
        acc += weight;
        if (pick <= static_cast<double>(acc)) {
            return i;
        }
    }
    return 0;
}

i32 roundedIndex(Ctx& ctx, i32 n) {
    if (n <= 0) {
        return 0;  // UNKNOWN: guard for empty choice set
    }
    while (true) {
        const i64 k = roundHalfEven(ctx.rng.nextDouble() * static_cast<double>(n));
        if (k < n) {
            return static_cast<i32>(k);
        }
        // index n matches nothing: retry
    }
}

AlignChoiceRow alignmentChoice(const Arr<i32, 4>& counts, i32 chosenBefore) {
    AlignChoiceRow row{};
    for (i32 a = 0; a < 4; ++a) {
        const bool on = counts[static_cast<u32>(a)] > 0;
        row.enabled[static_cast<u32>(a)] = on;
        if (on) {
            row.stocked += 1;
            row.last = a;
        }
    }
    row.asks = row.stocked > 1;
    if (row.asks) {
        row.chosen = -1;
    } else if (row.stocked == 1) {
        row.chosen = row.last;
    } else {
        row.chosen = chosenBefore;
    }
    return row;
}

AlignChoiceRow storeBuyRowClick(const Arr<i32, 4>& counts, i32 chosenBefore) {
    return alignmentChoice(counts, chosenBefore);
}

void settleStoreSelection(StoreSelection& sel, bool soldOutOrHidden) {
    if (!soldOutOrHidden) {
        return;
    }
    sel.buyEnabled = false;
    sel.infoEnabled = false;
    sel.choosing = false;
    sel.alignment = -1;
}

bool storeRowClickAllowed(const StoreSelection& sel, i32 newRow, const TownModAnswers& mods) {
    if (!sel.choosing) {
        return true;
    }
    if (newRow == sel.row) {
        return true;  // not "another row"
    }
    return mods.rowChangeAllowed;
}

AlignChoiceRow confinementRowClick(const Arr<i32, 4>& penCounts, i32 chosenBefore) {
    // Pen counts are used as given. The previous version zeroed penCounts[0],
    // which disabled pen 0 and changed the stocked count (reference: stocked 2, last 2).
    Arr<i32, 4> counts = penCounts;
    return alignmentChoice(counts, chosenBefore);
}

StoreSaleResult storeSale(Ctx& ctx, Party& party, i32 sellerIndex, Item& item, Vec<Item>& store,
                          const TownModAnswers& mods) {
    constexpr Currency kCurrencyCeiling = 9223372036854775807LL;
    StoreSaleResult out{};

    if (item.id < 0 || item.id >= static_cast<i32>(ctx.data.items.size())) {
        return out;
    }
    const ItemDef& def = ctx.data.items[static_cast<u32>(item.id)];

    // R15 steps 1 and 2: payee (seller by default; TownIncomeBank may name another).
    const i32 payee = townIncomePayee(party, sellerIndex, mods);
    if (payee < 0 || payee >= party.size) {
        return out;
    }
    Character& receiver = party.members[static_cast<u32>(payee)];

    // Sale amount: the store pays a share of base value (R17).
    const Currency amount = generalStorePayout(def.price);

    // R15 step 4: overflow refuses the sale with nothing moved.
    if (receiver.wallet.goldOnHand > kCurrencyCeiling - amount) {
        return out;
    }

    // R15 step 3 and R16: shelving test.
    const bool shelves = storeShelvesItem(ctx, item, store);

    receiver.wallet.goldOnHand += amount;
    out.sold = true;
    out.payee = payee;
    out.amount = amount;

    if (shelves) {
        store.push_back(item);
        out.shelved = true;
        // R15 step 3: a sale that shelves nothing raises no StoreShelved event.
        ctx.say("city.storeShelved", "Item shelved in the General Store",
                {static_cast<i64>(store.size())}, {});
    }

    ctx.say("city.storeSale", "Item sold to the General Store",
            {amount, static_cast<i64>(payee)}, {});
    return out;
}

bool storeShelvesItem(const Ctx& ctx, const Item& item, const Vec<Item>& store) {
    if (item.id < 0 || item.id >= static_cast<i32>(ctx.data.items.size())) {
        return false;
    }
    const ItemDef& def = ctx.data.items[static_cast<u32>(item.id)];
    const bool cursed = item.cursed != CurseNone;
    const bool unaligned = item.alignment == ItemAlign::Unaligned;
    const bool floorZero = def.floor == 0;
    if (cursed) {
        return false;
    }
    if (unaligned && floorZero) {
        return false;
    }
    return storeRowCount(store, item.alignment) < kShelfRowCap;
}

i32 storeRowCount(const Vec<Item>& store, ItemAlign align) {
    i32 n = 0;
    for (const Item& it : store) {
        if (it.alignment == align) {
            ++n;
        }
    }
    return n;
}

Currency generalStorePayout(Currency baseValue) {
    return roundHalfEven(0.5 * static_cast<double>(baseValue));
}

i32 storeShelfFloorCap(i32 deepestReached) {
    return (deepestReached >= kTownDeepestFloor) ? kTownDeepestFloor : deepestReached;
}

bool confinementBuy(Ctx& ctx, Party& party, i32 payerIndex, PenBook& pens, i32 monsterRef,
                    i32 align, const TownModAnswers& mods) {
    if (payerIndex < 0 || payerIndex >= party.size) {
        return false;
    }
    if (monsterRef < 0 || monsterRef >= static_cast<i32>(ctx.data.monsters.size())) {
        return false;
    }
    if (align < 0 || align >= kPenAlignCount) {
        return false;
    }
    if (!penTakeAllowed(pens, monsterRef, align)) {
        return false;
    }

    i32 penned = 0;
    if (static_cast<u32>(monsterRef) < pens.byRef.size()) {
        penned = pens.byRef[static_cast<u32>(monsterRef)][static_cast<u32>(align)];
    }

    const Character& payer = party.members[static_cast<u32>(payerIndex)];
    const Currency base = creatureBaseWorth(
        ctx.data.monsters[static_cast<u32>(monsterRef)], payer.activeLevel());
    const Currency cost = penBuyPrice(base, penned);

    const ChargeResult paid = townCharge(ctx, party, payerIndex, cost, mods);
    if (!paid.paid) {
        return false;
    }
    releaseOne(pens, monsterRef, align);
    ctx.say("city.penBought", "Companion released from confinement",
            {cost, static_cast<i64>(monsterRef)}, {});
    return true;
}

bool confinementSell(Ctx& ctx, Party& party, i32 sellerIndex, PenBook& pens,
                     const Companion& companion, const TownModAnswers& mods) {
    if (sellerIndex < 0 || sellerIndex >= party.size) {
        return false;
    }
    // CompanionAlignment Good=1, Neutral=2, Evil=3 matches ItemAlign values.
    const ItemAlign penAlign = static_cast<ItemAlign>(static_cast<i32>(companion.alignment));
    const i32 align = penIndexOfItemAlign(penAlign);
    if (align < 0 || align >= kPenAlignCount) {
        return false;
    }
    const i32 ref = companion.ref;
    if (ref < 0 || companion.monsterId < 0 ||
        companion.monsterId >= static_cast<i32>(ctx.data.monsters.size())) {
        return false;
    }

    i32 before = 0;
    bool anyPenned = false;
    if (static_cast<u32>(ref) < pens.byRef.size()) {
        const PenCounts& c = pens.byRef[static_cast<u32>(ref)];
        before = c[static_cast<u32>(align)];
        for (i32 k = 0; k < kPenAlignCount; ++k) {
            if (c[static_cast<u32>(k)] > 0) {
                anyPenned = true;
            }
        }
    }

    const i32 payee = townIncomePayee(party, sellerIndex, mods);
    if (payee < 0 || payee >= party.size) {
        return false;
    }

    if (!penOne(pens, ref, align, companion.level)) {
        return false;
    }

    const Character& seller = party.members[static_cast<u32>(sellerIndex)];
    const Currency base = creatureBaseWorth(
        ctx.data.monsters[static_cast<u32>(companion.monsterId)], seller.activeLevel());
    const Currency price = penSellPrice(base, before, anyPenned,
                                        static_cast<i32>(companion.idLevel));

    party.members[static_cast<u32>(payee)].wallet.goldOnHand += price;
    ctx.say("city.penSold", "Companion penned for sale",
            {price, static_cast<i64>(ref)}, {});
    return true;
}

bool penOne(PenBook& pens, i32 ref, i32 align, i32 levelFound) {
    (void)levelFound;
    if (ref < 0 || align < 0 || align >= kPenAlignCount) {
        return false;
    }
    const u32 r = static_cast<u32>(ref);
    while (pens.byRef.size() <= r) {
        PenCounts zero{};
        pens.byRef.push_back(zero);
    }
    PenCounts& c = pens.byRef[r];
    const u32 a = static_cast<u32>(align);
    if (c[a] >= kPenShelfCap) {
        return false;
    }
    c[a] += 1;
    return true;
}

void releaseOne(PenBook& pens, i32 ref, i32 align) {
    if (ref < 0 || align < 0 || align >= kPenAlignCount) {
        return;
    }
    const u32 r = static_cast<u32>(ref);
    if (r >= pens.byRef.size()) {
        return;
    }
    PenCounts& c = pens.byRef[r];
    const u32 a = static_cast<u32>(align);
    if (c[a] > 0) {
        c[a] -= 1;
    }
}

bool penTakeAllowed(const PenBook& pens, i32 ref, i32 align) {
    if (ref < 0 || align < 0 || align >= kPenAlignCount) {
        return false;
    }
    if (ref >= static_cast<i32>(pens.byRef.size())) {
        return false;
    }
    return pens.byRef[static_cast<u32>(ref)][static_cast<u32>(align)] > 0;
}

Currency penBuyPrice(Currency baseValue, i32 pennedCount) {
    // CONFLICT: R22 says Log(0) gives price 0 for an empty pen (the original error trap), while the
    // quirk note says the port uses Max(1, ...). Following the explicit formula and the stated
    // "buying from an empty pen gives price 0" result: an empty pen gives 0.
    if (pennedCount <= 0) {
        return 0;
    }
    Currency value = maxv(baseValue, static_cast<Currency>(10));  // value = max(BaseValue, 10)
    i32 stock = pennedCount - 1;                                  // stock = penned - 1
    if (stock > 9) {                                              // stock = min(stock, 9)
        stock = 9;
    }
    double denom = std::log(static_cast<double>(stock) + 1.0) + 1.15;
    double price = (1.5 * static_cast<double>(value)) / denom;
    if (!std::isfinite(price)) {
        return 0;
    }
    return roundHalfEven(price);  // Long, round half to even
}

Currency penBuyPriceSet2(Currency baseValue, i32 pennedCount) {
    if (pennedCount <= 0) {
        return 0;
    }
    return roundHalfEven((1.5 * static_cast<double>(baseValue)) / 1.15);
}

Currency penSellPrice(Currency baseValue, i32 pennedCount, bool anyAlignmentPenned, i32 idLevel) {
    i32 stock = pennedCount;
    if (stock == 0 && anyAlignmentPenned) {
        stock = 1;
    }
    if (stock > 9) {
        stock = 9;
    }
    double price = ((0.9 * static_cast<double>(baseValue)) / (static_cast<double>(stock) + 1.15)) /
                   static_cast<double>(idLevel + 1);
    i64 r = roundHalfEven(price);  // Long
    return r < 0 ? 0 : r;          // floor 0
}

Currency penIdentifyPrice(Currency baseValue, i32 pennedCount, i32 idLevel) {
    // UNKNOWN: idLevel <= 0 is not an identify case (R20 step 3); returning 0 avoids divide by zero.
    if (idLevel <= 0) {
        return 0;
    }
    i32 stock = pennedCount;
    if (stock > 9) {
        stock = 9;
    }
    // As written: the "+ 1" is applied after the division by idLevel (R25 note).
    double v = ((0.13 * static_cast<double>(baseValue)) /
                ((static_cast<double>(stock) / 2.0 + 1.0) * 0.9)) /
                   static_cast<double>(idLevel) +
               1.0;
    i64 r = roundHalfEven(v);
    return r < 0 ? 0 : r;  // floor 0
}

void seedStartingPens(Ctx& ctx, PenBook& pens) {
    const Vec<ClassRange> first = buildClassRanges(ctx);
    const auto start = [&first](i32 kind) { return kind < static_cast<i32>(first.size()) ? first[static_cast<u32>(kind)].first : -1; };
    const i32 picked[10] = {start(0), start(0) + 1, start(7), start(7) + 1, start(8), start(8) + 1,
                            start(14), start(14) + 1, start(1), start(9)};
    const auto& monsters = ctx.data.monsters;
    const i32 n = static_cast<i32>(monsters.size());
    for (i32 i = 0; i < n; ++i) {
        bool hit = false;
        for (i32 k = 0; k < 10; ++k) hit = hit || picked[k] == i;
        if (!hit) continue;
        const i32 align = static_cast<i32>(monsters[static_cast<u32>(i)].alignmentValue);
        if (align < 0 || align >= kPenAlignCount) continue;
        while (static_cast<i32>(pens.byRef.size()) <= i) pens.byRef.push_back(PenCounts{});
        pens.byRef[static_cast<u32>(i)][static_cast<u32>(align)] = 2;   // R27: pen(i, AlignmentOf(monster i)) = 2 (set, not add)
    }
}

void restockPens(Ctx& ctx, PenBook& pens, i64 daysAged, i32 deepestReached) {
    const auto& monsters = ctx.data.monsters;
    i32 n = static_cast<i32>(monsters.size());
    if (n <= 0) {
        return;
    }

    // chance = clamp(days, 1, 50)
    i64 chance = daysAged;
    if (chance < kRestockChanceMin) {
        chance = kRestockChanceMin;
    }
    if (chance > kRestockChanceMax) {
        chance = kRestockChanceMax;
    }

    // UNKNOWN: deepest < 1 is not covered by the SRD; clamp to the 1..14 range.
    i32 deepest = deepestReached;
    if (deepest < 1) {
        deepest = 1;
    }
    if (deepest > kTownDeepestFloor) {
        deepest = kTownDeepestFloor;
    }

    // l0288: the one pen index both paths share, 0 (Good) at the start of each call (Confinement.cs:409-447).
    // It is not reset per pass.
    i32 l0288 = 0;

    i64 passes = 0;
    // while rnd*100 <= chance and passes < 500 (left to right, rnd drawn first)
    while (ctx.rng.nextDouble() * 100.0 <= static_cast<double>(chance) && passes < kReplenishPassCap) {
        ++passes;
        bool adding = ctx.rng.nextDouble() * 100.0 < static_cast<double>(kAddProbabilityPct);

        // roll = rnd(100)+1; floor = #f in 1..deepest with roll < 100 - (f/(deepest+1))*100
        i32 roll = static_cast<i32>(ctx.rng.below(100)) + 1;
        i32 floorNo = 0;
        for (i32 f = 1; f <= deepest; ++f) {
            double threshold = 100.0 - (static_cast<double>(f) / static_cast<double>(deepest + 1)) * 100.0;
            if (static_cast<double>(roll) < threshold) {
                ++floorNo;
            }
        }
        if (floorNo < 1) {
            floorNo = 1;
        }
        if (floorNo > deepest) {
            floorNo = deepest;
        }

        // retry up to 100 tries: draw kind (RoundedIndex), draw creature with LevelFound <= floor, LevelFound 0 excluded
        // UNKNOWN: "weighted by Chance" is implemented as acceptance with probability chance/100.
        i32 pick = -1;
        for (i32 t = 0; t < 100 && pick < 0; ++t) {
            i32 kind = roundedIndex(ctx, n);
            if (kind < 0 || kind >= n) {
                continue;
            }
            const auto& cand = monsters[static_cast<u32>(kind)];
            if (cand.levelFound <= 0 || cand.levelFound > floorNo) {
                continue;
            }
            i32 weight = cand.chance;
            if (weight < 0) {
                weight = 0;
            }
            if (weight > 100) {
                weight = 100;
            }
            if (static_cast<i32>(ctx.rng.below(100)) < weight) {
                pick = kind;
            }
        }
        if (pick < 0) {
            continue;
        }

        const auto& chosen = monsters[static_cast<u32>(pick)];
        i32 align = static_cast<i32>(chosen.alignmentValue);  // FIXED: was .alignment
        if (align < 0 || align >= kPenAlignCount) {
            continue;
        }
        if (adding) {
            // PenOne (Confinement.cs:452-460): the cap is tested on pen l0288, but the increment
            // lands on the creature's own alignment. A failed test still ends the pass.
            const u32 r = static_cast<u32>(pick);
            while (pens.byRef.size() <= r) {
                PenCounts zero{};
                pens.byRef.push_back(zero);
            }
            if (pens.byRef[r][static_cast<u32>(l0288)] >= kPenShelfCap) {
                continue;
            }
            pens.byRef[r][static_cast<u32>(align)] += 1;
        } else {
            // UNKNOWN: the reference ReleaseOne(chosen, rng, ref l0288) body is not in the packet, so
            // a release does not move l0288 here. The shared index stays at 0.
            releaseOne(pens, pick, align);                 // ReleaseOne
        }
    }
}

Currency creatureBaseWorth(const MonsterDef& def, i32 guildLevel) {
    double v = 500.0 * static_cast<double>(def.att) + 500.0 * static_cast<double>(def.def) +
               250.0 * static_cast<double>(def.hits);

    i32 statSum = def.stats[0] + def.stats[5];  // Stats[0] + Stats[5] (R22 quirk note on Stats(0))
    if (statSum < 1) {
        statSum = 1;                            // max(1, ...)
    }
    v = v * std::log(static_cast<double>(statSum));
    v = static_cast<double>(roundHalfEven(v * 10000.0)) / 10000.0;  // Currency rounding, 4 dp

    v = v * std::log(static_cast<double>(guildLevel) + 1.0);

    // Special attack bits: each set bit adds rate*GuildLevel + 1 (the +1 is a flat 1 gold).
    // UNKNOWN: rate units are taken to be the same units as v (gold).
    for (const BitRate& r : kSpecialAttackRates) {
        if (((def.specialAttackFlags >> r.bit) & 1u) != 0u) {
            v += static_cast<double>(r.rate) * static_cast<double>(guildLevel) + 1.0;
        }
    }

    // Spell bits, only if SpellFlags > 0.
    if (def.spellFlags > 0u) {
        for (const BitRate& r : kSpellRates) {
            if (((def.spellFlags >> r.bit) & 1u) != 0u) {
                v += static_cast<double>(r.rate) * static_cast<double>(guildLevel) + 1.0;
            }
        }
    }

    // Resistances 0..10: only positive values count (quirk note).
    for (i32 r = 0; r < kResistKinds; ++r) {
        i32 value = def.resistances[static_cast<u32>(r)];  // FIXED: was def.resistances.resist, which is the Arr itself
        if (value > 0) {
            v += 500.0 * static_cast<double>(value);
        }
    }

    if (def.hits == 1) {
        v = 1.0;
    }

    return roundHalfEven(v * 10000.0);
}

i32 penIndexOfItemAlign(ItemAlign align) {
    return static_cast<i32>(align) - 1;
}

VaultDeposit depositToVault(Ctx& ctx, Inventory& inv, i32 packSlot) {
    (void)ctx;
    // Slot 0 and slots 40 and above are refused.
    if (packSlot <= 0 || packSlot >= kPackSlots) {
        return VaultDeposit::Refused;
    }
    Item& src = inv.pack[static_cast<u32>(packSlot)];
    // Equipped items are refused.
    if (src.equipped) {
        return VaultDeposit::Refused;
    }

    // hole = first vault index with ItemId <= 0
    i32 hole = -1;
    i32 used = 0;
    for (i32 i = 0; i < kBankSlots; ++i) {
        if (inv.bank[static_cast<u32>(i)].id <= 0) {
            if (hole < 0) {
                hole = i;
            }
        } else {
            ++used;
        }
    }
    // A full vault (40 slots in use, no hole) is refused.
    if (hole < 0 && used >= kBankSlots) {
        return VaultDeposit::Refused;
    }
    // An empty pack slot succeeds without change.
    if (src.id <= 0) {
        return VaultDeposit::EmptySlot;
    }
    if (hole < 0) {
        return VaultDeposit::Refused;  // unreachable: a non-full vault always has a hole
    }
    inv.bank[static_cast<u32>(hole)] = src;
    src = Item{};
    return VaultDeposit::Stored;
}

i32 withdrawFromVault(Ctx& ctx, Inventory& inv, Party& party, const Vec<i32>& bankSlots) {
    (void)ctx;
    i32 moved = 0;
    for (u32 k = 0; k < static_cast<u32>(bankSlots.size()); ++k) {
        i32 b = bankSlots[k];
        if (b < 0 || b >= kBankSlots) {
            continue;
        }
        Item& src = inv.bank[static_cast<u32>(b)];
        if (src.id <= 0) {
            continue;
        }
        // UNKNOWN: pack slot 0 is refused for deposit, so the free-slot search starts at 1.
        i32 freeSlot = -1;
        for (i32 p = 1; p < kPackSlots; ++p) {
            if (inv.pack[static_cast<u32>(p)].id <= 0) {
                freeSlot = p;
                break;
            }
        }
        if (freeSlot < 0) {
            break;  // R32.2: a full pack stops a multiple withdrawal; the rest stays in the vault
        }
        // UNKNOWN: "the item is re-identified" has no defined effect in the SRD; left unchanged.
        inv.pack[static_cast<u32>(freeSlot)] = src;
        src = Item{};
        // Buffers naming that slot are let go.
        // UNKNOWN: ItemOrder.slot is taken to be the pack slot named by a buffer.
        for (u32 m = 0; m < static_cast<u32>(kPartyMaxSize); ++m) {
            if (party.itemOrders[m].slot == freeSlot) {
                party.itemOrders[m] = ItemOrder{};
            }
        }
        ++moved;
    }
    return moved;
}

i32 freeVaultSlots(const Inventory& inv) {
    i32 used = 0;
    for (i32 i = 0; i < kBankSlots; ++i) {
        if (inv.bank[static_cast<u32>(i)].id > 0) {
            ++used;
        }
    }
    return kBankSlots - used;
}

ChargeResult townCharge(Ctx& ctx, Party& party, i32 payerIndex, Currency cost, const TownModAnswers& mods) {
    ChargeResult res;
    if (payerIndex < 0 || payerIndex >= party.size) {
        return res;
    }
    Currency due = cost < 0 ? 0 : cost;
    Character& payer = party.members[static_cast<u32>(payerIndex)];

    // R34.2 and R34.3: short purse; the CoverShortfall hook may cover it first (R35).
    if (due > payer.purse()) {
        ShortfallCover cover = coverShortfall(ctx, party, payerIndex, due, mods);
        if (!cover.covered) {
            ctx.say("city.notEnoughGold", "Not enough gold!", {}, {});
            return res;
        }
    }

    // R34.1: gold on hand first, then the bank.
    Currency fromHand = payer.wallet.goldOnHand < due ? payer.wallet.goldOnHand : due;
    if (fromHand < 0) {
        fromHand = 0;
    }
    Currency fromBank = due - fromHand;
    payer.wallet.goldOnHand -= fromHand;
    payer.wallet.goldInBank -= fromBank;
    res.paid = true;
    res.fromHand = fromHand;
    res.fromBank = fromBank;
    return res;
}

ShortfallCover coverShortfall(Ctx& ctx, Party& party, i32 payerIndex, Currency cost, const TownModAnswers& mods) {
    ShortfallCover plan = wouldCoverShortfall(party, payerIndex, cost, mods);
    if (!plan.covered) {
        return plan;  // nothing moves; the original refusal follows
    }
    Character& payer = party.members[static_cast<u32>(payerIndex)];
    for (u32 k = 0; k < static_cast<u32>(plan.gifts.size()); ++k) {
        const ShortfallGift& g = plan.gifts[k];
        Character& giver = party.members[static_cast<u32>(g.giver)];
        giver.wallet.goldInBank -= g.amount;
        payer.wallet.goldOnHand += g.amount;
        // R35.6: one Messages line per giver.
        ctx.say("city.coverGift", "A party member covered part of the shortfall.",
                {g.amount}, {giver.name, payer.name});
    }
    return plan;
}

ShortfallCover wouldCoverShortfall(const Party& party, i32 payerIndex, Currency cost, const TownModAnswers& mods) {
    ShortfallCover out;
    if (payerIndex < 0 || payerIndex >= party.size) {
        return out;
    }
    const Character& payer = party.members[static_cast<u32>(payerIndex)];
    Currency need = cost - payer.purse();
    if (need <= 0) {
        // R35.1: the test applies only when cost > purse; otherwise nothing is needed.
        out.covered = true;
        return out;
    }
    // R35.1 conditions: mod hooks live, party size >= 2, payer in the city.
    // "in the city" is the payer's dungeon level being 0 (Party.cs PlanShortfall: payer.DungeonLevel != 0 -> null).
    if (mods.liveMods == 0) {
        return out;
    }
    if (party.size < 2) {
        return out;
    }
    if (payer.location.dungeonLevel != 0) {
        return out;
    }

    // Givers in the named order or in party order (R35.2). Per-giver amount already planned.
    Arr<Currency, kPartyMaxSize> taken{};
    // Distinct() (Party.cs PlanShortfall): each giver is asked once, so a repeat in a named order is skipped.
    Arr<bool, kPartyMaxSize> seen{};
    bool named = !mods.coverOrder.empty();
    i32 steps = named ? static_cast<i32>(mods.coverOrder.size()) : party.size;
    for (i32 s = 0; s < steps && need > 0; ++s) {
        i32 g = named ? mods.coverOrder[static_cast<u32>(s)] : s;
        if (g == payerIndex || g < 0 || g >= party.size) {
            continue;  // payer and non-members are skipped
        }
        const u32 gu = static_cast<u32>(g);
        if (seen[gu]) {
            continue;  // repeated name: already considered
        }
        seen[gu] = true;
        const Character& giver = party.members[gu];
        if (giver.location.dungeonLevel != 0 || giver.isDead()) {
            continue;  // not in the city, or dead
        }
        // R35.3: part = min(max(0, bank), need), minus what this plan already took from this giver.
        Currency avail = giver.wallet.goldInBank - taken[gu];
        if (avail < 0) {
            avail = 0;
        }
        Currency part = avail < need ? avail : need;
        if (part > 0) {
            ShortfallGift gift;
            gift.giver = g;
            gift.amount = part;
            out.gifts.push_back(gift);
            taken[gu] += part;
            need -= part;
        }
    }

    // R35.4: if the full shortfall cannot be covered, nothing moves.
    if (need > 0) {
        out.gifts = Vec<ShortfallGift>{};
        out.covered = false;
        return out;
    }
    out.covered = true;
    return out;
}

AltPoolOutcome chooseAltPPool(const Party& party, bool inTown, const TownModAnswers& mods) {
    // UNKNOWN: the SRD says the dungeon never asks; no pooling there is assumed (Refused).
    if (!inTown) {
        return AltPoolOutcome::Refused;
    }
    // A party of one is refused first and is not asked.
    if (party.size < kAltPoolMinParty) {
        return AltPoolOutcome::Refused;
    }
    // Default PoolOnHand; a mod may choose PoolAndDeposit.
    if (mods.altPoolAnswered && mods.altPoolDeposit) {
        return AltPoolOutcome::PoolAndDeposit;
    }
    return AltPoolOutcome::PoolOnHand;
}

bool storeRowVisible(const TownModAnswers& mods, i32 row) {
    if (mods.liveMods == 0) {
        return true;
    }
    for (u32 i = 0; i < static_cast<u32>(mods.hiddenRows.size()); ++i) {
        if (mods.hiddenRows[i] == row) {
            return false;
        }
    }
    return true;
}

bool storeRowOrderAccepted(const Vec<i32>& defaultRows, const Vec<i32>& modRows) {
    if (defaultRows.size() != modRows.size()) {
        return false;
    }
    for (u32 i = 0; i < static_cast<u32>(defaultRows.size()); ++i) {
        i32 v = defaultRows[i];
        u32 countDefault = 0;
        u32 countMod = 0;
        for (u32 j = 0; j < static_cast<u32>(defaultRows.size()); ++j) {
            if (defaultRows[j] == v) {
                ++countDefault;
            }
        }
        for (u32 j = 0; j < static_cast<u32>(modRows.size()); ++j) {
            if (modRows[j] == v) {
                ++countMod;
            }
        }
        if (countDefault != countMod) {
            return false;
        }
    }
    return true;
}

bool storeRowChangeAllowed(const TownModAnswers& mods) {
    return mods.rowChangeAllowed;
}

i32 townIncomePayee(const Party& party, i32 sellerIndex, const TownModAnswers& mods) {
    // R41: a non-member answer counts as null, so the payment goes to the seller's hand.
    // UNKNOWN: the seller's hand is returned as the seller's member index.
    if (mods.incomeAnswered) {
        i32 who = mods.incomePayee;
        if (who >= 0 && who < party.size) {
            return who;
        }
    }
    return sellerIndex;
}

i32 messageWindowLines(const TownModAnswers& mods) {
