void retarget(Ctx& ctx, GameState& game, Character& actor) {
    const i32 aimed = actor.order.aimedGroup;
    if (groupStanding(game, aimed)) {
        return;
    }
    const i32 first = standingGroupIndex(ctx, game, -1);
    if (first >= 0) {
        actor.order.aimedGroup = first;
    }
}

i32 standingGroupIndex(const Ctx& ctx, const GameState& game, i32 delta) {
    (void)ctx;
    // UNKNOWN: effect of delta on the search is not stated; the search always starts at group 0.
    (void)delta;
    for (i32 g = 0; g < kMaxGroups; ++g) {
        if (groupStanding(game, g)) {
            return g;
        }
    }
    return -1;
}

void engagementTick(Ctx& ctx, GameState& game) {
    // UNKNOWN: countdown semantics. A positive countdown is decremented and the tick waits.
    if (game.encounter.countdown > 0) {
        game.encounter.countdown -= 1;
        return;
    }
    const i32 lead = standingGroupIndex(ctx, game, 0);
    if (lead < 0) {
        return;
    }
    MonsterGroup& grp = game.encounter.groups[static_cast<u32>(lead)];

    if (grp.state == GroupState::Hostile) {
        // R17: a hostile waiting encounter attacks on the transition tick.
        // UNKNOWN: caller id for timer attacks; the monsters' own tick (0, no roll) is used.
        monstersFreeAttack(ctx, game, kCallerMonsterTick);
        return;
    }
    if (grp.state == GroupState::Peaced) {
        if (grp.joinOffer) {  // R18: a peaced encounter with a pending join offer stays put
            return;           // UNKNOWN: definition of join offer state
        }
        const i32 sel = game.party.selectedIndex;
        if (sel < 0 || sel >= game.party.size) {
            return;
        }
        Character& who = game.party.members[static_cast<u32>(sel)];
        // R19: lead monster and selected character, rolled against the hostile base formula.
        const i32 base = hostileBase(grp.front.align, who.alignment);
        const i32 cha = who.abilities.stats[static_cast<u32>(kStatIdxCha)];
        if (hostileRoll(ctx, base, cha)) {
            // UNKNOWN: effect of a successful roll. Assumed to make the group hostile; it attacks on a later tick.
            grp.state = GroupState::Hostile;
        }
    }
    // GroupState::Engaged: no timer action in the SRD text.
}

i32 hostileBase(CharAlign monsterAlign, Align charAlign) {
    return kHostileBase[static_cast<i32>(monsterAlign)][static_cast<i32>(charAlign)];
}

bool hostileRoll(Ctx& ctx, i32 base, i32 cha) {
    const i32 effCha = (cha < 1) ? 1 : cha;  // max(1, cha)
    const double x = static_cast<double>(base) - kHostileLnCoef * std::log(static_cast<double>(effCha));
    const i32 threshold = static_cast<i32>(x);  // truncation toward zero, as the SRD trunc()
    const i32 draw = static_cast<i32>(ctx.rng.below(kHostileRollMax)) + 1;  // 1..100
    return draw < threshold;
}

i32 freeAttackThreshold(i32 monsterDex, i32 charDex, bool cap) {
    i32 t = kFreeAttackBase + kFreeAttackPerDex * (monsterDex - charDex);
    if (t < kFreeAttackFloor) {
        t = kFreeAttackFloor;
    }
    if (cap && t > kFreeAttackCap) {
        t = kFreeAttackCap;  // R22: cap applies only on ChangedLevel
    }
    return t;
}

void monstersFreeAttack(Ctx& ctx, GameState& game, i32 caller) {
    const i32 size = game.party.size;
    if (size <= 0) {
        return;
    }
    const bool capped = (caller == kCallerChangedLevel);  // cap 98 only on ChangedLevel [c27]

    // RESOLVED-BY-REFERENCE: target weights are 100, 50, 25, 12, 6, 3, 1, 0, halved as integers,
    // summed once over the party as it stood when the monsters began (MULTIMOD.BAS:305-308).
    double total = 0.0;
    i32 share = 100;
    for (i32 i = 0; i < size; ++i) {
        total += static_cast<double>(share);
        share /= 2;
    }

    for (i32 g = 0; g < kMaxGroups; ++g) {
        if (!groupStanding(game, g)) {
            continue;
        }
        // REFERENCE: UBound(Chars) is read afresh for every group (MULTIMOD.BAS:320-324).
        const i32 last = game.party.size - 1;
        if (last < 0) {
            return;
        }
        const MonsterGroup& grp = game.encounter.groups[static_cast<u32>(g)];

        // REFERENCE: the target draw happens for every group, whatever the caller.
        // The front of the party draws the fire; the cumulative weight walk is ported literally.
        i32 target = 0;
        const i32 roll = static_cast<i32>(ctx.rng.below(kHostileRollMax)) + 1;  // 1..100
        i32 acc = 100;
        i32 step = 100;
        i32 guard = 0;
        while (static_cast<double>(acc) / total * 100.0 < static_cast<double>(roll) && guard < 32) {
            ++guard;
            ++target;
            if (target > last) {
                target = last;
            }
            step /= 2;
            acc += step;
        }
        if (target > last) {
            target = last;
        }
        const Character& who = game.party.members[static_cast<u32>(target)];
        // UNKNOWN: REFERENCE says a dead member can be picked and then the group wastes its turn.
        // The alive field is not in the shown Character headers, so that skip is not applied here.

        if (caller == kCallerMonsterTick) {
            // R26: monsters' own tick, no roll; every group goes.
            ctx.say("clock.monster_attack", "Monster group attacks",
                    {static_cast<i64>(g), static_cast<i64>(target)}, {});
            continue;
        }
        // R22/R26: per-group DEX free-attack roll (REFERENCE: Moved and ChangedLevel paths).
        const i32 threshold = freeAttackThreshold(grp.front.dex, who.abilities.stats[static_cast<u32>(kStatIdxDex)], capped);
        const i32 draw = static_cast<i32>(ctx.rng.below(kHostileRollMax)) + 1;  // 1..100
        if (draw < threshold) {
            ctx.say("clock.monster_attack", "Monster group attacks",
                    {static_cast<i64>(g), static_cast<i64>(target), static_cast<i64>(threshold)}, {});
        } else {
            ctx.say("clock.monster_miss", "Monster group does not attack",
                    {static_cast<i64>(g), static_cast<i64>(target), static_cast<i64>(threshold)}, {});
        }
    }
    // UNKNOWN: damage resolution is in the combat-resolution module; this module reports the attack decisions.
}

void freeRound(Ctx& ctx, GameState& game) {
    // UNKNOWN: caller id for the free round; Moved (1) assumed since no argument is given.
    freeRoundAs(ctx, game, kCallerMoved);
}

void onMove(Ctx& ctx, GameState& game, i32 arg) {
    if (arg == kMoveSameArea) {  // R23
        return;
    }
    if (!game.party.engaged) {   // R25: a free round applies only while engaged
        return;
    }
    if (arg == kMoveArgMoved) {  // R21: hostile room arrival, argument 1, uncapped
        freeRoundAs(ctx, game, kCallerMoved);
        return;
    }
    if (arg == kMoveArgChangedLevel) {  // R22: departure or level change, argument 2, capped at 98
        freeRoundAs(ctx, game, kCallerChangedLevel);
    }
}

void meleeHold(Ctx& ctx, i32 ms) {
    // The core never reads the clock, so the host performs the wait; the core reports the requested hold.
    // CONFLICT: port uses 250 ms each side; the VB3 trace describes a 500 ms hold per group result [c23]. The caller passes ms.
    ctx.say("clock.melee_hold", "Melee hold", {static_cast<i64>(ms)}, {});
}

void endCombat(Ctx& ctx, GameState& game) {
    endFight(ctx, game);            // R10: clear standing orders; CombatSetting unchanged
    game.inCombatRound = false;
    // Keys pressed during a hold were queued. The host replays them in order; the core reports each one.
    for (i32 k : game.queuedKeys) {
        ctx.say("clock.replay_key", "Replay queued key", {static_cast<i64>(k)}, {});
    }
    game.queuedKeys.clear();
}

f64 lnOf(f64 x) {
    return std::log(x);
}

i64 drawBelow(IRng& rng, f64 n) {
    return vbInt(rng.nextDouble() * n);
}

i32 ceilToI32(f64 x) {
    const i64 f = vbInt(x);
    return static_cast<i32>(static_cast<f64>(f) == x ? f : f + 1);
}

bool groupStanding(const MonsterGroup& g) {
    return g.livingCount > 0;
}

bool validGroupIndex(i32 index) {
    return index >= 0 && index < kMaxGroups;
}

i32 firstStandingGroup(const Encounter& enc) {
    for (i32 i = 0; i < kMaxGroups; ++i) {
        if (groupStanding(enc.groups[static_cast<u32>(i)])) {
            return i;
        }
    }
    return -1;
}

bool monsterHasBit(const Creature& m, i32 bit) {
    if (bit < 0 || bit > 31) {
        return false;
    }
    return ((m.specialPropertyFlags >> static_cast<u32>(bit)) & 1u) != 0u;
}

bool arrivalCombatStarts(const MonsterGroup& group) {
    if (group.count <= 0) {
        return false;
    }
    if (!group.front.hostile) {
        return false;
    }
    if (group.livingCount <= 0) {
        return false;
    }
    return true;
}

bool aimMustMove(const Encounter& enc, i32 aimedGroup) {
    if (!validGroupIndex(aimedGroup)) {
        return true;
    }
    return !groupStanding(enc.groups[static_cast<u32>(aimedGroup)]);
}

i32 furtherSwingAim(const Encounter& enc, i32 aimedGroup) {
    if (!aimMustMove(enc, aimedGroup)) {
        return aimedGroup;
    }
    // UNKNOWN: fn0DCD body not given; using first standing group (R5 wording).
    return firstStandingGroup(enc);
}

bool combatSettingApplies(const CombatOrder& order) {
    return order.kind == CombatOrderKind::None;
}

bool defendSuppressesAttack(const CombatOrder& order) {
    return order.kind == CombatOrderKind::Defend;
}

i32 swingsPerWeapon(i32 actorSwings, i32 weaponSwings) {
    return actorSwings + weaponSwings;
}

bool applyNoWeaponDefend(Ctx& ctx, Character& actor, bool hasWeapon, i32 totalSwings) {
    if (hasWeapon && totalSwings >= 1) {
        return false;
    }
    ctx.say("combat.no_weapon", "Using no weapon!", {}, {actor.name});
    actor.order.kind = CombatOrderKind::Defend;
    return true;
}

Vec<i32> equippedWeaponSlots(const Inventory& inv) {
    Vec<i32> slots;
    const i32 count = static_cast<i32>(inv.worn.size());
    for (i32 i = 0; i < count; ++i) {
        if (inv.worn[static_cast<u32>(i)].equipped) {
            slots.push_back(i);
        }
    }
    return slots;
}

i32 extraSwingsFromMultiple(f64 m, i32 guildLevel) {
    if (m <= 0.0) {
        return 0;
    }
    // UNKNOWN: m >= 11 makes ln(11-m) undefined in the SRD; grant nothing.
    if (m >= 11.0) {
        return 0;
    }
    const f64 step = lnOf(10.0 - m + 1.0);
    i64 threshold = roundHalfEven(step * 50.0);
    i32 extra = 0;
    for (i32 level = 1; level <= guildLevel; ++level) {
        if (static_cast<i64>(level) > threshold) {
            ++extra;
            threshold = roundHalfEven(step * static_cast<f64>(threshold) * 2.0);
        }
    }
    return extra;
}

i32 raiseSwingsIfHigher(i32 currentSwings, i32 award) {
    return award > currentSwings ? award : currentSwings;
}

void recalcSwings(Ctx& ctx, Character& c) {
    (void)ctx;
    for (i32 g = 0; g < kGuildCount; ++g) {
        const u32 gi = static_cast<u32>(g);
        const f64 m = static_cast<f64>(c.guilds[gi].abilityRating[static_cast<u32>(kMultipleSwingsAbility)]);
        const i32 award = extraSwingsFromMultiple(m, c.guilds[gi].level);
        c.combat.swings = raiseSwingsIfHigher(c.combat.swings, award);
    }
}

bool weaponBlockedByNeedsGoodWeapon(const Creature& target, i32 weaponFloor) {
    return monsterHasBit(target, kBitNeedsGoodWeapon) && weaponFloor < target.levelFound / 2;
}

bool weaponNullifiedByImmunity(const Creature& target) {
    return monsterHasBit(target, kBitImmuneToWeapons);
}

WeaponGateOutcome checkWeaponGate(const Creature& target, i32 weaponFloor) {
    if (weaponBlockedByNeedsGoodWeapon(target, weaponFloor)) {
        return WeaponGateOutcome::NeedsGoodWeaponBlocked;
    }
    if (weaponNullifiedByImmunity(target)) {
        return WeaponGateOutcome::ImmuneNoEffect;
    }
    return WeaponGateOutcome::Pass;
}

void applyBlockedHandDefend(Ctx& ctx, Party& party, i32 actorSlot) {
    (void)ctx;
    if (actorSlot < 0 || actorSlot >= party.size) {
        return;
    }
    const u32 s = static_cast<u32>(actorSlot);
    party.itemOrders[s] = ItemOrder{};
    party.members[s].order.kind = CombatOrderKind::Defend;
    party.combatOrders[s].kind = CombatOrderKind::Defend;
}

bool swingUnseen(const Character& actor, const Creature& target) {
    return target.unseen && !actor.ailments.seeInvisible;
}

i32 meleeHitAndDamage(Ctx& ctx, i32 atk, i32 def, i32 level, i32 strength, f64 damMod) {
    // R18: threshold first.
    const i32 threshold = hitThresholdPercent(atk, def);

    if (damMod <= 0.0) {
        damMod = kMinDamMod;
    }

    // str = max(1, strength); str = B(str - Ln(str)*((Ln(str)-2.4)*2.25)) + 1
    const i32 base = strength < 1 ? 1 : strength;
    const f64 lnS = lnOf(static_cast<f64>(base));
    const f64 s = static_cast<f64>(roundHalfEven(static_cast<f64>(base) - lnS * ((lnS - 2.4) * 2.25))) + 1.0;

    // if damMod > 1: damMod -= Ln(damMod)^2
    if (damMod > 1.0) {
        const f64 l = lnOf(damMod);
        damMod -= l * l;
    }

    const f64 lvlTerm = (lnOf(static_cast<f64>(level) + 5.0) + 1.0) / lnOf(1.2);
    const f64 strTerm = s / 30.0;

    // roll = Int(U1*((s+10)/2) + (s+10)/4) / 10
    const f64 roll = static_cast<f64>(vbInt(ctx.rng.nextDouble() * ((s + 10.0) / 2.0) + (s + 10.0) / 4.0)) / 10.0;

    i64 dmg = vbInt(lvlTerm * strTerm * roll * damMod);

    // R19: adj = Int(Int((def-atk)/2)/4)
    i64 adj = attackDefenceTerm(atk, def);
    // adj = adj - Int(U2*(adj+1)) + 1   (U2 always drawn)
    adj = adj - drawBelow(ctx.rng, static_cast<f64>(adj + 1)) + 1;

    // if Int(U3*1000)+1 > 1: dmg -= adj   (U3 always drawn; applies 999 in 1000)
    if (drawBelow(ctx.rng, 1000.0) + 1 > 1) {
        dmg -= adj;
    }

    if (dmg < 1) {
        dmg = 0;
    }

    // R18 gate: miss when Int(U4*100)+1 >= threshold (U4 always drawn).
    if (!rollHitGate(ctx, threshold)) {
        return 0;
    }
    return static_cast<i32>(dmg);
}

i32 hitThresholdPercent(i32 atk, i32 def) {
    f64 p = static_cast<f64>(kHitGateNeutralPercent);
    if (atk == def) {
        p = static_cast<f64>(kHitGateNeutralPercent);
    } else {
        const i32 denom = atk > def ? atk : def;
        if (denom != 0) {
            p = 50.0 + 50.0 * static_cast<f64>(atk - def) / static_cast<f64>(denom);
        }
    }
    if (p < static_cast<f64>(kHitGateMinPercent)) {
        p = static_cast<f64>(kHitGateMinPercent);
    }
    if (p > static_cast<f64>(kHitGateMaxPercent)) {
        p = static_cast<f64>(kHitGateMaxPercent);
    }
    return ceilToI32(p);
}

bool rollHitGate(Ctx& ctx, i32 thresholdPercent) {
    const i64 roll = vbInt(ctx.rng.nextDouble() * 100.0) + 1;
    return roll < static_cast<i64>(thresholdPercent);
}

i32 attackDefenceTerm(i32 att, i32 def) {
    const i64 half = vbInt(static_cast<f64>(def - att) / 2.0);
    return static_cast<i32>(vbInt(static_cast<f64>(half) / 4.0));
}

bool isMissedSwing(i32 damage) {
    return damage < 1;
}

bool weaponChainContinues(i32 damage, bool killedTarget) {
    return killedTarget && !isMissedSwing(damage);
}

f64 meleeBaseFactor(i32 guildLevel, f64 fightingMod) {
    return 0.6 + ((lnOf(100.0 + static_cast<f64>(guildLevel)) / 1.75 - 2.3) * (fightingMod * fightingMod) / 2.0);
}

f64 characterDamageMod(i32 guildLevel, f64 fightingMod, f64 weaponMod, bool crit, bool backstab, bool invisibleTarget, i32 sizeDiff) {
    f64 damMod = meleeBaseFactor(guildLevel, fightingMod);
    damMod *= (weaponMod <= 0.0 ? 1.0 : weaponMod);
    if (crit) {
        damMod += kCritDamBonus;
    }
    if (backstab) {
        damMod += kBackstabDamBonus;
    }
    if (invisibleTarget) {
        damMod -= damMod / 2.0;
    }
    if (sizeDiff < 0) {
        damMod -= static_cast<f64>(-sizeDiff) / static_cast<f64>(kSizeDiffDivisor);
    }
    if (sizeDiff > 0) {
        damMod += static_cast<f64>(sizeDiff) / static_cast<f64>(kSizeDiffDivisor);
    }
    return damMod;
}

i32 characterDamage(Ctx& ctx, i32 guildLevel, f64 fightingMod, f64 weaponMod, i32 strength, i32 sizeDiff, bool crit, bool backstab, i32 attack, bool unseen) {
    const f64 damMod = characterDamageMod(guildLevel, fightingMod, weaponMod, crit, backstab, unseen, sizeDiff);
    return meleeHitAndDamage(ctx, attack, kPlayerMeleeDefence, guildLevel, strength, damMod);
}

i32 companionGateDefence(i32 targetDefence, bool crit, bool backstab) {
    i32 d = targetDefence;
    if (crit) {
        d += kCompanionCritDefence;
    }
    if (backstab) {
        d += kCompanionBackstabDefence;
    }
    return d;
}

f64 companionDamageMod(f64 baseMod, bool unseen) {
    return unseen ? baseMod / 2.0 : baseMod;
}

i32 chooseFightingGuild(const Ctx& ctx, const Character& c) {
    (void)ctx;
    return static_cast<i32>(c.activeGuild);
}

bool needsDeathProcessing(const Character& c) {
    return c.vitals.curHits <= 0;
}

bool leavesRoundAtOnce(const Character& c) {
    return c.isDead();
}

void processMidRoundDeath(Ctx& ctx, Party& party, i32 memberIndex) {
    if (memberIndex < 0 || memberIndex >= party.size) {
        return;
    }
    const u32 idx = static_cast<u32>(memberIndex);
    Character& m = party.members[idx];
    if (!needsDeathProcessing(m)) {
        return;
    }

    m.ailments = Ailments{};   // ailments are cleared
    m.saved = true;            // UNKNOWN: "saved" taken as the character's saved flag

    const Str name = m.name;
    party.morgueList.push_back(m);  // UNKNOWN: destination of pruned members

    const u32 last = static_cast<u32>(party.size - 1);
    for (u32 i = idx; i < last; ++i) {
        party.members[i] = party.members[i + 1];
        party.combatOrders[i] = party.combatOrders[i + 1];
        party.itemOrders[i] = party.itemOrders[i + 1];
    }
    party.members[last] = Character{};
    party.combatOrders[last] = CombatOrder{};
    party.itemOrders[last] = ItemOrder{};
    party.size -= 1;

    ctx.say("combat.member_pruned", "Party member removed after death.", {static_cast<i64>(memberIndex)}, {name});
}

bool roundLoopEnds(i32 membersLeft) {
    return membersLeft <= 1;
}

void awardBlowExperience(Ctx& ctx, Character& actor, i64 xp) {
    const i64 before = actor.experience;
    actor.experience += xp;
    const bool readyBefore = before >= actor.xpRequired;
    const bool readyAfter = actor.experience >= actor.xpRequired;
    if (!readyBefore && readyAfter) {
        ctx.say("combat.level_ready", "now has enough experience to make a level.", {}, {actor.name});
    }
}

i32 recordedHitsFor(i32 hitsTaken, i32 monsterHpRemaining) {
    return hitsTaken < monsterHpRemaining ? hitsTaken : monsterHpRemaining;
}

void recordMonsterStrike(Ctx& ctx, Character& owner, const Creature& target, i32 hitsTaken, bool killingBlow, bool charmed, bool companionCredit) {
    const i32 recorded = recordedHitsFor(hitsTaken, target.hits);
    const i64 kindFlag = companionCredit ? 1 : 0;

    if (!charmed) {
        owner.damageRecorded += static_cast<i64>(recorded);
        ctx.say("combat.damage_record", "Damage recorded.", {static_cast<i64>(recorded), kindFlag}, {});
    }
    if (killingBlow) {
        owner.kills += 1;
        owner.monsterKills.push_back(target.id);
        ctx.say("combat.kill_record", "Kill recorded.", {static_cast<i64>(target.id), kindFlag}, {});
    }
}

bool isLivingCompanionSlot(const Companion& c) {
    return c.occupied && !c.isDead && c.deathState == CompanionDeathState::Normal;
}

void countWeaponBlow(Ctx& ctx, Character& ch) {
    (void)ctx;
    ch.weaponBlows += 1;
}

i32 freeAttackChance(AttackKind kind, i32 monDex, i32 charDex) {
    i32 chance = kFreeAttackBase + (monDex - charDex) * kFreeAttackPerDex;
    if (kind == AttackKind::ChangedLevel && chance > kFreeAttackChangedLevelCap) {
        chance = kFreeAttackChangedLevelCap;  // R33 stairs cap; Moved has no ceiling (quirk)
    }
    if (chance < kFreeAttackFloor) {
        chance = kFreeAttackFloor;
    }
    return chance;
}

bool rollFreeAttack(Ctx& ctx, AttackKind kind, i32 monDex, i32 charDex) {
    const i32 chance = freeAttackChance(kind, monDex, charDex);
    const i32 roll = static_cast<i32>(ctx.rng.below(kPercentDie)) + 1;
    return roll < chance;
}

i32 pickMonsterTarget(Ctx& ctx, const Party& party, const Arr<Companion, kCompanionSlots>& companions) {
    (void)party;  // R34 uses the companion array only.
    i32 alive = 0;
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        if (isLivingCompanionSlot(companions[static_cast<u32>(i)])) {
            ++alive;
        }
    }
    i32 t = 0;
    // R34: if alive > 0 and (Rnd(100)+1) < 100.0/(alive+1): t = 0 (character).
    // The roll is drawn only when alive > 0 (short-circuit, as in the SRD).
    const bool characterTargeted =
        alive > 0 &&
        static_cast<f64>(ctx.rng.below(kPercentDie) + 1) < 100.0 / static_cast<f64>(alive + 1);
    if (characterTargeted) {
        t = 0;
    } else {
        // R34: else pick = Rnd(4)+1 until a living companion at that slot, 100 tries.
        // QUIRK (faithful): this loop also runs when alive == 0, drawing RNG each try.
        for (i32 tries = 0; tries < kTargetPickTries; ++tries) {
            const i32 pick = static_cast<i32>(ctx.rng.below(kCompanionSlots)) + 1;
            if (isLivingCompanionSlot(companions[static_cast<u32>(pick - 1)])) {
                t = pick;
                break;
            }
        }
    }
    return t;
}

f64 meleeDamageModifier(Ctx& ctx, const MeleeModInput& in) {
    // CONFLICT: T10 table says floor 0.1 when caller passes <= 0; R35 text says 1. Using R35.
    // Reference (Combat.cs SwingOnce) passes weapon.DamageMod straight through and shows no floor.
    f64 damMod = in.damageMod <= 0.0 ? 1.0 : in.damageMod;

    // Target invisible and attacker lacks see-invisible (bit 0).
    if (in.targetInvisible && !in.attackerSeesInvisible) {
        damMod -= kInvisibleMalus;
    }
    // Character opening chest.
    if (in.targetOpeningChest) {
        damMod += kOpeningChestBonus;
    }
    // bit10 crit. CONFLICT: SRD text says Rnd(100)+1 <= chance; reference (Combat.cs SwingOnce)
    // says `_rng.Next(100) < chance`, i.e. Int(Rnd*100) against a Single, fractional part counts.
    // Using the reference form.
    if (in.critCapable) {
        const f64 chance = monsterCritChance(in.monsterLevel, in.levelFound, in.characterLevel, false);
        if (static_cast<f64>(ctx.rng.below(kPercentDie)) < chance) {
            damMod += kCritDamageBonus;
        }
    }
    // bit11 backstab: same test with backstab = true (reference form, as above).
    if (in.backstabCapable) {
        const f64 chance = monsterCritChance(in.monsterLevel, in.levelFound, in.characterLevel, true);
        if (static_cast<f64>(ctx.rng.below(kPercentDie)) < chance) {
            damMod += kBackstabDamageBonus;
        }
    }
    // Size: +sizeDiff/10 if target smaller than monster, -sizeDiff/10 if larger.
    damMod += sizeDamageAdjust(in.targetSize, in.monsterSize);
    return damMod;
}

f64 sizeDamageAdjust(i32 targetSize, i32 monsterSize) {
    const i32 diff = targetSize > monsterSize ? targetSize - monsterSize : monsterSize - targetSize;
    const f64 step = static_cast<f64>(diff) / kSizeStepDivisor;
    if (targetSize < monsterSize) {
        return step;
    }
    if (targetSize > monsterSize) {
        return -step;
    }
    return 0.0;
}

i64 protectionBonus(i32 protection) {
    if (protection <= 0) {
        return 0;
    }
    const f64 lg = std::log(static_cast<f64>(protection));
    return vbInt(lg * (lg * kProtectionLogScale));
}

i32 defenceWithProtection(i32 defence, i32 protection) {
    return defence + static_cast<i32>(protectionBonus(protection));
}

i32 monsterBlow(Ctx& ctx, i32 monAtt, i32 targetDef, i32 monLvl, i32 monStr, f64 damMod) {
