i32 equippedAtt(const Ctx& ctx, const Inventory& inv) {
    i32 sum = 0;
    for (u64 i = 0; i < inv.worn.size(); ++i) {
        const Item& item = inv.worn[i];
        if (!item.equipped) {
            continue;
        }
        const ItemDef* def = itemDefOf(ctx, item);
        if (def != nullptr) {
            sum += def->att;
        }
    }
    return sum;
}

i32 equippedDef(const Ctx& ctx, const Inventory& inv) {
    i32 sum = 0;
