    AdPair pair{};
    pair.att = floorAtZero(baseAD(local, c) + best.att + equippedAtt(ctx, inv));
    pair.def = floorAtZero(baseAD(local, c) + best.def + equippedDef(ctx, inv));
    return pair;
}

