    if (t > joinBar(cha, levelFound)) {
        return 0;
    }
    i32 n = minv(groupCount, kJoinOfferGroupCap);
    if (n < 1) {
        n = 1;  // UNKNOWN: zero groups with an offer; treated as one.
    }
    return static_cast<i32>(ctx.rng.below(n)) + 1;
}

