f64 companionDriftContent(i32 hits, i32 maxHits) {
    // R34 drift content (Binding < 0): max(0.5, (MaxHits - Hits) / MaxHits * 15); 0 if MaxHits <= 0.
    // The floor and scale are written out from the SRD. Check that kDriftContentFloor
    // is 0.5 and kDriftContentScale is 15.0 wherever they are defined.
    // The floor is applied with an explicit comparison, not maxv, so fractional results are kept.
    constexpr f64 kContentFloor = 0.5;
    constexpr f64 kContentScale = 15.0;
    if (maxHits <= 0) {
        return 0.0;
    }
    const f64 raw = static_cast<f64>(maxHits - hits) / static_cast<f64>(maxHits) * kContentScale;
    return (raw > kContentFloor) ? raw : kContentFloor;
}

f64 companionDriftBound(i32 guildLevel, i32 topGuildLevel, i32 bindingLevel) {
    // R34 drift bound (Binding > 0): max(1, GuildLevel / ln(3) * 2 - TopGuildLevel / ln(12) * |Binding / 2|)
    // The floor and formula are written out from the SRD so they do not depend on the
    // kDriftBoundFloor value. Check that kDriftBoundFloor is 1.0 wherever it is defined.
    // The floor is applied with an explicit comparison, not maxv, so fractional results are kept.
    constexpr f64 kBoundFloor = 1.0;
    const f64 a = static_cast<f64>(guildLevel) / std::log(3.0) * 2.0;
    const f64 b = static_cast<f64>(topGuildLevel) / std::log(12.0) *
                  std::fabs(static_cast<f64>(bindingLevel) / 2.0);
    const f64 raw = a - b;
    return (raw > kBoundFloor) ? raw : kBoundFloor;
}

void companionMoodRound(Ctx& ctx, Companion& c, i32 topGuildLevel) {
    if (c.forLife) {
        return;
    }
    f64 drift = 0.0;
    if (c.bindingLevel < 0) {
        drift = companionDriftContent(c.hits, c.maxHits);
    } else if (c.bindingLevel > 0) {
        drift = companionDriftBound(c.guildLevel, topGuildLevel, c.bindingLevel);
    }
    if (ctx.rng.nextDouble() * kDriftRollRange < drift) {
        c.bindingLevel += (c.bindingLevel > 0 ? -1 : 1);
    }
}

i32 boundFromBinding(i32 bindingLevel) {
    const f64 mag = static_cast<f64>(absI(bindingLevel)) * kBoundScale;
    return static_cast<i32>(roundHalfEven(mag));
}

f64 companionChanceToLeave(const Companion& c, i32 topGuildLevel, i32 charisma) {
    if (c.bindingLevel == kBindingMax) {
        return 0.0;
    }
    const i32 bound = boundFromBinding(c.bindingLevel);
    const f64 mon = std::log(static_cast<f64>(c.guildLevel) + 1.0) * kMonsterLeaveScale;
    f64 x = mon * kMonsterLeaveWeight -
            (static_cast<f64>(bound) * kBoundWeight +
             std::log(static_cast<f64>(topGuildLevel) / kTopGuildLnDivisor + 1.0) * kTopGuildLnWeight);
    x = x - static_cast<f64>(charisma) / kChaDivisor;
    x = x / kLeaveNormDivisor * kLeaveNormScale;
    // UNKNOWN: maxHits == 0 would divide by zero; the hits term is then omitted.
    if (c.maxHits > 0) {
        x = x + static_cast<f64>(c.maxHits - c.hits) / static_cast<f64>(c.maxHits) * kHitsLeaveScale;
    }
    x = x / kLeaveFinalDivisor;
    return clampv(x, 0.0, static_cast<f64>(kChanceToLeaveMax));
}

Str companionLeaveDescribe(f64 chance) {
    if (chance <= 0.0) {
        return Str("Completely");
    }
    if (chance <= kLeaveDescribeLimit[0]) {
        return Str("Excellently");
    }
    if (chance <= kLeaveDescribeLimit[1]) {
        return Str("Fairly");
    }
    if (chance <= kLeaveDescribeLimit[2]) {
        return Str("Marginally");
    }
    if (chance <= kLeaveDescribeLimit[3]) {
        return Str("Weakly");
    }
    return Str("Very Weakly");
}

bool companionLeaveRoll(Ctx& ctx, const Companion& c, f64 chance) {
    const bool roll = ctx.rng.nextDouble() * kLeaveRollRange < chance;
    return roll || c.bindingLevel == 0;
}

TurnOutcome companionTurnCheck(Ctx& ctx, const Companion& c, Align ownerAlign, CharAlign creatureAlign,
                               bool forced, const Vec<Creature>& foes, bool groupSlotFree) {
    const f64 rnd1 = ctx.rng.nextDouble();
    const f64 rnd2 = ctx.rng.nextDouble();
    const i32 creatureA = static_cast<i32>(creatureAlign);
    const i32 ownerA = static_cast<i32>(ownerAlign);

    bool turns = absI(creatureA - ownerA) > 1;
    if (creatureAlign == CharAlign::Evil && rnd1 * 100.0 < kTurnEvilPercent) {
        turns = true;
    }
    if (creatureAlign == CharAlign::Neutral && rnd2 * 100.0 < kTurnNeutralPercent) {
        turns = true;
    }
    if (forced) {
        turns = true;
    }
    if (!forced) {
        if (creatureAlign == CharAlign::Good) {
            turns = false;  // R36 rule 1
        }
        if (c.bindingLevel <= 0) {
            turns = false;  // R36 rule 2
        }
    }
    if (turns && !foes.empty() && absI(static_cast<i32>(foes[0].align) - creatureA) > 1) {
        ctx.say("companion.refuses", "Your companion refuses to join the current monsters!", {}, {});
        return TurnOutcome::RefusedByFoe;
    }
    if (turns && !groupSlotFree) {
        return TurnOutcome::NoGroupSlot;  // R36 rule 3
    }
    return turns ? TurnOutcome::Joins : TurnOutcome::Holds;
}

i32 uidx(i32 i) {
    return static_cast<i32>(i);
}

bool isDeadCompanion(const Companion& c) {
    // R37.2 / R46 / R39: dead means Hits at or below 0, or the dead flag.
    return c.hits <= 0 || c.isDead;
}

Vec<Creature>& liveSetOf(LiveSetRef& live) {
    // R41.1: combat monsters if a fight exists, else the waiting group.
    return live.fightExists ? live.combatMonsters : live.waitingGroup;
}

void joinLiveSet(const Companion& c, CharAlign creatureAlign, LiveSetRef& live) {
    Creature m;
    m.id = c.monsterId;
    m.align = creatureAlign;
    m.hits = c.hits;
    m.maxHits = c.maxHits;
    m.guildLevel = c.guildLevel;
    m.alive = c.hits > 0;
    m.hostile = false;
    liveSetOf(live).push_back(m);
}

i32 keptSlotOf(const Inventory& inv) {
    if (inv.carryIndex >= 0 && inv.carryIndex < kCompanionSlots) {
        return inv.carryIndex;
    }
    return -1;
}

void companionRoundPass(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, const Character& owner,
                        const Arr<CharAlign, kCompanionSlots>& creatureAligns, LiveSetRef& live) {
    const i32 charisma = owner.abilities.stats[static_cast<u32>(StatIndex::Cha)];
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        Companion& c = slots[static_cast<u32>(i)];
        if (!c.occupied || c.forLife) {
            continue;  // R34: ForLife is never touched
        }
        companionMoodRound(ctx, c, owner.topGuildLevel);  // R34.1
        const f64 chance = companionChanceToLeave(c, owner.topGuildLevel, charisma);
        if (!companionLeaveRoll(ctx, c, chance)) {  // R34 leave test
            continue;
        }
        const CharAlign creatureAlign = creatureAligns[static_cast<u32>(i)];
        const TurnOutcome t = companionTurnCheck(ctx, c, owner.alignment, creatureAlign, false,
                                                 liveSetOf(live), live.groupSlotFree);  // R34.2
        if (t == TurnOutcome::Joins) {  // R34.3: turns and joins the fight
            ctx.say("companion.turns", "Your companion turns into a monster!", {static_cast<i64>(i)}, {});
            joinLiveSet(c, creatureAlign, live);
        } else {
            // R34.3 leave line. UNKNOWN: also used when refused or no group slot.
            ctx.say("companion.leaves", "Your companion leaves.", {static_cast<i64>(i)},
                    {companionLeaveDescribe(chance)});
        }
        c.occupied = false;  // slot left empty
        c.released = true;
    }
}

bool carryChoiceOpen(i32 carryIndex) {
    return carryIndex < kCompanionSlots;
}

i32 pickCarryCandidate(const Arr<Companion, kCompanionSlots>& slots, const Arr<i32, kCompanionSlots>& bodySizes) {
    (void)bodySizes;
    i32 best = -1;
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        const Companion& c = slots[static_cast<u32>(i)];
        if (!c.occupied || c.hits > 0) {
            continue;
        }
        if (best < 0 || c.maxHits > slots[static_cast<u32>(best)].maxHits) {
            best = i;
        }
    }
    return best;
}

bool carryPickTest(i32 bodySize, i32 carrierSize) {
    return bodySize - carrierSize <= 1;
}

void runCarryChoice(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, Inventory& inv,
                    const Arr<i32, kCompanionSlots>& bodySizes, i32 carrierSize) {
    if (!carryChoiceOpen(inv.carryIndex)) {  // R37.1 (morgue body carried: skipped)
        return;
    }
    i32 best = -1;
    for (i32 i = 0; i < kCompanionSlots; ++i) {  // R37.2 scan
        const Companion& c = slots[static_cast<u32>(i)];
        if (!c.occupied || c.hits > 0) {
            continue;
        }
        if (best < 0) {
            best = i;
            continue;
        }
        if (c.maxHits > slots[static_cast<u32>(best)].maxHits) {
            if (inv.carryIndex == kCarryNone) {
                // QUIRK: slot -1 printed, then the sub ends (no pickup, no sweep).
                ctx.say("companion.dropped", "dropped", {static_cast<i64>(kCarryNone)}, {});
                return;
            }
            ctx.say("companion.dropped", "dropped", {static_cast<i64>(best)}, {});
            best = i;
        }
    }
    if (best < 0) {
        sweepFallenCompanions(ctx, slots, keptSlotOf(inv));  // R37.4
        return;
    }
    if (carryPickTest(bodySizes[static_cast<u32>(best)], carrierSize)) {  // R37.3
        inv.carryIndex = best;
        // UNKNOWN: SRD text for the carried companion's hit points was not supplied.
        // Reference value (test expects 0 after pickup from negative hits) is used.
        // A picked-up companion with negative hits is brought to 0 hits.
        if (slots[static_cast<u32>(best)].hits < 0) {
            slots[static_cast<u32>(best)].hits = 0;
        }
        sweepFallenCompanions(ctx, slots, best);  // R37.4
        return;
    }
    // R37.3: too big to carry, the winner is released.
    ctx.say("companion.tooBig", "too big to carry", {static_cast<i64>(best)},
            {slots[static_cast<u32>(best)].name});
    slots[static_cast<u32>(best)].released = true;
    slots[static_cast<u32>(best)].occupied = false;
    sweepFallenCompanions(ctx, slots, keptSlotOf(inv));  // R37.4
}

void sweepFallenCompanions(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, i32 keptSlot) {
    (void)ctx;
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        if (i == keptSlot) {
            continue;
        }
        Companion& c = slots[static_cast<u32>(i)];
        if (c.occupied && c.hits <= 0) {
            c.occupied = false;
            c.released = true;
        }
    }
}

void companionsLetGoOnDeath(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, Inventory& inv) {
    (void)ctx;
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        Companion& c = slots[static_cast<u32>(i)];
        if (c.occupied) {
            c.occupied = false;
            c.released = true;
        }
    }
    inv.carryIndex = kCarryNone;
}

i64 creatureBaseValue(const Creature& c) {
    if (c.hits == 1) {
        return 1;
    }
    i64 value = 0;
    if (c.resistance > 0) {
        value += c.resistance;
    }
    if (c.magicResistance > 0) {
        value += c.magicResistance;
    }
    return value;
}

bool companionDeathTrigger(const Companion& c) {
    return c.hits <= 0;
}

KickOutCheck kickOutCheck(const Companion& c, bool inCity) {
    KickOutCheck r;
    r.warnBound = c.bindingLevel > 0;
    if (isDeadCompanion(c)) {
        r.allowed = false;
        r.refusal = KickOutRefusal::Dead;
        return r;
    }
    if (inCity) {
        r.allowed = false;
        r.refusal = KickOutRefusal::City;
        return r;
    }
    r.allowed = true;
    r.refusal = KickOutRefusal::None;
    return r;
}

bool kickOutCompanion(Ctx& ctx, Companion& c, const Character& owner, CharAlign creatureAlign,
                      bool inCity, bool confirmed, LiveSetRef& live) {
    const KickOutCheck chk = kickOutCheck(c, inCity);
    if (!chk.allowed) {
        if (chk.refusal == KickOutRefusal::Dead) {
            ctx.say("companion.dropFirst", "Drop it first.", {}, {});
        } else {
            ctx.say("companion.kickRefusedCity", "You cannot kick out a companion in the city.", {}, {});
        }
        return false;  // R39.3: selection untouched
    }
    if (chk.warnBound) {
        ctx.say("companion.boundWarning", "This companion is bound to you.", {}, {});
    }
    if (!confirmed) {
        return false;  // R39.2: No changes nothing
    }
    return letCompanionGo(ctx, c, owner, creatureAlign, live, false);  // R39.2 Yes
}

RightClickOutcome rightClickAttackCheck(const Companion& c, Align compareAlign) {
    if (c.hits <= 0) {
        return RightClickOutcome::Ignored;
    }
    const bool companionGood = c.alignment == CompanionAlignment::Good;
    if (companionGood && compareAlign == Align::Good) {
        return RightClickOutcome::Refused;
    }
    return RightClickOutcome::LetGo;
}

bool rightClickAttack(Ctx& ctx, Companion& c, const Character& owner, CharAlign creatureAlign,
                      Align compareAlign, LiveSetRef& live) {
    const RightClickOutcome o = rightClickAttackCheck(c, compareAlign);
    if (o == RightClickOutcome::Ignored) {
        return false;
    }
    if (o == RightClickOutcome::Refused) {
        ctx.say("companion.rightClickRefused", "Your companion will not attack.", {}, {});
        return false;
    }
    return letCompanionGo(ctx, c, owner, creatureAlign, live, true);
}

bool letCompanionGo(Ctx& ctx, Companion& c, const Character& owner, CharAlign creatureAlign,
                    LiveSetRef& live, bool forced) {
    const TurnOutcome t = companionTurnCheck(ctx, c, owner.alignment, creatureAlign, forced,
                                             liveSetOf(live), live.groupSlotFree);  // R41.1-2
    if (t == TurnOutcome::RefusedByFoe) {
        return false;  // R41.2: stop
    }
    if (t == TurnOutcome::Joins) {  // R41.3
        joinLiveSet(c, creatureAlign, live);
        c.occupied = false;
        c.released = true;
        return true;
    }
    if (forced) {
        return false;  // UNKNOWN: forced with no group slot: stop, companion stays.
    }
    // R41.4: non-forced and does not turn: slot cleared silently.
    c.occupied = false;
    c.released = true;
    return true;
}

i32 morgueRaiseChance(i32 companionCon) {
    return minv(kMorgueRaiseCap, kMorgueRaiseBase + companionCon);
}

i32 morgueOfferSlot(const Arr<Companion, kCompanionSlots>& slots) {
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        const Companion& c = slots[static_cast<u32>(i)];
        if (c.occupied && c.hits == 0) {
            return i;
        }
    }
    return -1;
}

MorgueRaiseOutcome raiseCompanionAtMorgue(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, Character& owner,
                                          Inventory& ownerInv, Currency cost) {
    const i32 slot = morgueOfferSlot(slots);
    if (slot < 0) {
        return MorgueRaiseOutcome::NoDeadSlot;
    }
    Companion& c = slots[static_cast<u32>(slot)];
    owner.wallet.goldOnHand -= cost;  // R42.1
    const i32 chance = morgueRaiseChance(c.stats[static_cast<u32>(kCompanionConIndex)]);
    const bool failed = ctx.rng.below(100) > chance;  // R42.2
    ownerInv.carryIndex = kCarryNone;                 // R42.3
    owner.carryingCharacterName = Str();              // R42.3
    if (failed) {
        c.occupied = false;  // slot released and left empty
        c.released = true;
        return MorgueRaiseOutcome::Failed;
    }
    c.hits = c.maxHits;
    c.isDead = false;
    c.deathState = CompanionDeathState::Normal;
    return MorgueRaiseOutcome::Raised;
}

void settleLegacyCompanionId(Ctx& ctx, Companion& c, i32 legacyId) {
    (void)ctx;
    c.monsterId = legacyId;
}

void fillUnalignedCompanionAlignment(Companion& c, CharAlign creatureAlign) {
    if (static_cast<i32>(c.alignment) != 0) {
        return;
    }
    c.alignment = static_cast<CompanionAlignment>(static_cast<i32>(creatureAlign) + 1);
}

void putDownCarriedBodyOnLoad(Ctx& ctx, Inventory& inv) {
    (void)ctx;
    if (inv.carryIndex >= kCompanionSlots) {
        inv.carryIndex = kCarryNone;
    }
}

i32 firstCompanionHole(const Arr<Companion, kCompanionSlots>& slots) {
    for (i32 i = 0; i < kCompanionSlots; ++i) {
        if (!slots[static_cast<u32>(i)].occupied) {
            return i;
        }
    }
    return -1;
}

Str keepSlotName(const Companion& previousOccupant) {
    return previousOccupant.name;
}

i32 placeNewCompanion(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, Companion incoming) {
    (void)ctx;
    const i32 hole = firstCompanionHole(slots);
    if (hole < 0) {
        return -1;
    }
    Str name = keepSlotName(slots[static_cast<u32>(hole)]);
    if (name.empty()) {
        // UNKNOWN: SRD text not supplied; a blank name falls back to the
        // reference default "Companion #<slot number>" (1-based).
        name = "Companion #" + std::to_string(hole + 1);
    }
    incoming.name = name;
    incoming.slot = hole;
    incoming.occupied = true;
    incoming.released = false;
    slots[static_cast<u32>(hole)] = incoming;
    return hole;
}

DragSwapOutcome dragSwapCompanions(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, i32 fromSlot, i32 toSlot) {
    // UNKNOWN: SRD refusal text refers to dead companions only; empty slots are not dead.
    // Assumes Companion has a `present` flag (true = occupied). Verify against the struct.
    if (fromSlot < 0 || fromSlot >= kCompanionSlots || toSlot < 0 || toSlot >= kCompanionSlots) {
        return DragSwapOutcome::RefusedDead;
    }
    const Companion& a = slots[static_cast<u32>(fromSlot)];
    const Companion& b = slots[static_cast<u32>(toSlot)];
    const bool aDead = a.present && isDeadCompanion(a);
    const bool bDead = b.present && isDeadCompanion(b);
    if (aDead || bDead) {
        ctx.say("companion.dragDead", "No use re-arranging a dead companion!", {}, {});
        return DragSwapOutcome::RefusedDead;
    }
    if (fromSlot == toSlot) {
        return DragSwapOutcome::Swapped;
    }
    Companion tmp = slots[static_cast<u32>(fromSlot)];
    slots[static_cast<u32>(fromSlot)] = slots[static_cast<u32>(toSlot)];
    slots[static_cast<u32>(toSlot)] = tmp;
    slots[static_cast<u32>(fromSlot)].slot = fromSlot;
    slots[static_cast<u32>(toSlot)].slot = toSlot;
    return DragSwapOutcome::Swapped;
}

bool monsterMayJoin(CharAlign monsterAlign, Align charAlign) {
    switch (monsterAlign) {
        case CharAlign::Good:
            return charAlign == Align::Good;
        case CharAlign::Neutral:
            return true;
        case CharAlign::Evil:
            return false;
    }
    return false;
}

bool monsterHostileToCharacter(Ctx& ctx, CharAlign monsterAlign, Align charAlign) {
    switch (monsterAlign) {
        case CharAlign::Good:
            return charAlign != Align::Good;
        case CharAlign::Neutral:
            return ctx.rng.percent(kNeutralMonsterHostilePercent);
        case CharAlign::Evil:
            return true;
    }
    return true;
}

bool charmCreatureAsCompanion(Ctx& ctx, Arr<Companion, kCompanionSlots>& slots, const Character& caster,
                              i32 monsterId) {
    (void)caster;
    if (firstCompanionHole(slots) < 0) {
        ctx.say("companion.noRoom", "There is no room for another companion.", {}, {});
        return false;
    }
    Companion incoming;
    incoming.monsterId = monsterId;
    incoming.joinedFreely = false;
    const i32 slot = placeNewCompanion(ctx, slots, incoming);
    if (slot < 0) {
        return false;
    }
    ctx.say("companion.charmed", "Your companion is charmed.", {static_cast<i64>(slot)}, {});
    return true;
}

bool bindSpellMeetsRequirements(const Character& c, BindSpell spell) {
    const i32 s = static_cast<i32>(spell);
    const Arr<i32, kStatCount>& st = c.abilities.stats;
    return st[static_cast<u32>(StatIndex::Int)] >= kBindReqInt[s] &&
           st[static_cast<u32>(StatIndex::Wis)] >= kBindReqWis[s] &&
           st[static_cast<u32>(StatIndex::Con)] >= kBindReqCon[s] &&
           st[static_cast<u32>(StatIndex::Cha)] >= kBindReqCha[s];
}

bool bindSpellApplies(const Companion& c) {
    return !c.joinedFreely;
}

void castBindSpell(Ctx& ctx, Companion& target, BindSpell spell) {
    if (!bindSpellApplies(target)) {
        ctx.say("companion.bindNoEffect", "It has no effect.", {}, {});
        return;
    }
    switch (spell) {
        case BindSpell::Control:
            target.bindingLevel = target.bindingLevel + kControlBaseLevel;
            break;
        case BindSpell::Bind:
            target.bindingLevel = maxv(target.bindingLevel, kBindBaseLevel);
            break;
        case BindSpell::Domination:
            target.bindingLevel = maxv(target.bindingLevel, kDominationBaseLevel);
            break;
    }
    target.bindingLevel = minv(target.bindingLevel, kBindingMax);
    ctx.say("companion.bindLevel", "Bind level changed.", {static_cast<i64>(target.bindingLevel)}, {});
}

void controlDragonFailure(Ctx& ctx, Creature& target) {
    target.hostile = true;
    ctx.say("companion.controlFailed", "The dragon resists your control.", {}, {});
}

void dominateDemonBind(Ctx& ctx, Companion& demon) {
    demon.bound = true;
    demon.bindingLevel = maxv(demon.bindingLevel, kDominationBaseLevel);
    ctx.say("companion.demonBound", "The demon is bound to you.", {static_cast<i64>(demon.bindingLevel)}, {});
}

void fillFromCreature(Companion& slot, const Creature& front, i32 binding) {
    slot.occupied = true;
    slot.ref = front.ref;
    slot.monsterId = front.id;
    slot.name = front.knownAs;
    slot.alignment = itemAlignOf(static_cast<Align>(static_cast<i32>(front.align)));
    slot.bindingLevel = binding;
    slot.bound = binding > 0;                 // R7: positive = bound
    slot.forLife = (binding == kBindingMax);  // R7: 100 = ForLife
    slot.hits = front.hits;                   // CONFLICT-free: engine c7 uses front monster's hits
    slot.maxHits = front.maxHits;
    slot.guildLevel = front.guildLevel;
    slot.specialPropertyFlags = front.specialPropertyFlags;
    slot.isDead = false;
    slot.deathState = CompanionDeathState::Normal;
    slot.pendingRaise = false;
    slot.released = false;
    slot.present = true;
}

f64 bindingCostRaw(i32 monsterGuildLevel, i32 currentBinding) {
    i32 a = currentBinding < 0 ? -currentBinding : currentBinding;
    i32 f = bindingCostFactor(a);
    return static_cast<f64>(monsterGuildLevel) * static_cast<f64>(kBindingCostUnit) *
           static_cast<f64>(f) * static_cast<f64>(a) / 4.0;
}

Currency bindingCharge(i32 monsterGuildLevel, i32 currentBinding) {
    return roundHalfEven(bindingCostRaw(monsterGuildLevel, currentBinding));
}

bool joinOfferRoll(Ctx& ctx, i32 cha, i32 levelFound) {
    i32 bar = joinBar(cha, levelFound);
    i64 t = ctx.rng.range(1, 3000);
    return t <= static_cast<i64>(bar);
}

bool groupMayOffer(const MonsterGroup& group, Align viewer) {
    return monsterJoinsCharacter(group.front.align, viewer);
}

bool monsterJoinsCharacter(CharAlign monsterAlign, Align charAlign) {
    if (monsterAlign == CharAlign::Neutral) {
        return true;
    }
    return static_cast<i32>(monsterAlign) == static_cast<i32>(charAlign);
}

void acceptJoin(Ctx& ctx, const Creature& front, Companion& slot, i32 ownerIndex) {
    fillFromCreature(slot, front, joinerBinding());
    slot.owner = ownerIndex;
    slot.joinedFreely = true;
    ctx.say("companion.join",
            "A monster joins your party.",
            {static_cast<i64>(ownerIndex), static_cast<i64>(slot.bindingLevel)},
            {front.knownAs});
}

Currency companionSalePrice(const Companion& c) {
    return bindingCharge(c.guildLevel, c.bindingLevel);
}

void sellCompanion(Ctx& ctx, Character& seller, Companion& slot) {
    if (!slot.occupied) {
        ctx.say("companion.sell_refused", "There is no companion to sell.", {}, {});
        return;
    }
    Currency price = companionSalePrice(slot);
    Str nm = slot.name;
    seller.wallet.goldOnHand += price;
    slot = Companion{};  // R2: slot returns to empty (Ref = -1)
    ctx.say("companion.sold",
            "Companion sold.",
            {static_cast<i64>(price)},
            {nm});
}

bool buyCompanion(Ctx& ctx, Character& buyer, Companion& slot, const Companion& penEntry, Currency price) {
    if (slot.occupied) {
        ctx.say("companion.buy_refused", "That slot is already taken.", {}, {});
        return false;
    }
    if (penEntry.ref < 0) {
        ctx.say("companion.buy_refused", "That pen entry is empty.", {}, {});
        return false;
    }
    if (penEntry.forLife || penEntry.bindingLevel == kBindingMax) {
        ctx.say("companion.buy_refused", "That companion cannot be bought.", {}, {});
        return false;
    }
    if (buyer.wallet.goldOnHand < price) {
        ctx.say("companion.buy_refused", "Not enough gold.",
                {static_cast<i64>(price)}, {});
        return false;
    }
    i32 bind = boughtBinding(penEntry.level);  // R8
    buyer.wallet.goldOnHand -= price;
    slot = penEntry;
    slot.occupied = true;
    slot.bindingLevel = bind;
    slot.bound = bind > 0;
    slot.forLife = false;
    slot.joinedFreely = false;
    ctx.say("companion.bought",
            "Companion bought.",
            {static_cast<i64>(price), static_cast<i64>(bind)},
            {penEntry.name});
    return true;
}

void bindRenew(Ctx& ctx, Companion& c) {
    if (isForLife(c)) {
        ctx.say("companion.bind_none", "The Bind cannot be renewed.", {}, {c.name});
        return;
    }
    if (c.joinedFreely) {
        ctx.say("companion.bind_none", "The Bind does not hold.", {}, {c.name});
        return;
    }
    if (c.bindingLevel > 0 && c.bindingLevel < kBindingBaseLevel) {
        c.bindingLevel = kBindingBaseLevel;
        c.bound = true;
    }
    ctx.say("companion.bind_renewed",
            "The Bind is renewed.",
            {static_cast<i64>(c.bindingLevel)},
            {c.name});
}

void bindControl(Ctx& ctx, Companion& c, i32 amount) {
    if (amount < 0) {
        amount = 0;
    }
    if (isForLife(c)) {
        ctx.say("companion.bind_none", "The Bind cannot be raised.", {}, {c.name});
        return;
    }
    i32 next = c.bindingLevel + amount;
    if (next > kBindingMax) {
        next = kBindingMax;
    }
    c.bindingLevel = next;
    c.bound = next > 0;
    c.forLife = (next == kBindingMax);
    ctx.say("companion.bind_raised",
            "The Bind is raised.",
            {static_cast<i64>(c.bindingLevel)},
            {c.name});
}

i32 dominationCharmCount(i32 groupCount) {
    if (groupCount <= 0) {
        return 0;
    }
    return groupCount < kDominationTargets ? groupCount : kDominationTargets;
}

bool charmIntoSlot(Ctx& ctx, Character& caster, Companion& slot, const Creature& target) {
    if (slot.occupied) {
        ctx.say("companion.charm_refused", "No free companion slot.", {}, {caster.name});
        return false;
    }
    i32 bind = startingBinding(target.floor);  // R8
    fillFromCreature(slot, target, bind);
    slot.joinedFreely = false;
    ctx.say("companion.charmed",
            "A creature is charmed to your side.",
            {static_cast<i64>(bind)},
            {target.knownAs, caster.name});
    return true;
}

f64 spitShare(i32 livingCount) {
    if (livingCount <= 0) {
        return 0.0;
    }
    f64 n = static_cast<f64>(livingCount);
    return n / (n + 1.0);
}

i32 breathFirePercent(i32 leadGuildLevel, i32 companionGuildLevel) {
    f64 lead = static_cast<f64>(leadGuildLevel);
    f64 comp = static_cast<f64>(companionGuildLevel);
    if (lead > comp * kBreathLeadRatio) {
        return kBreathFireStrong;
    }
    if (lead * kBreathLeadRatio < comp) {
        return kBreathFireWeak;
    }
    return kBreathFireBase;
}

bool breathFireRoll(Ctx& ctx, i32 leadGuildLevel, i32 companionGuildLevel) {
    i32 pct = breathFirePercent(leadGuildLevel, companionGuildLevel);
    i32 roll = static_cast<i32>(ctx.rng.below(100));
    return roll < pct;
}

bool breathSweepContinues(i32 killsSoFar, bool survivorStopsIt) {
    if (survivorStopsIt) {
        return false;
    }
    return killsSoFar < kBreathSweepGiveUpKills;
}

MishapResult rollMishap(Ctx& ctx, const Party& party, i32 ownerIndex, MishapKind kind,
                        i32 guildLevel, i32 bodies) {
    MishapResult r;
    r.chance = mishapChance(kind, guildLevel, bodies);
    f64 roll = ctx.rng.nextDouble() * 100.0;
    if (!(roll < r.chance)) {
        return r;
    }
    // The draw is 1-based (1..partySize); the victim is draw - 1 (0-based). Drawing the owner
    // (draw == owner + 1) means no mishap, as in the reference CompanionMishap.Victim.
    const i32 drawn = mishapVictimIndex(ctx, party.size);
    const i32 victim = drawn - 1;
    if (victim == ownerIndex || victim < 0 || victim >= party.size) {
        return r;
    }
    r.happened = true;
    r.victimIndex = victim;
    return r;
}

i32 mishapVictimIndex(Ctx& ctx, i32 partySize) {
    // The 1-based draw: round_half_even(Rnd * (partySize - 1)) + 1. rollMishap turns it into a
    // 0-based victim (draw - 1) and spares the owner (draw == owner + 1).
    const f64 x = ctx.rng.nextDouble() * static_cast<f64>(partySize - 1);
    return static_cast<i32>(roundHalfEven(x)) + 1;
}

i32 companionCritBonus(u32 specialPropertyFlags) {
    i32 bonus = 0;
    if ((specialPropertyFlags & kSpecialBitCrit10) != 0) {
        bonus += kCritBit10Bonus;
    }
    if ((specialPropertyFlags & kSpecialBitCrit11) != 0) {
        bonus += kCritBit11Bonus;
    }
    return bonus;
}

i32 companionBlowDamageMod(i32 damMod, u32 specialPropertyFlags) {
    return damMod + companionCritBonus(specialPropertyFlags);
}

i32 resistedCompanionDamage(i32 damage, i32 resistPercent) {
    return damage - (damage * (resistPercent / 2)) / 100;
}

f64 companionStoneChance(i32 con, i32 levelFound) {
    i32 m = con > kStoneConFloor ? con : kStoneConFloor;
    f64 c = static_cast<f64>(con);
    f64 v = c * (std::log(static_cast<f64>(m)) / std::log(2.5)) - static_cast<f64>(levelFound);
    if (v > static_cast<f64>(kCompanionStoneCap)) {
        v = static_cast<f64>(kCompanionStoneCap);
    }
    return v;
}

bool companionStoneRoll(Ctx& ctx, i32 con, i32 levelFound) {
    f64 chance = companionStoneChance(con, levelFound);
    f64 roll = ctx.rng.nextDouble() * 100.0;
    return roll < chance;
}

f64 driftContentStep(i32 hits, i32 maxHits) {
    if (maxHits <= 0) {
        return 0.5;
    }
    f64 d = static_cast<f64>(maxHits - hits) / static_cast<f64>(maxHits) * 15.0;
    return d > 0.5 ? d : 0.5;
}

f64 driftBoundStep(i32 guildLevel, i32 topGuildLevel, i32 bindingLevel) {
    f64 gl = static_cast<f64>(guildLevel);
    f64 tl = static_cast<f64>(topGuildLevel);
    f64 half = std::fabs(static_cast<f64>(bindingLevel) / kDriftBoundBindingDivisor);
    f64 v = gl / std::log(kDriftBoundGuildBase) * kDriftBoundGuildScale
          - tl / std::log(kDriftBoundTopBase) * half;
    return v > 1.0 ? v : 1.0;
}

void driftCompanion(Ctx& ctx, Companion& c, i32 topGuildLevel) {
    (void)ctx;  // no randomness in drift
    if (isForLife(c)) {
        return;
    }
    if (c.bindingLevel <= 0) {
        f64 step = driftContentStep(c.hits, c.maxHits);
        i32 move = static_cast<i32>(roundHalfEven(step));
        if (move < 1) {
            move = 1;
        }
        i32 next = c.bindingLevel + move;
        if (next > 0) {
            next = 0;
        }
        c.bindingLevel = next;
    } else {
        f64 step = driftBoundStep(c.guildLevel, topGuildLevel, c.bindingLevel);
        i32 move = static_cast<i32>(roundHalfEven(step));
        if (move < 1) {
            move = 1;
        }
        i32 next = c.bindingLevel - move;
        if (next < 0) {
            next = 0;
        }
        c.bindingLevel = next;
    }
    c.bound = c.bindingLevel > 0;
}

bool companionLeaves(Ctx& ctx, const Companion& c) {
    if (isForLife(c)) {
        return false;
