    // show an offer.
    // UNKNOWN: "multi-group" taken as more than one group with count > 0.
    if (groupIndex != 0) {
        return false;
    }
    i32 groupsPresent = 0;
    for (u32 i = 0; i < static_cast<u32>(kMaxGroups); ++i) {
        if (enc.groups[i].count > 0) {
            ++groupsPresent;
        }
    }
    if (groupsPresent != 1) {
        return false;
