            return IdLevel::All;
        case 1:
            // UNKNOWN: codes 1 and 2 are inferred from "counts down"; the source does not number them.
            return IdLevel::Mostly;
        case 2:
            // UNKNOWN: see above.
            return IdLevel::Partial;
        case 3:
            return IdLevel::Barely;
        default:
            return IdLevel::Unknown;
    }
}

