        const char c = name[i];
        const bool bad = c == '\\' || c == '/' || c == ':' || c == '*' || c == '?' ||
                         c == '"' || c == '<' || c == '>' || c == '|' ||
                         static_cast<unsigned char>(c) < 32;
        out += bad ? '_' : c;
    }
    return out;
}

bool characterNameCollides(const Vec<Str>& existingNames, const Str& candidate) {
