Str escapeModCell(const Str& raw) {
    Str out;
    for (i64 i = 0; i < static_cast<i64>(raw.size()); ++i) {
        const char c = raw[i];
        if (c == '\r' || c == '\n') {
            out += ' ';
        } else if (c == '\\') {
            out += "\\\\";
        } else if (c == '|') {
            out += "\\|";
        } else if (c == ';') {
            out += "\\;";
        } else {
            out += c;
        }
    }
    return out;
}

Str encodeModRows(const Vec<Vec<Str>>& rows) {
    Str out;
    for (std::size_t r = 0; r < rows.size(); ++r) {
        if (r > 0) {
            out += ';';
        }
        const Vec<Str>& row = rows[r];
        for (std::size_t c = 0; c < row.size(); ++c) {
            if (c > 0) {
                out += '|';
            }
            out += escapeModCell(row[c]);
        }
    }
    return out;
}

Vec<Vec<Str>> decodeModRows(const Str& line) {
    Vec<Vec<Str>> rows;
    if (line.empty()) {
        return rows;
    }
    Vec<Str> row;
    Str cell;
    const i64 n = static_cast<i64>(line.size());
    for (i64 i = 0; i < n; ++i) {
        const char c = line[i];
        if (c == '\\' && i + 1 < n) {
            cell += line[i + 1];
            ++i;  // skip the escaped character
        } else if (c == '|') {
            row.push_back(cell);  // end cell
            cell.clear();
        } else if (c == ';') {
            row.push_back(cell);  // end cell
            cell.clear();
            rows.push_back(row);  // end row
            row.clear();
        } else {
            cell += c;
        }
    }
    row.push_back(cell);  // end cell
    rows.push_back(row);  // end row
    return rows;
}

