    if (payer.purse() < fee) {
        ctx.say("death.morgue.not_enough_gold", "Not Enough Gold!", {}, {});
        return MorgueFeeOutcome::NotEnoughGold;
    }
    chargeGold(payer, fee);
    return MorgueFeeOutcome::Charged;
