}

CounterRaiseRefusal counterRaiseRefusal(const Character& body) {
    if (body.deathState == DeathState::Rock) {
        return CounterRaiseRefusal::Rock;
    }
    if (raisePending(body)) {
        return CounterRaiseRefusal::AlreadyPending;
    }
    return CounterRaiseRefusal::None;
}

i32 morgueCounterChance(i32 naturalCon, DeathState cause) {
    (void)cause;
    double v = kMorgueConWeight * (static_cast<double>(naturalCon) / kMorgueConDivisor) +
               static_cast<double>(kMorgueCounterBase);
    return static_cast<i32>(clampChance(roundHalfEven(v)));
}

void initiatePendingRaise(Ctx& ctx, Character& body, const Character& raiser, i32 chance, RaiseKind by) {
    (void)ctx;
    body.raiseChance = chance;
    body.raisedBy = raiser.name;
    if (chance > 0) {
        body.raiseKind = by;
    }
    body.pendingRaise = chance > 0;
    body.location.x = raiser.location.x;
    body.location.y = raiser.location.y;
    body.location.dungeonLevel = raiser.location.dungeonLevel;
    body.location.area = raiser.location.area;
}

bool validRescueCoordinates(i32 x, i32 y, i32 level, i32 partCount) {
    if (partCount != kRescueCoordParts) {
        return false;
    }
    if (x < 1 || y < 1) {
        return false;
    }
    return level >= kRescueLevelMin && level <= kRescueLevelMax;
}

Currency rescueSearchCost(i32 level) {
    if (level < 1) {
        return 0;
    }
    double v = kRescueSearchCostFactor * std::log(static_cast<double>(level) + 1.0) *
               static_cast<double>(level);
    return static_cast<Currency>(v);
}

bool payRescueHire(Party& party, Currency cost) {
    if (party.goldLeaderIndex < 0 || party.goldLeaderIndex >= party.size) {
        return false;
    }
    return chargeGold(party.members[uidx(party.goldLeaderIndex)], cost);
}

bool rescuersReturn(Ctx& ctx, i32 level) {
    double roll = ctx.rng.nextDouble() * 100.0;
    bool returns = roll > static_cast<double>(level * kRescueReturnPercentPerLevel);
    if (!returns) {
        ctx.say("death.rescue.no_return", "The rescuers did not return", {level}, {});
    }
    return returns;
}

bool closeEnough(i32 rescuerX, i32 rescuerY, i32 rescuerLevel,
                 i32 targetX1, i32 targetY1, i32 targetLevel) {
    return rescuerLevel == targetLevel &&
           absDiff(rescuerX, targetX1) < kRescueCloseRange &&
           absDiff(rescuerY, targetY1) < kRescueCloseRange;
}

bool bodyRecoverable(const Character& who) {
    if (who.deathState == DeathState::Rock) {
        return false;
    }
    if (who.isDead()) {
        return true;
    }
    return static_cast<double>(who.vitals.curHits) <=
           static_cast<double>(who.vitals.maxHits) * kRescueRecoverFraction;
}

bool raisePending(const Character& who) {
    return who.raiseChance > 0;
}

void settleRaiseAccept(Character& who, bool succeeded) {
    if (!succeeded) {
        who.raiseKind = RaiseKind::None;
    }
    who.raiseChance = 0;
    who.raisedBy = Str{};
    who.pendingRaise = false;
}

void clearPendingRaise(Character& who) {
    who.raiseChance = 0;
    who.raisedBy = Str{};
    who.pendingRaise = false;
}

AskToJoinRefusal askToJoinRefusal(const Character& body, bool inCombat, bool carryingBody) {
    if (inCombat) {
        return AskToJoinRefusal::InCombat;
    }
    if (carryingBody) {
        return AskToJoinRefusal::Carried;
    }
    if (!raisePending(body)) {
        return AskToJoinRefusal::NoPendingRaise;
    }
    return AskToJoinRefusal::None;
}

AskToJoinResult askToJoin(Ctx& ctx, Character& body, bool inCombat, bool carryingBody,
                          bool inAParty, bool accepted) {
    AskToJoinResult out{};
    AskToJoinRefusal refusal = askToJoinRefusal(body, inCombat, carryingBody);
    if (refusal != AskToJoinRefusal::None) {
        out.outcome = AskToJoinOutcome::Refused;
        out.refusal = refusal;
        return out;
    }
    if (!accepted) {
        out.outcome = AskToJoinOutcome::Declined;
        return out;
    }
    RaiseResult rr = resolveRaise(ctx, body, body.raiseKind, body.raiseChance, false, inAParty);
    out.complicated = rr.complicated;
    out.outcome = rr.raised ? AskToJoinOutcome::Raised : AskToJoinOutcome::Failed;
    return out;
}

void clearRaiseOnRockedUnload(Character& who) {
    if (who.ailments.rocked) {
        clearPendingRaise(who);
    }
}

i32 racialMinimumStub(const Character& ch, i32 statIndex) {
    (void)ch;
    (void)statIndex;
    return kRacialMinimumStub;
}

i32 raiseRefusalFor(const Character& body) {
    // R12.2 / Table 3: RaiseRefusal by cause of death.
    // UNKNOWN: Table 3 is not in the SRD chunk. No refusal is modelled; 0 means none.
    (void)body;
    return 0;
}

i32 raiseFailAgeDays(DeathState state) {
    // R12 AgeDays = 84 if stoned, 124 if rock, else 54.
    if (state == DeathState::Stoned) return kAgeStonedDays;
    if (state == DeathState::Rock) return kAgeRockDays;
    return kAgeOrdinaryDays;
}

i32 raisedCurHits(RaiseKind kind, i32 maxHits) {
    // R12 CurHits = (kind in {22, 23}) ? MaxHits : 1.
    if (kind == RaiseKind::Resurrect || kind == RaiseKind::Morgue) return maxHits;
    return 1;
}

bool raiseRollFails(Ctx& ctx, i32 chance, bool rock) {
    // R12.5: roll = 0 if rock else chance; the raise fails if Next(100) > roll.
    const i32 roll = rock ? 0 : chance;
    const i32 draw = ctx.rng.below(kRaiseRollRange);
    return draw > roll;
}

bool rollRaiseComplication(Ctx& ctx, i32 complicationChance) {
    // R12.6: complication when the roll falls under the complication chance.
    // CONFIRMED-BY-REFERENCE: Raising.cs Complicates: "rng.Next(100) < ComplicationChance(...)" is a
    // strict "<". Rock is tested first by the caller, as in "c.CauseOfDeath == Rules.DeathRock ||".
    const i32 roll = ctx.rng.below(kRaiseRollRange);
    return roll < complicationChance;
}

void applyRaiseComplication(Ctx& ctx, Character& body) {
    (void)ctx;
    // R12.8 step 1: complication count up.
    // UNKNOWN: Character has no complication-count field; this step is omitted.

    // R12.8 step 2: each of the six stats down by 5, but not below the racial minimum.
    for (i32 s = 0; s < kStatCount; ++s) {
        i32& stat = body.abilities.stats[static_cast<u32>(s)];
        const i32 floor = racialMinimumStub(body, s);
        const i32 lowered = stat - kComplicationStatLoss;
        if (lowered >= floor) {
            stat = lowered;
        } else if (stat > floor) {
            stat = floor;
        }
    }

    // R12.8 step 3: age +5475 days (15 years).
    body.ageDays += kComplicationAgeDays;

    // R12.8 step 4: MaxHits = int(MaxHits / 1.2), minimum 1.
    i32 newMax = static_cast<i32>(static_cast<double>(body.vitals.maxHits) / kComplicationDivisor);
    if (newMax < kComplicationMinMaxHits) newMax = kComplicationMinMaxHits;
    body.vitals.maxHits = newMax;

    // R12.8 step 5: CurHits = the new MaxHits.
    body.vitals.curHits = newMax;

    // R12.8 step 6: equipped items whose stat requirements now fail are unequipped.
    // UNKNOWN: ItemDef stat-requirement fields are not given; this step is omitted.
}

void applyRaiseSuccess(Ctx& ctx, Character& body) {
    (void)ctx;
    // R12.9: age added (Table 4). CONFIRMED-BY-REFERENCE: Raising.cs Resolve charges
    // AgeDaysFor(CauseOfDeath): AgeDaysStoned, AgeDaysRock or AgeDaysOrdinary. raiseFailAgeDays
    // keys the same mapping on the state before the raise (assumes raiseFailAgeDays has that mapping).
    body.ageDays += raiseFailAgeDays(body.deathState);

    // R12.9: no longer dead or stoned.
    body.deathState = DeathState::Alive;

    // R12.9: cause becomes ordinary.
    // RESOLVED-BY-REFERENCE: Raising.cs Resolve: "c.CauseOfDeath = Rules.DeathOrdinary;". The port
    // has no separate cause field, so the Alive state carries the ordinary cause.

    // R12.9 / Table 2: hits set per kind.
    body.vitals.curHits = raisedCurHits(body.raiseKind, body.vitals.maxHits);
}

void applyStoneConLoss(Character& body) {
    // R12.9 / R12.11 and quirk: stone costs 1 CON on any raise, regardless of outcome.
    // CONFIRMED-BY-REFERENCE: Raising.cs Resolve: "c.Stats[(int)Stat.Con] -= 1;" with no floor.
    body.abilities.stats[static_cast<u32>(StatIndex::Con)] -= kStoneConLoss;
}

void applyMorgueConRoll(Ctx& ctx, Character& body) {
    // R12.9 / R12.11 and quirk: the CON-loss roll applies only to kind 23 (Morgue).
    if (body.raiseKind != RaiseKind::Morgue) return;
    // UNKNOWN: the probability of the morgue CON-loss roll is not in the SRD chunk.
    // Stub: no loss is applied. No RNG is drawn.
    (void)ctx;
    (void)body;
}

void resetConToRacialMinimum(Ctx& ctx, Character& body) {
    // R12.9: own-body raises reset CON to the racial minimum.
    (void)ctx;
    const u32 con = static_cast<u32>(StatIndex::Con);
    body.abilities.stats[con] = racialMinimumStub(body, static_cast<i32>(con));
}

RaiseResult resolveRaise(Ctx& ctx, Character& body) {
    RaiseResult result{};
    // UNKNOWN: RaiseResult fields are not given here (they are defined in death1a.h). The result
    // is returned default-constructed.

    // R12.1: points are spent first. UNKNOWN: the point cost is not in the SRD chunk; the caller
    // is assumed to spend it.

    // R12.2: refusal by cause (Table 3).
    if (raiseRefusalFor(body) != 0) return result;

    const DeathState before = body.deathState;
    const bool rock = before == DeathState::Rock;
    const bool stoned = before == DeathState::Stoned;

    // R12.4: rock zeroes the chance before the offer, so the roll can only fail.
    const i32 chance = rock ? 0 : body.raiseChance;

    // R12.5: roll. The raise fails when the roll is greater than the chance.
    if (!raiseRollFails(ctx, chance, rock)) {
        // R12.9: success effects (state, age, cause, hits), see applyRaiseSuccess.
        ctx.say("raise.success", "Success!", {}, {});
        applyRaiseSuccess(ctx, body);
    } else {
        // Every failure says "Raise Failed!" before the complication roll.
        // RESOLVED-BY-REFERENCE: Raising.cs Resolve: "outcome.Lines.Add("Raise Failed!");" comes
        // before the Complicates test, for every failure including rock.
        ctx.say("raise.failed", "Raise Failed!", {}, {});
        // R12.6: complication roll. Rock always complicates.
        const bool complicated = rock || rollRaiseComplication(ctx, kComplicationChanceStub);
        if (!complicated) {
            // R12.7: a quiet failure ages 54 days whatever the cause and the character stays dead.
            // RESOLVED-BY-REFERENCE: Raising.cs Resolve: "outcome.Lines.Add(c.AgeBy(AgeDaysOrdinary,
            // inAParty)); return outcome;" (still dead). The reference returns here, so no stone
            // CON loss and no morgue roll follow a quiet failure.
            body.ageDays += kAgeOrdinaryDays;
            return result;
        }
        // R12.8: complication effects, in order.
        applyRaiseComplication(ctx, body);
        // R12.9 / R12.10 / R12.11: a complicated raise revives the character (Raising.cs: "c.IsDead
        // = false" follows ApplyComplications with no return), ages per cause, and sets hits.
        // RESOLVED-BY-REFERENCE: Raising.cs Resolve: "if (!Complicates(...)) {...} ApplyComplications(...)"
        // then the common tail: "c.IsDead = false; ... c.CurHits = kind is ByResurrect or ByMorgue ? c.MaxHits : 1;"
        applyRaiseSuccess(ctx, body);
    }

    // R12.9 / R12.11: CON loss for stone, reached only when the raise did not end quietly.
    if (stoned) applyStoneConLoss(body);

    // R12.9 / R12.11: morgue CON-loss roll (kind 23 only).
    applyMorgueConRoll(ctx, body);

    // R12.9: own-body CON reset. UNKNOWN: this 2-argument resolveRaise has no ownBody flag, so
    // the reset is not applied here. The 6-argument resolveRaise in death1a.h handles it.

    // R12.12: a raise does not clear ailments. No ailment is touched.
    return result;
}

i32 spellRaiseTier(RaiseKind effect) {
    // R13: tier = max(1, effect - 19). 20 -> 1, 21 -> 2, 22 -> 3.
    const i32 tier = static_cast<i32>(effect) - 19;
    return tier < 1 ? 1 : tier;
}

i32 spellRaiseChance(i32 naturalCon, RaiseKind effect, bool causeIsRock) {
    // R13: chance = clamp(round_half_even(35 * (CON / 4.5) + tier * 10), 10, 98);
    // if cause == Rock: chance = 10.
    if (causeIsRock) return kRockSpellChance;
    const i32 tier = spellRaiseTier(effect);
    const double raw =
        kSpellChanceConFactor * (static_cast<double>(naturalCon) / kSpellChanceConDivisor) +
        static_cast<double>(tier * kSpellTierMultiplier);
    i64 rounded = roundHalfEven(raw);
    if (rounded < kSpellChanceFloor) rounded = kSpellChanceFloor;
    if (rounded > kRaiseChanceCap) rounded = kRaiseChanceCap;
    return static_cast<i32>(rounded);
}

i32 morgueRaiseChance(i32 naturalCon, bool ownBody) {
    // R14: own body and counter use different constants (CONFLICT 1).
    // UNKNOWN: the formula shape is not given. Assumed chance = CON + bonus, clamped to 1..98;
    // the lower bound of 1 is the documented quirk (tier lifted to 1).
    const i32 bonus = ownBody ? kMorgueOwnBonus : kMorgueCounterBonus;
    i32 chance = naturalCon + bonus;
    if (chance > kRaiseChanceCap) chance = kRaiseChanceCap;
    if (chance < kMorgueChanceFloor) chance = kMorgueChanceFloor;
    return chance;
}

Currency morgueFeeCounter(i32 maxHits) {
    // R15 counter: cost = round_half_even(2912.32 * (MaxHits / 1.5)).
    // UNKNOWN: the fee is read as whole gold and stored in 1/10000 gold.
    const double raw = kMorgueFeeFactor * (static_cast<double>(maxHits) / kMorgueFeeDivisor);
    return roundHalfEven(raw) * kGoldToCurrency;
}

Currency morgueFeeOwnBody(i32 maxHits) {
    // R15 own-body offer: cost = Int(2912.32 * (MaxHits / 1.5)). Int is floor (vbInt).
    const double raw = kMorgueFeeFactor * (static_cast<double>(maxHits) / kMorgueFeeDivisor);
    return vbInt(raw) * kGoldToCurrency;
}

bool morgueGuildPays(const Character& ch, Currency cost) {
    // R15: lowLevel = TopGuildLevel <= 5; guildPays = lowLevel && Purse < cost.
    // Purse is taken as Character::purse() (on hand plus bank).
    const bool lowLevel = ch.topGuildLevel <= kGuildPaysMaxLevel;
    return lowLevel && ch.purse() < cost;
}

bool companionRaiseRefused(const Party& party) {
    // R16.1: refused if the caster is carrying a character.
    // UNKNOWN: "carrying a character" is mapped to CarryingSlot::DeadCharacter.
    return party.carryingSlot == CarryingSlot::DeadCharacter;
}

Vec<i32> companionRaiseCandidates(const Party& party, const Vec<Companion>& companions,
                                  i32 casterSlot, i32 area) {
    // R16.2: candidates are dead, not the caster, not already pending a raise, not carried by
    // any party member, on this level and in this area. Companions are listed by slot.
    Vec<i32> out;
    for (std::size_t i = 0; i < companions.size(); ++i) {
        const Companion& c = companions[i];
        const i32 idx = static_cast<i32>(i);
        if (!c.occupied) continue;
        // UNKNOWN: "dead" is taken as isDead, or Hits 0 (the R16.2 listing rule).
        const bool dead = c.isDead || c.hits == 0;
        if (!dead) continue;
        if (c.pendingRaise) continue;
        // Carried by any party member.
        const bool carried =
            c.carry != -1 ||
            (party.carryingSlot == CarryingSlot::Companion && party.carryingCompanion == idx);
        if (carried) continue;
        // UNKNOWN: "not the caster" compares the companion slot with casterSlot.
        if (c.slot == casterSlot) continue;
        if (c.dungeonLevel != party.dungeonLevel) continue;
        if (c.area != area) continue;
        out.push_back(c.slot);
    }
    return out;
}

void putDownCarriedCompanion(Party& party) {
    // R16.4: the carried companion is put down, silently, either way.
    if (party.carryingSlot == CarryingSlot::Companion) {
        party.carryingSlot = CarryingSlot::None;
        party.carryingCompanion = -1;
    }
}

i32 companionRaiseCon(const GameData& data, const Companion& comp) {
    // R16.3: con = MonsterOf(comp).Stats[3] ?? 10.
    // UNKNOWN: MonsterDef stat field names are not given. The companion's own stats[3] (CON) is
    // used when the monster exists; the fallback 10 applies when it does not.
    if (comp.monsterId < 0 ||
        static_cast<std::size_t>(comp.monsterId) >= data.monsters.size()) {
        return kCompanionConFallback;
    }
    return comp.stats[static_cast<std::size_t>(static_cast<u32>(StatIndex::Con))];
}

Currency companionMorgueCost(i32 maxHits, i32 floor) {
    // R16.5: cost = round_half_even(MaxHits * 1244.34 * Floor).
    // UNKNOWN: the cost is read as whole gold and stored in 1/10000 gold.
    const double raw = static_cast<double>(maxHits) * kCompanionMorgueFactor *
                       static_cast<double>(floor);
    return roundHalfEven(raw) * kGoldToCurrency;
}

i32 companionMorgueChance(i32 naturalCon) {
    // R16.5: chance = min(98, 75 + CON).
    const i32 raw = kCompanionMorgueBase + naturalCon;
    return raw < kRaiseChanceCap ? raw : kRaiseChanceCap;
}

bool rollMorgueCompanion(Ctx& ctx, i32 naturalCon) {
    // R16.5: fail if Int(Rnd*100) > chance. This function returns true when the raise passes.
    // UNKNOWN: the return sense (true = success) is chosen here. The companion's second check,
    // CompanionRaiseChance, is not part of this function.
    const i32 chance = companionMorgueChance(naturalCon);
    const i32 draw = ctx.rng.below(kRaiseRollRange);
    return !(draw > chance);
}

void killPartyMember(Ctx& ctx, Party& party, Vec<Companion>& companions, i32 slot,
                     DeathState state, bool runCleanup) {
    (void)companions;
    if (slot < 0 || slot >= party.size) return;
    Character& m = party.members[static_cast<std::size_t>(slot)];
    m.deathState = state;
    if (runCleanup) {
        // UNKNOWN: the cleanup run by the original Kill (sub0930) is not described in the SRD
        // chunk. Nothing is done here.
    }
    ctx.say("death.kill", m.name + " has died.", {slot}, {m.name});
}

TeleportRockResult teleportIntoRock(Ctx& ctx, Party& party, Vec<Companion>& companions,
                                    Vec<FloorState>& levels, OffMapStore& offMap,
                                    i32 level, i32 x, i32 y) {
    TeleportRockResult res{};
    const i32 count = static_cast<i32>(levels.size());

    // R17.1: the in-floor test. UNKNOWN: floor extent fields are not in the given state or data
    // headers. Placeholder: level in 1..Count with x, y >= 0.
    // UNKNOWN: writing the rock square to the automap needs the square index for (x, y), which
    // is not given. The square write is therefore omitted.
    const bool onMap = level >= 1 && level <= count && x >= 0 && y >= 0;

    if (level <= 0) {
        // R17.4: level 0 is a separate ordinary death.
        // CONFLICT: the R17 pseudo-code gives every member the rock cause at level 0 too. The
        // header and R17.4 give an ordinary death; that is followed here.
        res.outcome = TeleportRockOutcome::LevelZeroDeath;
        res.area = -1;   // R17.3
    } else if (onMap) {
        res.outcome = TeleportRockOutcome::LandedInRock;
        res.area = 0;    // R17.3
    } else {
        res.outcome = TeleportRockOutcome::BodiesOffMap;
        res.area = 0;    // R17.3
    }

    if (level > 0) {
        // R17.1 / quirk: X, Y and DungeonLevel are kept past the deepest level.
        party.dungeonLevel = level;
        party.x = x;
        party.y = y;
    }
    if (level > 0 && !onMap) {
        // R17.2: bodies stored off the map at (level, x, y).
        offMap.level = level;
        offMap.x = x;
        offMap.y = y;
    }

    // R17.3: every member dies with cause rock (ordinary at level 0, per CONFLICT above).
    const DeathState state = (level <= 0) ? DeathState::Dead : DeathState::Rock;
    for (i32 i = 0; i < party.size; ++i) {
        party.members[static_cast<std::size_t>(i)].location.area = res.area;
        killPartyMember(ctx, party, companions, i, state, true);
    }

    if (level > 0 && !onMap) {
        for (i32 i = 0; i < party.size; ++i) {
            offMap.bodies.push_back(party.members[static_cast<std::size_t>(i)]);
        }
    }
    return res;
}

void fellOutOfTheSky(Ctx& ctx, Party& party, Vec<Companion>& companions) {
    // R17.5: each member dies with DeathOrdinary and a tell box is shown.
    // CONFLICT 30: R17 gives DeathOrdinary cause 0; R18 and R24 give 1. DeathState::Dead
    // (value 1) is used, per kOrdinaryDeathValue.
    for (i32 i = 0; i < party.size; ++i) {
        killPartyMember(ctx, party, companions, i, DeathState::Dead, true);
    }
    ctx.say("death.fall", "You fall out of the sky!", {}, {});
}

OpenerTrapOutcome chestOpenerDeathCheck(Ctx& ctx, Party& party, Vec<Companion>& companions,
                                        SquareState& chest, i32 openerSlot) {
    (void)chest;   // The chest stays untrapped with its gold; it is not changed here.

    // R18: the leader is at 1 or more hits, so the trap rule does not apply.
    if (party.members[static_cast<std::size_t>(kFirstMemberIndex)].vitals.curHits >= 1) {
        return OpenerTrapOutcome::LeaderStanding;
    }

    // R18.1: only the opener in slot 0, and not already dead, is set dead (ordinary).
    OpenerTrapOutcome outcome = OpenerTrapOutcome::NobodyKilled;
    const Character& leader = party.members[static_cast<std::size_t>(kFirstMemberIndex)];
    if (openerSlot == kFirstMemberIndex && !leader.isDead()) {
        // R18.3: Kill with sub0930 false, so no cleanup.
        killPartyMember(ctx, party, companions, openerSlot, DeathState::Dead, false);
        outcome = OpenerTrapOutcome::OpenerKilled;
    }
    // Quirk: the leader is down but no one is set dead. This is the deliberate deviation for
    // a non-slot-0 opener, which avoids the original's hang.

    // R18: ShowChest(); RefreshCombat(); RefreshParty(); SaveChar(). These are presentation
    // and save duties of the caller. The core emits a single event.
    ctx.say("chest.opener_check", "The chest's trap has struck the party.", {}, {});
    return outcome;
}

double oldAgePercent(i32 ageDays, i32 raceLifespanYears) {
    // R19.1: pct = (ageDays / 365) / raceLifespanYears * 100.
    // UNKNOWN: a non-positive lifespan returns 0 (guard).
    if (raceLifespanYears <= 0) return 0.0;
    return (static_cast<double>(ageDays) / kDaysPerYear) /
           static_cast<double>(raceLifespanYears) * 100.0;
}

bool rollOldAgeDeath(Ctx& ctx, double pct) {
    // R19.2: if pct >= 98 and Int(Rnd*100) < 5 + Ln(pct - 98), the character dies.
    // CONFLICT 13: "passes 98%" (rule text) and "pct >= 98" (formula) differ. The formula is
    // followed. The sign of 5 + Ln(...) is negative for pct between 98 and about 98.37, so no
    // clamp is applied.
    if (pct < kOldAgeThresholdPct) return false;
    const double excess = pct - kOldAgeThresholdPct;
    // Documented quirk: Ln(0) at exactly 98% is a runtime error in the original. The port
    // guards it: no roll is drawn and the character does not die.
    if (excess <= 0.0) return false;
    const double threshold = kOldAgeChanceBase + std::log(excess);
    const i32 roll = ctx.rng.below(kRaiseRollRange);
    return static_cast<double>(roll) < threshold;
}

void registerNewCharacter(Ctx& ctx, Vec<Character>& roster, Character& ch,
                          HallOfRecords& hall, i64 day) {
    // R20.1: on successful creation the new character is saved and placed in the roster.
    // UNKNOWN: "saved" is taken to be the Character.saved flag.
    ch.saved = true;
    roster.push_back(ch);
    // R20.1: the guild they were born into logs a join.
    appendGuildLog(ctx, hall, GuildLogKind::Join, ch.activeGuild, day, ch);
    // R20.2: all six natural stats are offered to the Hall of Records.
    offerNaturalStatsToHall(ctx, hall, ch, day);
}

void offerNaturalStatsToHall(Ctx& ctx, HallOfRecords& hall, const Character& ch, i64 day) {
    // R22 code: for i in 0..5: CheckAndLog(Kind(i), ch, ch.Stats[i], alone: true).
    // Kind(i) is taken as category i.
    for (i32 i = 0; i < kStatCount; ++i) {
        const i64 value = static_cast<i64>(ch.abilities.stats[static_cast<u32>(i)]);
        offerHallRecord(ctx, hall, i, ch, value, true, day);
    }
}

bool characterDeletable(const Character& ch, bool saveFileExists) {
    // R20.3: deletable only once its save is gone. Delete Character is the only path;
    // that path is the caller's concern.
    (void)ch;
    return !saveFileExists;
}

bool isKillRecordable(bool groupIdentified, bool monsterInvisible, const Character& killer) {
    // R21.1: recordable only for the killer, and only when the group is identified. An invisible
    // monster also needs the killer to see invisible.
    return groupIdentified && (!monsterInvisible || killer.ailments.seeInvisible);
}

bool recordKill(Ctx& ctx, Character& killer, const Creature& monster,
                bool groupIdentified, bool monsterInvisible) {
    (void)ctx;
    if (!isKillRecordable(groupIdentified, monsterInvisible, killer)) return false;
    killer.kills += 1;
    killer.monsterKills.push_back(monster.id);
    return true;
}

i32 chestFindCredit(i32 leadIndex, i32 foes0KnownAs, i32 leadId,
                    bool leadInvisible, const Character& taker) {
    // R21.2: ChestFindFrom = (leadIndex == foes0KnownAs && !(lead.Invisible &&
    // !taker.SeeingInvisible)) ? lead.Id : -2.
    // UNKNOWN: -2 is the "unknown monster" credit (no further meaning given).
    const bool hidden = leadInvisible && !taker.ailments.seeInvisible;
    return (leadIndex == foes0KnownAs && !hidden) ? leadId : -2;
}

void settleMonsterQuestAtKill(Ctx& ctx, Character& killer, i32 monsterId) {
    // R21.3: a monster quest is settled at the kill, for the current guild only, whether or not
    // the fight is won. The quest message names the character.
    // UNKNOWN: quest target matching (target == monsterId) and the quest count/level handling
    // are not given. Completion sets the state to Done.
    GuildMembership& g = killer.guilds[static_cast<u32>(killer.activeGuild)];
    GuildQuest& q = g.quest;
    if (q.kind != QuestKind::Defeat) return;
    if (q.state != QuestState::Active) return;
    if (q.target != monsterId) return;
    q.state = QuestState::Done;
    g.questDone = true;
    ctx.say("guild.quest_done", killer.name + " has completed a monster quest.", {},
            {killer.name});
}

bool offerHallRecord(Ctx& ctx, HallOfRecords& hall, i32 category, const Character& ch,
                     i64 value, bool alone, i64 day) {
    // R22.3: the Hall file is saved when any offer is made.
    hall.dirty = true;
    // UNKNOWN: the comparison against hall.records[category] needs HallRecord fields, which are
    // not given. No record is taken here, and false is returned. The offer is still logged as
    // dirty.
    (void)ctx;
    (void)category;
    (void)ch;
    (void)value;
    (void)alone;
    (void)day;
    return false;
}

void checkLevelRecords(Ctx& ctx, HallOfRecords& hall, const Character& ch, i64 day) {
    // R22.1: after a level, the Fighting, Magic and Thieving skill records are checked.
    // UNKNOWN: category ids are not given. Guild indices are used: Warrior (Fighting), Mage
    // (Magic) and Thief (Thieving). The value is the guild level; alone is taken as true.
    offerHallRecord(ctx, hall, static_cast<i32>(Guild::Warrior), ch,
                    static_cast<i64>(ch.guilds[static_cast<u32>(Guild::Warrior)].level),
                    true, day);
    offerHallRecord(ctx, hall, static_cast<i32>(Guild::Mage), ch,
                    static_cast<i64>(ch.guilds[static_cast<u32>(Guild::Mage)].level),
                    true, day);
    offerHallRecord(ctx, hall, static_cast<i32>(Guild::Thief), ch,
                    static_cast<i64>(ch.guilds[static_cast<u32>(Guild::Thief)].level),
                    true, day);
}

void checkWealthiestRecord(Ctx& ctx, HallOfRecords& hall, const Character& ch,
                           Currency wealth, i64 day) {
    // R22.2: if pv0104 > M73F5 then M73F5 = pv0104 (exact comparison).
    (void)day;
    if (wealth > hall.wealthiest) {
        hall.wealthiest = wealth;
        hall.dirty = true;   // R22.3
        ctx.say("hall.wealthiest", ch.name + " is the wealthiest adventurer.", {wealth},
                {ch.name});
    }
}

void appendGuildLog(Ctx& ctx, HallOfRecords& hall, GuildLogKind kind, Guild guild,
                    i64 day, const Character& ch) {
    // R22.4 and R20.1: guild log lines for death, resurrection, demotion and join.
    // UNKNOWN: the wording of each line is not given. English text is supplied here.
    Str text = ch.name;
    switch (kind) {
        case GuildLogKind::Death:
            text += " has died.";
            break;
        case GuildLogKind::Resurrection:
            text += " has been raised.";
            break;
        case GuildLogKind::Demotion:
            text += " has been demoted.";
            break;
        case GuildLogKind::Join:
            text += " has joined the guild.";
            break;
    }
    GuildLogLine line{};
    line.guild = guild;
    line.day = day;
    line.text = text;
    hall.log.push_back(line);
    hall.dirty = true;   // R22.3
    ctx.say("guild.log", text, {day}, {ch.name});
}

i64 hallStatField(i64 value) {
    // R22: stored = value * 10000 (the byte-level encoding is the file layer's concern).
    return value * kHallStatMultiplier;
}

i64 hallDateField(i64 daysSince1900) {
    // R22: dateField = daysSince(1900-01-01) + 2.
    return daysSince1900 + kHallDateOffset;
}

SoulCheck retrieveSoulStatus(const Character& ch, i32 currentDungeonLevel) {
    // R23.1: lists only characters dead in rock (DeathState 8), on this level, in area 0.
    // R23.2: typed errors "Character is not on this level!" and "Character is not in ROCK!".
    // CONFLICT: the quirk note says the port offers any dead character. R23 (the original's
    // rule) is followed here.
    if (ch.location.dungeonLevel != currentDungeonLevel) return SoulCheck::NotOnThisLevel;
    if (ch.deathState != DeathState::Rock || ch.location.area != 0) {
        return SoulCheck::NotInRock;
    }
    return SoulCheck::Ok;
}

Vec<Str> splitCoordinateInput(const Str& text) {
    // Morgue input: coordinates split on commas; a trailing comma is ignored.
    Vec<Str> parts;
    Str current;
    for (std::size_t i = 0; i < text.size(); ++i) {
        const char c = text[i];
        if (c == ',') {
            parts.push_back(current);
            current = Str();
        } else {
            current += c;
        }
    }
    const bool endsWithComma = !text.empty() && text[text.size() - 1] == ',';
    if (!endsWithComma) {
        parts.push_back(current);
    }
    return parts;
}

i64 valLikeOriginal(const Str& text) {
    // Morgue input, VB Val: skips spaces, reads an optional sign, digits and an optional
    // fraction, and stops at the first non-numeric character (1-2 -> 1; x -> 0).
    // The result is rounded (3.7 -> 4).
    // UNKNOWN: the rounding mode for Val is not stated. roundHalfEven is used.
    const std::size_t n = text.size();
    std::size_t i = 0;
    double sign = 1.0;
    double value = 0.0;

    while (i < n && text[i] == ' ') ++i;
    if (i < n && text[i] == '-') {
        sign = -1.0;
        ++i;
    } else if (i < n && text[i] == '+') {
        ++i;
    }

    while (i < n) {
        const char c = text[i];
        if (c == ' ') {
            ++i;
            continue;
        }
        if (c >= '0' && c <= '9') {
            value = value * 10.0 + static_cast<double>(c - '0');
            ++i;
        } else {
            break;
        }
    }

    if (i < n && text[i] == '.') {
        ++i;
        double scale = 0.1;
        while (i < n) {
            const char c = text[i];
            if (c == ' ') {
                ++i;
                continue;
            }
            if (c >= '0' && c <= '9') {
                value += static_cast<double>(c - '0') * scale;
                scale *= 0.1;
                ++i;
            } else {
                break;
            }
        }
    }

    return roundHalfEven(sign * value);
}

bool rollComplication(Ctx& ctx, i32 ageDays, i32 raceLifespanYears) {
    // RESOLVED-BY-REFERENCE: Raising.cs ComplicationChance returns 0 when raceLifespanYears <= 0, and
    // Complicates still evaluates rng.Next(100) < chance, so a draw is taken with chance 0 (never true).
    // RESOLVED-BY-REFERENCE: Raising.cs Complicates has no guaranteed branch. At or past half lifespan the
    // chance is >= 100 and the draw is still taken, so the port takes the draw there too.
    // Assumes kComplicationDrawRange == 100, matching the reference's rng.Next(100).
    // Rock (DeathRock) complicates with no draw in the reference (short-circuit `||`); the caller must
    // handle rock before calling this function.
    double chance = 0.0;
    if (raceLifespanYears > 0) {
        // R25 chance% = (Age_days/365)/(RaceMaxAge/2)*100 = 200*age/(365*lifespan), uncapped.
        chance = 200.0 * static_cast<double>(ageDays) /
                 (static_cast<double>(kDaysPerYear) * static_cast<double>(raceLifespanYears));
    }
    const double draw = static_cast<double>(ctx.rng.below(kComplicationDrawRange));
    return draw < chance;
}

i32 conLossChancePercent(i32 naturalCon) {
    const i32 value = kConLossBase - naturalCon * kConLossPerCon;
    return value < 0 ? 0 : value;
}

i32 morgueConLossThreshold(i32 con) {
    return kConLossBase - con * kConLossPerCon;
}

bool rollConLoss(Ctx& ctx, Character& ch, i32 threshold) {
    const i64 draw = static_cast<i64>(ctx.rng.below(kConLossDrawRange));
    if (!(draw < static_cast<i64>(threshold))) {
        return false;
    }
    const u32 con = static_cast<u32>(StatIndex::Con);
    ch.abilities.stats[con] -= kConLossStep;  // CONFLICT 27: 1 CON per loss
    // UNKNOWN: statMax and statMods are not changed here; the event carries no numbers.
    ctx.say("death2a.con_loss", "Constitution was lost in a raise", {}, {});
    return true;
}

bool stoneConLossRoll(Ctx& ctx, Character& ch) {
    const i32 naturalCon = ch.abilities.stats[static_cast<u32>(StatIndex::Con)];
    return rollConLoss(ctx, ch, conLossChancePercent(naturalCon));
}

bool morgueConLossRoll(Ctx& ctx, Character& ch) {
    const i32 naturalCon = ch.abilities.stats[static_cast<u32>(StatIndex::Con)];
    return rollConLoss(ctx, ch, morgueConLossThreshold(naturalCon));
}

i32 raiseAgeDays(DeathState cause) {
    switch (cause) {
        case DeathState::Stoned:
            return kAgeStoned;
        case DeathState::Rock:
            return kAgeRock;
        default:
            return kAgeOther;
    }
}

double oldAgePercent(const Character& ch, i32 raceLifespanYears) {
    if (raceLifespanYears <= 0) {
        return 0.0;  // guard: no lifespan means no old-age check
    }
    const double ageYears = static_cast<double>(ch.ageDays) / kDaysPerYear;
    return 100.0 * ageYears / static_cast<double>(raceLifespanYears);
}

double oldAgeThreshold(double pct) {
    if (!(pct > kOldAgeStartPct)) {
        // Port guard: Ln(0) at exactly 98% is a runtime error in the original.
        return 0.0;
    }
    return kOldAgeBaseChance + std::log(pct - kOldAgeStartPct);
}

bool oldAgeCheckApplies(const Character& ch, i32 raceLifespanYears, bool inDungeon) {
    if (!inDungeon) {
        return false;
    }
    return oldAgePercent(ch, raceLifespanYears) > kOldAgeStartPct;
}

bool rollOldAgeDeath(Ctx& ctx, Character& ch, i32 raceLifespanYears, bool inDungeon) {
    if (!oldAgeCheckApplies(ch, raceLifespanYears, inDungeon)) {
        return false;
    }
    const double pct = oldAgePercent(ch, raceLifespanYears);
    const double threshold = oldAgeThreshold(pct);
    if (!ctx.rng.percent(threshold)) {
        return false;
    }
    // Ordinary death: DeathState::Dead (Table 1, value 0 in this port).
    ch.deathState = DeathState::Dead;
    // UNKNOWN: whether ch.deaths is incremented here or by the caller. The SRD does not say.
    // "Still [is] not a permanent one" (archive quirk): raising is handled elsewhere.
    ctx.say("death.oldAge", "A character has died of old age in the dungeon.", {}, {ch.name});
    return true;
}

i32 partyCopyIndexOf(const Party& party, const Character& picked) {
    i32 n = party.size;
    if (n > kPartyMaxSize) {
        n = kPartyMaxSize;
    }
    if (n < 0) {
        n = 0;
    }
    for (i32 i = 0; i < n; ++i) {
        if (&party.members[static_cast<u32>(i)] == &picked) {
            return i;
        }
    }
    for (i32 i = 0; i < n; ++i) {
        if (party.members[static_cast<u32>(i)].name == picked.name) {
            return i;
        }
    }
    return -1;
}

static i32 naturalCon(const Character& ch) {
    return ch.abilities.stats[static_cast<u32>(StatIndex::Con)];
}

i32 morgueOwnBodyChance(const Character& ch) {
    return clampRaiseChance(naturalCon(ch) + kMorgueOwnBodyBonus);
}

i32 morgueCounterChance(const Character& ch) {
    return clampRaiseChance(morgueCounterChance(naturalCon(ch), ch.deathState));
}

i32 morgueChance(const Character& ch, MorgueRoute route) {
    switch (route) {
        case MorgueRoute::OwnBody:
            return morgueOwnBodyChance(ch);
        case MorgueRoute::Counter:
            return morgueCounterChance(ch);
    }
    return 0;
}

i32 clampRaiseChance(i32 raw) {
    return clampv(raw, kLocalRaiseChanceMin, kLocalRaiseChanceMax);
}

i32 spellRaiseChance(const Character& ch, RaiseKind kind) {
    return spellRaiseChance(naturalCon(ch), kind, ch.deathState == DeathState::Rock);
}

double oldAgeTerm(i32 pct) {
    if (!isOldAgePct(pct)) {
        return 0.0;
    }
    return kOldAgeBase + std::log(static_cast<double>(pct - kOldAgePct));
}

bool isOldAgePct(i32 pct) {
    return pct >= kOldAgePct;
}

RevivalPayment quoteRevival(const Character& ch) {
    RevivalPayment p;
    p.fee = revivalFee(ch);
    p.guildPays = guildPaysRevival(ch, p.fee);
    // Level 5 or under: no question asked (paid by guild or from purse). Above 5: asks payer.
    p.asksPayer = ch.topGuildLevel > kGuildPaysMaxLevel;
    return p;
}

Currency revivalFee(const Character& ch) {
    const double hitsDiv = static_cast<double>(ch.vitals.maxHits) / kRevivalFeeHitDivisor;
    const i64 gold = vbInt(kRevivalFeeFactor * hitsDiv);
    return currencyFromWhole(gold);
}

bool guildPaysRevival(const Character& ch, Currency fee) {
    return ch.topGuildLevel <= kGuildPaysMaxLevel && ch.purse() < fee;
}

MorgueRefusal morgueRefusal(const Character& body) {
    if (body.deathState == DeathState::Rock) {
        return MorgueRefusal::RockCannotHelp;
    }
    const i32 lvl = body.activeLevel();
    if (lvl < kMorgueMinLevel) {
        return MorgueRefusal::LevelTooLow;
    }
    if (lvl > kMorgueMaxLevel) {
        return MorgueRefusal::LevelTooHigh;
    }
    return MorgueRefusal::None;
}

bool complicationGuaranteed(i32 age, i32 raceMaxAge) {
    return age >= raceMaxAge / 2;
}

i32 complicatedMaxHits(i32 maxHits) {
    return static_cast<i32>(vbInt(static_cast<double>(maxHits) / kComplicationHitDivisor));
}

i32 raiseAgeCost(DeathState cause) {
    if (cause == DeathState::Stoned) {
        return kAgeStoned;
    }
    if (cause == DeathState::Rock) {
        return kAgeRock;
    }
    return kAgeQuietFailure;
}

bool livingRecoversAtMorgue(const Character& ch) {
    if (ch.isDead()) {
        return false;
    }
    return static_cast<double>(ch.vitals.curHits) <=
           kLivingRecoverFraction * static_cast<double>(ch.vitals.maxHits);
}

bool isPruneCandidate(const Character& ch) {
    return ch.isDead() && ch.vitals.curHits <= 0;
}

bool cityRestApplies(const Character& ch) {
    return !ch.isDead();
}

void demoteGuildLevel(Ctx& ctx, Character& ch, Guild guild) {
    GuildMembership& g = ch.guilds[static_cast<u32>(guild)];
    if (g.level <= 0) {
        return;
    }
    g.level -= 1;
    ctx.say("death.guild.demoted", "Guild level reduced by one.", {g.level}, {});
}

PlayerRaiseResult raiseCharacter(Ctx& ctx, Character& ch, RaiseKind kind, i32 chance) {
    PlayerRaiseResult res;

    // Refusals, checked before any roll.
    if (kind == RaiseKind::None) {
        res.outcome = RaiseAttemptOutcome::Refused;
        ctx.say("death.raise.refused", "No raise was offered.", {}, {});
        return res;
    }
    if (kind == RaiseKind::Morgue && morgueRefusal(ch) != MorgueRefusal::None) {
        res.outcome = RaiseAttemptOutcome::Refused;
        ctx.say("death.raise.refused", "The morgue cannot help.", {}, {});
        return res;
    }
    // Rock is lifted only by Resurrect (note 22, engine c19).
    if (ch.deathState == DeathState::Rock && kind != RaiseKind::Resurrect) {
        res.outcome = RaiseAttemptOutcome::Refused;
        ctx.say("death.raise.refused", "Only Resurrect lifts rock.", {}, {});
        return res;
    }
    // Stone accepts Restore Flesh; morgue also passes (note 9, UNKNOWN whether intended).
    if (ch.deathState == DeathState::Stoned && kind != RaiseKind::RestoreFlesh &&
        kind != RaiseKind::Morgue) {
        res.outcome = RaiseAttemptOutcome::Refused;
        ctx.say("death.raise.refused", "Stone accepts only Restore Flesh.", {}, {});
        return res;
    }

    const DeathState cause = ch.deathState;

    // Stone costs 1 CON on any raise, regardless of outcome (engine c17, note 27).
    if (cause == DeathState::Stoned) {
        ch.abilities.stats[static_cast<u32>(StatIndex::Con)] -= kStoneConLoss;
        res.conLost = kStoneConLoss;
    }

    // RESOLVED-BY-REFERENCE: Raising.cs:110 `if (c.CauseOfDeath == Rules.DeathRock) roll = 0;`
    // Being pulled into rock zeroes the chance before the roll.
    const i32 effChance = (cause == DeathState::Rock) ? 0 : chance;
    res.chanceUsed = effChance;

    // Roll against the chance.
    if (ctx.rng.percent(effChance)) {
        res.outcome = RaiseAttemptOutcome::Success;
        res.ageAdded = 0;
        ch.deathState = DeathState::Alive;
        // Raise Dead and Restore Flesh give one hit; Resurrect and the morgue give all of them.
        // REFERENCE: Raising.cs:110 `c.CurHits = kind is ByResurrect or ByMorgue ? c.MaxHits : 1;`
        ch.vitals.curHits = (kind == RaiseKind::Resurrect || kind == RaiseKind::Morgue)
                                ? ch.vitals.maxHits
                                : 1;
        ch.pendingRaise = false;
        ch.raiseKind = RaiseKind::None;
        ctx.say("death.raise.success", "The character is raised.", {}, {});
        return res;
    }

    // Failure. RESOLVED-BY-REFERENCE: Raising.cs:38 and Raising.cs:110 (Complicates).
    // Rock always complicates and draws no roll; otherwise the complication roll is
    // Int(Rnd*100) < (ageDays/365)/(raceLifespan/2)*100. Rock is checked first, as in the reference.
    // The old-age guarantee is the case where that chance reaches 100.
    const double complicationPct =
        (kDefaultRaceMaxAge > 0)
            ? (static_cast<double>(ch.ageDays) / 365.0) /
                  (static_cast<double>(kDefaultRaceMaxAge) / 2.0) * 100.0
            : 0.0;
    const bool complicates =
        (cause == DeathState::Rock) ||
        (static_cast<double>(ctx.rng.below(100)) < complicationPct);

    if (complicates) {
        res.outcome = RaiseAttemptOutcome::Complicated;
        // Age added on a complicated failure is the cause-based value (CONFIRMED by Raising.cs:110,
        // AgeBy(AgeDaysFor(CauseOfDeath)) runs on every path that is not own-body).
        res.ageAdded = raiseAgeCost(cause);
        ch.ageDays += res.ageAdded;
        ch.deathState = DeathState::Alive;
        ch.vitals.maxHits = complicatedMaxHits(ch.vitals.maxHits);
        // Hits after a complicated raise follow the same kind rule as success (Raising.cs:110).
        ch.vitals.curHits = (kind == RaiseKind::Resurrect || kind == RaiseKind::Morgue)
                                ? ch.vitals.maxHits
                                : 1;
        ch.pendingRaise = false;
        ch.raiseKind = RaiseKind::None;
        ctx.say("death.raise.complicated", "The raise is complicated.",
                {static_cast<i64>(res.ageAdded), static_cast<i64>(ch.vitals.maxHits)}, {});
        return res;
    }

    // Quiet failure: stays dead, age 54 (engine c17, note 5).
    // REFERENCE: Raising.cs:110 `outcome.Lines.Add(c.AgeBy(AgeDaysOrdinary, ...)); return outcome;`
    // The quiet failure returns before any morgue Constitution roll.
    res.outcome = RaiseAttemptOutcome::QuietFailure;
    res.ageAdded = kAgeQuietFailure;
    ch.ageDays += res.ageAdded;
    res.conRollMade = false;
    ctx.say("death.raise.failed", "The raise fails.",
            {static_cast<i64>(res.ageAdded)}, {});
    return res;
}

Currency hallWealthiestRecord(Currency bank) {
    return currencyFromWhole(currencyWhole(bank));
}

i32 mapHeight(const FloorDef& def) {
    // Height = total fields / this floor's own width (not the global kMapWidth).
    // Guard against a zero width so the function stays total.
    if (def.width <= 0) {
        return 0;
    }
    return static_cast<i32>(def.fields.size()) / def.width;
}

i32 stateHeight(const FloorState& floor) {
    return static_cast<i32>(floor.squares.size()) / kMapWidth;
}

bool inMap(i32 x, i32 y, i32 height) {
    return x >= 1 && x <= kMapWidth && y >= 1 && y <= height;
}

bool cellInState(const FloorState& floor, i32 x, i32 y) {
    return inMap(x, y, stateHeight(floor));
}

i32 cellOf(i32 x, i32 y) {
    return mapSquareIndex(x, y) - 1;
}

SquareState& sqAt(FloorState& floor, i32 x, i32 y) {
    return floor.squares[static_cast<std::size_t>(cellOf(x, y))];
}

const SquareState& sqAt(const FloorState& floor, i32 x, i32 y) {
    return floor.squares[static_cast<std::size_t>(cellOf(x, y))];
}

EdgeRef edgeRefOf(i32 x, i32 y, Facing f) {
    switch (f) {
        case Facing::N: return {x, y, kBitWallNorth, kBitDoorNorth, kBitSecretNorth};
        case Facing::E: return {x, y, kBitWallEast, kBitDoorEast, kBitSecretEast};
        case Facing::S: return {x, y - 1, kBitWallNorth, kBitDoorNorth, kBitSecretNorth};
        case Facing::W: return {x - 1, y, kBitWallEast, kBitDoorEast, kBitSecretEast};
    }
    return {x, y, 0, 0, 0};
}

i32 senseAbilityValue(const Party& party) {
    const Character& leader = party.leader();
    return leader.abilities.stats[kDungeonSenseAbility] +
           leader.abilities.statMods[kDungeonSenseAbility];
}

i32 raceSizeOf(const Ctx& ctx, const Character& c) {
    i32 idx = static_cast<i32>(c.race);
    if (idx < 0 || idx >= static_cast<i32>(ctx.data.races.size())) return 0;
    return ctx.data.races[static_cast<std::size_t>(idx)].size;
}

Facing turnRightOf(Facing f) {
    return static_cast<Facing>((static_cast<i32>(f) + 1) & 3);  // R1 TurnRight (f+1)&3
}

Facing turnLeftOf(Facing f) {
    return static_cast<Facing>((static_cast<i32>(f) + 3) & 3);  // R1 TurnLeft (f+3)&3
}

Facing turnAroundOf(Facing f) {
    return static_cast<Facing>((static_cast<i32>(f) + 2) & 3);  // R2 Opposite (f+2)&3
}

void facingDelta(Facing f, i32& dx, i32& dy) {
    switch (f) {  // R1 Delta: N(0,+1) E(+1,0) S(0,-1) W(-1,0)
        case Facing::N: dx = 0; dy = 1; break;
        case Facing::E: dx = 1; dy = 0; break;
        case Facing::S: dx = 0; dy = -1; break;
        case Facing::W: dx = -1; dy = 0; break;
    }
}

void applyMoveKey(Ctx& ctx, Party& party, FloorState& floor, const FloorDef& def, MoveKey key, bool shift) {
    // R3: paralysis stops both the turn and the step.
    if (party.members[0].ailments.paralysed) return;
    switch (key) {
        case MoveKey::Up:  // R2 Up steps forward
            tryMoveForward(ctx, party, floor, def);
            return;
        case MoveKey::Down:  // R2 Down turns around
            party.facing = turnAroundOf(party.facing);
            break;
        case MoveKey::Left:  // R2 Left turns left
            party.facing = turnLeftOf(party.facing);
            break;
        case MoveKey::Right:  // R2 Right turns right
            party.facing = turnRightOf(party.facing);
            break;
    }
    // R3: shift with a turn is followed by one forward step (fn1521, False).
    if (shift) tryMoveForward(ctx, party, floor, def);
    // UNKNOWN: AfterMove square effects (R33) are run by the caller through runSquareEffects,
    // because they need the leader's ability-5 chance.
}

bool tryMoveForward(Ctx& ctx, Party& party, FloorState& floor, const FloorDef& def) {
    i32 x = party.x;
    i32 y = party.y;
    Facing f = party.facing;
    i32 dx = 0;
    i32 dy = 0;
    facingDelta(f, dx, dy);
    i32 tx = x + dx;
    i32 ty = y + dy;

    // R7: a step off the map is clamped with OUCH and records nothing.
    if (stepLeavesMap(def, x, y, f)) {
        reportWallHit(ctx);
        return false;
    }
    // R5 / R1: the target edge is classified. A Wall refuses the move.
    EdgeClass edge = classifyEdge(floor, x, y, f);
    if (edge == EdgeClass::Wall) {
        // R8 / R18: a wall bump in fog records the wall on the bumped edge.
        if (squareIsFogged(floor, x, y)) recordFogWallBump(ctx, floor, x, y, f);
        reportWallHit(ctx);  // R6
        return false;
    }
    // R5: target rock refuses the move.
    if (!canMoveFacing(floor, def, x, y, f)) {
        reportWallHit(ctx);  // R6
        return false;
    }
    // R20: lost handling on arrival. Runs before the new square is marked, so the mapped check
    // sees the pre-step automap state.
    arrivalLostCheck(ctx, party, floor, tx, ty);
    // R17: passing through a door records the door bit and clears the wall bit.
    if (edge == EdgeClass::Door || edge == EdgeClass::SecretDoor) {
        recordDoorPassage(ctx, floor, x, y, f);
    }
    // R10: placement sets position with no rock check. Marks explored if not rock (R15 gated).
    setPartyPosition(ctx, party, floor, tx, ty);
    // R11-R15: entry recording. A fresh guard is used because Party has no guard field.
    MapRecordGuard guard{};
    recordArrival(ctx, party, floor, def, guard, tx, ty);
    // R16: secret doors roll on entry.
    rollSecretDoorsOnEntry(ctx, floor, tx, ty, senseAbilityValue(party));
    // R4: the party shares the leader's lost flags.
    shareLeaderLostFlags(ctx, party);
    return true;
}

void reportWallHit(Ctx& ctx) {
    ctx.say("move.ouch", "", {}, {Str("OUCH")});  // R6: plays OUCH with no text
}

void shareLeaderLostFlags(Ctx& ctx, Party& party) {
    (void)ctx;
    // R4: the party shares the leader's lost flags.
    for (i32 i = 1; i < party.size; ++i) {
        party.members[i].lost = party.members[0].lost;
    }
    // Party-level mirror flags follow the leader.
    const LostState& L = party.members[0].lost;
    party.lostLevel = L.level;
    party.lostPosition = L.position;
    party.lostFacing = L.facing;
    party.lost = party.members[0].isLost();
}

bool squareIsRock(const FloorState& floor, i32 x, i32 y) {
    // R1/R10 rock flag.
    // UNKNOWN: the rock flag is read from the live SquareState::bits copy here. canMoveFacing
    // reads the static FloorDef flags instead.
    return cellInState(floor, x, y) && (sqAt(floor, x, y).bits & kBitRock) != 0;
}

bool squareIsFogged(const FloorState& floor, i32 x, i32 y) {
    // R11 fog read from the square.
    return cellInState(floor, x, y) && (sqAt(floor, x, y).bits & kBitFog) != 0;
}

EdgeClass classifyEdge(const FloorState& floor, i32 x, i32 y, Facing f) {
    // R1 Classify: wall -> Wall; else door -> Door; else secret -> SecretDoor; else Open.
    EdgeRef e = edgeRefOf(x, y, f);
    if (!cellInState(floor, e.cx, e.cy)) return EdgeClass::Wall;  // R7: off the map counts as a wall
    u32 b = sqAt(floor, e.cx, e.cy).bits;
    if (b & e.wall) return EdgeClass::Wall;
    if (b & e.door) return EdgeClass::Door;
    if (b & e.secret) return EdgeClass::SecretDoor;
    return EdgeClass::Open;
}

bool canMoveFacing(const FloorState& floor, const FloorDef& def, i32 x, i32 y, Facing f) {
    // R5 CanMove: edge != Wall and not rock at target.
    if (stepLeavesMap(def, x, y, f)) return false;  // R7
    if (classifyEdge(floor, x, y, f) == EdgeClass::Wall) return false;
    i32 dx = 0;
    i32 dy = 0;
    facingDelta(f, dx, dy);
    if (fieldFlagsAt(def, mapSquareIndex(x + dx, y + dy)) & kBitRock) return false;
    return true;
}

bool stepLeavesMap(const FloorDef& def, i32 x, i32 y, Facing f) {
    // R7 step off the map.
    i32 dx = 0;
    i32 dy = 0;
    facingDelta(f, dx, dy);
    return !inMap(x + dx, y + dy, mapHeight(def));
}

i32 mapSquareIndex(i32 x, i32 y) {
    // R19 Square = X + 30 * (Y - 1), 1-based.
    return x + kMapWidth * (y - 1);
}

u32 fieldFlagsAt(const FloorDef& def, i32 square) {
    // R19 Walls(square) = (1 <= square <= fields.Length) ? fields[square-1].Flags : 0
    if (square < 1 || square > static_cast<i32>(def.fields.size())) return 0;
    return static_cast<u32>(def.fields[static_cast<std::size_t>(square - 1)].flags);
}

bool mappingEnabled(const Party& party) {
    // R9 nav.Mapping = !leader.IsLost
    return !party.leader().isLost();
}

void markExplored(Ctx& ctx, const Party& party, FloorState& floor, i32 x, i32 y) {
    (void)ctx;
    // R15: writes only if Mapping is on.
    if (!mappingEnabled(party)) return;
    if (!cellInState(floor, x, y)) return;
    sqAt(floor, x, y).explored = true;
}

void setPartyPosition(Ctx& ctx, Party& party, FloorState& floor, i32 x, i32 y) {
    // R10 SetPosition: X=x; Y=y; mark explored if not rock. No rock check on placement.
    party.x = x;
    party.y = y;
    for (i32 i = 0; i < party.size; ++i) {
        party.members[i].location.x = x;
        party.members[i].location.y = y;
        party.members[i].location.dungeonLevel = party.dungeonLevel;
    }
    if (!squareIsRock(floor, x, y)) markExplored(ctx, party, floor, x, y);
}

void mapRecordOnEntry(Ctx& ctx, FloorState& floor, const FloorDef& def, i32 x, i32 y) {
    (void)ctx;
    // R11-R13 MapRecord.OnEntry. Fog is read once, from the stepped-onto square.
    i32 h = mapHeight(def);
    if (!inMap(x, y, h) || !cellInState(floor, x, y)) return;
    u32 own = fieldFlagsAt(def, mapSquareIndex(x, y));
    SquareState& here = sqAt(floor, x, y);
    here.bits |= (own & kFeatureBitsEntry);  // R13 seven features (fog included)
    if (own & kBitFog) return;               // R11/R12 in fog: no edges recorded
    here.bits |= (own & kEdgeBitsEntry);     // R12/R13 own East and North edges
    // R12 far edges (x = Width-1, y = Height-1) are recorded as seen.
    // UNKNOWN: the spec's "Width-1" is taken as the last column, kMapWidth (1-based x).
    if (x == kMapWidth) here.bits |= kBitWallEast;
    if (y == h) here.bits |= kBitWallNorth;
    // R12 west neighbour contributes only its East wall or door.
    if (x > 1) {
        u32 w = fieldFlagsAt(def, mapSquareIndex(x - 1, y));
        sqAt(floor, x - 1, y).bits |= (w & (kBitWallEast | kBitDoorEast));
    }
    // R12 south neighbour contributes only its North wall or door.
    if (y > 1) {
        u32 s = fieldFlagsAt(def, mapSquareIndex(x, y - 1));
        sqAt(floor, x, y - 1).bits |= (s & (kBitWallNorth | kBitDoorNorth));
    }
}

void recordArrival(Ctx& ctx, const Party& party, FloorState& floor, const FloorDef& def,
                   MapRecordGuard& guard, i32 x, i32 y) {
    // R15 guard: here = (level, x, y); if here == lastRecorded return.
    i32 level = party.dungeonLevel;
    if (guard.valid && guard.level == level && guard.x == x && guard.y == y) return;
    guard.level = level;
    guard.x = x;
    guard.y = y;
    guard.valid = true;
    // R9: the map record is written only when neither LostPosition nor LostLevel is set.
    if (!mappingEnabled(party)) return;
    mapRecordOnEntry(ctx, floor, def, x, y);
}

void rollSecretDoorsOnEntry(Ctx& ctx, FloorState& floor, i32 x, i32 y, i32 leaderAbility5Value) {
    // R16: for each unrecorded secret edge on the squares touched, one roll is made.
    // Touched edges: own N, own E, west neighbour's E, south neighbour's N.
    const EdgeRef edges[4] = {
        edgeRefOf(x, y, Facing::N),
        edgeRefOf(x, y, Facing::E),
        edgeRefOf(x, y, Facing::W),
        edgeRefOf(x, y, Facing::S),
    };
    for (const EdgeRef& e : edges) {
        if (!cellInState(floor, e.cx, e.cy)) continue;
        SquareState& s = sqAt(floor, e.cx, e.cy);
        if (!(s.bits & e.secret)) continue;  // recorded secret doors are never rolled again
        // NoticesSecretDoor: rng.Next(100) < BestAbilityValue(c, 5, gear) / 5 (integer division assumed)
        i32 chance = leaderAbility5Value / kSecretDoorDivisor;
        bool found = ctx.rng.below(100) < chance;
        s.bits &= ~e.secret;
        if (found) {
            s.bits |= e.door;     // success records the secret door
            s.bits &= ~e.wall;    // and clears the wall
        } else {
            s.bits |= e.wall;     // failure records the wall
        }
    }
}

void recordDoorPassage(Ctx& ctx, FloorState& floor, i32 x, i32 y, Facing f) {
    (void)ctx;
    // R17: if secret: Record(secretBit) else if door: Record(doorBit); then Unrecord(wallBit).
    // UNKNOWN: an unrecorded secret edge that is passed through is recorded as a door, clearing
    // the secret marker. The SRD does not say how a secret marker is represented.
    EdgeRef e = edgeRefOf(x, y, f);
    if (!cellInState(floor, e.cx, e.cy)) return;
    SquareState& s = sqAt(floor, e.cx, e.cy);
    if (s.bits & e.secret) {
        s.bits &= ~e.secret;
        s.bits |= e.door;
    } else if (s.bits & e.door) {
        s.bits |= e.door;  // Record(doorBit)
    }
    s.bits &= ~e.wall;  // Unrecord(wallBit)
}

void recordFogWallBump(Ctx& ctx, FloorState& floor, i32 x, i32 y, Facing f) {
    (void)ctx;
    // R8/R18: N:(x,y) WALL_NORTH; E:(x,y) WALL_EAST; S:(x,y-1) WALL_NORTH; W:(x-1,y) WALL_EAST
    EdgeRef e = edgeRefOf(x, y, f);
    if (!cellInState(floor, e.cx, e.cy)) return;
    sqAt(floor, e.cx, e.cy).bits |= e.wall;
}

void arrivalLostCheck(Ctx& ctx, Party& party, const FloorState& floor, i32 x, i32 y) {
    // R20 arrival order. (a) standing on mapped ground while lost: FoundYourself.
    // (b) still lost: TryToWorkItOut. Walking onto mapped ground ends the lost state outright (quirk).
    Character& leader = party.members[0];
    if (!leader.isLost()) return;
    bool mapped = cellInState(floor, x, y) && sqAt(floor, x, y).explored;
    if (mapped) foundYourself(ctx, leader.lost);
    if (leader.isLost()) tryToWorkItOut(ctx, leader.lost, leader.perception);
    shareLeaderLostFlags(ctx, party);
}

void becomeLost(Ctx& ctx, LostState& lost) {
    (void)ctx;
    // R25/R26 BecomeLost sets all three flags.
    lost.level = true;
    lost.position = true;
    lost.facing = true;
}

void foundYourself(Ctx& ctx, LostState& lost) {
    // R25 FoundYourself clears all three; the message shows only if the character was lost.
    bool wasLost = lost.level || lost.position || lost.facing;
    if (wasLost) ctx.say("lost.found", "You have found yourself.", {}, {});
    lost.level = false;
    lost.position = false;
    lost.facing = false;
}

void tryToWorkItOut(Ctx& ctx, LostState& lost, i32 perception) {
    // R28 working out position, each step, in this order.
    // Divisors are the literal R28/R30 values (15, 20, 25).
    double weight = workingOutWeight(perception);
    // (a) floor check, only if LostLevel is set. weight/15 > Rnd*100 (comparison direction UNKNOWN; ">" used).
    if (lost.level && weight / 15.0 > ctx.rng.nextDouble() * 100.0) {
        lost.level = false;
        ctx.say("lost.level_clear", "You work out which floor you are on.", {}, {});
    }
    // (b) facing check, only if LostFacing is set. weight/20 > Rnd*100.
    if (lost.facing && weight / 20.0 > ctx.rng.nextDouble() * 100.0) {
        lost.facing = false;
        ctx.say("lost.facing_clear", "You work out which way you are facing.", {}, {});
    }
    // (c) full position check, always rolled (R27). weight/25 > Rnd*100 -> FoundYourself.
    if (weight / 25.0 > ctx.rng.nextDouble() * 100.0) {
        foundYourself(ctx, lost);
    }
}

double workingOutWeight(i32 perception) {
    // R28: weight = p<=0 ? 0 : Math.Log(p)^2. Natural log assumed (UNKNOWN: log base not confirmed in source).
    if (perception <= 0) return 0.0;
    double l = std::log(static_cast<double>(perception));
    return l * l;
}

void applyRotatorLoss(Ctx& ctx, LostState& lost, i32 ability5Chance, i32 dungeonLevel) {
    // R29: saved if p >= Rnd*70 + DungeonLevel*2. Otherwise LostPosition and LostFacing are set.
    // The floor flag is not touched. Literals are taken from R29 directly.
    double threshold = ctx.rng.nextDouble() * 70.0 +
                       static_cast<double>(dungeonLevel) * 2.0;
    if (static_cast<double>(ability5Chance) >= threshold) return;  // saved
    lost.position = true;
    lost.facing = true;
    ctx.say("rotator.lost", "The rotator has turned you around.", {}, {});
}

void inheritLostOnJoin(Ctx& ctx, const Party& party, Character& newcomer) {
    (void)ctx;
    // R31 sub0848 True: copies lost-on-floor, in-position and in-facing from Chars(0).
    // Runs before dead joiners are refused (quirk: a refused newcomer keeps the flags).
    newcomer.lost = party.leader().lost;
}

void clearLostAtMorgue(Ctx& ctx, LostState& lost) {
    (void)ctx;
    // R32 a morgue visit clears all three lost flags. Silent.
    lost.level = false;
    lost.position = false;
    lost.facing = false;
}

void runSquareEffects(Ctx& ctx, Party& party, FloorState& floor, const FloorDef& def, i32 ability5Chance) {
    // R33 effects run in AfterMove. The leader perceives each bit just before its effect.
    i32 x = party.x;
    i32 y = party.y;
    u32 flags = fieldFlagsAt(def, mapSquareIndex(x, y));
    i32 perception = party.leader().perception;

    // (a) Water or quicksand per-tick costs apply unless levitating.
    // UNKNOWN: the per-tick cost rules (R69) are not in this part. Not applied here.
    (void)flags;

    // (b) anti-magic and stud perception, (c) extinguisher perception, (d) face bits perception,
    // (e) rotator perception. All noticeable types are perceived in one pass (R35).
    perceiveUnderfoot(ctx, party, floor, x, y, perception, true);

    // (c) extinguisher: clears protections for each member.
    if (flags & kBitExtinguisher) extinguishProtections(ctx, party);

    // (d) facing bits: the party turns silently to face.
    if (flags & kFaceBits) faceSquareBits(ctx, party, floor, x, y);

    // (e) rotator: random facing (R94), then the lose-direction check (R29).
    if (flags & kBitRotator) {
        party.facing = rollRotatorFacing(ctx);
        applyRotatorLoss(ctx, party.members[0].lost, ability5Chance, party.dungeonLevel);
        shareLeaderLostFlags(ctx, party);
    }

    // (f) pit falls per member, then the party-list UPDATE (R54, R55).
    if (flags & kBitPit) {
        bool stopStep = resolvePitFall(ctx, party, party.dungeonLevel);
        pitUpdateParty(ctx, party);
        if (stopStep) return;
    }

    // (g) stairs caption. A pit caption on the same square is overwritten (quirk).
    if (flags & kBitStairsUp) ctx.say("stairs.up", "There are stairs up here.", {}, {});
    if (flags & kBitStairsDown) ctx.say("stairs.down", "There are stairs down here.", {}, {});

    // (h) teleporter, (i) chute, (j) destination re-run: handled by the chute and teleporter
    // modules (dungeon1b and dungeon2). Not handled in this unit.
}

void extinguishProtections(Ctx& ctx, Party& party) {
    // R33(c): clears all protection masks and all eleven protection values for each member.
    for (i32 i = 0; i < party.size; ++i) {
        Resistances& r = party.members[i].resistances;
        r.protectionMasks.clear();
        for (auto& v : r.protectionValues) v = 0;
    }
    ctx.say("extinguish", "Your protections are extinguished!", {}, {});
}

void faceSquareBits(Ctx& ctx, Party& party, FloorState& floor, i32 x, i32 y) {
    // R33(d), R45: the FACE bits are perceived and written to the map. The party turns silently.
    // UNKNOWN: the SRD does not say which face wins if several are set. The first in N,E,S,W order wins.
    if (!cellInState(floor, x, y)) return;
    u32 b = sqAt(floor, x, y).bits;
    if (b & kBitFaceN) {
        party.facing = Facing::N;
    } else if (b & kBitFaceE) {
        party.facing = Facing::E;
    } else if (b & kBitFaceS) {
        party.facing = Facing::S;
    } else if (b & kBitFaceW) {
        party.facing = Facing::W;
    }
    if (b & kFaceBits) markExplored(ctx, party, floor, x, y);
}

bool castBlockedBySquare(Ctx& ctx, FloorState& floor, i32 x, i32 y) {
    // R34: casting on an anti-magic square prints "Anti-Magic area!" and writes the square's bit.
    // CONFLICT: R34 also cites extinguish squares, per the modding doc. The preferred behaviour
    // is used here: anti-magic only.
    if (!cellInState(floor, x, y)) return false;
    SquareState& s = sqAt(floor, x, y);
    if (!(s.bits & kBitAntiMagic)) return false;
    s.bits |= kBitAntiMagic;  // writes the square's bit (sub087C, True)
    ctx.say("cast.antimagic", "Anti-Magic area!", {}, {});
    return true;
}

void perceiveUnderfoot(Ctx& ctx, const Party& party, FloorState& floor, i32 x, i32 y,
                       i32 perception, bool messagesOn) {
    if (!cellInState(floor, x, y)) return;
    bool leaderLost = party.leader().isLost();
    u32 bits = sqAt(floor, x, y).bits;

    // R35: a teleporter is always named and mapped, with no roll, unless the character is lost.
    // UNKNOWN: the SRD omits the teleporter from the noticeable list. This follows the
    // "always named" statement. R39: suppressed when messages are off.
    if ((bits & kBitTeleporter) && !leaderLost) {
        if (messagesOn) ctx.say("perceive.teleporter", "There is a teleporter here.", {}, {});
        markExplored(ctx, party, floor, x, y);
    }

    // R35: the noticeable types are checked.
    if (!(bits & kNoticeBits)) return;

    SquareNotice notice = rollSquarePerception(ctx, perception);  // R36
    // R36: identify maps the square unless the leader is lost.
    if (notice.identified && !leaderLost) markExplored(ctx, party, floor, x, y);
    bool mapped = sqAt(floor, x, y).explored;

    if (notice.noticed && notice.identified && messagesOn) {
        struct NameRow {
            u32 mask;
            const char* text;
        };
        const NameRow rows[] = {
            {kBitFaceN, "Something faces north here."},
            {kBitFaceE, "Something faces east here."},
            {kBitFaceS, "Something faces south here."},
            {kBitFaceW, "Something faces west here."},
            {kBitExtinguisher, "An extinguisher is here."},
            {kBitRotator, "A rotator is here."},
            {kBitAntiMagic, "An anti-magic area is here."},
            {kBitStud, "A stud is here."},
        };
        bool rotatorNamed = perception != 0 && perception != 100;  // R38 quirk
        for (const NameRow& row : rows) {
            if (!(bits & row.mask)) continue;
            if (row.mask == kBitRotator && !rotatorNamed) continue;
            ctx.say("perceive.feature", row.text, {}, {});
        }
    }

    if (notice.noticed && !notice.identified) {
        i32 guess = drawWrongGuessBit(ctx);  // R40 wrong guess
        if (messagesOn) {
            ctx.say("perceive.guess", "You think you sense something, but you are not sure what.",
                    {static_cast<i64>(guess)}, {});
        }
    }

    if (messagesOn) reportSquareCertainty(ctx, perception, mapped, leaderLost);  // R37
}

SquareNotice rollSquarePerception(Ctx& ctx, i32 perception) {
    SquareNotice out;
    // R36 Notice: rng.Next(100)+1 <= P
    out.noticed = (ctx.rng.below(100) + 1 <= perception);
    // R36 Identify (only if noticed): rng.Next(100)+1 <= P/2 (integer division)
    if (out.noticed) {
        out.identified = (ctx.rng.below(100) + 1 <= perception / 2);
    }
    return out;
}

void reportSquareCertainty(Ctx& ctx, i32 perception, bool squareMapped, bool leaderLost) {
    // R37 certainty wording. Uses (int) perception.
    if (perception <= kCertaintyLowLimit) {  // R37: at P <= 35 only this message
        ctx.say("perceive.vague", "You sense something different here...", {}, {});
        return;
    }
    if (leaderLost) {  // R37: named as absolutely certain, and not mapped
        ctx.say("perceive.absolute", "You are absolutely certain of what is here.", {}, {});
        return;
    }
    if (perception == 100 && squareMapped) return;  // R38 quirk: says nothing
    if (perception >= 200) {  // R38: passes both rolls
        ctx.say("perceive.complete", "You are completely certain of what is here.", {}, {});
        return;
    }
    if (squareMapped) {  // R37: a mapped square reads "completely"
        ctx.say("perceive.completely", "You are completely sure of this square.", {}, {});
    }
}

i32 drawWrongGuessBit(Ctx& ctx) {
    // R40: a wrong guess drawn from the 23 flag bits.
    // UNKNOWN: the exclusion count does not match the "eight bits always pass" comment. All 23 are used.
    return static_cast<i32>(ctx.rng.below(kWrongGuessBitCount));
}

bool perceiveAheadBlocked(const FloorState& floor, const FloorDef& def, i32 x, i32 y, Facing f) {
    // R41: walls, doors and secret doors on the shared edge, and the map edge, block the view.
    if (stepLeavesMap(def, x, y, f)) return true;
    return classifyEdge(floor, x, y, f) != EdgeClass::Open;
}

i32 capPerceiveAheadChance(i32 bestMemberAbility5Chance) {
    // R46: best = min(max over members, 95).
    return bestMemberAbility5Chance < kPerceiveAheadCap ? bestMemberAbility5Chance
                                                        : kPerceiveAheadCap;
}

i32 perceptionGearLookup(const Character& ch) {
    // R46 gear lookup: WIS + StatMods/4 (MAINMOD2 1962).
    // UNKNOWN: the StatMods index is taken as the WIS entry.
    u32 wis = static_cast<u32>(StatIndex::Wis);
    return ch.abilities.stats[wis] + ch.abilities.statMods[wis] / 4;
}

bool perceiveAheadHit(Ctx& ctx, i32 chance) {
    // R46: hit if rng.NextDouble()*100 < best.
    return ctx.rng.nextDouble() * 100.0 < static_cast<double>(chance);
}

void perceiveAheadFeatures(Ctx& ctx, FloorState& floor, const FloorDef& def, i32 aheadX, i32 aheadY,
                           i32 chance, bool standingInQuicksand) {
    // R42-R45. Each feature is checked against the ahead square's static flags. Speech is
    // gated on the chance. No automap check (R43).
    i32 h = mapHeight(def);
    if (!inMap(aheadX, aheadY, h) || !cellInState(floor, aheadX, aheadY)) return;
    u32 truth = fieldFlagsAt(def, mapSquareIndex(aheadX, aheadY));
    SquareState& s = sqAt(floor, aheadX, aheadY);

    // R45: FACE bits are perceived and written to the map (silent).
    if (truth & kFaceBits) s.explored = true;

    struct FeatureRow {
        u32 mask;
        const char* text;
    };
    // R42 AheadFeature order.
    const FeatureRow rows[] = {
        {kBitQuicksand, "Quicksand ahead."},
        {kBitStairsUp, "Stairs up ahead."},
        {kBitStairsDown, "Stairs down ahead."},
        {kBitTeleporter, "A teleporter ahead."},
        {kBitChute, "A chute ahead."},
        {kBitPit, "A pit ahead."},
        {kBitRotator, "A rotator ahead."},
        {kBitExtinguisher, "An extinguisher ahead."},
    };
    for (const FeatureRow& row : rows) {
        // RESOLVED-BY-REFERENCE: PerceiveAhead.Look checks fl.Has(ax, ay, bit) before the roll,
        // so an absent feature does not consume a roll; each present feature has its own
        // Rnd * 100 < perception roll.
        if (!(truth & row.mask)) continue;
        if (!perceiveAheadHit(ctx, chance)) continue;
        // Reference Look: map.Record(bit) happens only when the roll succeeds, before the speech test.
        s.bits |= row.mask;
        if (row.mask == kBitQuicksand) s.explored = true;  // R42 quicksand written to the map
        // R44: quicksand speech is suppressed only while standing in quicksand. The roll was
        // already taken above, and the bit is still mapped.
        if (row.mask == kBitQuicksand && standingInQuicksand) continue;
        ctx.say("ahead.feature", row.text, {}, {});
    }
}

bool encountersAllowed(i32 areaId) {
    // R47: area id > 0.
    return areaId > 0;
}

bool standingGroupKept(i64 nowStamp, const Area& area) {
    // R48: kept while (now - stamp) > 2 * respawnT.
    return (nowStamp - area.stamp) > static_cast<i64>(kStandingGroupAgeFactor) * area.respawnT;
}

void refillRoomIfDue(Ctx& ctx, Area& area, i64 nowStamp, bool neverStamped) {
    (void)ctx;
    // R48: an empty room refills once its stamp is more than 1 * respawnT old, or if never stamped.
    bool due = neverStamped ||
               (nowStamp - area.stamp) > static_cast<i64>(kEmptyRoomAgeFactor) * area.respawnT;
    if (!due) return;
    // Refills are written back immediately.
    // UNKNOWN: the spawn population is not in this part. Only the stamp and emptiedAt fields are reset here.
    area.stamp = nowStamp;
    area.emptiedAt = 0;
}

EncounterSquareTraits encounterTraitsForSquare(bool rock, bool stud, bool fog) {
    // R49: ROCK suppresses encounters. STUD raises the spawn floor by one. FOG leaves the group unidentified.
    EncounterSquareTraits t;
    t.suppressed = rock;
    t.floorBonus = stud ? 1 : 0;
    t.unidentified = fog;
    return t;
}

i32 rollEncounterSpread(Ctx& ctx, i32 level, bool onStud) {
    // R50: roll = Int(Rnd*100) + 1.
    i32 roll = ctx.rng.below(kSpreadRollSides) + 1;
    // R50 / MODULE4.BAS:1481: reference is Round_half_even((roll < 50 ? 1 : 0) + level / 5.0),
    // with float division. level/5.0 has a fractional part of 0, .2, .4, .6 or .8, never .5,
    // so half-even rounding is plain rounding: depth = level/5 + (level%5 >= 3 ? 1 : 0).
    i32 depth = level / 5 + ((level % 5) >= 3 ? 1 : 0);
    // CONFLICT: the SRD ladder tests "<50" first, so the 2 and 3 branches never run. Reproduced as written.
    i32 spread = (roll < 50 ? 1 : 0) + depth;
    // c18: if onStud and Rnd*75 < 50: spread = 1. The c24 replacement is unspecified (UNKNOWN).
    if (onStud && ctx.rng.nextDouble() * kStudSpreadRange < kStudSpreadThreshold) {
        spread = 1;
    }
    // spread = min(spread, level)
    if (spread > level) spread = level;
    // encounterFloor = level + 1 if onStud else level. The caller applies it (R50).
    return spread;
}

bool rollPitHover(Ctx& ctx, i32 pitLevel) {
    // R52: hovers if 5 + level/4.0 < Rnd*100. Literals taken from R52 directly.
    double threshold = 5.0 + static_cast<double>(pitLevel) / 4.0;
    return threshold < ctx.rng.nextDouble() * 100.0;
}

i32 rollPitDamage(Ctx& ctx, i32 pitLevel, i32 raceSize) {
    // R53: dmg = Round_half_even( Int(Rnd*(((level+1)/2)*15.5)) * Ln(raceSize+2) + 1 ).
    i32 span = (pitLevel + 1) / 2;  // integer division (VB)
    double range = static_cast<double>(span) * kPitDamageUnit;
    i64 base = vbInt(ctx.rng.nextDouble() * range);  // Int(Rnd*range)
    double raw = static_cast<double>(base) *
                     std::log(static_cast<double>(raceSize + kPitDamageSizeOffset)) +
                 1.0;
    return static_cast<i32>(roundHalfEven(raw));
}

bool resolvePitFall(Ctx& ctx, Party& party, i32 pitLevel) {
    // R52-R54. Each member falls per the pit rules. Only levitating members roll to float.
    // Returns true when a lone character dies here, which stops the step.
    bool stopStep = false;
    for (i32 i = 0; i < party.size; ++i) {
        Character& c = party.members[i];
        if (c.ailments.levitating && rollPitHover(ctx, pitLevel)) {
            continue;  // hovers: no damage
        }
        i32 dmg = rollPitDamage(ctx, pitLevel, raceSizeOf(ctx, c));  // R53
        c.vitals.curHits -= dmg;  // hits may drop below zero
        if (i == 0) {
            // R54 character on screen: "You have fallen into a pit for N hits." with FALL and HIT.
            Str text = Str("You have fallen into a pit for ") + std::to_string(dmg) + Str(" hits.");
            ctx.say("pit.fall", text, {static_cast<i64>(dmg)}, {Str("FALL"), Str("HIT")});
        } else {
            // R54 other members get a Messages line with no sound.
            Str text = c.name + Str(" falls into the pit for ") + std::to_string(dmg) + Str(" hits.");
            ctx.say("pit.member", text, {static_cast<i64>(dmg)}, {});
        }
        if (party.size == 1 && c.vitals.curHits <= 0) stopStep = true;  // R54 lone death stops the step
    }
    return stopStep;
}

void pitUpdateParty(Ctx& ctx, Party& party) {
    // R55 party-list UPDATE. Members at zero or below hits are dropped.
    // A member not yet dead is first marked dead (counted, logged, DIE.WAV).
    i32 kept = 0;
    for (i32 i = 0; i < party.size; ++i) {
        Character& c = party.members[i];
        if (c.vitals.curHits > 0) {
            if (kept != i) party.members[kept] = party.members[i];
            ++kept;
            continue;
        }
        if (!c.isDead()) {
            c.deathState = DeathState::Dead;
            c.deaths += 1;
            ctx.say("pit.die", "A party member has died in the pit.", {}, {c.name, Str("DIE.WAV")});
        }
    }
    // Remaining members move to the leader's square.
    for (i32 i = 0; i < kept; ++i) {
        party.members[i].location.x = party.x;
        party.members[i].location.y = party.y;
        party.members[i].location.dungeonLevel = party.dungeonLevel;
    }
    party.size = kept;
    if (kept == 0) party.wiped = true;
}

const FloorDef* floorDef(const GameData& data, i32 level) {
    if (level < 1 || level > static_cast<i32>(data.floors.size())) return nullptr;
    return &data.floors[static_cast<u32>(level - 1)];
}

const FloorField* fieldAt(const GameData& data, i32 level, i32 x, i32 y) {
    const FloorDef* f = floorDef(data, level);
    if (f == nullptr) return nullptr;
    if (x < 0 || y < 0 || x >= f->width || y >= f->height) return nullptr;
    const i32 idx = y * f->width + x;
    if (static_cast<u32>(idx) >= f->fields.size()) return nullptr;
    return &f->fields[static_cast<u32>(idx)];
}

const FloorTeleporter* findTeleporter(const GameData& data, i32 level, i32 x, i32 y) {
    const FloorDef* f = floorDef(data, level);
    if (f == nullptr) return nullptr;
    for (u32 i = 0; i < f->teleporters.size(); ++i) {
        const FloorTeleporter& t = f->teleporters[i];
        if (t.x == x + 1 && t.y == y + 1) return &t;
    }
    return nullptr;
}

bool isLimitedDeadEnd(i32 build, i32 level) {
    return build == kBuildLimited && level >= kLimitedLevelCap;
}

void setPartyPosition(Party& party, i32 x, i32 y, i32 level) {
    party.x = x;
    party.y = y;
    party.dungeonLevel = level;
    const u32 n = static_cast<u32>(party.size);
    for (u32 i = 0; i < n; ++i) {
        party.members[i].location.x = x;
        party.members[i].location.y = y;
        party.members[i].location.dungeonLevel = level;
    }
}

void pruneDeadMembers(Party& party) {
    const u32 n = static_cast<u32>(party.size);
    if (n == 0) return;
    Arr<Character, kPartyMaxSize> kept{};
    kept[0] = party.members[0];
    u32 k = 1;
    for (u32 i = 1; i < n; ++i) {
        if (party.members[i].isDead()) {
            party.morgueList.push_back(party.members[i]);
        } else {
            kept[k++] = party.members[i];
        }
    }
    party.members = kept;
    party.size = static_cast<i32>(k);
}

void saveOnFloor(Vec<FloorState>& floors, const GameData& data, i32 level, i32 x, i32 y,
                 Character who) {
    if (level < 1 || level > static_cast<i32>(floors.size())) return;
    FloorState& fs = floors[static_cast<u32>(level - 1)];
    const i32 idx = squareIndexOf(data, level, x, y);
    i32 area = 0;
    if (idx >= 0 && static_cast<u32>(idx) < fs.squares.size()) {
        area = fs.squares[static_cast<u32>(idx)].areaId;
    }
    if (area < 0 || area >= 201) area = 0;
    who.location.x = x;
    who.location.y = y;
    who.location.dungeonLevel = level;
    who.location.area = area;
    fs.areas[static_cast<u32>(area)].occupants.push_back(who);
}

bool sameSquare(const TeleporterDest& a, const TeleporterDest& b) {
    return a.x == b.x && a.y == b.y && a.level == b.level;
}

DisplaceOutcome toDisplaceOutcome(ArrivalOutcome o) {
    switch (o) {
        case ArrivalOutcome::FallsFromTheSky:
            return static_cast<DisplaceOutcome>(kDisplaceFallsFromTheSky);
        case ArrivalOutcome::IntoRock:
            return static_cast<DisplaceOutcome>(kDisplaceIntoRock);
        default:
            return static_cast<DisplaceOutcome>(kDisplaceArrives);
    }
}

i32 identifyChanceFromSkill(f64 skill, bool darkness) {
    // R72: chance = skill + 20, clamped to 10..90 (VB Int = floor).
    // Clamp is applied before the darkness reduction, in the order R72 lists them.
    // SRD-AMBIGUOUS: R72 "darkness: chance costs a quarter" is read here as chance / 4
    // (the test and its comment assume this). A literal "costs a quarter" could mean chance * 3/4.
    i32 chance = static_cast<i32>(vbInt(skill + 20.0));
    if (chance < 10) {
        chance = 10;
    }
    if (chance > 90) {
        chance = 90;
    }
    if (darkness) {
        chance = chance / 4;  // integer division: VB Int of the quartered value
    }
    return chance;
}

i32 dungeonLevelCount(const GameData& data, i32 build) {
    (void)build;
    // R59 dungeon.Count. The limited build's denial happens in the R59 clamp and R67/R68.
    return static_cast<i32>(data.floors.size());
}

i32 mapWidth(const GameData& data, i32 level) {
    const FloorDef* f = floorDef(data, level);
    return f != nullptr ? f->width : 0;
}

i32 mapHeight(const GameData& data, i32 level) {
    const FloorDef* f = floorDef(data, level);
    return f != nullptr ? f->height : 0;
}

i32 squareIndexOf(const GameData& data, i32 level, i32 x, i32 y) {
    const FloorDef* f = floorDef(data, level);
    if (f == nullptr) return -1;
    if (x < 0 || y < 0 || x >= f->width || y >= f->height) return -1;
    return y * f->width + x;
}

bool isRockSquare(const GameData& data, i32 level, i32 x, i32 y) {
    // R75, R84 ROCK tile. UNKNOWN: ROCK is assumed to be FLAG_ROCK in FloorField.flags.
    const FloorField* fld = fieldAt(data, level, x, y);
    if (fld == nullptr) return false;
    return (static_cast<u32>(fld->flags) & (1u << static_cast<u32>(FLAG_ROCK))) != 0u;
}

bool isTeleporterSquare(const GameData& data, i32 level, i32 x, i32 y) {
    // R75 teleporter tile: a teleporter record stands on the square.
    return findTeleporter(data, level, x, y) != nullptr;
}

bool isUnmappedSquare(const GameData& data, i32 build, i32 level, i32 x, i32 y) {
    // UNKNOWN: exact test for unmapped. Taken as: the square is off the map
    // or the level has no floor data.
    (void)build;
    return squareIndexOf(data, level, x, y) < 0;
}

i32 limitedLevelClamp(i32 build, i32 level) {
    // R86 the Limited build clamps level to 3.
    return build == kBuildLimited ? minv(level, kLimitedLevelCap) : level;
}

i32 findChuteRecord(const GameData& data, i32 level, i32 x, i32 y) {
    // R56 first chute at (x+1, y+1) with Depth > 0; otherwise no fall.
    const FloorDef* f = floorDef(data, level);
    if (f == nullptr) return kNoRecord;
    for (u32 i = 0; i < f->chutes.size(); ++i) {
        const FloorChute& c = f->chutes[i];
        if (c.x == x + 1 && c.y == y + 1 && c.depth > 0) return static_cast<i32>(i);
    }
    return kNoRecord;
}

ChuteFloatRolls rollChuteFloats(Ctx& ctx, const Party& party) {
    // R57 one roll per member, leader first, even when following.
    // UNKNOWN: float chance is not in the SRD half. The draw is always made; a
    // levitating member floats.
    ChuteFloatRolls r{};
    const u32 n = static_cast<u32>(party.size);
    for (u32 i = 0; i < n; ++i) {
        ctx.rng.nextDouble();
        r.floats[i] = party.members[i].ailments.levitating;
    }
    return r;
}

ChuteFallPlan planChuteFall(const Party& party, const ChuteFloatRolls& rolls, bool followYes) {
    // R57, R58 pure plan from the rolls.
    ChuteFallPlan plan{};
    const u32 n = static_cast<u32>(party.size);
    if (n == 0) return plan;
    const bool leaderFloats = rolls.floats[0];
    plan.leaderFloatHint = leaderFloats;                 // R57 hint when the leader floats
    plan.askFollow = !leaderFloats && n >= 2;            // R58 Follow Leader box
    if (leaderFloats) {
        // R57 a floating leader goes nowhere, with the hint.
        // CONFLICT: R57 says "goes nowhere" but the original also reads as "the leader stays".
        // The SRD wording is followed.
        // UNKNOWN: whether non-floating members still fall when the leader floats. Kept up here.
        plan.goesNowhere[0] = true;
        for (u32 i = 1; i < n; ++i) {
            if (rolls.floats[i]) plan.goesNowhere[i] = true;  // R57 floaters that do not follow
        }
        return plan;
    }
    plan.falls[0] = true;
    for (u32 i = 1; i < n; ++i) {
        if (followYes) {
            plan.falls[i] = true;                        // R58 Yes: sent down, no roll
        } else if (rolls.floats[i]) {
            plan.goesNowhere[i] = true;                  // R57 floated and did not follow
        }
    }
    return plan;
}

i32 chuteDestinationLevel(const GameData& data, i32 build, i32 fromLevel, i32 depth) {
    // R59 to = clamp(from + max(0, depth), 1, dungeon.Count)
    const i32 count = dungeonLevelCount(data, build);
    return clampv(fromLevel + maxv(0, depth), 1, count);
}

i32 rollChuteDamage(Ctx& ctx, i32 level, bool levitating) {
    // R60 damage = RoundHalfEven(Floor(Rnd * level * 10.5) * Log(4) + 5); 0 if levitating.
    if (levitating) return 0;
    const double raw = static_cast<double>(vbInt(ctx.rng.nextDouble() * (level * kChuteDamageStep)))
                       * std::log(4.0) + 5.0;
    return static_cast<i32>(roundHalfEven(raw));
}

void reportChuteOnScreen(Ctx& ctx, const Party& party, const ChuteFallPlan& plan) {
    // R61 members who did not fall, if on screen, get the chute message (once).
    bool shown = false;
    const u32 n = static_cast<u32>(party.size);
    for (u32 i = 0; i < n; ++i) {
        if (!plan.falls[i] && party.members[i].visible) shown = true;
    }
    if (shown) {
        ctx.say("chute.here", "There is a chute here.  Select TAKE to use.", {}, {});
    }
}

void chuteBreakUp(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                  i32 belowLevel, i32 landX, i32 landY) {
    // R62 sub0908 break-up. Anyone off the leader's level has disappeared from view.
    // A member at hits <= 0 dies there. Others are saved on the floor below at the
    // landing square and dropped from the party.
    const u32 n = static_cast<u32>(party.size);
    if (n == 0) return;
    const i32 leaderLevel = party.members[0].location.dungeonLevel;
    Arr<Character, kPartyMaxSize> kept{};
    kept[0] = party.members[0];
    u32 k = 1;
    for (u32 i = 1; i < n; ++i) {
        Character who = party.members[i];
        if (who.location.dungeonLevel == leaderLevel) {
            kept[k++] = who;
            continue;
        }
        ctx.say("chute.disappear", "has disappeared from view!", {}, {who.name});
        if (who.vitals.curHits <= 0) {
            // UNKNOWN: SetDead semantics; direct death state used.
            who.deathState = DeathState::Dead;
        }
        saveOnFloor(floors, data, belowLevel, landX, landY, who);
    }
    party.members = kept;
    party.size = static_cast<i32>(k);
}

void afterAFall(Ctx& ctx, Party& party) {
    // R63 a lone character at CurHits <= 0 and not dead gets Kill("").
    (void)ctx;
    if (party.size != 1) return;
    Character& who = party.members[0];
    if (who.vitals.curHits > 0 || who.isDead()) return;
    // UNKNOWN: Kill(_ch, "") cause text is empty; direct death state used.
    who.deathState = DeathState::Dead;
}

void changeLevel(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                 i32& flags, i32 newLevel) {
    // R64 ChangeLevel.
    // UNKNOWN: the full ChangeLevel body is not in this SRD half. It sets the
    // new level and then settles the area.
    party.dungeonLevel = newLevel;
    const u32 n = static_cast<u32>(party.size);
    for (u32 i = 0; i < n; ++i) party.members[i].location.dungeonLevel = newLevel;
    settleArea(ctx, party, floors, data, flags);
}

void settleAfterChute(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                      i32& flags, bool leaderChangedLevel, bool chuteUnderCaster) {
    // R64 if the leader changed floor, ChangeLevel runs. Otherwise the square
    // settles, unless a chute under the caster (the fall settles the area).
    if (leaderChangedLevel) {
        changeLevel(ctx, party, floors, data, flags, party.dungeonLevel);
        return;
    }
    if (!chuteUnderCaster) settleArea(ctx, party, floors, data, flags);
}

bool chuteRerunsSquare(const Party& party, bool takenByTake) {
    // R65 TAKE always re-runs. A walked chute re-runs when a companion is with the party.
    // CONFLICT: the count of re-runs is not settled by the dossier; one re-run is used.
    if (takenByTake) return true;
    return party.aliveCompanions > 0;
}

void partyListUpdate(Ctx& ctx, Party& party, Vec<Companion>& companions) {
    // R66 the party-list UPDATE runs after walked chutes and pit falls. It prunes the
    // dead. Companions of a dropped member are not released here (sub0930 does that).
    (void)ctx;
    (void)companions;
    pruneDeadMembers(party);
}

void rerunSquare(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                 i32& flags) {
    // R65, R81 re-run of the square. CONFLICT: re-run count. The port only settles and
    // describes the new square (quirk note), so a chute or teleporter here does not fire
    // again and no loop guard is needed.
    settleArea(ctx, party, floors, data, flags);
}

ChuteWalkResult walkChute(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                          i32 build, Vec<Companion>& companions, i32& flags, bool followYes) {
    // R56-R66 orchestrated walked chute.
    ChuteWalkResult res{};
    const i32 level = party.dungeonLevel;
    const i32 rec = findChuteRecord(data, level, party.x, party.y);   // R56
    if (rec == kNoRecord) return res;                                 // R56 no fall
    res.recordFound = true;
    const FloorChute& chute = floorDef(data, level)->chutes[static_cast<u32>(rec)];
    res.destLevel = chuteDestinationLevel(data, build, level, chute.depth);   // R59
    if (isLimitedDeadEnd(build, level)) {                              // R68
        reportLimitedChuteWalkOn(ctx);
        return res;
    }
    const u32 n = static_cast<u32>(party.size);
    const ChuteFloatRolls rolls = rollChuteFloats(ctx, party);         // R57
    const ChuteFallPlan plan = planChuteFall(party, rolls, followYes); // R57, R58
    if (plan.leaderFloatHint) {
        // UNKNOWN: text of the leader's float hint is not in the SRD half.
        ctx.say("chute.floatHint", "You float over the chute.", {}, {});
    }
    reportChuteOnScreen(ctx, party, plan);                             // R61
    if (plan.falls[0]) {
        res.fell = true;
        res.leaderChangedLevel = true;
        for (u32 i = 0; i < n; ++i) {
            if (!plan.falls[i]) continue;
            Character& who = party.members[i];
            who.location.dungeonLevel = res.destLevel;
            const i32 dmg = rollChuteDamage(ctx, res.destLevel, who.ailments.levitating);  // R60
            who.vitals.curHits -= dmg;
            if (dmg > 0) {
                // Text carries N; the value is in nums.
                ctx.say("chute.fell", "You have fallen into a chute for N hits.",
                        {static_cast<i64>(dmg)}, {});
            }
            if (i == 0) res.damage = dmg;
        }
        party.dungeonLevel = res.destLevel;
        chuteBreakUp(ctx, party, floors, data, res.destLevel, party.x, party.y);   // R62
        afterAFall(ctx, party);                                                    // R63
        settleAfterChute(ctx, party, floors, data, flags, true, false);            // R64
    }
    res.rerun = chuteRerunsSquare(party, false);                                   // R65
    partyListUpdate(ctx, party, companions);                                       // R66
    if (res.rerun) rerunSquare(ctx, party, floors, data, flags);                   // R65
    return res;
}

ChuteTakeOutcome takeChute(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                           i32 build, Vec<Companion>& companions, i32& flags, i32 recordIndex) {
    // R67 TAKE sends everyone down with no roll, no question and no sound.
    (void)companions;
    const i32 level = party.dungeonLevel;
    if (isLimitedDeadEnd(build, level)) {                              // R67 refused
        ctx.say("chute.takeRefused", "You cannot take this Chute in the Limited Version.", {}, {});
        return ChuteTakeOutcome::RefusedLimitedDeadEnd;
    }
    i32 depth = 0;
    const FloorDef* f = floorDef(data, level);
    if (f != nullptr && recordIndex >= 0 && recordIndex < static_cast<i32>(f->chutes.size())) {
        depth = f->chutes[static_cast<u32>(recordIndex)].depth;
    }
    const i32 destLevel = chuteDestinationLevel(data, build, level, depth);   // R59
    changeLevel(ctx, party, floors, data, flags, destLevel);                   // R64 ChangeLevel
    if (chuteRerunsSquare(party, true)) {                                      // R65 TAKE always
        rerunSquare(ctx, party, floors, data, flags);
    }
    return ChuteTakeOutcome::Dropped;
}

void reportLimitedChuteWalkOn(Ctx& ctx) {
    // R68 walk-on on the limited dead-end level.
    ctx.say("chute.limitedWalk",
            "There is a chute here, but it doesn't do anything in the Limited Version.", {}, {});
}

bool canClimbUp(const Character& who) {
    // R69 up-climb refused when paralysed or in the death state.
    return !who.ailments.paralysed && !who.isDead();
}

StairsOutcome useStairs(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                        i32 build, i32& flags, bool up) {
    // R69 UseStairs. Stairs down and chutes sit outside the paralysis test.
    if (up && !canClimbUp(party.members[0])) {
        return party.members[0].ailments.paralysed ? StairsOutcome::RefusedParalysed
                                                   : StairsOutcome::RefusedDead;
    }
    const i32 count = dungeonLevelCount(data, build);
    // UNKNOWN: landing square of the stairs is not in the SRD half; only the level changes.
    const i32 newLevel = clampv(party.dungeonLevel + (up ? -1 : 1), 0, count);
    changeLevel(ctx, party, floors, data, flags, newLevel);
    return StairsOutcome::Taken;
}

bool rollWaterItemLoss(Ctx& ctx, i32 dungeonLevel) {
    // R71 takes if rng.Next(100) < dungeonLevel/25.0*100.
    return static_cast<double>(ctx.rng.below(100)) < dungeonLevel / 25.0 * 100.0;
}

void applyWaterTick(Ctx& ctx, Character& who, Inventory& inventory, i32 dungeonLevel,
                    bool quicksand, bool levitating) {
    // R70 water and quicksand cost hits each tick unless levitating.
    if (levitating) return;
    // RESOLVED-BY-REFERENCE: scaling. Rules.cs WaterHurts doc (FRMDUNM.BAS:500-525): "costs you hits equal to the dungeon level, every tick".
    who.vitals.curHits -= static_cast<i32>(kWaterHurts) * dungeonLevel;
    // R70 quicksand may take a pack slot, using the R71 roll.
    // CONFLICT: R71 names water and quicksand; the roll is applied to quicksand only.
    if (quicksand && rollWaterItemLoss(ctx, dungeonLevel)) {
        const u32 slot = static_cast<u32>(ctx.rng.below(kPackSlots));
        if (inventory.pack[slot].id != 0) inventory.pack[slot] = Item{};
    }
}

i32 identifyChance(const Character& who, bool darkness, bool fog) {
    // Formulas, Identify skill: skill = ((INT+WIS)/2) * Ln((topGuildLevel+5)/10 + 1), 0 if topGuildLevel <= 0.
    // Then the Chances formula (see identifyChanceFromSkill).
    // UNKNOWN: the fog argument has no SRD effect on identify chance; accepted and ignored.
    (void)fog;
    f64 skill = 0.0;
    if (who.topGuildLevel > 0) {
        const f64 intWis =
            (who.abilities.stats[static_cast<u32>(StatIndex::Int)] +
             who.abilities.stats[static_cast<u32>(StatIndex::Wis)]) / 2.0;
        skill = intWis * std::log((who.topGuildLevel + 5) / 10.0 + 1.0);
    }
    // FIXED: call the skill-based helper; identifyChance(f64, bool) is not a declared overload.
    return identifyChanceFromSkill(skill, darkness);
}

bool rollIdentify(Ctx& ctx, const Character& who, bool darkness, bool fog) {
    // R72 rolled per group, per character, per tick.
    return ctx.rng.percent(identifyChance(who, darkness, fog));
}

bool fourSecondTickDue(i64 nowMs, i64 lastTickMs) {
    // R73 true when four seconds have passed.
    return nowMs - lastTickMs >= kFourSecondsMs;
}

void runFourSecondTick(Ctx& ctx, Party& party, Inventory& inventory,
                       i64 nowMs, i64& lastTickMs) {
    // R73 every four seconds the ailment and item tick runs.
    if (!fourSecondTickDue(nowMs, lastTickMs)) return;
    lastTickMs = nowMs;
    // UNKNOWN: the body of the ailment and item tick is not in this SRD half. Only the
    // clock advance is modelled.
    (void)ctx;
    (void)party;
    (void)inventory;
}

i32 teleporterLevel(i32 z2, i32 fromLevel) {
    // R76 Z2 if Z2 > 0 and differs from the current level; otherwise the current level.
    return (z2 > 0 && z2 != fromLevel) ? z2 : fromLevel;
}

i32 teleporterLoadedLevel(const Party& party, const GameData& data, i32 build) {
    // R75 loaded = leader.level if 1 <= leader.level <= dungeon.Count.
    // UNKNOWN: leader.level is read as location.dungeonLevel. Fallback when out of range
    // is the party level (not in the SRD half).
    const i32 leaderLevel = party.members[0].location.dungeonLevel;
    const i32 count = dungeonLevelCount(data, build);
    if (leaderLevel >= 1 && leaderLevel <= count) return leaderLevel;
    return party.dungeonLevel;
}

Vec<TeleporterDest> rollTeleporterDestinations(Ctx& ctx, const GameData& data, i32 build,
                                               i32 fromLevel, const FloorTeleporter& tp,
                                               i32 memberCount) {
    // R75 X2/Y2/Z2 fixed or random. R76 level and loaded level.
    // RESOLVED-BY-REFERENCE: Teleporting.cs:35 (ForSquare) starts with "int loaded = fromLevel;"
    // and draws each random square on "dungeon[loaded - 1]". After each member it sets
    // "if (dest[0].Level >= 1 && dest[0].Level <= dungeon.Count) loaded = dest[0].Level;".
    // So the leader's draw is on fromLevel, and every later member's draw is on the level the
    // leader went to (when that is in range). The stored level is still the destination level.
    Vec<TeleporterDest> dests;
    const i32 count = dungeonLevelCount(data, build);
    const i32 level = teleporterLevel(tp.z2, fromLevel);       // R76
    const bool randomDest = (tp.x2 == 0 || tp.y2 == 0);
    i32 loaded = fromLevel;
    for (i32 m = 0; m < memberCount; ++m) {
        TeleporterDest d{};
        d.level = level;
        if (randomDest) {
            // R75 each member drawn fresh on the loaded level, redrawn until neither rock nor teleporter.
            const i32 w = mapWidth(data, loaded);
            const i32 h = mapHeight(data, loaded);
            do {
                d.x = w > 0 ? ctx.rng.below(w) : 0;
                d.y = h > 0 ? ctx.rng.below(h) : 0;
            } while (w > 0 && h > 0 &&
                     (isRockSquare(data, loaded, d.x, d.y) || isTeleporterSquare(data, loaded, d.x, d.y)));
        } else {
            d.x = tp.x2 - 1;                                   // R75 fixed, 1-based stored 0-based
            d.y = tp.y2 - 1;
        }
        d.unmapped = isUnmappedSquare(data, build, level, d.x, d.y);   // R77
        dests.push_back(d);
        // Reference: loaded follows the leader's destination once that level is in range.
        if (level >= 1 && level <= count) loaded = level;
    }
    return dests;
}

void becomeLost(Ctx& ctx, Character& who) {
    // R77 BecomeLost sets the three lost flags.
    (void)ctx;
    who.lost.position = true;
    who.lost.level = true;
    who.lost.facing = true;
}

void splitTeleportedParty(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                          Vec<Companion>& companions, const Vec<TeleporterDest>& dests) {
    // R78 members i >= 1 with dest[i] != dest[0] leave the party and are saved where they landed.
    // R79 documents that random teleporters almost always split the party.
    // UNKNOWN: companion release on split is not in the SRD half.
    (void)ctx;
    (void)companions;
    const u32 n = static_cast<u32>(party.size);
    if (n == 0 || dests.size() == 0) return;
    const TeleporterDest d0 = dests[0];
    Arr<Character, kPartyMaxSize> kept{};
    kept[0] = party.members[0];
    u32 k = 1;
    for (u32 i = 1; i < n; ++i) {
        const TeleporterDest di = (i < dests.size()) ? dests[i] : d0;
        Character who = party.members[i];
        if (sameSquare(di, d0)) {
            kept[k++] = who;
            continue;
        }
        if (who.vitals.curHits <= 0) {                 // R78
            who.vitals.curHits = 0;
            // UNKNOWN: SetDead semantics; direct death state used.
            who.deathState = DeathState::Dead;
        }
        saveOnFloor(floors, data, di.level, di.x, di.y, who);
    }
    party.members = kept;
    party.size = static_cast<i32>(k);
}

void finishTeleportLeader(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                          i32& flags, const TeleporterDest& leaderDest, bool partyShrank) {
    // R80 if the party shrank: PruneTheDead. The leader moves to dest[0].
    // AfterAFall, RerunSquare (no loop guard), SettleArea last.
    if (partyShrank) pruneDeadMembers(party);                  // R80
    const i32 oldLevel = party.dungeonLevel;
    setPartyPosition(party, leaderDest.x, leaderDest.y, oldLevel);   // R80 leader to dest[0]
    if (leaderDest.level != oldLevel) {
        // UNKNOWN: level 0 is not checked on the teleporter path (quirk note R-level 0).
        changeLevel(ctx, party, floors, data, flags, leaderDest.level);
    }
    afterAFall(ctx, party);                                    // R80
    rerunSquare(ctx, party, floors, data, flags);              // R80, R81
    settleArea(ctx, party, floors, data, flags);               // R80 last
}

void walkOntoTeleporter(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                        i32 build, Vec<Companion>& companions,
                        i32& flags, const FloorTeleporter& tp) {
    // R74 walking on a teleporter: no fall and no rock death.
    const i32 from = party.dungeonLevel;
    const i32 destLevel = teleporterLevel(tp.z2, from);        // R76
    const i32 lastLevel = dungeonLevelCount(data, build);
    if (destLevel > lastLevel) {                                // R82 only logs
        reportTeleportPastLastLevel(ctx, destLevel, lastLevel);
        return;
    }
    const Vec<TeleporterDest> dests = rollTeleporterDestinations(ctx, data, build, from, tp,
                                                                 party.size);   // R75
    if (dests.size() == 0) return;
    const u32 n = static_cast<u32>(party.size);
    for (u32 i = 0; i < n && i < dests.size(); ++i) {
        if (dests[i].unmapped) becomeLost(ctx, party.members[i]);              // R77
    }
    const i32 before = party.size;
    splitTeleportedParty(ctx, party, floors, data, companions, dests);        // R78, R79
    const bool shrank = party.size < before;
    finishTeleportLeader(ctx, party, floors, data, flags, dests[0], shrank);  // R80
}

void reportTeleportPastLastLevel(Ctx& ctx, i32 destLevel, i32 lastLevel) {
    // R82 a record past the last level only logs a message.
    // UNKNOWN: message text is not in the SRD half.
    ctx.say("teleport.pastLast", "The teleporter leads past the last level.",
            {static_cast<i64>(destLevel), static_cast<i64>(lastLevel)}, {});
}

Location displaceTarget(const Location& from, Facing facing, i32 right, i32 forward, i32 down) {
    // R83 destination relative to facing, 1-based for the formula, wrapped 30x30.
    // Location is stored 0-based.
    i32 nx = from.x + 1;
    i32 ny = from.y + 1;
    switch (facing) {
        case Facing::N: nx += right;   ny += forward; break;
        case Facing::E: nx += forward; ny -= right;   break;
        case Facing::S: nx -= right;   ny -= forward; break;
        case Facing::W: nx -= forward; ny += right;   break;
    }
    nx = wrapCoordinate(nx, kTeleportWrapSize);
    ny = wrapCoordinate(ny, kTeleportWrapSize);
    i32 level = from.dungeonLevel;
    if (down != 0) level += clampv(down, -kDisplaceLevelLimit, kDisplaceLevelLimit);
    if (level < 0) level = 0;
    Location out{};
    out.x = nx - 1;
    out.y = ny - 1;
    out.dungeonLevel = level;
    out.facing = from.facing;
    return out;
}

ArrivalOutcome teleportArrivalTest(const GameData& data, i32 build, i32 level, i32 x, i32 y) {
    // R84 ForSpell order: FallsFromTheSky, IntoRock, Arrives. R86 clamp applies first.
    // UNKNOWN: MaxDungeonLevel (mc0276) value is not in the SRD half; dungeon.Count is used.
    const i32 lvl = limitedLevelClamp(build, level);           // R86
    if (lvl <= 0) return ArrivalOutcome::FallsFromTheSky;      // R84(a)
    if (lvl > dungeonLevelCount(data, build)) return ArrivalOutcome::IntoRock;   // R84(b)
    if (squareIndexOf(data, lvl, x, y) < 0) return ArrivalOutcome::IntoRock;    // R84(c)
    if (isRockSquare(data, lvl, x, y)) return ArrivalOutcome::IntoRock;         // R84(d)
    return ArrivalOutcome::Arrives;                                              // R84(e)
}

DisplaceOutcome displaceParty(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                              i32 build, i32& flags,
                              i32 right, i32 forward, i32 down) {
    // R83-R85 Teleport spell move.
    Location from{};
    from.x = party.x;
    from.y = party.y;
    from.dungeonLevel = party.dungeonLevel;
    from.facing = static_cast<i32>(party.facing);
    const Location target = displaceTarget(from, party.facing, right, forward, down);   // R83
    const i32 level = limitedLevelClamp(build, target.dungeonLevel);                     // R86
    const ArrivalOutcome outcome = teleportArrivalTest(data, build, level, target.x, target.y);  // R84
    if (outcome != ArrivalOutcome::Arrives) {
        applyFailedTeleport(ctx, party, floors, data, build, outcome, level, target.x, target.y);  // R85
        return toDisplaceOutcome(outcome);
    }
    const i32 oldLevel = party.dungeonLevel;
    setPartyPosition(party, target.x, target.y, oldLevel);
    if (level != oldLevel) {
        changeLevel(ctx, party, floors, data, flags, level);
    } else {
        settleArea(ctx, party, floors, data, flags);
    }
    // FIXED: DisplaceOutcome::Arrives is not declared; value supplied by constant.
    return static_cast<DisplaceOutcome>(kDisplaceArrives);
}

void applyFailedTeleport(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                         i32 build, ArrivalOutcome outcome,
                         i32 level, i32 x, i32 y) {
    // R85 failed teleport.
    // Level 0: the party falls and is killed.
    // Rock, or below the deepest level: the square is written as rock on the automap, and
    // everyone is killed with a cause that only Resurrect undoes.
    // UNKNOWN: the cause enum for rock death is not in the SRD half. DeathState::Rock is used.
    (void)ctx;
    (void)build;
    if (outcome == ArrivalOutcome::Arrives) return;
    const u32 n = static_cast<u32>(party.size);
    if (outcome == ArrivalOutcome::FallsFromTheSky) {
        for (u32 i = 0; i < n; ++i) party.members[i].deathState = DeathState::Dead;
        return;
    }
    if (level >= 1 && level <= static_cast<i32>(floors.size())) {
        FloorState& fs = floors[static_cast<u32>(level - 1)];
        const i32 idx = squareIndexOf(data, level, x, y);
        if (idx >= 0 && static_cast<u32>(idx) < fs.squares.size()) {
            // UNKNOWN: automap field; rockRecorded marks the square as rock on the automap.
            fs.squares[static_cast<u32>(idx)].rockRecorded = true;
        }
    }
    for (u32 i = 0; i < n; ++i) party.members[i].deathState = DeathState::Rock;
}

PortalOutcome etherealPortalStep(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                                 i32 build, i32& flags) {
    // R87 StepThrough: one square forward, wrapping at edges. The party moves first,
    // then the rock test runs. True means the party dies.
    // CONFLICT: which square is tested. The new square is used.
    Location from{};
    from.x = party.x;
    from.y = party.y;
    from.dungeonLevel = party.dungeonLevel;
    from.facing = static_cast<i32>(party.facing);
    const Location next = displaceTarget(from, party.facing, 0, 1, 0);
    setPartyPosition(party, next.x, next.y, party.dungeonLevel);       // party moves first
    if (isRockSquare(data, party.dungeonLevel, next.x, next.y)) {      // rock test
        applyFailedTeleport(ctx, party, floors, data, build, ArrivalOutcome::IntoRock,
                            party.dungeonLevel, next.x, next.y);
        // FIXED: PortalOutcome::PartyDies is not declared; value supplied by constant.
        return static_cast<PortalOutcome>(kPortalPartyDies);
    }
    settleArea(ctx, party, floors, data, flags);                       // UNKNOWN: settle after the step
    // FIXED: PortalOutcome::Survived is not declared; value supplied by constant.
    return static_cast<PortalOutcome>(kPortalSurvived);
}

RelativeDirection soulSearchDirection(i32 right, i32 forward) {
    const i32 sr = (right > 0) - (right < 0);
    const i32 sf = (forward > 0) - (forward < 0);
    if (sf > 0 && sr == 0) return RelativeDirection::North;
    if (sf > 0 && sr > 0) return RelativeDirection::NorthEast;
    if (sf == 0 && sr > 0) return RelativeDirection::East;
    if (sf < 0 && sr > 0) return RelativeDirection::SouthEast;
    if (sf < 0 && sr == 0) return RelativeDirection::South;
    if (sf < 0 && sr < 0) return RelativeDirection::SouthWest;
    if (sf == 0 && sr < 0) return RelativeDirection::West;
    if (sf > 0 && sr < 0) return RelativeDirection::NorthWest;
    return RelativeDirection::North;
}

Str intStr(i64 v) {
    Str out;
    if (v < 0) {
        out += '-';
        v = -v;
    }
    char buf[24];
    i32 n = 0;
    do {
        buf[n++] = static_cast<char>('0' + (v % 10));
        v /= 10;
    } while (v > 0);
    while (n > 0) {
        out += buf[--n];
    }
    return out;
}

i32 floorIndex(const Vec<FloorState>& floors, i32 level) {
    for (u32 i = 0; i < static_cast<u32>(floors.size()); ++i) {
        if (floors[i].dungeonLevel == level) {
            return static_cast<i32>(i);
        }
    }
    return -1;
}

i32 currentArea(const Party& party) {
    return party.members[0].location.area;
}

i32 carrierIndex(const Party& party) {
    if (party.carryingSlot != CarryingSlot::DeadCharacter) {
        return -1;
    }
    for (i32 i = 0; i < party.size; ++i) {
        if (!party.members[static_cast<u32>(i)].carryingCharacterName.empty()) {
            return i;
        }
    }
    return -1;
}

bool isCarriedBody(const Party& party, i32 idx) {
    if (party.carryingSlot != CarryingSlot::DeadCharacter) {
        return false;
    }
    const Str name = party.members[static_cast<u32>(idx)].name;
    if (name.empty()) {
        return false;
    }
    for (i32 j = 0; j < party.size; ++j) {
        if (party.members[static_cast<u32>(j)].carryingCharacterName == name) {
            return true;
        }
    }
    return false;
}

void removeMember(Party& party, i32 idx) {
    for (i32 k = idx; k + 1 < party.size; ++k) {
        party.members[static_cast<u32>(k)] = party.members[static_cast<u32>(k + 1)];
    }
    party.size -= 1;
    party.members[static_cast<u32>(party.size)] = Character{};
}

void setPartyPosition(Party& party, i32 level, i32 x, i32 y) {
    party.dungeonLevel = level;
    party.x = x;
    party.y = y;
    for (i32 i = 0; i < party.size; ++i) {
        Location& loc = party.members[static_cast<u32>(i)].location;
        loc.dungeonLevel = level;
        loc.x = x;
        loc.y = y;
    }
}

const char* facingText(Facing f) {
    // R101 readout: the original prints the facing's full name (LookAround.cs:127, facing.ToString()).
    switch (f) {
        case Facing::N: return "North";
        case Facing::E: return "East";
        case Facing::S: return "South";
        case Facing::W: return "West";
        default: return "West";  // UNKNOWN: out-of-range facing; W is the original switch's default
    }
}

void putDownBodyOnly(Ctx& ctx, Party& party) {
    if (party.carryingSlot != CarryingSlot::DeadCharacter) {
        return;
    }
    const i32 c = carrierIndex(party);
    if (c >= 0) {
        party.members[static_cast<u32>(c)].carryingCharacterName = Str();
    }
    party.carryingSlot = CarryingSlot::None;
    ctx.say("dungeon.putDown", "You put down the body.", {}, {});
}

void markForcedSettle(i32& flags, i32 source) {
    if (source == kForceTeleporterSquare || source == kForceTeleportSpell || source == kForceChestTeleporter) {
        flags |= kForcedSettleBit;
    }
}

bool settleArea(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data, i32& flags) {
    const bool forced = (flags & kForcedSettleBit) != 0;  // R90 take
    flags &= ~kForcedSettleBit;                           // R90 clear
    const i32 fi = floorIndex(floors, party.dungeonLevel);
    if (fi < 0) {
        return false;  // UNKNOWN: no floor record for this level
    }
    FloorState& floor = floors[static_cast<u32>(fi)];
    const i32 area = currentArea(party);
    // UNKNOWN: "same area" is tested against FloorState::roomStamp, the loaded area id (-1 = none loaded).
    if (floor.roomStamp != static_cast<i64>(area)) {
        changeAreaDifferent(ctx, party, floors, data, flags, area);  // R94 different area
        return true;
    }
    if (!forced) {
        return false;  // R93
    }
    settleForcedSameArea(ctx, party, floors, data, flags);  // R91
    return true;
}

void afterTurn(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data, i32& flags) {
    if ((flags & kForcedSettleBit) != 0) {
        settleArea(ctx, party, floors, data, flags);
    }
}

void settleForcedSameArea(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data, i32& flags) {
    (void)flags;  // flag already taken by settleArea (R90)
    const i32 fi = floorIndex(floors, party.dungeonLevel);
    if (fi < 0) {
        return;
    }
    FloorState& floor = floors[static_cast<u32>(fi)];
    const i32 area = currentArea(party);
    // (a) R91 room stored. UNKNOWN: write-back target reduced to the loaded-area id.
    floor.roomStamp = static_cast<i64>(area);
    // (b) R91 engaged group takes a free round (MonstersRound AttackKind 2). UNKNOWN: MonstersRound not in API INDEX; not called.
    // (c) R91 character saved.
    saveCharacters(ctx, party, floors, data);
    // (d) R91 carried bodies put down. Companion release needs the companion list, so only bodies are handled here.
    putDownBodyOnly(ctx, party);
    // (e) R91 nearby others reported.
    reportLookAround(ctx, party, floor);
    // R92 timCombat off, no sub0A91 reload. UNKNOWN: timCombat mapped to Party::engaged.
    party.engaged = false;
    // (f) R91 Arrived() runs.
    arrived(ctx, party, floors, data);
}

void leaveArea(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data) {
    (void)ctx;
    (void)party;
    (void)data;
    const i32 fi = floorIndex(floors, party.dungeonLevel);
    if (fi < 0) {
        return;
    }
    // The old room is no longer loaded.
    floors[static_cast<u32>(fi)].roomStamp = -1;
}

void loadArea(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data, bool arrivalRound) {
    (void)ctx;
    (void)data;
    (void)arrivalRound;  // arrival round not called (MonstersRound not in API INDEX)
    const i32 fi = floorIndex(floors, party.dungeonLevel);
    if (fi < 0) {
        return;
    }
    floors[static_cast<u32>(fi)].roomStamp = static_cast<i64>(currentArea(party));
}

void saveCharacters(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data) {
    (void)ctx;
    (void)floors;
    (void)data;
    for (i32 i = 0; i < party.size; ++i) {
        party.members[static_cast<u32>(i)].saved = true;
    }
}

void arrived(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data) {
    (void)data;
    const i32 fi = floorIndex(floors, party.dungeonLevel);
    if (fi < 0) {
        return;
    }
    reportLookAround(ctx, party, floors[static_cast<u32>(fi)]);
}

void changeAreaDifferent(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data,
                         i32& flags, i32 newArea) {
    (void)flags;
    leaveArea(ctx, party, floors, data);
    // UNKNOWN: PruneTheDead() not called (signature not in API INDEX).
    saveCharacters(ctx, party, floors, data);
    for (i32 i = 0; i < party.size; ++i) {
        party.members[static_cast<u32>(i)].location.area = newArea;
    }
    arrived(ctx, party, floors, data);
    loadArea(ctx, party, floors, data, true);
}

Facing rollRotatorFacing(Ctx& ctx) {
    return static_cast<Facing>(ctx.rng.below(4));
}

const Creature* leadGroupCreature(const Encounter& combat, const Vec<Creature>& waiting) {
    if (!combat.monsters.empty()) {
        for (u32 i = 0; i < static_cast<u32>(combat.monsters.size()); ++i) {
            if (combat.monsters[i].alive) {
                return &combat.monsters[0];
            }
        }
        return nullptr;
    }
    if (waiting.empty()) {
        return nullptr;
    }
    return &waiting[0];
}

bool isAsmodeusLead(const Creature* lead) {
    if (lead == nullptr) {
        return false;
    }
    return lead->knownAs == Str("Asmodeus");
}

PictureLayout asmodeusPictureLayout(bool noStretch, i32 viewW, i32 viewH) {
    PictureLayout p;
    if (noStretch) {
        p.w = 100;
        p.h = 100;
        p.x = static_cast<i32>(vbInt(static_cast<double>(viewW - 100) / 2.0));
        p.y = static_cast<i32>(vbInt(static_cast<double>(viewH - 100) / 2.0));
    } else {
        p.x = 0;
        p.y = 0;
        p.w = viewW;
        p.h = viewH;
    }
    return p;
}

bool includeInRoster(const Party& party, const Character& r, bool everywhere) {
    if (everywhere) {
        return true;
    }
    const Character& leader = party.members[0];
    if (r.name == leader.name) {
        return true;  // leader always included
    }
    return r.location.dungeonLevel == leader.location.dungeonLevel && r.location.area == leader.location.area;
}

RosterCounts countRoster(const Party& party, const Vec<Character>& roster, bool everywhere) {
    RosterCounts c;
    for (u32 i = 0; i < static_cast<u32>(roster.size()); ++i) {
        const Character& r = roster[i];
        if (!includeInRoster(party, r, everywhere)) {
            continue;
        }
        const bool isLeader = r.name == party.members[0].name;
        if (r.isDead() && !isLeader) {
            c.dead += 1;
        } else {
            c.living += 1;
        }
    }
    return c;
}

Str roomReadout(const Party& party, const Vec<Character>& roster, bool everywhere, i32 listedDead) {
    const RosterCounts c = countRoster(party, roster, everywhere);
    const i32 dead = c.dead > listedDead ? c.dead : listedDead;
    Str out;
    if (party.lostPosition) {
        // setReadout order implies (lostPosition, lostLevel, lostFacing); lost level hides the level number.
        if (party.lostLevel) {
            out += Str("(Lost)");
        } else {
            out += Str("(Lost on ") + intStr(party.dungeonLevel) + Str(")");
        }
    } else {
        out += intStr(party.x) + Str(",") + intStr(party.y) + Str(",") + intStr(party.dungeonLevel);
    }
    out += Str(" ");
    out += party.lostFacing ? Str("?") : Str(facingText(party.facing));
    if (dead > 0) {
        out += Str(" [ ") + intStr(c.living) + Str("+") + intStr(dead) + Str(" ]");
    } else {
        out += Str(" [ ") + intStr(c.living) + Str(" ]");
    }
    return out;
}

void reportLookAround(Ctx& ctx, const Party& party, const FloorState& floor) {
    const i32 area = currentArea(party);
    if (area < 0 || area >= kAreaCount) {
        return;
    }
    i32 bodies = 0;
    for (i32 i = 1; i < party.size; ++i) {  // leader's own body does not count
        const Character& m = party.members[static_cast<u32>(i)];
        if (!m.isDead()) {
            continue;
        }
        if (m.location.dungeonLevel != floor.dungeonLevel || m.location.area != area) {
            continue;
        }
        if (isCarriedBody(party, i)) {
            continue;
        }
        bodies += 1;
    }
    if (bodies == 1) {
        ctx.say("dungeon.lookBody", "There is a dead body here!", {}, {});
    } else if (bodies >= 2) {
        ctx.say("dungeon.lookBodies", "There are dead bodies here!", {}, {intStr(bodies)});
    }
    const Vec<Character>& occupants = floor.areas[static_cast<u32>(area)].occupants;
    bool stranger = false;
    for (u32 k = 0; k < static_cast<u32>(occupants.size()); ++k) {
        if (!occupants[k].isDead()) {
            stranger = true;  // occupants are non-party characters
            break;
        }
    }
    if (stranger) {
        ctx.say("dungeon.lookStranger", "Somebody else is in the room!", {}, {});
    }
}

Vec<i32> pickUpCandidates(const Party& party, const FloorState& floor, const GameData& data, i32 pickerSlot) {
    (void)data;
    Vec<i32> out;
    if (pickerSlot < 0 || pickerSlot >= party.size) {
        return out;
    }
    const Character& picker = party.members[static_cast<u32>(pickerSlot)];
    for (i32 i = 0; i < party.size; ++i) {
        if (i == pickerSlot) {
            continue;
        }
        const Character& m = party.members[static_cast<u32>(i)];
        if (!m.isDead()) {
            continue;
        }
        if (isCarriedBody(party, i)) {
            continue;
        }
        if (m.location.dungeonLevel != floor.dungeonLevel || m.location.area != picker.location.area) {
            continue;
        }
        if (!m.visible) {
            continue;  // hidden cannot be picked up
        }
        out.push_back(i);
    }
    return out;
}

void putDownWhatIsCarried(Ctx& ctx, Party& party, FloorState& floor, const GameData& data,
                          Vec<Companion>& companions) {
    (void)floor;
    (void)data;
    if (party.carryingSlot == CarryingSlot::Companion) {
        const i32 ci = party.carryingCompanion;
        if (ci >= 0 && ci < static_cast<i32>(companions.size())) {
            Companion& c = companions[static_cast<u32>(ci)];
            c.released = true;   // R106 released from slot
            c.occupied = false;  // UNKNOWN: occupied flag cleared on release
            c.carry = kCarryNone;
        }
        party.carryingCompanion = -1;
        party.carryingSlot = CarryingSlot::None;
        ctx.say("dungeon.putDownCompanion", "You put down your companion.", {}, {});
        return;
    }
    putDownBodyOnly(ctx, party);  // R106 body not left in its slot
}

void deliverCarried(Ctx& ctx, Party& party) {
    if (party.carryingSlot != CarryingSlot::DeadCharacter) {
        return;
    }
    const i32 c = carrierIndex(party);
    if (c < 0) {
        party.carryingSlot = CarryingSlot::None;
        return;
    }
    Character& carrier = party.members[static_cast<u32>(c)];
    const Str bodyName = carrier.carryingCharacterName;
    for (i32 j = 0; j < party.size; ++j) {
        const Character& m = party.members[static_cast<u32>(j)];
        if (m.name == bodyName) {
            party.morgueList.push_back(m);
            break;
        }
    }
    carrier.carryingCharacterName = Str();
    party.carryingSlot = CarryingSlot::None;
    ctx.say("dungeon.deliver", "Your companion is delivered.", {}, {bodyName});
}

void syncAreas(Ctx& ctx, Party& party, Vec<FloorState>& floors, const GameData& data) {
    (void)floors;
    if (party.dungeonLevel == 0) {
        for (i32 i = 0; i < party.size; ++i) {
            party.members[static_cast<u32>(i)].location.area = -1;
        }
    }
    for (i32 i = party.size - 1; i >= 0; --i) {
        Character& m = party.members[static_cast<u32>(i)];
        if (!m.isDead()) {
            continue;
        }
        if (m.location.dungeonLevel > 0 &&
            isRockSquare(data, m.location.dungeonLevel, m.location.x, m.location.y)) {
            m = Character{};  // written as nought
            removeMember(party, i);
            ctx.say("dungeon.noughtBody", "A body is lost in the rock.", {}, {});
        }
    }
}

void applyRescueArrival(Character& body, i32 daysWaited) {
    body.ageDays += daysWaited;
    body.location.dungeonLevel = 0;
    body.location.area = -1;
}

void loadSavedBodyOnRock(Ctx& ctx, FloorState& floor, const GameData& data, Character& body) {
    const i32 idx = squareIndexOf(data, floor.dungeonLevel, body.location.x, body.location.y);
    if (idx < 0 || !isRockSquare(data, floor.dungeonLevel, body.location.x, body.location.y)) {
        return;
    }
    floor.squares[static_cast<u32>(idx)].bodies.push_back(body);
    ctx.say("dungeon.bodyOnRock", "A body lies on the rock.", {}, {body.name});
}

bool townScreenWanted(const Party& party) {
    return party.dungeonLevel == 0 && !party.members[0].isDead();
}

bool deadScreenOwed(const Party& party) {
    return party.members[0].isDead() && party.size == 1;
}

bool waitActsOn(const Character& who) {
    return who.isDead();
}

void showRescueArrival(Ctx& ctx, Party& party, Character& body, i32 daysWaited) {
    (void)party;
    applyRescueArrival(body, daysWaited);  // R109
    ctx.say("dungeon.rescueArrival", "The body is brought up from the dungeon.", {}, {body.name});
}

double rescueThresholdDays(i32 level) {
    const double l = level < 1 ? 1.0 : static_cast<double>(level);
    const double ln = std::log(l);
    return ln * ln * 100.0 + 21.0;
}

double rescueCeiling(i32 level, i32 area, i32 daysWaited) {
    if (level == 1 && area <= 18) {
        return 100.0;
    }
    return static_cast<double>(daysWaited) < rescueThresholdDays(level) ? 10000.0 : 1000.0;
}

bool rollBodyFoundToday(Ctx& ctx, i32 level, i32 area, i32 daysWaited, bool easyToFind) {
    const double ceiling = rescueCeiling(level, area, daysWaited);
    const double chance = rescueChance(level, easyToFind);
    return ctx.rng.nextDouble() * ceiling <= chance;
}

i32 waitForRescueDays(Ctx& ctx, i32 level, i32 area, bool easyToFind) {
    for (i32 day = 1; day <= kRescueDayCap; ++day) {
        if (rollBodyFoundToday(ctx, level, area, day, easyToFind)) {
            return day;
        }
    }
    return kRescueDayCap;
}

void stepChestCountdown(Ctx& ctx, Character& opener) {
    if (opener.chestCountdown > 0) {
        opener.chestCountdown -= 1;
        if (opener.chestCountdown == 0) {
            ctx.say("dungeon.chestCountdownEnd", "The guards are alerted!", {}, {opener.name});
        }
    }
}

ChestOpenStart beginChestAfterCombat(Ctx& ctx, Party& party, FloorState& floor,
                                     const GameData& data, i32 openerSlot) {
    if (openerSlot < 0 || openerSlot >= party.size) {
        return ChestOpenStart{};
    }
    Character& opener = party.members[static_cast<u32>(openerSlot)];
    if (opener.isDead()) {
        return ChestOpenStart{};  // UNKNOWN: valid opener taken as alive
    }
    const i32 idx = squareIndexOf(data, party.dungeonLevel, party.x, party.y);
    if (idx < 0) {
        return ChestOpenStart{};
    }
    SquareState& sq = floor.squares[static_cast<u32>(idx)];
    if (!sq.hasChest || sq.chestLock != ChestLock::UNLOCKED) {
        return ChestOpenStart{};
    }
    stepChestCountdown(ctx, opener);  // R116 countdown step first
    bool guardsAlive = false;
    for (u32 g = 0; g < 4; ++g) {
        const FoeGroup& fg = sq.foes[g];
        for (u32 m = 0; m < static_cast<u32>(fg.members.size()); ++m) {
            if (fg.members[m].alive) {
                guardsAlive = true;
            }
        }
    }
    if (guardsAlive) {
        for (u32 k = 0; k < kPartyMaxSize; ++k) {
            party.combatOrders[k].kind = CombatOrderKind::None;  // R116 attack order cleared
        }
        if (sq.chestDisarm > 10) {
            opener.chestCountdown = chestCountdownRounds(sq.chestDisarm);  // R116, R119
        }
    }
    return ChestOpenStart{};
}

DisarmResult disarmChestTrap(Ctx& ctx, Party& party, Character& opener, SquareState& chest,
                             i32 bestThiefChance) {
    (void)party;
    const i32 roll = static_cast<i32>(ctx.rng.below(100)) + 1;  // R117 1..100 draw
    if (roll <= bestThiefChance) {
        chest.chestTrap = ChestTrap::NotTrapped;  // R117 disarmed
        ctx.say("dungeon.disarmed", "You disarm the trap.", {}, {opener.name});
    } else {
        // UNKNOWN: the trap effect is applied by the caller (chest.chestTrap still set).
        ctx.say("dungeon.disarmFailed", "The trap goes off!", {}, {opener.name});
    }
    return DisarmResult{};
}

ChestTeleportOutcome chestTeleporterTrap(Ctx& ctx, Party& party, Vec<FloorState>& floors,
                                         const GameData& data, i32 build,
                                         i32& flags, i32 openerSlot,
                                         i32 level, i32 x, i32 y) {
    if (openerSlot < 0 || openerSlot >= party.size) {
        return ChestTeleportOutcome::Unmapped;
    }
    const bool unmapped = isUnmappedSquare(data, build, level, x, y);  // R118 UNKNOWN test
    if (unmapped) {
        party.lostLevel = true;     // R118 all three lost flags
        party.lostPosition = true;
        party.lostFacing = true;
        party.lost = true;
    }
    if (party.size > 1) {
        removeMember(party, openerSlot);  // R118 opener removed from party
        // UNKNOWN: PruneTheDead() not called (signature not in API INDEX). No gold, no treasure.
        return ChestTeleportOutcome::OpenerRemoved;
    }
    setPartyPosition(party, level, x, y);  // R118 SetPosition(x, y)
    markForcedSettle(flags, kForceChestTeleporter);  // R89 lone opener sets the forced flag
    settleArea(ctx, party, floors, data, flags);     // R118 SettleArea
    return unmapped ? ChestTeleportOutcome::Unmapped : ChestTeleportOutcome::Teleported;
}

i32 chestCountdownRounds(i32 disarm) {
    if (disarm <= 10) {
        return 0;
    }
    const double v = 10.0 - 2.0 * std::log(static_cast<double>(disarm - 10));
    const i32 r = static_cast<i32>(vbInt(v));
    return r < 2 ? 2 : r;
}

i32 chestDisarmChance(i32 wis, i32 dex, i32 joinedGuildLevel, double thiefValue,
                      i32 guardGuildLevel, i32 depth) {
    const double l = static_cast<double>(joinedGuildLevel);
    const double m = guardGuildLevel < 2 ? 2.0 : static_cast<double>(guardGuildLevel);
    const double d = static_cast<double>(depth);
    const double v = wis / 4.0 + dex / 2.0
                   + (4.5 + std::exp(std::log(l + 1.0) / std::log(15.0))) * 1.4 * thiefValue
                   - 9.375 * std::log(m) * std::log(d + 1.0);
    i64 r = vbInt(v);
    if (r < 5) {
        r = 5;
    }
    if (r > 98) {
        r = 98;
    }
    return static_cast<i32>(r);
}

i64 disarmXpBase(double thiefValue, i32 guardGuildLevel, i32 leaderActiveLevel) {
    const double v = thiefValue * (static_cast<double>(guardGuildLevel) / 2.0)
                   / (1.0 + static_cast<double>(leaderActiveLevel) / 333.0);
    return vbInt(v);
}

i32 trapIdentifyChance(i32 wis, i32 mLvl, i32 mDex, i32 gLvl, i32 disarm) {
    const double lm = std::log(mLvl >= 1 ? static_cast<double>(mLvl) : 1.0);
    const double ld = std::log(mDex >= 1 ? static_cast<double>(mDex) : 1.0);
    const double lg = std::log(gLvl >= 1 ? static_cast<double>(gLvl) : 1.0);
    const double base = static_cast<double>(vbInt(wis / 4.0)) - static_cast<double>(vbInt(lm * ld * 2.5));
    const double inner = static_cast<double>(vbInt(base + static_cast<double>(disarm) / 1.2));
    i64 r = vbInt(inner + lg * lg);
    if (r < 2) {
        r = 2;
    }
    if (r > 98) {
        r = 98;
    }
    return static_cast<i32>(r);
}

bool rollTrapIdentify(Ctx& ctx, i32 wis, i32 mLvl, i32 mDex, i32 gLvl, i32 disarm) {
    const i32 chance = trapIdentifyChance(wis, mLvl, mDex, gLvl, disarm);
    const i32 roll = static_cast<i32>(ctx.rng.below(100)) + 1;
    const bool ok = roll <= chance;
    if (!ok) {
        ctx.say("dungeon.trapGuess", "You are not sure what kind of trap this is.", {}, {});
    }
    return ok;
}

bool leaderAliveForJoin(const Party& party) {
    return party.size > 0 && !party.members[0].isDead();
}

Str numberText(i32 n) {
    if (n == 0) {
        return Str("0");
    }
    const bool negative = n < 0;
    i64 v = negative ? -static_cast<i64>(n) : static_cast<i64>(n);
    Str digits;
    while (v > 0) {
        digits = Str(1, static_cast<char>('0' + static_cast<int>(v % 10))) + digits;
        v /= 10;
    }
    if (negative) {
        digits = Str("-") + digits;
    }
    return digits;
}

char lowerAscii(char c) {
    if (c >= 'A' && c <= 'Z') {
        return static_cast<char>(c - 'A' + 'a');
    }
    return c;
}

bool equalNoCase(const Str& a, const Str& b) {
    const i32 n = static_cast<i32>(a.size());
    if (n != static_cast<i32>(b.size())) {
        return false;
    }
    for (i32 i = 0; i < n; ++i) {
        if (lowerAscii(a[i]) != lowerAscii(b[i])) {
            return false;
        }
    }
    return true;
}

i32 blurAxis(Ctx& ctx, i32 v, i32 spread, i32 limit) {
    const bool minus = ctx.rng.percent(50);
    // UNKNOWN: spread <= 0 is not stated; no offset is drawn in that case.
    const i32 shift = spread > 0 ? static_cast<i32>(ctx.rng.below(spread)) : 0;
    const i32 moved = minus ? v - shift : v + shift;
    return clampv(moved, 1, limit);
}

ActionRunStart beginActionRun(Ctx& ctx, ActionRunState& run, ActionTrigger trigger,
                              const Vec<ModHookSlot>& mods) {
    // R123: an active run refuses and logs the new request.
    if (run.active) {
        ctx.say("dungeon.action.refused",
                "An action run is already active; the new request is refused.",
                {static_cast<i32>(trigger)}, {});
        return ActionRunStart::Refused;
    }
    // R123: with no hooked mod the task completes at once; the context
    // factory is never called, so the run never becomes active.
    const i32 n = static_cast<i32>(mods.size());
    for (i32 i = 0; i < n; ++i) {
        if (mods[i].live && mods[i].hasHook && !mods[i].disabled) {
            run.active = true;
            return ActionRunStart::RunHooks;
        }
    }
    return ActionRunStart::NoHooks;
}

i32 nextHookedMod(const Vec<ModHookSlot>& mods, i32 afterIndex) {
    // R123: hooks run in load order (vector order).
    const i32 n = static_cast<i32>(mods.size());
    const i32 start = maxv(afterIndex + 1, 0);
    for (i32 i = start; i < n; ++i) {
        if (mods[i].live && mods[i].hasHook && !mods[i].disabled) {
            return i;
        }
    }
    return -1;
}

void disableModAfterHookFailure(Ctx& ctx, ModHookSlot& mod) {
    // R123: a hook that throws disables its mod.
    mod.disabled = true;
    ctx.say("dungeon.action.hookDisabled",
            "A mod hook failed and has been disabled.",
            {static_cast<i32>(mod.loadOrder)}, {});
}

void finishActionRun(ActionRunState& run) {
    // R123: the context is closed and the run ends.
    run.active = false;
}

void climbToTownAlive(Ctx& ctx, Party& party) {
    // R124: the leader's position is placed at the party's square and the
    // party exits to town alive.
    // RESOLVED-BY-REFERENCE: town is dungeon level 0. Rescue.cs CarryHome: "carried to town -
    // DungeonLevel = 0". The town level is therefore 0, not the party's level.
    Location& at = party.members[0].location;
    at.x = party.x;
    at.y = party.y;
    at.dungeonLevel = 0;
    at.facing = static_cast<i32>(party.facing);
    party.inDungeon = false;
    party.onStairs = false;
    ctx.say("dungeon.climb.town", "You climb the stairs to town.", {}, {});
}

bool stairsClimbStillValid(const Party& party) {
    // R124: the climb goes on only if still on the stairs and in the dungeon.
    return party.onStairs && party.inDungeon;
}

bool monstersInArea(const Party& party, const FloorState& floor) {
    // R125 "monsters are in the area".
    // UNKNOWN: exact predicate not stated. Monsters count as present if a
    // living party foe exists, a living foe sits in the leader's area, or the
    // leader's area has a standing group.
    const i32 foeCount = static_cast<i32>(party.foes.size());
    for (i32 i = 0; i < foeCount; ++i) {
        if (party.foes[i].alive) {
            return true;
        }
    }
    const i32 areaIndex = party.members[0].location.area;
    if (areaIndex >= 0 && areaIndex < kAreaSlots) {
        const Area& area = floor.areas[areaIndex];
        for (i32 j = 0; j < 4; ++j) {
            if (area.foes[j].alive) {
                return true;
            }
        }
        if (static_cast<i32>(area.standingGroup.size()) > 0) {
            return true;
        }
    }
    return false;
}

ExitMenuOutcome requestExitToMenu(Ctx& ctx, const Party& party, const FloorState& floor) {
    // R125: refused with a beep when monsters are present and the character is alive.
    // UNKNOWN: "the character" taken as the party leader. The beep is carried by the event code.
    if (monstersInArea(party, floor) && !party.members[0].isDead()) {
        ctx.say("dungeon.exit.blockedBeep",
                "Cannot exit while monsters are in the area!", {}, {});
        return ExitMenuOutcome::BlockedByMonsters;
    }
    ctx.say("dungeon.exit.prompt", "Exit to Main Menu?", {}, {});
    return ExitMenuOutcome::ConfirmPrompt;
}

void confirmExitToMenu(Ctx& ctx, Party& party) {
    // R125 Yes: save, unload party, return to title. The character stays where
    // it stood; there is no town arrival.
    const i32 n = static_cast<i32>(party.size);
    for (i32 i = 0; i < n && i < kPartyMaxSize; ++i) {
        party.members[i].saved = true;
    }
    party.loaded = false;
    party.inDungeon = false;
    ctx.say("dungeon.exit.confirmed", "Saving and returning to the title screen.", {}, {});
}

void refuseWindowClose(Ctx& ctx) {
    // R126: user-initiated window close is refused.
    ctx.say("dungeon.window.closeRefused",
            "Please use the Mordor EXIT buttons to leave the game.", {}, {});
}

SessionCloseOutcome requestSessionEndClose(Ctx& ctx, const Party& party, const FloorState& floor) {
    // R127 (FRMMAIN.BAS:148-191): refused when monsters are present, the
    // character is alive and the level is above 0.
    if (monstersInArea(party, floor) && !party.members[0].isDead() && party.dungeonLevel > 0) {
        ctx.say("dungeon.close.blocked",
                "Cannot exit while monsters are in the area!", {}, {});
        return SessionCloseOutcome::RefusedMonsters;
    }
    ctx.say("dungeon.close.prompt", "Exit Mordor?", {}, {});
    return SessionCloseOutcome::ConfirmExit;
}

TakeTarget takeButtonTarget(const FloorState& floor, const Party& party) {
    // Original quirk: the Take button uses stairs or chute, not Objects & Spells (c33).
    // UNKNOWN: the square flags are read from SquareState::bits using the Field.Flags
    // bit numbers. The square index is the 1-based header index minus one.
    // UNKNOWN: stairs are checked before chute; the order is not stated.
    const i32 idx = squareIndexOf(party.x, party.y) - 1;
    if (idx < 0 || idx >= static_cast<i32>(floor.squares.size())) {
        return TakeTarget::None;
    }
    const u32 bits = floor.squares[idx].bits;
    const bool stairs = (bits & (1u << kBitStairsUp)) != 0u || (bits & (1u << kBitStairsDown)) != 0u;
    if (stairs) {
        return TakeTarget::Stairs;
    }
    if ((bits & (1u << kBitChute)) != 0u) {
        return TakeTarget::Chute;
    }
    return TakeTarget::None;
}

i32 clampLevelRequest(Ctx& ctx, ReleaseKind release, i32 requestedLevel) {
    // R128: every level change goes through this clamp. Limit is 15 (full) or 3 (limited).
    const i32 limit = buildLevelLimit(release);
    // RESOLVED-BY-REFERENCE: LimitedVersion.cs Clamp: "if (!On || level < 0 || level > DeepestLevel
    // || level <= LastLevel) return (level, null);" so requests below 0 or above DeepestLevel pass
    // through unchanged with no message. Requests in (LastLevel, DeepestLevel] are denied with
    // LevelDenied and set to LastLevel. DeepestLevel is mc015C (GameFiles.FullLevels), 15 in the
    // full build.
    constexpr i32 kDeepestLevel = 15; // mc015C
    if (requestedLevel < 0 || requestedLevel > kDeepestLevel) {
        return requestedLevel;
    }
    if (requestedLevel > limit) {
        // R128: denial message; level is set to the limit.
        ctx.say("dungeon.levelDenied",
                "LIMITED VERSION: Request to go to Level n is Denied.",
                {requestedLevel}, {});
        return limit;
    }
    return requestedLevel;
}

ReleaseKind classifyRelease(i32 levelsWord, bool someMonsterLevelAtOrBelowThreshold,
                            bool someItemFloorAtOrBelowThreshold) {
    // R129: Full only if levels >= 15, some monster LevelFound <= 15 and some item Floor <= 15.
    if (levelsWord >= kReleaseLevelThreshold &&
        someMonsterLevelAtOrBelowThreshold &&
        someItemFloorAtOrBelowThreshold) {
        return ReleaseKind::Full;
    }
    return ReleaseKind::Limited;
}

LimitedMessageKind reportLimitedMessage(Ctx& ctx, LimitedAction action, i32 level, i32 lastLevel) {
    // R130. The m0622 and m02A6 message flags are not modelled: the limited
    // build's messages are taken as on (original quirk, c33/c35).
    // For TeleporterDestination, `level` is the destination Z2.
    switch (action) {
        case LimitedAction::TakeChute:
            // m0622 and DungeonLevel = last level
            if (level == lastLevel) {
                ctx.say("dungeon.limited.chuteTakeDenied",
                        "You cannot take this Chute in the Limited Version.",
                        {level, lastLevel}, {});
                return LimitedMessageKind::ChuteTakeDenied;
            }
            return LimitedMessageKind::None;
        case LimitedAction::WalkOnChute:
            // m02A6 and DungeonLevel = last level
            if (level == lastLevel) {
                ctx.say("dungeon.limited.chuteWalkOn",
                        "There is a chute here, but it doesn't do anything in the Limited Version.",
                        {level, lastLevel}, {});
                return LimitedMessageKind::ChuteWalkOnNoEffect;
            }
            return LimitedMessageKind::None;
        case LimitedAction::TeleporterDestination:
            // m02A6 and Z2 > last level
            if (level > lastLevel) {
                ctx.say("dungeon.limited.teleporterDenied",
                        "..but it doesn't go anywhere in the limited version...",
                        {level, lastLevel}, {});
                return LimitedMessageKind::TeleporterDenied;
            }
            return LimitedMessageKind::None;
        default:
            return LimitedMessageKind::None;
    }
}

bool isDestinationDenied(i32 destinationLevel, ReleaseKind release) {
    // R131: teleporter and chute destinations past the limit are denied.
    return destinationLevel > buildLevelLimit(release);
}

bool seerCanReach(i32 dungeonLevel) {
    // R132: nothing below dungeon level 12 (DeepestHeCanReach).
    return dungeonLevel <= kSeerDeepestReach;
}

SeerEarlyResult rollSeerEarlyFailure(Ctx& ctx, i32 level) {
    // R133: fail if Int(Rnd*100)+1 < level*5. On failure a second roll names
    // the level if Rnd*100 >= level*5, otherwise it says nothing.
    SeerEarlyResult result;
    const i32 threshold = level * kSeerEarlyFactor;
    const i32 roll = static_cast<i32>(ctx.rng.below(100)) + 1;
    if (roll < threshold) {
        result.failed = true;
        const double second = ctx.rng.nextDouble() * 100.0;
        result.namesLevel = second >= static_cast<double>(threshold);
    }
    return result;
}

bool isSeerNamePrefix(const Str& typed, const Str& name) {
    // R134: case-insensitive prefix; the name must be at least as long as the typed text.
    const i32 typedLen = static_cast<i32>(typed.size());
    const i32 nameLen = static_cast<i32>(name.size());
    if (nameLen < typedLen) {
        return false;
    }
    for (i32 i = 0; i < typedLen; ++i) {
        if (lowerAscii(typed[i]) != lowerAscii(name[i])) {
            return false;
        }
    }
    return true;
}

SeerNameMatch matchSeerNames(const Str& typed, const Vec<Str>& names) {
    // R134: an exact match wins at once. Count 0 none, 1 one, 2 or more several.
    SeerNameMatch match;
    const i32 n = static_cast<i32>(names.size());
    for (i32 i = 0; i < n; ++i) {
        if (equalNoCase(typed, names[i])) {
            match.count = 1;
            match.index = i;
            match.exact = true;
            return match;
        }
        if (isSeerNamePrefix(typed, names[i])) {
            match.count += 1;
            match.index = i;
        }
    }
    if (match.count != 1) {
        match.index = -1;
    }
    return match;
}

i32 seerFirstRecord(SeerTargetKind kind) {
    // R134 (FRMSEEK.BAS:66-86): monsters from record 1, items from record 0.
    // UNKNOWN: character record start not stated; 0 is used.
    switch (kind) {
        case SeerTargetKind::Monster:
            return kSeerMonsterFirstRecord;
        case SeerTargetKind::Item:
            return kSeerItemFirstRecord;
        case SeerTargetKind::Character:
        default:
            return 0;
    }
}

Str monsterNameFor(const GameData& data, i32 monsterId, i32 nameForm, IdLevel idLevel) {
    // R134: the plural branch is monsterNameFor(Me, 2, record) with IdLevel 0.
    // UNKNOWN: MonsterDef name fields were not supplied to this module. Assumed:
    // data.monsters indexed by monster id, with .name and .pluralName.
    // idLevel is accepted for the call shape; the R134 plural call passes 0 and it is not used here.
    (void)idLevel;
    if (monsterId < 0 || monsterId >= static_cast<i32>(data.monsters.size())) {
        return Str();
    }
    const MonsterDef& def = data.monsters[monsterId];
    if (nameForm == kSeerPluralNameForm) {
        // FIXED: MonsterDef has no pluralName member; the plural form is not
        // available, so the singular name is returned.
        return def.name;
    }
    return def.name;
}

SeerMonsterPick locateMonster(Ctx& ctx, const FloorState& floor, i32 monsterId, i32 monsterType) {
    // R135: a lair is returned 75% of the time when reached (Rnd*100 < 75).
    // Otherwise a random candidate area whose spawn mask admits the type is returned.
    SeerMonsterPick pick;

    i32 lairArea = -1;
    for (i32 i = 0; i < kAreaSlots; ++i) {
        if (floor.areas[i].lairId == monsterId) {
            lairArea = i;
            break;
        }
    }
    if (lairArea >= 0 && ctx.rng.nextDouble() * 100.0 < static_cast<double>(kSeerLairPercent)) {
        pick.lairResult = true;
        pick.areaIndex = lairArea;
        return pick;
    }

    // UNKNOWN: monsterType outside 0..31 cannot be a spawn bit; no candidate is found.
    if (monsterType < 0 || monsterType > 31) {
        pick.areaIndex = -1;
        return pick;
    }
    const u32 typeBit = 1u << static_cast<u32>(monsterType);
    i32 candidates = 0;
    for (i32 i = 0; i < kAreaSlots; ++i) {
        if ((static_cast<u32>(floor.areas[i].spawnMask) & typeBit) != 0u) {
            candidates += 1;
        }
    }
    if (candidates == 0) {
        pick.areaIndex = -1;
        return pick;
    }
    const i32 chosen = static_cast<i32>(ctx.rng.below(candidates));
    i32 seen = 0;
    for (i32 i = 0; i < kAreaSlots; ++i) {
        if ((static_cast<u32>(floor.areas[i].spawnMask) & typeBit) != 0u) {
            if (seen == chosen) {
                pick.areaIndex = i;
                return pick;
            }
            seen += 1;
        }
    }
    pick.areaIndex = -1;
    return pick;
}

i32 countSpawnClasses(i32 spawnMask) {
    // R135 classes = popcount of SpawnMask.
    u32 bits = static_cast<u32>(spawnMask);
    i32 count = 0;
    while (bits != 0u) {
        count += static_cast<i32>(bits & 1u);
        bits >>= 1u;
    }
    return count;
}

SeerCommonality seerCommonality(i32 classCount) {
    // Seer commonality table (c20).
    if (classCount <= 2) {
        return SeerCommonality::VeryCommon;
    }
    if (classCount <= 4) {
        return SeerCommonality::FairlyCommon;
    }
    if (classCount <= 7) {
        return SeerCommonality::Uncommon;
    }
    if (classCount <= 11) {
        return SeerCommonality::Rare;
    }
    return SeerCommonality::AlmostUnheard;
}

SeerFrequency seerFrequency(i32 chancePercent) {
    // Seer frequency table (c20).
    if (chancePercent <= 2) {
        return SeerFrequency::AlmostNever;
    }
    if (chancePercent <= 8) {
        return SeerFrequency::VeryRarely;
    }
    if (chancePercent <= 15) {
        return SeerFrequency::Rarely;
    }
    if (chancePercent <= 35) {
        return SeerFrequency::Uncommonly;
    }
    if (chancePercent <= 50) {
        return SeerFrequency::Commonly;
    }
    return SeerFrequency::VeryCommonly;
}

SeerCharacterReport locateCharacter(Ctx& ctx, const Character& subject, i32 searchLevel,
                                    bool subjectInCity) {
    // R136: a character in the city cannot be located.
    SeerCharacterReport report;
    if (subjectInCity) {
        report.outcome = SeerCharacterOutcome::CityRefused;
        return report;
    }
    // Reference Seer.cs:122. need = level*3; roll = Int(Rnd*100)+1.
    // UNKNOWN: "level" in R136 is taken as searchLevel (see R133 legend).
    const i32 need = searchLevel * kSeerNeedFactor;
    const i32 roll = static_cast<i32>(ctx.rng.below(100)) + 1;
    if (roll < need) {
        if (roll + kSeerLevelOnlySlack >= need) {
            // UNKNOWN: "level only" has no SeerCharacterOutcome value. It is reported as
            // Located with the level set and the coordinates left at 0.
            report.outcome = SeerCharacterOutcome::Located;
            report.level = subject.location.dungeonLevel;
            return report;
        }
        report.outcome = SeerCharacterOutcome::Failed;
        return report;
    }
    report.outcome = SeerCharacterOutcome::Located;
    report.x = subject.location.x;
    report.y = subject.location.y;
    report.level = subject.location.dungeonLevel;
    report.amongDead = subject.isDead();
    return report;
}

BlurredPoint blurPoint(Ctx& ctx, i32 x, i32 y, i32 spread) {
    // R137: each coordinate is shifted by up to `spread` either way and clamped
    // to the floor. Monsters use spread 4; characters and items spread is UNKNOWN (R139).
    BlurredPoint point;
    point.x = blurAxis(ctx, x, spread, kFloorWidth);
    point.y = blurAxis(ctx, y, spread, kFloorHeight);
    return point;
}

Currency chargeSeerFee(Ctx& ctx, Purse& wallet, Currency fee) {
    // R138: the fee is taken as charPay takes it. The bank makes up a short purse.
    // UNKNOWN: charPay's internals are not in this module. Policy chosen: on-hand gold
    // first, then the bank covers the shortfall.
    if (fee <= 0) {
        return 0;
    }
    const Currency fromHand = fee < wallet.goldOnHand ? fee : wallet.goldOnHand;
    wallet.goldOnHand -= fromHand;
    const Currency shortfall = fee - fromHand;
    const Currency fromBank = shortfall < wallet.goldInBank ? shortfall : wallet.goldInBank;
    wallet.goldInBank -= fromBank;
    const Currency charged = fromHand + fromBank;
    if (charged < fee) {
        ctx.say("dungeon.seer.feeShort",
                "The Seer's fee could not be fully paid.",
                {static_cast<i32>(fee), static_cast<i32>(charged)}, {});
    }
    return charged;
}

bool noteDepth(i32 level, i32& deepestReached) {
