void foundYourself(Ctx& ctx, Character& who) {
    // R46 / R47: clears lost position and lost level. UNKNOWN: whether lost facing is also
    // cleared; left unchanged. Order within a step not stated.
    if (!who.lost.position && !who.lost.level) {
        return;
    }
    who.lost.position = false;
    who.lost.level = false;
    // RESOLVED-BY-REFERENCE: Lost.cs TryToWorkItOut emits "You've figured out where you are!"
    ctx.say("dungeon.found_yourself", "You've figured out where you are!", {}, {});
}

bool tryToWorkItOut(Ctx& ctx, Character& who) {
    // RESOLVED-BY-REFERENCE: Lost.cs TryToWorkItOut. Three independent rolls on
    // weight = Log(perception)^2 with divisors 15 (level), 20 (facing), 25 (position);
    // each passes when weight / n > Rnd * 100. noticePasses is no longer used here.
    // UNKNOWN: the reference takes perception from Rules.BestAbilityChance over the party;
    // that function is not in this signature, so who.perception is used.
    if (!who.isLost()) {
        return true;
    }
    const double perception = static_cast<double>(who.perception);
    const double weight = perception <= 0.0 ? 0.0 : std::log(perception) * std::log(perception);

    if (who.lost.level && weight / 15.0 > ctx.rng.nextDouble() * 100.0) {
        who.lost.level = false;
        ctx.say("dungeon.figured_level", "You've figured out what level you're on...", {}, {});
    }
    if (who.lost.facing && weight / 20.0 > ctx.rng.nextDouble() * 100.0) {
        who.lost.facing = false;
        ctx.say("dungeon.figured_facing", "You've figured out what direction you're facing...", {}, {});
    }
    if (weight / 25.0 > ctx.rng.nextDouble() * 100.0) {
        foundYourself(ctx, who);
    }
    return !who.isLost();
}

void applySquareEffects(Ctx& ctx, Arr<Character, kPartyMaxSize>& members, i32 partySize, FloorState& floor, Location& loc) {
    (void)members;
    (void)partySize;
    const i32 index = squareIndexOf(loc.x, loc.y);
    if (index < 0 || index >= static_cast<i32>(floor.squares.size())) {
        return;
    }
    SquareState& square = floor.squares[static_cast<u32>(index)];

    // UNKNOWN: order of automap recording versus square effects is not stated (R47).
    // Automap recording is placed first here.
    mapSquareOnAutomap(ctx, square, false, false);

    // c44 order (preferred), steps not specified in this SRD part:
    //   1. water / quicksand (WADE)            UNKNOWN: handled by the water module
    //   2. anti-magic and stud perception       UNKNOWN: square fields not given
    //   3. extinguisher, facing, rotator        UNKNOWN: square fields not given
    //   4. pit                                  handled by dungeon2b
    //   5. stairs caption, teleporter, chute    handled by dungeon2b / dungeon1b
    // Only automap recording is implemented in this part.
}

void mapSquareOnAutomap(Ctx& ctx, SquareState& square, bool fogEdge, bool wallBump) {
    (void)ctx;
    // R48 / c42 / c44: fog edges are not mapped in the grey view. A wall bump is recorded in fog.
    if (fogEdge && !wallBump) {
        return;
    }
    square.explored = true;
    // UNKNOWN: encoding of the wall-bump record in square fields is not given. Not stored here.
    (void)wallBump;
}

void applyRotatorLoss(Ctx& ctx, Character& who) {
    // R49 / c13: the floor is kept, so the floor is not touched.
    // c44: the port rotator uses rng.Next(4), which is 0-based (R42).
    // UNKNOWN: the ability-5 chance of the other overload is not part of this signature.
    who.location.facing = static_cast<i32>(ctx.rng.below(kFacingCount));
    who.lost.facing = true;
}

i32 stairsUpDestination(i32 dungeonLevel) {
    // R52 / c39 / c45: stairs up from level 1 reach town (level 0). Otherwise one level up.
    return maxv(dungeonLevel - 1, 0);
}

i32 rollStudSpread(Ctx& ctx) {
    // CONFLICT: c24 leaves the replacement value unspecified. c18 gives spread = 1 when
    // Rnd*75 < 50. Otherwise 0 is used. Original unconfirmed.
    return ctx.rng.nextDouble() * kStudDrawRange < kStudDrawLimit ? kStudSpreadOn : 0;
}

void applyEtherealPortal(Ctx& ctx, Arr<Character, kPartyMaxSize>& members, i32 partySize, const FloorState& floor, Location& loc) {
    // CONFLICT: engine (c9): step one forward, then test the square stepped onto.
    // Wiki (c89) tests the square behind; not used.
    // UNKNOWN: forward direction per facing (R42). Mapping used: see kStepDx / kStepDy.
    const i32 facing = loc.facing & 3;
    loc.x += kStepDx[facing];
    loc.y += kStepDy[facing];

    // UNKNOWN: rock test. SquareState has no direct rock flag in this SRD part; rockRecorded is
    // used as the closest field.
    const i32 index = squareIndexOf(loc.x, loc.y);
    bool isRock = false;
    if (index >= 0 && index < static_cast<i32>(floor.squares.size())) {
        isRock = floor.squares[static_cast<u32>(index)].rockRecorded;
    }

    const i32 count = minv(partySize, kPartyMaxSize);
    for (i32 i = 0; i < count; ++i) {
        Character& member = members[static_cast<u32>(i)];
        member.location = loc;
        if (isRock && !member.isDead()) {
            // Rock = death (c9). UNKNOWN: whether DeathState::Rock is the correct state.
            member.deathState = DeathState::Rock;
            // UNKNOWN: message text is not in the SRD; placeholder wording.
            ctx.say("dungeon.ethereal_rock", "The portal sends you into solid rock.", {}, {});
        }
    }
}

Str bufferInt(i64 v) {
  if (v == 0) return "0";
  bool neg = v < 0;
  if (neg) v = -v;
  Str out;
  while (v > 0) {
    out.insert(out.begin(), static_cast<char>('0' + (v % 10)));
    v /= 10;
  }
  if (neg) out.insert(out.begin(), '-');
  return out;
}

bool bufferParseInt(const Str& t, i32& out) {
  if (t.empty() || t.size() > 6) return false;
  i32 v = 0;
  for (char c : t) {
    if (c < '0' || c > '9') return false;
    v = v * 10 + (c - '0');
  }
  out = v;
  return true;
}

Str bufferJoin(const Vec<Str>& w, size_t from) {
  Str out;
  for (size_t i = from; i < w.size(); ++i) {
    if (i > from) out += ' ';
    out += w[i];
  }
  return out;
}

const SpellDef* bufferSpellDef(const Session& s, i32 spellIndex) {
  if (spellIndex < 0 || spellIndex >= static_cast<i32>(s.data.spells.size())) return nullptr;
  return &s.data.spells[static_cast<size_t>(spellIndex)];
}

bool bufferFindSpell(const Session& s, const Str& name, i32& spellIndex) {
  const SpellDef* hit = accSpellByName(s, name);
  if (hit == nullptr) return false;
  for (size_t i = 0; i < s.data.spells.size(); ++i) {
    if (&s.data.spells[i] == hit) {
      spellIndex = static_cast<i32>(i);
      return true;
    }
  }
  return false;
}

bool bufferSpellCost(Session& s, i32 member, i32 spellIndex, i64& out) {
  Character* c = accMember(s, member);
  const SpellDef* sp = bufferSpellDef(s, spellIndex);
  if (c == nullptr || sp == nullptr) return false;
  Ctx ctx = s.ctx();
  out = castCostSp(ctx, *c, *sp, 0);
  return true;
}

bool bufferMemberExists(Session& s, i32 member) {
  return accMember(s, member) != nullptr;
}

Str bufferMemberName(Session& s, i32 member) {
  Character* c = accMember(s, member);
  return c != nullptr ? c->name : Str();
}

Str bufferKey(i32 member, i32 slot) {
  return "buffers." + bufferInt(member) + "." + bufferInt(slot);
}

Str bufferOrderKey(i32 member) {
  return "order." + bufferInt(member);
}

void bufferOrderSet(Session& s, i32 member, const Str& order) {
  s.featureState[bufferOrderKey(member)] = order;
}

void bufferOrderClear(Session& s, i32 member) {
  s.featureState.erase(bufferOrderKey(member));
}

Str buffersDescribe(Session& s, i32 member, i32 slot) {
  const i32 b = buffersRead(s, member, slot);
  if (b < 0) return "(Nothing)";
  if (bufferIsItem(b)) {
    if (b < kFirstBufferablePackSlot) {
      s.featureState.erase(bufferKey(member, slot));
      return "(Nothing)";
    }
    Item* it = accPackItem(s, member, b);
    if (it == nullptr || it->id <= 0) {
      s.featureState.erase(bufferKey(member, slot));
      return "(Nothing)";
    }
    const ItemDef* def = accItemDef(s, it->id);
    return def != nullptr ? "\"" + def->name + "\"" : Str("(unknown item)");
  }
  const i32 idx = bufferSpellIndex(b);
  const SpellDef* sp = bufferSpellDef(s, idx);
  if (sp == nullptr) return "(Nothing)";
  i64 c = 0;
  const Str cost = bufferSpellCost(s, member, idx, c)
                       ? (c == 0 ? Str("?") : bufferInt(c))  // lblBufferStat: "?" when the cost is nought
                       : Str("(cost unknown)");
  return "\"" + sp->name + "\"  " + cost;
}

Str buffersListText(Session& s, i32 member) {
  Str out = "Buffers for member " + bufferInt(member) + " (" + bufferMemberName(s, member) + "):";
  for (i32 slot = 1; slot <= kBufferSlotsExposed; ++slot) {
    out += "\n" + bufferInt(slot) + ". " + buffersDescribe(s, member, slot);
  }
  return out;
}

bool bufferCommand(Session& s, const Vec<Str>& w, Str& reply) {
  const size_t first = (!w.empty() && w[0] == "buffer") ? 1 : 0;
  if (w.size() <= first) {
    reply = kBufferUsage;
    return true;
  }
  i32 member = 0;
  if (!bufferParseInt(w[first], member) || member < 1) {
    reply = kBufferUsage;
    return true;
  }
  if (!bufferMemberExists(s, member)) {
    reply = "No party member " + bufferInt(member) + ".";
    return true;
  }
  const size_t argc = w.size() - first - 1;
  if (argc == 0) {
    reply = buffersListText(s, member);
    return true;
  }
  if (argc < 2) {
    reply = kBufferUsage;
    return true;
  }
  i32 slot = 0;
  if (!bufferParseInt(w[first + 1], slot) || slot < 1 || slot > kBufferSlotsExposed) {
    reply = "Slot must be 1 to 4.";
    return true;
  }
  const Str spellName = bufferJoin(w, first + 2);
  if (spellName.empty()) {
    reply = kBufferUsage;
    return true;
  }
  if (accLower(spellName) == "clear") {
    s.featureState.erase(bufferKey(member, slot));
    reply = "Buffer " + bufferInt(slot) + " of member " + bufferInt(member) + " is now empty.";
    return true;
  }
  i32 spellIndex = 0;
  if (!bufferFindSpell(s, spellName, spellIndex)) {
    reply = "No spell called \"" + spellName + "\".";
    return true;
  }
  s.featureState[bufferKey(member, slot)] = bufferInt(bufferForSpell(spellIndex));
  reply = "Buffer " + bufferInt(slot) + " of member " + bufferInt(member) +
          " now holds \"" + spellName + "\".";
  return true;
}

i32 buffersRead(Session& s, i32 member, i32 slot) {
  auto it = s.featureState.find(bufferKey(member, slot));
  if (it == s.featureState.end()) return kBufferEmpty;
  i32 v = 0;
  if (!bufferParseInt(it->second, v)) return kBufferEmpty;
  return v;
}

CastDisposition buffersDisposition(bool monstersPresent, bool fightOn, SpellUse use) {
  if (monstersPresent && (fightOn || use != SpellUse::NonCombat)) return CastDisposition::BecomesOrder;
  return CastDisposition::CastNow;
}

BufferFire buffersFireFromShift(i32 buffer, bool monstersPresent, bool fightOn, SpellUse use) {
  if (buffer < 0) return BufferFire::Nothing;
  if (bufferIsItem(buffer)) return BufferFire::UseItem;
  if (!bufferIsSpell(buffer)) return BufferFire::Nothing;
  return buffersDisposition(monstersPresent, fightOn, use) == CastDisposition::BecomesOrder
             ? BufferFire::StandingOrder
             : BufferFire::CastNow;
}

BufferFire buffersFireFromCombatSetting(i32 buffer) {
  if (buffer < 0) return BufferFire::Nothing;
  if (bufferIsItem(buffer)) return BufferFire::UseItem;
  if (!bufferIsSpell(buffer)) return BufferFire::Nothing;
  return BufferFire::StandingOrder;
}

Str buffersStandingOrderText(Session& s, i32 member) {
  auto it = s.featureState.find(bufferOrderKey(member));
  return it == s.featureState.end() ? Str("none") : it->second;
}

void buffersClearStandingOrder(Session& s, i32 member) {
  bufferOrderClear(s, member);
}

BufferFire buffersApplyCombatSetting(Session& s, i32 member, i32 combatSetting) {
  if (!bufferMemberExists(s, member)) return BufferFire::Nothing;
  if (combatSetting == 1) {
    bufferOrderSet(s, member, "fight");
    return BufferFire::Nothing;
  }
  if (combatSetting == 2) {
    bufferOrderSet(s, member, "defend");
    return BufferFire::Nothing;
  }
  const i32 slot = combatSetting - kCombatSettingBufferBase;
  if (combatSetting < 3 || slot < 1 || slot > kBufferSlotsExposed) {
    bufferOrderClear(s, member);
    return BufferFire::Nothing;
  }
  const i32 b = buffersRead(s, member, slot);
  if (bufferIsItem(b)) {
    bufferOrderClear(s, member);
    return BufferFire::UseItem;
  }
  if (bufferIsSpell(b)) {
    const SpellDef* sp = bufferSpellDef(s, bufferSpellIndex(b));
    if (sp != nullptr) {
      bufferOrderSet(s, member, "spell:" + bufferInt(sp->id));
      return BufferFire::StandingOrder;
    }
  }
  bufferOrderClear(s, member);
  return BufferFire::Nothing;
}

BufferFire buffersFireSlot(Session& s, i32 member, i32 slot, bool monstersPresent, bool fightOn) {
  if (!bufferMemberExists(s, member)) return BufferFire::Nothing;
  const i32 b = buffersRead(s, member, slot);
  SpellUse use = SpellUse::Either;
  const SpellDef* sp = nullptr;
  if (bufferIsSpell(b)) {
    sp = bufferSpellDef(s, bufferSpellIndex(b));
    if (sp == nullptr) return BufferFire::Nothing;
    use = spellUse(*sp);
  }
  const BufferFire fire = buffersFireFromShift(b, monstersPresent, fightOn, use);
  if (fire == BufferFire::StandingOrder && sp != nullptr) {
    bufferOrderSet(s, member, "spell:" + bufferInt(sp->id));
  }
  return fire;
}

