DcastPlan dcastPlanOf(i32 effect, i32 damage2, i32 category) {
  const i32 base = effect >= kEffPartyOffset ? effect - kEffPartyOffset : effect;
  if (base == kEffDamage) {
    return (category == kHealSchool && damage2 > 0) ? DcastPlan::Heal : DcastPlan::Unsupported;
  }
  switch (base) {
    case kEffCurePoison:
    case kEffCureDisease:
    case kEffCureParalysis:
      return DcastPlan::Cure;
    case kEffLevitate:
      return DcastPlan::Levitate;
    case kEffInvisible:
      return DcastPlan::Invisible;
    case kEffSeeInvisible:
      return DcastPlan::SeeInvisible;
    case kEffProtect:
      return DcastPlan::Protect;
    case kEffTeleport:
      return DcastPlan::Teleport;
    case kEffDetectRock:
      return DcastPlan::DetectRock;
    case kEffDepthPerception:
      return DcastPlan::DetectDepth;
    case kEffFindDirection:
      return DcastPlan::DetectFacing;
    default:
      return DcastPlan::Unsupported;
  }
}

i32 dcastParseMember(const Str& word) {
  if (word.empty() || word.size() > static_cast<size_t>(kMaxMemberDigits)) return 0;
  i32 n = 0;
  for (char c : word) {
    if (c < '0' || c > '9') return 0;
    n = n * 10 + (c - '0');
  }
  return n;
}

Str dcastJoin(const Vec<Str>& w, size_t from) {
  Str out;
  for (size_t i = from; i < w.size(); ++i) {
    if (i > from) out += ' ';
    out += w[i];
  }
  return out;
}

bool dcastDepth(Ctx& ctx, const Party& party, const Str& casterName, const Str& spellName, Str& note) {
  const i32 level = static_cast<i32>(party.dungeonLevel);
  note = casterName + " cast " + spellName + ": the party is on dungeon level " + std::to_string(level) + ".";
  ctx.say("dcast.depth", note, {level}, {});
  return true;
}

bool dcastFacing(Ctx& ctx, const Party& party, const Str& casterName, const Str& spellName, Str& note) {
  const i32 facing = static_cast<i32>(party.facing);
  note = casterName + " cast " + spellName + ": the party faces facing code " + std::to_string(facing) + ".";
  ctx.say("dcast.facing", note, {facing}, {});
  return true;
}

bool dcastRun(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() < 3) {
    reply = "Usage: cast <member> <spell name or id>";
    return true;
  }
  const i32 member = dcastParseMember(w[1]);
  Character* caster = accMember(s, member);
  if (member <= 0 || caster == nullptr) {
    reply = "Cast for which party member? Give a party number.";
    return true;
  }
  const Str spellName = dcastJoin(w, 2);
  const SpellDef* spell = accSpellByName(s, spellName);
  if (spell == nullptr) {
    reply = "No spell called " + spellName + ".";
    return true;
  }
  if (spellUse(*spell) == SpellUse::Combat) {
    reply = spell->name + " is a combat spell and cannot be cast out of a fight.";
    return true;
  }
  const DcastPlan plan = dcastPlanOf(spell->effect, spell->damage2, spell->category);
  if (plan == DcastPlan::Unsupported) {
    reply = spell->name + " has no effect the dungeon can apply.";
    return true;
  }

  Ctx ctx = s.ctx();

  // R9 / mdrcharCheckCast: the caster's guilds must teach it, at a level they have, with stats met.
  const CastRefusal gate = unfitGateCheck(ctx, *caster, *spell);
  if (static_cast<i32>(gate) != 0) {
    reply = caster->name + " cannot cast " + spell->name + " (gate refusal).";
    return true;
  }
  if (spellUnreachable(ctx, *spell)) {
    reply = spell->name + " cannot be reached from here.";
    return true;
  }
  const i32 cost = castCostSp(ctx, *caster, *spell, 0);
  if (caster->vitals.curSpellPoints < cost) {
    reply = caster->name + " does not have the spell points for " + spell->name + ".";
    return true;
  }

  Str note;
  bool applied = false;
  switch (plan) {
    case DcastPlan::DetectDepth:
      applied = dcastDepth(ctx, s.game.party, caster->name, spell->name, note);
      break;
    case DcastPlan::DetectFacing:
      applied = dcastFacing(ctx, s.game.party, caster->name, spell->name, note);
      break;
    case DcastPlan::Heal:
      // NEED: healAmount (the heal amount for a Category 9 Damage2 > 0 spell, and the hits write).
      note = spell->name + " cannot heal yet: the heal amount is not available to the dungeon.";
      break;
    case DcastPlan::Cure:
    case DcastPlan::Levitate:
    case DcastPlan::Invisible:
    case DcastPlan::SeeInvisible:
    case DcastPlan::Protect:
      // NEED: ailmentSetters (set or clear the Levitate, Invisible, SeeInvisible, Protection and
      // poison/disease/paralysis flags on Character.ailments; SpellAilmentKind names them).
      note = spell->name + " has no effect yet: nothing in the dungeon sets that ailment.";
      break;
    case DcastPlan::Teleport:
      // NEED: teleportDestination (the destination level/x/y rule for the spell, then the
      // fall and rock outcomes via teleportLevelIsRock).
      note = spell->name + " cannot move the party yet: its destination is not available.";
      break;
    case DcastPlan::DetectRock:
      // NEED: squareWallQuery (whether the square ahead of the party is solid, from SquareState).
      note = spell->name + " cannot read the square ahead yet: wall data is not available.";
      break;
    case DcastPlan::Unsupported:
      note = spell->name + " has no effect the dungeon can apply.";
      break;
  }

  if (!applied) {
    reply = note;
    return true;  // no SP spent: the effect was not applied
  }
  caster->vitals.curSpellPoints -= cost;
  reply = note;
  return true;
}

void register_dcast() {
  registerFeatureCommand({"cast", Screen::Dungeon, &dcastRun, "cast <member> <spell name or id>  - cast a non-combat spell"});
}

const char* disarmTrapName(i32 trap) {
  switch (trap) {
    case 0: return "Not Trapped";
    case 1: return "Poison Gas";
    case 2: return "Disease Spores";
    case 3: return "Exploding Trap";
    case 4: return "Fire Trap";
    case 5: return "Slime";
    case 6: return "Fate";
    case 7: return "Teleporter";
    case 8: return "Blackout";
    case 9: return "Fear";
    case 10: return "Withering";
    default: return "Unknown Trap";
  }
}

i32 disarmGuildLevel(const Character& c) {
  const i32 g = static_cast<i32>(c.activeGuild);
  if (g < 0 || g >= kGuildCount) return 0;
  return static_cast<i32>(c.guilds[static_cast<size_t>(g)].level);
}

i64 disarmAward(i32 chance, i32 monsterGuildLevel, i32 firstCharGuildLevel, i32 partySize) {
  const double xp = static_cast<double>(chance) * (static_cast<double>(monsterGuildLevel) / 2.0)
                  / (1.0 + static_cast<double>(firstCharGuildLevel) / 333.0);
  const double party = 1.0 - static_cast<double>(partySize - 1) * 0.04;
  return static_cast<i64>(static_cast<double>(roundHalfEven(party * static_cast<double>(roundHalfEven(xp)))));
}

bool disarmParseMember(const Session& s, const Vec<Str>& w, i32& member) {
  if (w.size() < 2) return false;
  i64 value = 0;
  if (!accParseInt(w[1], value)) return false;
  if (value < 1 || value > accPartySize(s)) return false;
  member = static_cast<i32>(value);
  return true;
}

SquareState* disarmChestHere(Session& s) {
  SquareState* sq = accSquareHere(s);
  return (sq != nullptr && sq->hasChest) ? sq : nullptr;
}

bool cmdInspect(Session& s, const Vec<Str>& w, Str& reply) {
  (void)w;
  const SquareState* chest = disarmChestHere(s);
  if (chest == nullptr) {
    reply = "There is no chest here.";
    return true;
  }
  const i32 trap = static_cast<i32>(chest->chestTrap);
  if (trap == 0) {
    reply = "This chest is not trapped.";
    return true;
  }
  // UNKNOWN: whether the name is gated by the opener's skill. The reference shows the
  // name in lblTrap; the skill gate is not in the evidence, so the name is revealed.
  reply = Str("This chest is trapped: ") + disarmTrapName(trap) + ".";
  return true;
}

bool cmdDisarm(Session& s, const Vec<Str>& w, Str& reply) {
  i32 member = 0;
  if (!disarmParseMember(s, w, member)) {
    reply = "Usage: disarm <member>";
    return true;
  }
  const SquareState* chest = disarmChestHere(s);
  if (chest == nullptr) {
    reply = "There is no chest here.";
    return true;
  }
  const i32 trap = static_cast<i32>(chest->chestTrap);
  if (trap == 0) {
    reply = "This chest is not trapped.";
    return true;
  }
  // The roll itself (rollTrapDisarm, chance = chest->chestDisarm) needs a Ctx for the rng.
  // This command receives only the Session, so it cannot draw the roll yet. Nothing is changed.
  reply = "The disarm roll cannot be made from here yet; the chest is untouched.";
  return true;
}

bool disarmFinish(Session& s, i32 member, bool success, i32 monsterGuildLevel, Str& reply) {
  SquareState* chest = disarmChestHere(s);
  if (chest == nullptr) {
    reply = "There is no chest here.";
    return false;
  }
  Character* who = accMember(s, member);
  if (who == nullptr) {
    reply = "No such party member.";
    return false;
  }
  const i32 trap = static_cast<i32>(chest->chestTrap);
  if (trap == 0) {
    reply = "This chest is not trapped.";
    return false;
  }
  const char* name = disarmTrapName(trap);
  if (success) {
    // R4 (ch05): paid only when a trap is present (it is, here). The level discount uses the
    // first party member's current guild, not the opener's.
    const i64 award = disarmAward(static_cast<i32>(chest->chestDisarm), monsterGuildLevel,
                                  disarmGuildLevel(*accMember(s, 1)), accPartySize(s));
    who->experience += static_cast<decltype(who->experience)>(award);
    chest->chestTrap = ChestTrap::NotTrapped;
    reply = Str("You disarm the ") + name + ". Experience gained: " + std::to_string(award) + ".";
  } else {
    // The trap springs and the chest is no longer trapped. The per-trap effects on the party
    // are not applied here; see the limitations.
    chest->chestTrap = ChestTrap::NotTrapped;
    reply = Str("You fail, and the ") + name + " goes off!";
  }
  return true;
}

void register_disarm() {
  registerFeatureCommand({"inspect", Screen::Dungeon, &cmdInspect, "inspect  - tells what trap the chest on this square has"});
  registerFeatureCommand({"disarm", Screen::Dungeon, &cmdDisarm, "disarm <member>  - tries to disarm the chest trap on this square"});
}

bool duseParseIndex(const Str& w, i32& out) {
  if (w.empty()) return false;
  i64 v = 0;
  for (char ch : w) {
    if (ch < '0' || ch > '9') return false;
    v = v * 10 + (ch - '0');
    if (v > 100000) return false;
  }
  out = static_cast<i32>(v);
  return true;
}

Str duseUsage() {
  return "use <member> <slot>  - use an item from a pack slot (potions heal, scrolls cast)";
}

void duseSay(Str& reply, const Str& line) {
  if (!reply.empty()) reply += "\n";
  reply += line;
}

bool duseMustBeEquipped(i32 type) {
  return (type >= 1 && type <= 22) || type == 29 || type == 32 || type == 33 || type == 34;
}

bool duseConsumedWhenEmpty(i32 type) {
  return (type >= 23 && type <= 28) || type == 30 || type == 31;
}

bool duseAlignedToOther(const Item& it, const Character& c) {
  const i32 ia = duseItemAlign(it);
  if (ia == kDuseUnaligned) return false;
  return ia != duseCharAlign(c);
}

DuseFit duseFitOfItem(const Item& it, const Character& c) {
  const i32 ia = duseItemAlign(it);
  if (ia == kDuseUnaligned) return DuseFit::Same;
  const i32 d = duseAbs(ia - duseCharAlign(c));
  if (d == 0) return DuseFit::Same;
  if (d == 1) return DuseFit::Adjacent;
  return DuseFit::Opposed;
}

bool duseApplyStatMods(Character& c, const ItemDef& def, bool reversed) {
  (void)c;
  (void)def;
  (void)reversed;
  return false;
}

void duseGainSpellPoints(Character& c, i32 amount) {
  c.vitals.curSpellPoints += amount;
  if (c.vitals.curSpellPoints > c.vitals.maxSpellPoints) {
    c.vitals.curSpellPoints = c.vitals.maxSpellPoints;
  }
}

void duseYounger(Character& c, i32 years) {
  c.ageDays -= years * kDuseYearDays;
  if (c.ageDays < 0) c.ageDays = 0;
}

void duseOlder(Character& c, i32 days) {
  c.ageDays += days;
}

bool duseCastItemSpell(Session& s, Character& c, const Item& used, const SpellDef& spell) {
  (void)s;
  (void)c;
  (void)used;
  (void)spell;
  return false;
}

bool duseUse(Session& s, const Vec<Str>& w, Str& reply) {
  reply.clear();
  if (w.size() != 3) {
    reply = duseUsage();
    return true;
  }
  i32 memberNo = 0;
  i32 slotNo = 0;
  if (!duseParseIndex(w[1], memberNo) || !duseParseIndex(w[2], slotNo)) {
    reply = duseUsage();
    return true;
  }

  Character* c = accMember(s, memberNo);
  if (c == nullptr) {
    reply = "No such member.";  // UNKNOWN wording
    return true;
  }
  // sub15CD refuses silently for an incapacitated member (MAINMOD2.BAS:6085).
  // UNKNOWN: which deathState values count as incapacitated (M5483 mapping).
  if (c->deathState != DeathState::Alive) return true;

  // Slot 1 is the hands and never an item; an empty slot is silent.
  Item* it = accPackItem(s, memberNo, slotNo);
  if (it == nullptr) {
    reply = "No such slot.";  // UNKNOWN wording
    return true;
  }
  if (it->id <= 0) return true;
  const ItemDef* def = accItemDef(s, it->id);
  if (def == nullptr) return true;

  // ---- ItemUse.Problem, in the original's order (MAINMOD2.BAS:6085-6119) ----
  // A negative specialType means the item is not usable and says nothing.
  if (def->specialType < 0) return true;
  // NEED: ItemDef max-charges field, for the "doesn't appear to do much" check
  // (MAINMOD2.BAS:6093). Skipped until the field is named.
  if (it->charges <= 0) {
    reply = "\"" + c->name + "\", the Item is out of charges!";
    return true;
  }
  // The hands and worn-count limits are skipped here (EquipProblem with skipLimits).
  if (def->spellId > 0) {
    if (duseAlignedToOther(*it, *c)) {
      reply = "Nothing Happens.";
      return true;
    }
    if (duseMustBeEquipped(def->type) && !it->equipped) {
      reply = "Item must be Equipped to use!";
      return true;
    }
  }

  // ---- sub1149: spend the charge first (MAINMOD2.BAS:5684-5711) ----
  const Item used = *it;  // snapshot: the spell and effect read the item as it was
  it->charges -= 1;
  const bool gone = it->charges <= 0 && duseConsumedWhenEmpty(def->type);
  if (gone) *it = Item();  // the used-up item leaves the pack

  // ---- the spell, cast before the special effect (sub15CD order) ----
  if (def->spellId > 0) {
    if (const SpellDef* spell = accSpellById(s, def->spellId)) {
      duseCastItemSpell(s, *c, used, *spell);
    }
  }

  // ---- ApplySpecial (MAINMOD2.BAS:6145-6230) ----
  // Guild crests are silent here. Specials at or below zero do nothing more.
  if (def->specialType <= 0) return true;
  if (def->specialType >= kDuseGuildIssuedBase && def->specialType <= kDuseGuildIssuedLast) return true;

  const DuseFit fit = duseFitOfItem(used, *c);
  if (fit == DuseFit::Adjacent) {
    reply = "Nothing Happens.";  // the charge is already spent
    return true;
  }
  const bool reversed = fit == DuseFit::Opposed;

  bool statsApplied = false;
  switch (def->specialType) {
    case 1:  // potions: stat modifiers
      statsApplied = duseApplyStatMods(*c, *def, reversed);
      break;
    case 11:  // Scroll of Spells: 50 spell points (none when reversed)
      if (!reversed) duseGainSpellPoints(*c, kDuseScrollSpellPoints);
      break;
    case 12:  // Tome of Spells: 200 spell points
      if (!reversed) duseGainSpellPoints(*c, kDuseTomeSpellPoints);
      break;
    case 13:  // Potion of Youth: one year younger, then stat modifiers
      if (!reversed) duseYounger(*c, 1);
      statsApplied = duseApplyStatMods(*c, *def, reversed);
      break;
    case 14:  // Dragon's Blood: ten years younger, then stat modifiers
      if (!reversed) duseYounger(*c, 10);
      statsApplied = duseApplyStatMods(*c, *def, reversed);
      break;
    default:
      break;
  }

  // NEED: canWear / gear check after stat modifiers: out-of-reach gear comes off.

  // Kind 25 stat items age the user 28 days, whether or not the fit reversed the modifiers.
  if (def->type == 25 && statsApplied) {
    duseOlder(*c, kDuseKind25AgeDays);
    duseSay(reply, "You are now 4 week(s) older.");
  }
  return true;
}

