double giveVal(const Str& t) {
  size_t i = 0;
  while (i < t.size() && giveIsBlank(t[i])) ++i;
  double sign = 1.0;
  if (i < t.size() && (t[i] == '+' || t[i] == '-')) {
    if (t[i] == '-') sign = -1.0;
    ++i;
  }
  double v = 0.0;
  double scale = 1.0;
  bool point = false;
  for (; i < t.size(); ++i) {
    char c = t[i];
    if (c >= '0' && c <= '9') {
      if (!point) {
        v = v * 10.0 + (c - '0');
      } else {
        scale /= 10.0;
        v += (c - '0') * scale;
      }
    } else if (c == '.' && !point) {
      point = true;
    } else {
      break;
    }
  }
  return sign * v;
}

bool giveCLng(const Str& t, i64& out) {
  size_t b = 0;
  size_t e = t.size();
  while (b < e && giveIsBlank(t[b])) ++b;
  while (e > b && giveIsBlank(t[e - 1])) --e;
  if (b == e) return false;
  bool neg = false;
  if (t[b] == '+' || t[b] == '-') {
    neg = (t[b] == '-');
    ++b;
  }
  i64 whole = 0;
  bool sawDigit = false;
  bool point = false;
  int firstFrac = -1;
  bool restNonzero = false;
  int fracIdx = 0;
  for (size_t i = b; i < e; ++i) {
    char c = t[i];
    if (c >= '0' && c <= '9') {
      sawDigit = true;
      if (!point) {
        if (whole > 100000000000LL) return false;
        whole = whole * 10 + (c - '0');
      } else {
        if (fracIdx == 0) firstFrac = c - '0';
        else if (c != '0') restNonzero = true;
        ++fracIdx;
      }
    } else if (c == '.' && !point) {
      point = true;
    } else {
      return false;
    }
  }
  if (!sawDigit) return false;
  bool up = firstFrac > 5 || (firstFrac == 5 && restNonzero) ||
            (firstFrac == 5 && !restNonzero && (whole % 2 == 1));
  if (up) ++whole;
  out = neg ? -whole : whole;
  return true;
}

bool giveMember(const Str& text, i32& member) {
  i64 n = 0;
  if (!giveCLng(text, n)) return false;
  if (n < 1 || n > kPartyMaxSize) return false;
  member = static_cast<i32>(n);
  return true;
}

GiveGoldStep giveGoldAmount(const Str& text, i64 heldUnits, i64& amountUnits, Str& refusal) {
  if (text.empty()) return GiveGoldStep::Nothing;
  double v = giveVal(text);
  if (v < 1.0) return GiveGoldStep::Nothing;
  double held = static_cast<double>(heldUnits) / static_cast<double>(kGiveGoldUnit);
  if (v > held) {
    refusal = kGiveNotEnoughGold;
    return GiveGoldStep::Refused;
  }
  i64 gold = 0;
  if (!giveCLng(text, gold)) return GiveGoldStep::Nothing;
  if (gold < 1) return GiveGoldStep::Nothing;
  i64 units = gold * kGiveGoldUnit;
  // UNKNOWN: CLng can round up past what is held (1.5 held, "1.5" typed -> 2). Refused, as for Val.
  if (units > heldUnits) {
    refusal = kGiveNotEnoughGold;
    return GiveGoldStep::Refused;
  }
  amountUnits = units;
  return GiveGoldStep::Give;
}

i32 giveSlot(const Str& text) {
  i64 n = 0;
  if (!giveCLng(text, n)) return -1;
  if (n < 2 || n > kPackSlots) return -1;
  return static_cast<i32>(n);
}

Item* giveFreeSlot(Session& s, i32 member1) {
  for (i32 slot = 2; slot <= kPackSlots; ++slot) {
    Item* it = accPackItem(s, member1, slot);
    if (it != nullptr && it->id <= 0) return it;
  }
  return nullptr;
}

bool giveGold(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() != 5) {
    reply = kGiveUsage;
    return true;
  }
  i32 from = 0;
  i32 to = 0;
  if (!giveMember(w[2], from) || !giveMember(w[3], to)) {
    reply = kGiveUsage;
    return true;
  }
  Character* giver = accMember(s, from);
  Character* receiver = accMember(s, to);
  if (giver == nullptr || receiver == nullptr) {
    reply = kGiveNoMember;
    return true;
  }
  if (from == to) {
    // UNKNOWN: the reference offers everyone but the giver; the port's refusal wording is its own.
    reply = "Cannot give to yourself.";
    return true;
  }
  Currency& held = accGoldOnHand(*giver);
  i64 units = 0;
  Str refusal;
  switch (giveGoldAmount(w[4], held, units, refusal)) {
    case GiveGoldStep::Refused:
      reply = refusal;
      return true;
    case GiveGoldStep::Nothing:
      reply = "Nothing given.";  // UNKNOWN: the reference prints nothing here
      return true;
    case GiveGoldStep::Give:
      break;
  }
  held -= units;
  accGoldOnHand(*receiver) += units;
  // UNKNOWN: the reference's success line for gold is not in the packet.
  reply = "Gave " + std::to_string(units / kGiveGoldUnit) + " gold.";
  return true;
}

bool giveItem(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() != 5) {
    reply = kGiveUsage;
    return true;
  }
  i32 from = 0;
  i32 to = 0;
  if (!giveMember(w[2], from) || !giveMember(w[4], to)) {
    reply = kGiveUsage;
    return true;
  }
  Character* giver = accMember(s, from);
  Character* receiver = accMember(s, to);
  if (giver == nullptr || receiver == nullptr) {
    reply = kGiveNoMember;
    return true;
  }
  if (from == to) {
    reply = "Cannot give to yourself.";  // UNKNOWN, as for gold
    return true;
  }
  // The reference treats "" and "0" as no item: nothing is handed over.
  if (w[3].empty() || w[3] == "0") {
    reply = "Nothing given.";  // UNKNOWN
    return true;
  }
  const i32 slot = giveSlot(w[3]);
  if (slot < 0) {
    reply = kGiveNoItem;
    return true;
  }
  Item* src = accPackItem(s, from, slot);
  if (src == nullptr || src->id <= 0) {
    reply = kGiveNoItem;
    return true;
  }
  if (src->equipped) {
    reply = kGiveItemEquipped;
    return true;
  }
  if (src->guildIssued) {
    reply = kGiveGuildIssued;
    return true;
  }
  // The receiver's room is checked before anything leaves the giver.
  Item* dst = giveFreeSlot(s, to);
  if (dst == nullptr) {
    reply = "\"" + receiver->name + "\" has no free slots!";  // UNKNOWN: port wording
    return true;
  }
  *dst = *src;
  *src = Item();
  reply = "Gave item " + w[3] + ".";  // UNKNOWN: success line not in packet
  return true;
}

bool cmdGive(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() < 2) {
    reply = kGiveUsage;
    return true;
  }
  if (w[1] == "gold") return giveGold(s, w, reply);
  if (w[1] == "item") return giveItem(s, w, reply);
  reply = kGiveUsage;
  return true;
}

void register_give() {
  registerFeatureCommand({"give", Screen::Town, &cmdGive, "give gold <from> <to> <amount> | give item <from> <slot> <to>  - hand gold or a pack item to another member"});
  registerFeatureCommand({"give", Screen::Dungeon, &cmdGive, "give gold <from> <to> <amount> | give item <from> <slot> <to>  - hand gold or a pack item to another member"});
}

Str glGet(const Session& s, const Str& key) {
  auto it = s.featureState.find(key);
  return it == s.featureState.end() ? Str() : it->second;
}

i64 glParseInt(const Str& t, bool& ok) {
  ok = false;
  size_t i = 0;
  bool neg = false;
  if (i < t.size() && t[i] == '-') {
    neg = true;
    ++i;
  }
  if (i >= t.size()) return 0;
  i64 v = 0;
  for (; i < t.size(); ++i) {
    if (t[i] < '0' || t[i] > '9') return 0;
    v = v * 10 + static_cast<i64>(t[i] - '0');
  }
  ok = true;
  return neg ? -v : v;
}

Str glTrim(const Str& t) {
  const size_t b = t.find_first_not_of(" \t");
  if (b == Str::npos) return Str();
  const size_t e = t.find_last_not_of(" \t");
  return t.substr(b, e - b + 1);
}

i64 glToday(const Session& s) {
  bool ok = false;
  const i64 d = glParseInt(glGet(s, "guildlog.today"), ok);
  return ok ? d : 0;
}

i32 glGuildCount(const Session& s) {
  const size_t n = s.data.guilds.size();
  const size_t cap = static_cast<size_t>(kGuildCount);
  return static_cast<i32>(n < cap ? n : cap);
}

Str glGuildName(const Session& s, i32 guild) {
  if (guild < 0 || guild >= glGuildCount(s)) return std::to_string(guild);
  return glTrim(s.data.guilds[static_cast<size_t>(guild)].name);
}

Str glLeaderName(Session& s) {
  Character* c = accMember(s, 1);
  return c != nullptr ? glTrim(c->name) : Str();
}

Str glPack(const GuildlogRow& r) {
  return std::to_string(r.guild) + "|" + std::to_string(r.day) + "|" + r.text;
}

bool glUnpack(const Str& raw, GuildlogRow& r) {
  const size_t p1 = raw.find('|');
  if (p1 == Str::npos) return false;
  const size_t p2 = raw.find('|', p1 + 1);
  if (p2 == Str::npos) return false;
  bool okG = false;
  bool okD = false;
  const i64 g = glParseInt(raw.substr(0, p1), okG);
  const i64 d = glParseInt(raw.substr(p1 + 1, p2 - p1 - 1), okD);
  if (!okG || !okD) return false;
  r.guild = static_cast<i32>(g);
  r.day = d;
  r.text = raw.substr(p2 + 1);
  return true;
}

Vec<GuildlogRow> glLoadAll(const Session& s) {
  Vec<GuildlogRow> rows;
  bool ok = false;
  const i64 n = glParseInt(glGet(s, "guildlog.count"), ok);
  if (!ok || n <= 0) return rows;
  for (i64 i = 0; i < n; ++i) {
    GuildlogRow r;
    if (glUnpack(glGet(s, glEntryKey(i)), r)) rows.push_back(r);
  }
  return rows;
}

void glStoreAll(Session& s, const Vec<GuildlogRow>& rows) {
  bool ok = false;
  i64 old = glParseInt(glGet(s, "guildlog.count"), ok);
  if (!ok || old < 0) old = 0;
  const i64 n = static_cast<i64>(rows.size());
  for (i64 i = 0; i < n; ++i) s.featureState[glEntryKey(i)] = glPack(rows[static_cast<size_t>(i)]);
  for (i64 i = n; i < old; ++i) s.featureState.erase(glEntryKey(i));
  s.featureState["guildlog.count"] = std::to_string(n);
}

Str glPrefix(i64 day, i64 today) {
  const i64 gap = day > today ? day - today : today - day;
  if (gap == 0) return "TODAY: ";
  if (gap == 1) return "1 DAY AGO: ";
  return std::to_string(gap) + " DAYS AGO: ";
}

Str glJoinArgs(const Vec<Str>& w, size_t from) {
  Str out;
  for (size_t i = from; i < w.size(); ++i) {
    if (!out.empty()) out += " ";
    out += w[i];
  }
  return out;
}

bool glParseGuild(const Session& s, const Str& arg, i32& guild) {
  const Str want = accLower(glTrim(arg));
  if (want.empty()) return false;
  const i32 count = glGuildCount(s);
  bool ok = false;
  const i64 g = glParseInt(want, ok);
  if (ok) {
    if (g < 0 || g >= static_cast<i64>(count)) return false;
    guild = static_cast<i32>(g);
    return true;
  }
  for (i32 i = 0; i < count; ++i) {
    if (accLower(glGuildName(s, i)) == want) {
      guild = i;
      return true;
    }
  }
  return false;
}

bool glNeedsCleaning(const Session& s) {
  const i64 total = static_cast<i64>(glLoadAll(s).size());
  i64 guilds = static_cast<i64>(glGuildCount(s));
  if (guilds < 1) guilds = 1;
  return total > static_cast<i64>(kGuildLogKeepOnClean) * guilds;
}

void glArchive(Session& s, const Vec<GuildlogRow>& removed, i64 today) {
  Str text = glGet(s, "guildlog.text");
  text += "BEGIN GUILD LOG CLEAN (day " + std::to_string(today) + ")\n";
  text += "Done By: \"" + glLeaderName(s) + "\"\n";
  for (const GuildlogRow& r : removed) {
    text += "GUILD: " + glGuildName(s, r.guild) + "\n";
    text += " DATE: " + std::to_string(r.day) + "\n";
    text += "  LOG: " + r.text + "\n";
  }
  s.featureState["guildlog.text"] = text;
}

bool glClean(Session& s, Str& reply) {
  if (!glNeedsCleaning(s)) {
    reply = "The guild log is not over the cleaning threshold.";
    return true;
  }
  const Vec<GuildlogRow> rows = glLoadAll(s);
  const i64 keep = static_cast<i64>(kGuildLogKeepOnClean);
  const i64 total = static_cast<i64>(rows.size());
  if (total <= keep) {
    reply = "Nothing to clean.";
    return true;
  }
  const i64 cut = total - keep;
  const Vec<GuildlogRow> removed(rows.begin(), rows.begin() + static_cast<std::ptrdiff_t>(cut));
  const Vec<GuildlogRow> kept(rows.begin() + static_cast<std::ptrdiff_t>(cut), rows.end());
  glArchive(s, removed, glToday(s));
  glStoreAll(s, kept);
  reply = "Guild log cleaned: " + std::to_string(cut) + " entries removed, " + std::to_string(keep) + " kept.";
  return true;
}

bool cmdGuildlog(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() < 2) {
    reply = "Usage: guildlog <guild number 0-11> | guildlog clean";
    return false;
  }
  if (accLower(w[1]) == "clean") return glClean(s, reply);

  i32 guild = 0;
  if (!glParseGuild(s, glJoinArgs(w, 1), guild)) {
    reply = "No such guild.";
    return false;
  }

  const Vec<GuildlogRow> rows = glLoadAll(s);
  const i64 today = glToday(s);
  Str out;
  bool first = true;
  // Newest first, as GuildLog.For reverses the list.
  for (size_t i = rows.size(); i-- > 0;) {
    if (rows[i].guild != guild) continue;
    if (!first) out += "\n";
    out += glPrefix(rows[i].day, today) + rows[i].text;
    first = false;
  }
  reply = out.empty() ? Str("No Entries") : out;
  return true;
}

void guildlogAppend(Session& s, i32 guild, i64 day, const Str& text) {
  Vec<GuildlogRow> rows = glLoadAll(s);
  GuildlogRow r;
  r.guild = guild;
  r.day = day;
  r.text = text;
  rows.push_back(r);
  glStoreAll(s, rows);
}

void guildlogSeedNewGame(Session& s, const Vec<Str>& masterNames) {
  if (glGet(s, "guildlog.seeded") == "1") return;
  Vec<GuildlogRow> rows = glLoadAll(s);
  const i64 day = glToday(s);
  const i32 count = glGuildCount(s);
  for (i32 g = 0; g < count && static_cast<size_t>(g) < masterNames.size(); ++g) {
    const Str who = glTrim(masterNames[static_cast<size_t>(g)]);
    if (who.empty()) continue;
    GuildlogRow r;
    r.guild = g;
    r.day = day;
    r.text = glWroteAppointed(who);
    rows.push_back(r);
  }
  glStoreAll(s, rows);
  s.featureState["guildlog.seeded"] = "1";
}

void register_guildlog() {
  registerFeatureCommand({"guildlog", Screen::Town, &cmdGuildlog,
                          "guildlog <guild 0-11>  - show a guild's log;  guildlog clean  - keep the newest 50"});
}

HallRow hallRow(i32 k) {
  switch (k) {
    case 0: return {"Strongest", "Strongest Character"};
    case 1: return {"Smartest", "most Intelligent Character"};
    case 2: return {"Wisest", "Wisest Character"};
    case 3: return {"Healthiest", "Healthiest Character"};
    case 4: return {"Most Attractive", "most Attractive Character"};
    case 5: return {"Quickest", "Quickest Character"};
    case 6: return {"Deadliest Creature Defeated", "most powerful creature defeated"};
    case 7: return {"Most Experienced Explorer", "most experience"};
    case 8: return {"Wealthiest Explorer", "wealthiest character"};
    case 9: return {"Master of Fighting", "highest fighting ability"};
    case 10: return {"Master of Magic", "highest spell knowledge & power level"};
    default: return {"Master of Thieving", "highest thieving ability"};
  }
}

Str hallKey(i32 k, const char* field) {
  return "hall." + std::to_string(k) + "." + field;
}

Str hallGetS(const Session& s, i32 k, const char* field) {
  auto it = s.featureState.find(hallKey(k, field));
  return it == s.featureState.end() ? Str() : it->second;
}

i64 hallParseI(const Str& t) {
  bool neg = false;
  size_t i = 0;
  if (i < t.size() && t[i] == '-') {
    neg = true;
    ++i;
  }
  i64 v = 0;
  for (; i < t.size(); ++i) {
    char c = t[i];
    if (c < '0' || c > '9') break;
    v = v * 10 + (c - '0');
  }
  return neg ? -v : v;
}

i64 hallGetI(const Session& s, i32 k, const char* field) {
  return hallParseI(hallGetS(s, k, field));
}

Str hallTrimEnd(const Str& t) {
  size_t n = t.size();
  while (n > 0 && t[n - 1] == ' ') --n;
  return t.substr(0, n);
}

Str hallCurrencyText(i64 v) {
  bool neg = v < 0;
  i64 a = neg ? -v : v;
  i64 whole = a / 10000;
  i64 frac = a % 10000;
  Str out = neg ? "-" : "";
  out += std::to_string(whole);
  if (frac != 0) {
    Str digits;
    for (int d = 0; d < 4; ++d) {
      digits += static_cast<char>('0' + frac / 1000);
      frac = (frac % 1000) * 10;
    }
    while (!digits.empty() && digits.back() == '0') digits.pop_back();
    out += "." + digits;
  }
  return out;
}

Str hallValueText(i32 k, i64 v) {
  if (k == kHallDeadliest) return "Monster id " + std::to_string(v);  // UNKNOWN: creature record value text (FRMHALL)
  if (k == kHallWealthiest) return hallCurrencyText(v) + " gold";     // UNKNOWN: exact gold wording
  if (k >= kHallFirstSkill && k <= kHallLastSkill) return std::to_string(v) + "%";  // UNKNOWN: skill percentage wording
  return std::to_string(v);
}

i64 hallOfferValue(const Character& c, i32 k) {
  switch (k) {
    case kHallConstitution: return c.vitals.maxHits;
    case kHallMostExperience: return c.experience;
    case kHallWealthiest: return c.wallet.goldOnHand + c.wallet.goldInBank;
    default: return c.abilities.stats[static_cast<size_t>(k)];
  }
}

Str hallDescribe(const Session& s, i32 k) {
  HallRow row = hallRow(k);
  Str holder = hallGetS(s, k, "holder");
  i64 day = hallGetI(s, k, "day");
  Str who = day != 0 ? "Set on day " + std::to_string(day) + " by " : Str("Set by Original RecordHolder ");
  Str out = Str(row.heading) + "\n";
  out += who + "\"" + holder + "\"\n";
  out += hallValueText(k, hallGetI(s, k, "value"));
  return out;
}

bool hallCheck(Session& s, i32 k, const Str& name, i64 value, i64 key, i64 day,
               bool alone, Str& announce) {
  if (key <= hallGetI(s, k, "key")) return false;  // did not beat the record (creature: by power)
  bool alreadyTheirs = hallGetS(s, k, "holder") == name;
  s.featureState[hallKey(k, "holder")] = name;
  s.featureState[hallKey(k, "key")] = std::to_string(key);
  s.featureState[hallKey(k, "value")] = std::to_string(value);
  s.featureState[hallKey(k, "day")] = std::to_string(day);
  if (alreadyTheirs || k == kHallDeadliest) return false;
  HallRow row = hallRow(k);
  announce = alone
                 ? "You have just set the record for " + Str(row.logName) + "!"
                 : "\"" + name + "\" just set the record for " + Str(row.logName) + "!";
  return true;
}

bool cmdHall(Session& s, const Vec<Str>& w, Str& reply) {
  (void)w;
  Str out = "Hall of Records";
  for (i32 k = 0; k < kHallCount; ++k) out += "\n" + hallDescribe(s, k);
  reply = out;
  return true;
}

Vec<Str> hallArrivalUpdate(Session& s, i64 daySerial) {
  Vec<Str> lines;
  const i32 n = accPartySize(s);
  const bool alone = n == 1;
  for (i32 m = 1; m <= n; ++m) {
    const Character* c = accMember(s, m);
    if (c == nullptr) continue;
    const Str name = hallTrimEnd(c->name);
    for (i32 k : kArrivalRecords) {
      const i64 offer = hallOfferValue(*c, k);
      Str said;
      if (hallCheck(s, k, name, offer, offer, daySerial, alone, said)) lines.push_back(said);
    }
  }
  return lines;
}

bool hallRecordKill(Session& s, i32 member1, i32 monsterId, i64 power, i64 daySerial, Str& announce) {
  const Character* c = accMember(s, member1);
  if (c == nullptr) return false;
  return hallCheck(s, kHallDeadliest, hallTrimEnd(c->name), monsterId, power, daySerial,
                   accPartySize(s) == 1, announce);
}

void register_hall() {
  registerFeatureCommand({"hall", Screen::Town, &cmdHall, "hall  - the Hall of Records: the twelve town-wide bests"});
}

Str upperCase(const Str& t) {
  Str r = t;
  for (char& c : r) {
    if (c >= 'a' && c <= 'z') c = static_cast<char>(c - 'a' + 'A');
  }
  return r;
}

int parseInt(const Str& t, int fallback) {
  if (t.empty()) return fallback;
  int v = 0;
  for (char c : t) {
    if (c < '0' || c > '9') return fallback;
    v = v * 10 + (c - '0');
    if (v > 1000000) return fallback;
  }
  return v;
}

Str joinFrom(const Vec<Str>& w, std::size_t from) {
  Str r;
  for (std::size_t i = from; i < w.size(); ++i) {
    if (!r.empty()) r += ' ';
    r += w[i];
  }
  return r;
}

Str factStr(const Session& s, const Str& kind, const Str& name, const char* field) {
  auto it = s.featureState.find(Str(kRecordPrefix) + kind + "." + name + "." + field);
  return it == s.featureState.end() ? Str() : it->second;
}

template <std::size_t N>
Str nameAt(const char* const (&names)[N], int i) {
  if (i >= 0 && i < static_cast<int>(N)) return Str(names[i]);
  return Str();
}

template <std::size_t N>
Str listedBits(int mask, const char* const (&names)[N]) {
  Str r;
  for (std::size_t b = 0; b < N; ++b) {
    if ((mask >> b) & 1) {
      if (!r.empty()) r += ", ";
      r += names[b];
    }
  }
  return r;
}

Vec<LibEntry> entries(const Session& s) {
  Vec<LibEntry> out;
  const std::size_t prefixLen = Str(kRecordPrefix).size();
  for (const auto& kv : s.featureState) {
    const Str& key = kv.first;
    if (key.compare(0, prefixLen, kRecordPrefix) != 0) continue;
    Str rest = key.substr(prefixLen);
    std::size_t dot = rest.find('.');
    if (dot == Str::npos) continue;
    Str kind = rest.substr(0, dot);
    Str name = rest.substr(dot + 1);
    if (name.find('.') != Str::npos) continue;  // a fact key, not a record
    if (kind != kKindMonster && kind != kKindItem) continue;
    int grade = parseInt(kv.second, 0);
    if (grade < kLibVeryLittle) continue;  // grade 0 = not in the Library
    out.push_back(LibEntry{kind, name, grade});
  }
  std::sort(out.begin(), out.end(), [](const LibEntry& a, const LibEntry& b) {
    Str ua = upperCase(a.name);
    Str ub = upperCase(b.name);
    if (ua != ub) return ua < ub;
    return a.kind < b.kind;
  });
  return out;
}

Str monsterPage(const Session& s, const LibEntry& e) {
  const Str& name = e.name;
  Str out = name + "\n";
  if (e.grade >= kLibVeryLittle) {
    int size = parseInt(factStr(s, kKindMonster, name, "size"), -1);
    Str word = nameAt(kSizes, size);
    out += "Size: " + (word.empty() ? Str("oddly") : word) + "\n";  // Librarian.Size(): "oddly" when out of range
  }
  if (e.grade >= kLibAGoodDealMore) {
    // UNKNOWN: class line of the grade-2 page (T-F) is not in evidence; placeholder reads the fact "class".
    Str cls = factStr(s, kKindMonster, name, "class");
    out += "Class: " + (cls.empty() ? Str("Unknown") : cls) + "\n";
  }
  if (e.grade >= kLibAlmostEverything) {
    // UNKNOWN: grade-3 statistics layout and its "nobody knows" wording (T-F) are not in evidence.
    out += "Statistics: " + factStr(s, kKindMonster, name, "stats") + "\n";
    out += "What it can do is not known.\n";
  }
  if (e.grade >= kLibEverything) {
    int align = parseInt(factStr(s, kKindMonster, name, "alignment"), -1);
    Str alignWord = nameAt(kAlignments, align);
    if (!alignWord.empty()) out += "Alignment: " + alignWord + "\n";
    int props = parseInt(factStr(s, kKindMonster, name, "properties"), 0);
    int attacks = parseInt(factStr(s, kKindMonster, name, "attacks"), 0);
    int spells = parseInt(factStr(s, kKindMonster, name, "spells"), 0);
    int resist = parseInt(factStr(s, kKindMonster, name, "resistances"), 0);
    Str p = listedBits(props, kMonsterProperties);
    Str a = listedBits(attacks, kMonsterAttacks);
    Str sp = listedBits(spells, kSpellSchools);
    Str r = listedBits(resist, kResistances);
    out += "Properties: " + (p.empty() ? Str("None") : p) + "\n";  // UNKNOWN: "None" wording
    out += "Attacks: " + (a.empty() ? Str("None") : a) + "\n";
    out += "Spells: " + (sp.empty() ? Str("None") : sp) + "\n";
    out += "Resistances: " + (r.empty() ? Str("None") : r) + "\n";
  }
  return out;
}

Str itemPage(const Session& s, const LibEntry& e) {
  Str out = e.name + "\n";
  if (e.grade >= kLibEverything) {
    int abilities = parseInt(factStr(s, kKindItem, e.name, "abilities"), 0);
    Str a = listedBits(abilities, kItemAbilities);
    out += "Abilities: " + (a.empty() ? Str("None") : a) + "\n";
    // UNKNOWN: damage modifier, curse, spell, effects and guild levels (T-G) are not in evidence.
  } else {
    // UNKNOWN: wording and content of the below-4 item page (T-G) are not in evidence.
    out += "Not everything is known.\n";
  }
  return out;
}

Str pageFor(const Session& s, const LibEntry& e) {
  return e.kind == kKindMonster ? monsterPage(s, e) : itemPage(s, e);
}

bool findEntry(const Vec<LibEntry>& all, const Str& kind, const Str& name, LibEntry& out) {
  Str want = upperCase(name);
  for (const LibEntry& e : all) {
    if (e.kind == kind && upperCase(e.name) == want) {
      out = e;
      return true;
    }
  }
  return false;
}

bool cmdLibrary(Session& s, const Vec<Str>& w, Str& reply) {
  Vec<LibEntry> all = entries(s);
  if (w.size() <= 1) {
    if (all.empty()) {
      reply = "The library is empty.";  // UNKNOWN: wording
      return true;
    }
    Str out;
    for (const LibEntry& e : all) {
      out += e.name + "\n";
    }
    reply = out;
    return true;
  }

  const Str& sub = w[1];
  if (sub == "search") {
    Str typed = upperCase(joinFrom(w, 2));
    Vec<std::size_t> hits;
    for (std::size_t i = 0; i < all.size(); ++i) {
      Str nm = upperCase(all[i].name);
      if (nm.compare(0, typed.size(), typed) == 0) hits.push_back(i);
    }
    if (hits.empty()) {
      reply = "No match was found.";
    } else if (hits.size() == 1) {
      reply = pageFor(s, all[hits[0]]);  // the one match is selected, so its page shows
    } else {
      reply = "ambiguous!";
    }
    return true;
  }

  if (sub == "monster" || sub == "item") {
    Str name = joinFrom(w, 2);
    if (name.empty()) {
      reply = kUsage;
      return true;
    }
    LibEntry e;
    const Str kind = (sub == "monster") ? Str(kKindMonster) : Str(kKindItem);
    if (!findEntry(all, kind, name, e)) {
      reply = "There is no entry for " + name + " in the library.";  // UNKNOWN: wording
      return true;
    }
    reply = pageFor(s, e);
    return true;
  }

  reply = kUsage;
  return true;
}

