}

Vec<Str> seerItemNames(const Session& s) {
  Vec<Str> out;
  for (const ItemDef& d : s.data.items) out.push_back(d.name);
  return out;
}

Vec<Str> seerMemberNames(const Session& s) {
  Vec<Str> out;
  for (i32 i = 1; i <= accPartySize(s); ++i) out.push_back(accMember(const_cast<Session&>(s), i)->name);
  return out;
}

Str seerJoinWords(const Vec<Str>& w, size_t from) {
  Str out;
  for (size_t i = from; i < w.size(); ++i) {
    if (i > from) out += ' ';
    out += w[i];
  }
  return out;
}

bool seerHasPending(const Session& s) {
  auto it = s.featureState.find(kSeerKindKey);
  return it != s.featureState.end() && !it->second.empty();
}

Str seerGet(const Session& s, const char* key) {
  auto it = s.featureState.find(key);
  return it == s.featureState.end() ? Str() : it->second;
}

void seerClearPending(Session& s) {
  s.featureState.erase(kSeerKindKey);
  s.featureState.erase(kSeerNameKey);
  s.featureState.erase(kSeerLevelKey);
}

void seerSetPendingPerson(Session& s, const Str& name, i32 level) {
  s.featureState[kSeerKindKey] = "person";
  s.featureState[kSeerNameKey] = name;
  s.featureState[kSeerLevelKey] = std::to_string(level);
}

bool seerTakeGold(Session& s, Currency amount) {
  Currency total = 0;
  for (i32 i = 1; i <= accPartySize(s); ++i) total += accGoldOnHand(*accMember(s, i));
  if (total < amount) return false;
  Currency left = amount;
  for (i32 i = 1; i <= accPartySize(s) && left > 0; ++i) {
    Currency& gold = accGoldOnHand(*accMember(s, i));
    const Currency take = gold < left ? gold : left;
    gold -= take;
    left -= take;
  }
  return true;
}

bool seerThingLevel(const Session& s, bool item, i32 index, i32& level) {
  (void)s;
  (void)item;
  (void)index;
  (void)level;
  return false;
}

bool seerSearchThing(Session& s, bool item, const Str& typed, Str& reply) {
  const Vec<Str> names = item ? seerItemNames(s) : seerMonsterNames(s);
  const SeerMatchResult m = seerMatch(typed, names);
  if (m.kind == SeerMatchKind::None) {
    reply = item ? kSeerNoSuchItem + typed + "'." : kSeerNoSuchMonster + typed + "'.";
    return true;
  }
  if (m.kind == SeerMatchKind::Several) {
    reply = item ? kSeerSeveralItems : kSeerSeveralMonsters;
    return true;
  }
  i32 level = 0;
  if (!seerThingLevel(s, item, m.index, level)) {
    reply = kSeerCannotDetect;
    return true;
  }
  reply = kSeerCannotDetect;  // unreachable until seerThingLevel is linked
  return true;
}

bool seerSearchPerson(Session& s, const Str& typed, Str& reply) {
  const Vec<Str> names = seerMemberNames(s);
  const SeerMatchResult m = seerMatch(typed, names);
  if (m.kind == SeerMatchKind::None) {
    reply = "I am unable to locate a character called '" + typed + "'.";  // UNKNOWN: text not in reference
    return true;
  }
  if (m.kind == SeerMatchKind::Several) {
    reply = "The name you provided is shared by more than one character.";  // UNKNOWN: text not in reference
    return true;
  }
  Character* c = accMember(s, m.index + 1);
  const i32 level = c->location.dungeonLevel;
  if (level < 1) {
    reply = kSeerInTheCity;
    return true;
  }
  const i64 fee = seerPersonFee(level);
  seerSetPendingPerson(s, c->name, level);
  reply = "I can feel their presense.  I will need " + seerMoney(fee) + " to attempt to locate " + c->name +
          ".\nIs this acceptable?";
  return true;
}

bool seerAnswer(Session& s, bool yes, Str& reply) {
  if (!seerHasPending(s)) {
    reply = "Nothing is awaiting your answer.";
    return true;
  }
  if (!yes) {
    seerClearPending(s);
    reply = "Cancelled.";  // UNKNOWN: reference shows no text for declining
    return true;
  }
  const Str name = seerGet(s, kSeerNameKey);
  i64 levelWide = 0;
  accParseInt(seerGet(s, kSeerLevelKey), levelWide);
  const i32 level = static_cast<i32>(levelWide);
  seerClearPending(s);

  const i32 member = accMemberByName(s, name);
  if (member == 0) {
    reply = "Nothing is awaiting your answer.";
    return true;
  }
  if (!seerTakeGold(s, seerPersonFee(level))) {
    reply = kSeerNotEnoughGold;
    return true;
  }
  Ctx ctx = s.ctx();
  Character* c = accMember(s, member);
  reply = seerLocateCharacterReply(ctx, c->name, level, c->location.x, c->location.y,
                                   c->deathState != DeathState::Alive);
  return true;
}

bool seerCommand(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() < 2) {
    reply = "seer creature <name>  - pay the Seer to search for a creature\n"
            "seer item <name>  - pay the Seer to search for an item\n"
            "seer person <name>  - pay the Seer to locate a person\n"
            "seer yes  /  seer no  - answer the Seer's offer";
    return true;
  }
  const Str sub = accLower(w[1]);
  if (sub == "yes" || sub == "no") return seerAnswer(s, sub == "yes", reply);
  if (sub == "creature" || sub == "item") {
    if (w.size() < 3) {
      reply = "Name what you seek.";
      return true;
    }
    return seerSearchThing(s, sub == "item", seerJoinWords(w, 2), reply);
  }
  if (sub == "person") {
    if (w.size() < 3) {
      reply = "Name what you seek.";
      return true;
    }
    return seerSearchPerson(s, seerJoinWords(w, 2), reply);
  }
  reply = "The Seer does not understand that request.";
  return true;
}

void register_seer() {
  registerFeatureCommand({"seer", Screen::Town, &seerCommand,
                          "seer <creature|item|person> <name> | seer yes | seer no  - the Seer searches for a fee"});
}

bool swapParseInt(const Str& text, i32& out) {
  size_t i = 0;
  size_t n = text.size();
  while (i < n && text[i] == ' ') ++i;
  while (n > i && text[n - 1] == ' ') --n;
  if (i >= n) return false;
  bool neg = false;
  if (text[i] == '+' || text[i] == '-') {
    neg = (text[i] == '-');
    ++i;
  }
  if (i >= n) return false;
  i64 v = 0;
  for (; i < n; ++i) {
    const char c = text[i];
    if (c < '0' || c > '9') return false;
    v = v * 10 + (c - '0');
    if (v > 1000000000LL) return false;
  }
  out = static_cast<i32>(neg ? -v : v);
  return true;
}

bool swapCombinableKind(i32 kind) {
  return kind == 23 || kind == 24 || kind == 25 || kind == 26 ||
         kind == 27 || kind == 28 || kind == 30 || kind == 31;
}

bool swapItemKind(const Session& s, const Item& it, i32& kind) {
  const ItemDef* def = accItemDef(s, it.id);
  if (def == nullptr) return false;
  kind = 0;
  return false;
}

SwapCombineCheck swapCombineCheck(bool firstKnown, bool secondKnown,
                                  bool firstCombinableKind, bool sameClass,
                                  bool sameId, bool sameAlignment,
                                  i64 chargesFirst, i64 chargesSecond) {
  if (!firstKnown) return SwapCombineCheck::NotIdentifiedFirst;
  if (!secondKnown) return SwapCombineCheck::NotIdentifiedSecond;
  if (!firstCombinableKind) return SwapCombineCheck::ClassCannotCombine;
  if (!sameClass) return SwapCombineCheck::NotCompatibleClass;
  if (!sameId) return SwapCombineCheck::NotSameType;
  if (!sameAlignment) return SwapCombineCheck::NotCompatibleAlignment;
  // CONFLICT: the original does not check this sum and stops with VB run-time error 6
  // ("Overflow") past 32,767. This port refuses instead and changes nothing.
  const i64 sum = chargesFirst + chargesSecond;
  if (sum > kSwapChargeMax || sum < kSwapChargeMin) return SwapCombineCheck::Overflow;
  return SwapCombineCheck::Ok;
}

Str swapCombineText(SwapCombineCheck c, i32 slotFirst, i32 slotSecond) {
  const Str a = std::to_string(slotFirst);
  const Str b = std::to_string(slotSecond);
  switch (c) {
    case SwapCombineCheck::NotIdentifiedFirst:
      return "Item #" + a + " Not Completely Identified!";
    case SwapCombineCheck::NotIdentifiedSecond:
      return "Item #" + b + " Not Completely Identified!";
    case SwapCombineCheck::ClassCannotCombine:
      return "Item Class cannot be Combined!";
    case SwapCombineCheck::NotCompatibleClass:
      return "STORE: Item #" + b + " is not compatible class.";
    case SwapCombineCheck::NotSameType:
      return "STORE: Item #" + b + " is not of the same type.";
    case SwapCombineCheck::NotCompatibleAlignment:
      return "STORE: Item #" + b + " is not compatible Alignment.";
    case SwapCombineCheck::Overflow:
      return "STORE: Item #" + b + " not combined: the charges would pass 32767. Nothing changed.";
    case SwapCombineCheck::Ok:
      return "STORE: Item #" + b + " combined to Item #" + a + ".";
  }
  return "";
}

bool swapApply(Session& s, i32 member, i32 slotA, i32 slotB, Str& reply) {
  if (accMember(s, member) == nullptr) {
    reply = "No such party member.";
    return false;
  }
  Item* a = accPackItem(s, member, slotA);
  Item* b = accPackItem(s, member, slotB);
  if (a == nullptr || b == nullptr) {
    reply = "Slots must be 2 to 40 (slot 1 is your hands and cannot be moved).";
    return false;
  }
  std::swap(*a, *b);
  reply = "Item swap completed!";
  return true;
}

bool combineApply(Session& s, i32 member, i32 slotA, i32 slotB, Str& reply) {
  if (accMember(s, member) == nullptr) {
    reply = "No such party member.";
    return false;
  }
  Item* first = accPackItem(s, member, slotA);
  Item* second = accPackItem(s, member, slotB);
  if (first == nullptr || second == nullptr) {
    reply = "Slots must be 2 to 40 (slot 1 is your hands and cannot be combined).";
    return false;
  }
  // UNKNOWN: an empty slot is not an item; the reference has no message for it. Refused here.
  if (first->id <= 0) {
    reply = "Item #" + std::to_string(slotA) + " is empty.";
    return false;
  }
  if (second->id <= 0) {
    reply = "Item #" + std::to_string(slotB) + " is empty.";
    return false;
  }

  const bool firstKnown =
      static_cast<i32>(first->idLevel) == static_cast<i32>(IdLevel::All);
  const bool secondKnown =
      static_cast<i32>(second->idLevel) == static_cast<i32>(IdLevel::All);

  i32 kindFirst = 0;
  i32 kindSecond = 0;
  const bool firstKindKnown = swapItemKind(s, *first, kindFirst);
  const bool secondKindKnown = swapItemKind(s, *second, kindSecond);
  const bool firstCombinable = firstKindKnown && swapCombinableKind(kindFirst);
  const bool sameClass = firstKindKnown && secondKindKnown && kindFirst == kindSecond;

  const SwapCombineCheck check = swapCombineCheck(
      firstKnown, secondKnown, firstCombinable, sameClass,
      first->id == second->id,
      first->alignment == second->alignment,
      static_cast<i64>(first->charges), static_cast<i64>(second->charges));
  reply = swapCombineText(check, slotA, slotB);
  if (check != SwapCombineCheck::Ok) return false;

  // UNKNOWN: an equipped copy is refused by the earlier port; the reference does not show it.
  // Kept as a conservative guard so an equipped item is never emptied by a combine.
  if (first->equipped || second->equipped) {
    reply = "Item #" + std::to_string(slotB) + " is equipped and cannot be combined.";
    return false;
  }

  const i64 sum = static_cast<i64>(first->charges) + static_cast<i64>(second->charges);
  first->charges = static_cast<decltype(first->charges)>(sum);
  *second = Item{};  // the poured-from slot is emptied
  return true;
}

bool cmdSwap(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() != 4) {
    reply = "Usage: swap <member> <slot1> <slot2>";
    return false;
  }
  i32 member = 0;
  i32 a = 0;
  i32 b = 0;
  if (!swapParseInt(w[1], member) || !swapMemberInRange(member)) {
    reply = "No such party member.";
    return false;
  }
  if (!swapParseInt(w[2], a) || !swapParseInt(w[3], b)) {
    reply = "Usage: swap <member> <slot1> <slot2>";
    return false;
  }
  // R45
  if (!swapSlotInRange(a) || !swapSlotInRange(b)) {
    reply = "Slots must be 2 to 40 (slot 1 is your hands and cannot be moved).";
    return false;
  }
  return swapApply(s, member, a, b, reply);
}

bool cmdCombine(Session& s, const Vec<Str>& w, Str& reply) {
  if (w.size() != 4) {
    reply = "Usage: combine <member> <slot1> <slot2>";
    return false;
  }
  i32 member = 0;
  i32 a = 0;
  i32 b = 0;
  if (!swapParseInt(w[1], member) || !swapMemberInRange(member)) {
    reply = "No such party member.";
    return false;
  }
  if (!swapParseInt(w[2], a) || !swapParseInt(w[3], b)) {
    reply = "Usage: combine <member> <slot1> <slot2>";
    return false;
  }
  // The original silently does nothing for a repeated slot (FRMCTYS.BAS:654-657).
  // Here the same slot is refused with a reason.
  if (a == b) {
    reply = "Those are the same slot; nothing to combine.";
    return false;
  }
  if (!swapSlotInRange(a) || !swapSlotInRange(b)) {
    reply = "Slots must be 2 to 40 (slot 1 is your hands and cannot be combined).";
    return false;
  }
  return combineApply(s, member, a, b, reply);
}

