bool setActiveGuild(Ctx& ctx, Character& character, Guild guild) {
    (void)ctx;
    if (!character.guilds[static_cast<u32>(guild)].joined) {
        return false;
    }
    if (character.activeGuild == guild) {
        return true;
    }
    character.activeGuild = guild;
    return true;
}

