void sayEquipRefusal(Ctx& ctx, EquipOutcome outcome) {
    switch (outcome) {
        case EquipOutcome::NoFreeHands:
            ctx.say("items.equip.no_free_hands", "No Free Hands!", {}, {});  // R6
            break;
        case EquipOutcome::TooManyWorn:
            ctx.say("items.equip.too_many_worn", "Using too Many!", {}, {});  // R7
            break;
        case EquipOutcome::ClassRestricted:
            // RESOLVED-BY-REFERENCE: Character.cs EquipProblem returns "Your current guild cannot use this item!" when it.ClassRestricted != 0 (R8)
            ctx.say("items.equip.class_restricted",
                    "Your current guild cannot use this item!", {}, {});  // R8
            break;
        case EquipOutcome::GuildRestricted:
            // RESOLVED-BY-REFERENCE: Character.cs EquipProblem returns "Your currently joined guilds cannot use this item!" when it.ClassRestricted == 0 (R8)
            ctx.say("items.equip.guild_restricted",
                    "Your currently joined guilds cannot use this item!", {}, {});  // R8
            break;
        case EquipOutcome::GuildLevelTooLow:
            // UNKNOWN: the reference has two texts, "Your guild level is too low to use item!" (ClassRestricted != 0)
            // and "All guild levels too low to use item!" (otherwise). The choice needs the item's flag, which this
            // function does not receive, and the signature must stay fixed.
            ctx.say("items.equip.guild_level",
                    "UNKNOWN: guild level message text.", {}, {});  // R9
            break;
        case EquipOutcome::StatsTooLow:
            // RESOLVED-BY-REFERENCE: Character.cs EquipProblem returns "One or more stats are too low!" (no stat named) (R10)
            ctx.say("items.equip.stats_too_low",
                    "One or more stats are too low!", {}, {});  // R10
            break;
        case EquipOutcome::CursedStatsTooLow:
            ctx.say("items.equip.cursed_stats",
                    "Your stats are too low for the item to properly attach!", {}, {});  // R12
            break;
        case EquipOutcome::SilentRefusal:
        case EquipOutcome::Ok:
            break;
    }
}

bool isHandsSlot(i32 internalIndex) {
    return internalIndex == kHandsSlot;
}

i32 firstFreePackSlot(const Inventory& inv) {
    for (i32 i = kFirstItemSlot; i <= kLastItemSlot; ++i) {
        if (slotIsEmpty(inv.pack[static_cast<u32>(i)])) {
            return i;
        }
    }
    return -1;  // UNKNOWN: no-free-slot sentinel value not given; -1 chosen.
}

bool slotIsEmpty(const Item& item) {
    return item.id == 0;
}

bool handsCheckPasses(const Inventory& inv, i32 handWidth) {
    const i32 inUse = kHandsTotal - inv.freeHands;
    return inUse + handWidth <= kHandsTotal;
}

bool classCapPasses(const Ctx& ctx, const Inventory& inv, const Item& item) {
    const i32 cap = wearClassCap(ctx, item);
    if (cap == kWearClassUnwearable) {
        return false;  // R7 silent exit
    }
    if (cap > 0) {
        const i32 cls = wearClassOf(ctx, item);
        i32 worn = 0;
        for (i32 i = kFirstItemSlot; i <= kLastItemSlot; ++i) {
            const Item& other = inv.pack[static_cast<u32>(i)];
            if (other.equipped && wearClassOf(ctx, other) == cls) {
                ++worn;
            }
        }
        if (worn >= cap) {
            return false;  // R7 "Using too Many!"
        }
    }
    return true;  // Table T-2: -1 no cap, or count below maximum
}

bool statsRequirementMet(const Ctx& ctx, const Character& c, const Inventory& inv, const Item& item) {
    (void)inv;
    for (i32 s = 0; s < kStatCount; ++s) {
        if (c.abilities.stats[static_cast<u32>(s)] < itemStatRequirement(ctx, item, s)) {
            return false;
        }
    }
    return true;
}

EquipOutcome equipCheck(Ctx& ctx, const Character& c, const Inventory& inv, const Item& item, bool storeLike) {
    if (!storeLike) {
        if (!handsCheckPasses(inv, itemHandWidth(ctx, item))) {
            return EquipOutcome::NoFreeHands;  // R6
        }
        if (!classCapPasses(ctx, inv, item)) {
            if (wearClassCap(ctx, item) == kWearClassUnwearable) {
                return EquipOutcome::SilentRefusal;  // R7 cap 0 exits silently
            }
            return EquipOutcome::TooManyWorn;  // R7
        }
    }
    if (!CanUse(ctx, item, c)) {  // R8
        return anyGuildJoined(c) ? EquipOutcome::GuildRestricted
                                 : EquipOutcome::ClassRestricted;
    }
    if (!MeetsUseLevel(ctx, item, c)) {  // R9
        return EquipOutcome::GuildLevelTooLow;
    }
    if (!statsRequirementMet(ctx, c, inv, item)) {  // R10
        return item.cursed == CurseKind2 ? EquipOutcome::CursedStatsTooLow  // R12
                                         : EquipOutcome::StatsTooLow;
    }
    return EquipOutcome::Ok;
}

bool equipSlot(Ctx& ctx, Character& c, Inventory& inv, i32 slot, bool storeLike) {
    if (isHandsSlot(slot) || !isItemSlot(slot)) {
        return false;  // R2 hands never equip; out-of-range slot
    }
    Item& it = inv.pack[static_cast<u32>(slot)];
    if (slotIsEmpty(it) || it.equipped) {
        return false;  // UNKNOWN: refusal for empty or already-equipped slot not given
    }
    const EquipOutcome outcome = equipCheck(ctx, c, inv, it, storeLike);
    if (outcome != EquipOutcome::Ok) {
        sayEquipRefusal(ctx, outcome);
        return false;
    }
    it.equipped = true;
    // UNKNOWN: store-like equips still consume hands; freeHands is not clamped.
    inv.freeHands -= itemHandWidth(ctx, it);  // R6
    applyEquipCurse(ctx, it, c.alignment);  // R11
    return true;
}

bool unequipAllowed(const Item& slot) {
    return !slot.slotCursed;
}

bool unequipSlot(Ctx& ctx, Character& c, Inventory& inv, i32 slot) {
    (void)c;
    if (isHandsSlot(slot) || !isItemSlot(slot)) {
        return false;
    }
    Item& it = inv.pack[static_cast<u32>(slot)];
    if (!it.equipped) {
        return false;  // "isn't equipped" refusal path (quirk R18 area)
    }
    if (!unequipAllowed(it)) {
        return false;  // R13
    }
    clearSlotCurseOnUnequip(ctx, it);  // R15: no-op here, flag already clear
    it.equipped = false;
    inv.freeHands += itemHandWidth(ctx, it);  // R6 hands released
    return true;
}

void applyGenerationCurse(Ctx& ctx, Item& item, bool fromChestTreasure) {
    (void)ctx;
    if (fromChestTreasure || item.cursed == CurseKind2) {
        item.slotCursed = true;
    }
}

void clearSlotCurseOnUnequip(Ctx& ctx, Item& slot) {
    (void)ctx;
    slot.slotCursed = false;
}

bool equipProblem(Ctx& ctx, const Character& c, const Inventory& inv, const Item& item) {
    if (!CanUse(ctx, item, c)) {
        return true;  // guild check
    }
    if (!MeetsUseLevel(ctx, item, c)) {
        return true;  // guild level check
    }
    if (!statsRequirementMet(ctx, c, inv, item)) {
        return true;  // stats check
    }
    return false;
}

void forcedUnequipPass(Ctx& ctx, Character& c, Inventory& inv, bool joiningGuild) {
    bool anyProblem = false;
    for (i32 i = kFirstItemSlot; i <= kLastItemSlot; ++i) {
        Item& it = inv.pack[static_cast<u32>(i)];
        if (!it.equipped || slotIsEmpty(it)) {
            continue;  // R16 skip
        }
        // R16: "lookup fails" skip is not modelled: no lookup is available here.
        if (!equipProblem(ctx, c, inv, it)) {
            continue;
        }
        anyProblem = true;
        if (it.slotCursed) {
            // R17: cursed item stays on; message printed first.
            if (!joiningGuild) {
                ctx.say("items.forced_unequip.cursed",
                        "You can no longer use this item.", {}, {});  // R18
            }
            continue;
        }
        unequipSlot(ctx, c, inv, i);  // R17
        if (!joiningGuild) {
            ctx.say("items.forced_unequip.removed",
                    "You can no longer use this item.", {}, {});  // R18
        }
    }
    if (joiningGuild && anyProblem) {
        ctx.say("items.forced_unequip.summary",
                "You can no longer use some of your items.", {}, {});  // R18
    }
}

i32 adWorthOfFit(i32 raw, FitClass fit) {
    switch (fit) {
        case FitClass::Full:
            return raw;
        case FitClass::Half:
            // Adjacent attack/defence worth: round_half_even(raw / 2.0)  (T-5, R19)
            return static_cast<i32>(roundHalfEven(static_cast<double>(raw) / 2.0));
        case FitClass::Subtract:
            return -raw;  // Opposed: -raw
    }
    return raw;
}

bool alignFlagsAllow(u8 alignFlags, Align charAlign) {
    if (alignFlags == 0) {
        return true;  // UNKNOWN
    }
    if ((alignFlags & kAlignBitUnaligned) != 0) {
        return true;  // UNKNOWN
    }
    u8 bit = 0;
    switch (charAlign) {
        case Align::Good:
            bit = kAlignBitGood;
            break;
        case Align::Neutral:
            bit = kAlignBitNeutral;
            break;
        case Align::Evil:
            bit = kAlignBitEvil;
            break;
    }
    return (alignFlags & bit) != 0;
}

ItemAlign normaliseItemAlign(i32 rawAlignField) {
    if (rawAlignField <= 1) {
        return Unaligned;  // R21: values 0 or 1 mean Unaligned
    }
    if (rawAlignField <= 3) {
        return static_cast<ItemAlign>(rawAlignField);
    }
    return Unaligned;  // UNKNOWN: out-of-range alignment field
}

LevelBand asmodeusDropBand(i32 itemDropLevel) {
    LevelBand band;
    band.lo = itemDropLevel - 2;  // R22: band runs ItemDropLevel-2 .. ItemDropLevel
    band.hi = itemDropLevel;
    return band;
}

i32 rollCharges(Ctx& ctx, i32 charges) {
    if (charges <= 0) return charges;  // UNKNOWN: no roll for non-positive charges
    const i32 spread = static_cast<i32>(
        vbInt(ctx.rng.nextDouble() * charges / kFoundChargesDivisor));
    const i32 low = charges - spread;
    return low + static_cast<i32>(ctx.rng.below(2 * spread + 1));
}

IdLevel readableLevel(Ctx& ctx, const Character& reader, const Item& item) {
    (void)ctx;
    (void)reader;
    return item.idLevel;  // UNKNOWN: reading formula not supplied
}

void readOnPickup(Ctx& ctx, const Character& reader, Item& item) {
    const IdLevel level = readableLevel(ctx, reader, item);
    if (level > item.idLevel) {
        item.idLevel = level;
    }
}

bool isIncapacitated(const Character& c) {
    return c.isDead() || c.ailments.paralysed;  // UNKNOWN
}

bool isMustBeEquippedType(i32 itemTypeCode) {
    // R81: MustBeEquipped covers types 1-22, 29, 32, 33, 34.
    return (itemTypeCode >= 1 && itemTypeCode <= 22)
        || itemTypeCode == 29
        || itemTypeCode == 32
        || itemTypeCode == 33
        || itemTypeCode == 34;
}

UseOutcome useItem(Ctx& ctx, Character& user, Inventory& inv, i32 slot, bool inDungeon) {
    // R29: incapacitated -> silent refusal.
    if (isIncapacitated(user)) return UseOutcome::Silent;
    if (slot < 0 || slot >= kPackSlots) return UseOutcome::Silent;  // UNKNOWN: bounds guard

    // R30: negative SpecialType -> silent refusal.
    // UNKNOWN: ItemDef field name for SpecialType is not in the supplied
    // header; assumed to be `specialType`, indexed by item.id.
    {
        i32 specialType = 0;
        const Item& probe = inv.pack[static_cast<u32>(slot)];
        if (probe.id >= 0 && probe.id < static_cast<i32>(ctx.data.items.size())) {
            specialType = ctx.data.items[static_cast<u32>(probe.id)].specialType;
        }
        if (specialType < 0) return UseOutcome::Silent;
    }

    Item& item = inv.pack[static_cast<u32>(slot)];

    // RESOLVED-BY-REFERENCE: ItemUse.cs Problem: "if (it.Charges <= 0) return ...doesn't appear to do
    // much of anything." The test is on the item kind's charges, mapped here to maxCharges, and is <= 0.
    if (item.maxCharges <= 0) {
        ctx.say("use.noEffect", "The Item doesn't appear to do much of anything.", {}, {});
        return UseOutcome::ItemNoEffect;
    }

    // R32: slot charges 0 -> "out of charges".
    if (item.charges <= 0) {
        ctx.say("use.outOfCharges", "The Item is out of charges!", {}, {});
        return UseOutcome::SlotOutOfCharges;
    }

    // R34: dungeon-only use (position UNKNOWN, see function comment).
    if (!inDungeon) {
        ctx.say("use.notInDungeon", "Must be in Dungeon to Use items.", {}, {});
        return UseOutcome::NotInDungeon;
    }

    // R35 / R33: spell items only. RESOLVED-BY-REFERENCE: ItemUse.cs Problem checks the spell
    // alignment first and the must-be-equipped test second, both inside "if (it.SpellIndex > 0)".
    // A non-spell item is not refused for being unworn. Only "Nothing Happens." spends no charge.
    if (item.spellId > 0) {
        if (!spellFiresOnUse(item, user.alignment)) {
            ctx.say("use.nothingHappens", "Nothing Happens.", {}, {});
            return UseOutcome::NothingHappens;
        }
        if (isMustBeEquippedType(static_cast<i32>(item.type)) && !item.equipped) {
            ctx.say("use.mustBeEquipped", "Item must be Equipped to use!", {}, {});
            return UseOutcome::MustBeEquipped;
        }
    }
    // Spell firing itself is performed by the casting module; not done here.

    // R19 / Table T-5: fit of the item relative to the user. Computed before
    // the charge spend (the item may be destroyed by the spend).
    FitClass fit = FitClass::Full;
    if (item.alignment != ItemAlign::Unaligned) {
        const i32 itemStep = static_cast<i32>(item.alignment) - 1;  // Good=0, Neutral=1, Evil=2
        const i32 userStep = static_cast<i32>(user.alignment);      // Good=0, Neutral=1, Evil=2
        const i32 steps = itemStep > userStep ? itemStep - userStep : userStep - itemStep;
        if (steps == 1) {
            fit = FitClass::Half;
        } else if (steps == 2) {
            fit = FitClass::Subtract;
        }
    }

    // R36: charge spend.
    const bool destroyed = subtractItemUse(ctx, inv, slot);
    if (destroyed) {
        resetEmptiedBuffers(user, slot);  // R66 / R76
    }

    // R37: one alignment step away -> "Nothing Happens." (charge already spent).
    if (fit == FitClass::Half) {
        ctx.say("use.nothingHappens", "Nothing Happens.", {}, {});
        return UseOutcome::NothingHappens;
    }

    // R37 / R38: non-spell fit, then special effects.
    // Two steps away reverses positive modifiers (reversed = true).
    applyNonSpellFit(ctx, user, item, fit);
    applySpecialEffects(ctx, user, inv, slot, fit == FitClass::Subtract);

    return destroyed ? UseOutcome::UsedAndDestroyed : UseOutcome::Used;
}

bool spellFiresOnUse(const Item& item, Align userAlign) {
    if (item.alignment == ItemAlign::Unaligned) return true;
    switch (userAlign) {
        case Align::Good:    return item.alignment == ItemAlign::Good;
        case Align::Neutral: return item.alignment == ItemAlign::Neutral;
        case Align::Evil:    return item.alignment == ItemAlign::Evil;
    }
    return false;
}

bool subtractItemUse(Ctx& ctx, Inventory& inv, i32 slot) {
    (void)ctx;
    if (slot < 0 || slot >= kPackSlots) return false;  // UNKNOWN: bounds guard
    Item& item = inv.pack[static_cast<u32>(slot)];
    if (item.charges > 0) {
        item.charges -= 1;  // R36
    }
    if (item.charges == 0 && isConsumedType(static_cast<i32>(item.type))) {
        item = Item{};  // R36: destroyed. UNKNOWN: empty-slot representation
        return true;
    }
    return false;
}

void applyNonSpellFit(Ctx& ctx, Character& user, Item& item, FitClass fit) {
    (void)ctx;
    (void)user;
    (void)item;
    (void)fit;
    // Full: no adjustment. Half: no effect (R37). Subtract: handled by caller.
}

void applySpecialEffects(Ctx& ctx, Character& user, Inventory& inv, i32 slot, bool reversed) {
    (void)ctx;
    (void)user;
    (void)inv;
    (void)slot;
    (void)reversed;
}

void applyYounger(Ctx& ctx, Character& user, i32 years) {
    const i32 floorDays = 16 * 365;  // R82: minimum age 16 * 365
    user.ageDays -= years * 365;     // R82: age -= years * 365
    if (user.ageDays < floorDays) {
        user.ageDays = floorDays;
        ctx.say("items.younger.limit", "You cannot get any younger.", {}, {});
    }
}

void applyStatModifier(Ctx& ctx, Character& user, StatIndex stat, i32 mod, bool reversed) {
    (void)applyStatMod(ctx, user, stat, mod, reversed);
}

void combatItemRound(Ctx& ctx, Character& who, Inventory& inv, i32 slot) {
    if (slot < 0 || slot >= kPackSlots) return;  // UNKNOWN: bounds guard

    Item& item = inv.pack[static_cast<u32>(slot)];
    if (item.charges <= 0) {
        who.order = CombatOrder{};  // R40: order drops at zero charges
        return;
    }

    // R40: the combat item becomes the order.
    who.order.kind = CombatOrderKind::Buffer;  // UNKNOWN: kind
    who.order.spellId = item.spellId;

    // R40: the spell is cast this round (casting module performs the cast).
    who.castThisRound = true;

    // R40: one charge per round.
    const bool destroyed = subtractItemUse(ctx, inv, slot);
    if (destroyed) {
        resetEmptiedBuffers(who, slot);  // R66 / R76
    }

    // R40: at zero charges the order drops (also when the item was destroyed).
    if (inv.pack[static_cast<u32>(slot)].charges <= 0) {
        who.order = CombatOrder{};
    }
}

DropOutcome dropItem(Ctx& ctx, Character& c, Inventory& inv, i32 slot, bool confirmed) {
    if (slot < 0 || slot >= kPackSlots) return DropOutcome::HandsSlot;  // UNKNOWN

    Item& item = inv.pack[static_cast<u32>(slot)];

    // R41: guild-issued items.
    if (item.guildIssued) {
        ctx.say("drop.guildIssued", "Cannot drop Guild-Issued Items!", {}, {});
        return DropOutcome::GuildIssued;
    }

    // R41: slot 0 cannot be dropped.
    if (isHandsSlot(slot)) return DropOutcome::HandsSlot;

    // R42: equipped cursed item: prompt first, then refuse.
    if (item.equipped && item.slotCursed) {
        if (!confirmed) return DropOutcome::NeedsConfirm;
        return DropOutcome::CursedEquipped;
    }

    // R43 / R44: unworn cursed items and all other items are destroyed.
    inv.pack[static_cast<u32>(slot)] = Item{};
    resetEmptiedBuffers(c, slot);  // R66 / R76
    return DropOutcome::Destroyed;
}

bool swapPackTyped(Ctx& ctx, Inventory& inv, i32 playerSlotA, i32 playerSlotB) {
    (void)ctx;
    const i32 a = playerSlotA - kPlayerSlotOffset;
    const i32 b = playerSlotB - kPlayerSlotOffset;
    if (a < kFirstItemSlot || a > kLastItemSlot) return false;  // UNKNOWN
    if (b < kFirstItemSlot || b > kLastItemSlot) return false;  // UNKNOWN
    if (a == b) return false;                                    // UNKNOWN
    const Item tmp = inv.pack[static_cast<u32>(a)];
    inv.pack[static_cast<u32>(a)] = inv.pack[static_cast<u32>(b)];
    inv.pack[static_cast<u32>(b)] = tmp;
    return true;
}

void swapPackDragged(Ctx& ctx, Character& c, Inventory& inv, i32 slotA, i32 slotB) {
    (void)ctx;
    if (slotA < kFirstItemSlot || slotA > kLastItemSlot) return;  // UNKNOWN
    if (slotB < kFirstItemSlot || slotB > kLastItemSlot) return;  // UNKNOWN
    if (slotA == slotB) return;                                    // UNKNOWN
    const Item tmp = inv.pack[static_cast<u32>(slotA)];
    inv.pack[static_cast<u32>(slotA)] = inv.pack[static_cast<u32>(slotB)];
    inv.pack[static_cast<u32>(slotB)] = tmp;
    swapBufferSlots(c, slotA, slotB);
}

void resetEmptiedBuffers(Character& c, i32 slot) {
    for (i32 i = 0; i < kSpellBuffers; ++i) {
        const u32 idx = static_cast<u32>(i);
        if (c.order.spellBuffers[idx] == slot) {
            c.order.spellBuffers[idx] = kSlotEmptyBuffer;
        }
    }
}

void swapBufferSlots(Character& c, i32 slotA, i32 slotB) {
    for (i32 b = 0; b < kSpellBuffers; ++b) {
        i32& buf = c.order.spellBuffers[static_cast<u32>(b)];
        if (buf == slotA) {
            buf = slotB;
        } else if (buf == slotB) {
            buf = slotA;
        }
    }
}

void giveRead(Ctx& ctx, Character& receiver, Item& slot) {
    if (slot.idLevel == All) {
        return;
    }
    IdLevel reading = readableLevel(ctx, receiver, slot);
    if (reading <= slot.idLevel) {
        return;
    }
    slot.idLevel = reading;
    // UNKNOWN: "file the item in the library" has no library API in this SRD half;
    // the filing step is not performed here.
    ctx.say("items.give_identified",
            "<0> identified the given item as <1>.",
            {},
            {receiver.name, itemDisplayName(ctx, slot, reading)});
}

void lootReadOnReceive(Ctx& ctx, const Character& receiver, Item& slot) {
    if (slot.idLevel == All) {
        return;
    }
    if (readableLevel(ctx, receiver, slot) <= slot.idLevel) {
        return;
    }
    // UNKNOWN: ItemDef field name for LevelScale is assumed to be `levelScale`.
    // Items[LevelScale] ?? it: if the index is not a valid table entry, use the item itself.
    Item scaled = slot;
    if (slot.id >= 0 && slot.id < static_cast<i32>(ctx.data.items.size())) {
        i32 scale = ctx.data.items[static_cast<u32>(slot.id)].levelScale;
        if (scale >= 0 && scale < static_cast<i32>(ctx.data.items.size())) {
            scaled.id = scale;
        }
    }
    slot.idLevel = readableLevel(ctx, receiver, scaled);
}

CombineResult storeCombine(Ctx& ctx, Inventory& storeInv, const Vec<i32>& slots) {
    CombineResult result;

    // R54 refusal is checked first.
    // UNKNOWN: refusal conditions are not itemised in the SRD; implemented as
    // "a listed slot is outside the pack item range".
    for (i32 s : slots) {
        if (s < kFirstItemSlot || s > kLastItemSlot) {
            result.outcome = CombineOutcome::Refused;
            return result;
        }
    }

    // R54 a list of one item does nothing.
    if (slots.size() < 2) {
        result.outcome = CombineOutcome::NothingToCombine;
        return result;
    }

    const Item& first = storeInv.pack[static_cast<u32>(slots[0])];

    // R54 the first item's type must be combinable.
    // UNKNOWN: combinable types are not listed in the SRD; isConsumedType is used as the test.
    if (!isConsumedType(static_cast<i32>(first.type))) {
        result.outcome = CombineOutcome::FirstNotCombinable;
        return result;
    }

    // R54 every item must be fully identified; each later item is then checked in order:
    // type, item id, alignment.
    const u32 count = static_cast<u32>(slots.size());
    for (u32 k = 0; k < count; ++k) {
        const Item& it = storeInv.pack[static_cast<u32>(slots[k])];
        if (it.idLevel != All) {
            result.outcome = CombineOutcome::NotIdentified;
            return result;
        }
        if (k == 0) {
            continue;
        }
        if (it.type != first.type) {
            // Original quirk: the "not of the same type" message is swapped in the original.
            result.outcome = CombineOutcome::TypeMismatch;
            return result;
        }
        if (it.id != first.id) {
            result.outcome = CombineOutcome::ItemIdMismatch;
            return result;
        }
        if (it.alignment != first.alignment) {
            result.outcome = CombineOutcome::AlignMismatch;
            return result;
        }
    }

    // R55 / R56 merge pass. Validation completes before any change is made.
    // UNKNOWN: the SRD does not say whether validation is per-item or all-first;
    // all-first is used.
    Item& head = storeInv.pack[static_cast<u32>(slots[0])];
    for (u32 k = 1; k < count; ++k) {
        const i32 s = slots[k];
        Item& it = storeInv.pack[static_cast<u32>(s)];
        const i64 total = static_cast<i64>(head.charges) + static_cast<i64>(it.charges);
        if (total > kChargeSumLimit) {
            // R56 overflow: the item's message shows but its charges are not added.
            // Original quirk: VB run-time error 6 is untrapped in the original (program ends).
            // UNKNOWN: slot is left unchanged on overflow.
            result.overflowed += 1;
            ctx.say("items.combine.overflow",
                    "Charges could not be combined from this item.",
                    {s},
                    {});
            continue;
        }
        // R55 charges added to the first item, passing item's slot emptied.
        head.charges = static_cast<i32>(total);
        it = Item{};
        result.merged += 1;
        ctx.say("items.combine.merged",
                "Charges combined into the first item.",
                {s},
                {});
    }
    result.outcome = CombineOutcome::Combined;
    return result;
}

BuyOutcome storeBuy(Ctx& ctx, Character& buyer, Inventory& inv, const Item& stock, Currency price) {
    // R58 scan slots 1 to 39 (internal indices; hands slot 0 excluded) for a blank.
    i32 freeSlot = -1;
    for (i32 s = kFirstItemSlot; s <= kLastItemSlot; ++s) {
        if (slotIsEmpty(inv.pack[static_cast<u32>(s)])) {
            freeSlot = s;
            break;
        }
    }
    if (freeSlot < 0) {
        ctx.say("items.buy.no_free_slot", "No free slots!", {}, {});
        return BuyOutcome::NoFreeSlot;
    }
    if (buyer.wallet.goldOnHand < price) {
        ctx.say("items.buy.not_enough_gold", "Not enough gold!", {}, {});
        return BuyOutcome::NotEnoughGold;
    }
    buyer.wallet.goldOnHand -= price;
    inv.pack[static_cast<u32>(freeSlot)] = stock;
    // UNKNOWN: slot number shown as player numbering (internal index + 1).
    const i32 shown = freeSlot + kPlayerSlotOffset;
    ctx.say("items.buy.success",
            "Slot #<0> now contains your <1>.",
            {shown},
            {itemDisplayName(ctx, stock, stock.idLevel)});
    return BuyOutcome::Bought;
}

Currency realignCost(Currency price, i32 multiplier) {
    return roundHalfEven(0.72 * static_cast<double>(price) * static_cast<double>(multiplier));
}

i32 realignMultiplier(ItemAlign from, ItemAlign to) {
    i32 diff = static_cast<i32>(from) - static_cast<i32>(to);
    if (diff < 0) {
        diff = -diff;
    }
    // UNKNOWN: realigning to the same alignment is not defined in the SRD; cost 0 is used.
    if (diff == 0) {
        return 0;
    }
    if (diff == 1) {
        return 1;
    }
    return 2;
}

UncurseOutcome uncurseItem(Ctx& ctx, Character& c, Inventory& inv, i32 slot) {
    (void)c;
    Item& item = inv.pack[static_cast<u32>(slot)];
    if (!item.slotCursed) {
        ctx.say("items.uncurse.not_cursed", "Item is not cursed!", {}, {});
        return UncurseOutcome::NotCursed;
    }
    if (!item.equipped) {
        ctx.say("items.uncurse.not_equipped", "Item isn't equipped!", {}, {});
        return UncurseOutcome::NotEquipped;
    }
    // R61 otherwise the uncurse proceeds.
    // UNKNOWN: the SRD half does not state what the uncurse changes; the slot flag is cleared.
    item.slotCursed = false;
    ctx.say("items.uncurse.done", "The curse is lifted.", {}, {});
    return UncurseOutcome::Uncursed;
}

bool isGuildCrest(const Item& item) {
    return item.id > kCrestItemIdBase && item.id <= kCrestItemIdBase + kGuildCount;
}

bool sellQuote(Ctx& ctx, const Item& item, Currency& quote) {
    if (isGuildCrest(item)) {
        return false;
    }
    quote = sellPrice(ctx, item);
    return true;
}

bool parseTypedAmount(const Str& text, Currency& amount) {
    using SizeT = decltype(text.size());
    const SizeT n = text.size();
    SizeT i = 0;
    while (i < n && text[i] == ' ') {
        ++i;
    }
    bool negative = false;
    if (i < n && (text[i] == '-' || text[i] == '+')) {
        negative = (text[i] == '-');
        ++i;
    }
    // UNKNOWN: upper cap on whole gold to keep the value within i64.
    const i64 kMaxWhole = 1000000000000LL;
    i64 whole = 0;
    bool sawDigit = false;
    while (i < n && text[i] >= '0' && text[i] <= '9') {
        sawDigit = true;
        whole = whole * 10 + static_cast<i64>(text[i] - '0');
        if (whole > kMaxWhole) {
            return false;
        }
        ++i;
    }
    i64 frac = 0;
    i32 fracDigits = 0;
    if (i < n && text[i] == '.') {
        ++i;
        while (i < n && text[i] >= '0' && text[i] <= '9') {
            sawDigit = true;
            if (fracDigits < 4) {
                frac = frac * 10 + static_cast<i64>(text[i] - '0');
                ++fracDigits;
            }
            ++i;
        }
    }
    while (fracDigits < 4) {
        frac *= 10;
        ++fracDigits;
    }
    while (i < n && text[i] == ' ') {
        ++i;
    }
    if (i != n || !sawDigit) {
        return false;
    }
    const i64 value = whole * 10000 + frac;
    if (value == 0) {
        return false;
    }
    amount = negative ? -value : value;
    return true;
}

bool bankDepositAllowed(Currency amount, Currency goldOnHand) {
    return amount > 0 && amount <= goldOnHand;
}

bool bankWithdrawAllowed(Currency amount, Currency bankGold) {
    return !(amount > bankGold || bankGold < 0);
}

bool depositItem(Ctx& ctx, Character& c, Inventory& inv, i32 slot) {
    (void)c;
    Item& item = inv.pack[static_cast<u32>(slot)];
    if (item.equipped) {
        ctx.say("items.bank.equipped", "Cannot put equipped items in the bank!", {}, {});
        return false;
    }
    if (slotIsEmpty(item)) {
        return false;
    }
    i32 bankFree = -1;
    for (i32 b = 0; b < kBankSlots; ++b) {
        if (slotIsEmpty(inv.bank[static_cast<u32>(b)])) {
            bankFree = b;
            break;
        }
    }
    if (bankFree < 0) {
        ctx.say("items.bank.full", "No free bank slots!", {}, {});
        return false;
    }
    inv.bank[static_cast<u32>(bankFree)] = item;
    item = Item{};
    ctx.say("items.bank.deposited", "Item deposited in the bank.", {}, {});
    return true;
}

bool retrieveFromBank(Ctx& ctx, Character& c, Inventory& inv, i32 bankSlot) {
    Item& stored = inv.bank[static_cast<u32>(bankSlot)];
    if (slotIsEmpty(stored)) {
        return false;
    }
    const i32 dest = firstFreePackSlot(inv);
    if (dest < kFirstItemSlot || dest > kLastItemSlot) {
        ctx.say("items.retrieve.no_free_slot", "No free slots!", {}, {});
        return false;
    }
    Item moved = stored;
    if (bankRetrievalReidentifies(ctx, c, moved)) {
        // UNKNOWN: re-identified level taken as the reading, never lowering the known level.
        const IdLevel level = readableLevel(ctx, c, moved);
        if (level > moved.idLevel) {
            moved.idLevel = level;
        }
        ctx.say("items.retrieve.reidentified",
                "You have re-identified the retrieved item as: <0>",
                {},
                {itemDisplayName(ctx, moved, moved.idLevel)});
    }
    inv.pack[static_cast<u32>(dest)] = moved;
    stored = Item{};
    // R66 original quirk: buffers are set to -1, not remapped.
    for (i32 b = 0; b < kSpellBuffers; ++b) {
        i32& buf = c.order.spellBuffers[static_cast<u32>(b)];
        if (buf == dest) {
            buf = kSlotEmptyBuffer;
        }
    }
    return true;
}

bool bankRetrievalReidentifies(Ctx& ctx, const Character& c, const Item& item) {
    (void)ctx;
    (void)c;
    (void)item;
    return false;
}

bool slimeRollReaches(Ctx& ctx, i32 dungeonLevel) {
    const i32 roll = static_cast<i32>(ctx.rng.below(kSlimeRollMax)) + 1;
    const i32 threshold = kSlimeRollBase + kSlimeRollPerLevel * dungeonLevel;
    return roll <= threshold;
}

i32 pickItemSlot(Ctx& ctx) {
    // Formulas (slime): slot = rng.Next(39) + 1, slots 1..39 (R69).
    return static_cast<i32>(ctx.rng.below(39)) + 1;
}

bool isDestructibleItem(const ItemDef& def) {
    return def.specialType >= 1 && def.specialType <= kDestructibleSpecialMax;
}

Str itemBaseName(const Ctx& ctx, const Item& item) {
    const auto& defs = ctx.data.items;
    if (item.id < 0 || static_cast<std::size_t>(item.id) >= defs.size()) {
        return Str("Unidentified Item");
    }
    return defs[static_cast<std::size_t>(item.id)].name;
}

Str itemTypeLabel(const Ctx& ctx, const Item& item) {
    const auto& types = ctx.data.itemTypes;
    const i32 idx = static_cast<i32>(item.type);
    if (idx < 0 || static_cast<std::size_t>(idx) >= types.size()) {
        return Str("Unidentified Item");
    }
    return types[static_cast<std::size_t>(idx)].name;
}

bool isDestructibleSpecial(i32 specialType) {
    return specialType < kGuildMarkerBase || specialType > kDestructibleSpecialMax;
}

void destroyItemSlot(Ctx& ctx, Inventory& inv, i32 slot, const char* code, const char* prefix) {
    Str name = itemBaseName(ctx, inv.pack[static_cast<std::size_t>(slot)]);
    inv.pack[static_cast<std::size_t>(slot)] = Item{};
    ctx.say(Str(code), Str(prefix) + name + Str(" Destroyed!"), {}, {name});
}

bool slimeDestroy(Ctx& ctx, Inventory& inv, i32 slot) {
    if (slot < kFirstItemSlot || slot > kLastItemSlot) {
        return false;
    }
    const Item& item = inv.pack[static_cast<std::size_t>(slot)];
    if (slotIsEmpty(item)) {
        return false;  // R69 empty slot: no effect
    }
    if (!isDestructibleSpecial(item.ailments)) {  // R70
        return false;
    }
    destroyItemSlot(ctx, inv, slot, "items.slime_destroyed", "SLIME: ");
    return true;
}

bool monsterDestroyCheck(Ctx& ctx, Inventory& inv, i32 slot, i32 monsterFloor, i32 levelFound) {
    if (slot < kFirstItemSlot || slot > kLastItemSlot) {
        return false;
    }
    const Item& item = inv.pack[static_cast<std::size_t>(slot)];
    if (slotIsEmpty(item)) {
        return false;
    }
    if (monsterFloor - kDestroyFloorOffset > levelFound) {  // R71 floor - 2 <= LevelFound
        return false;
    }
    if (!isDestructibleSpecial(item.ailments)) {  // R70 / R71
        return false;
    }
    if (!ctx.rng.percent(kDestroyChancePlaceholder)) {  // UNKNOWN: placeholder chance
        return false;
    }
    destroyItemSlot(ctx, inv, slot, "items.monster_destroyed", "MONSTER: ");
    return true;
}

i32 theftSlotRoll(Ctx& ctx) {
    // R72 / Formulas: TheftSlot = Int(Rnd * 39) + 2, range 2..40 (original quirk).
    return static_cast<i32>(ctx.rng.below(39)) + 2;
}

bool theftDecided(Ctx& ctx, i32 score, i32 monsterLevel) {
    const i32 margin = score - monsterLevel * 2;
    const i32 chance = clampv(margin, 0, 100);
    return ctx.rng.percent(chance);
}

void quicksandSlotRoll(Ctx& ctx, Inventory& inv) {
    const i32 slot = pickItemSlot(ctx);  // one slot in 1..39
    if (slotIsEmpty(inv.pack[static_cast<std::size_t>(slot)])) {
        return;
    }
    ctx.say("items.quicksand_slot", "Quicksand reaches an occupied slot.",
            {static_cast<i64>(slot)}, {});
}

bool seerCarrierHit(Ctx& ctx, i32 itemTypeCode, i32 dropLevel, i32 floor, bool named) {
    const i32 band = static_cast<i32>(ctx.rng.below(kSeerBandSides));
    if (named) {
        return true;  // R74 named items are certain
    }
    const bool typeMatch = itemTypeCode >= 0;  // UNKNOWN
    const bool levelInBand = dropLevel >= floor && dropLevel <= floor + band;
    return typeMatch && levelInBand;
}

i32 seerTakeCount(Ctx& ctx) {
    return 1 + static_cast<i32>(ctx.rng.below(kSeerTakeMax));
}

Str itemDisplayName(const Ctx& ctx, const Item& item, IdLevel level) {
    if (level == IdLevel::Unknown || level == IdLevel::Barely) {
        return Str("Unidentified Item");
    }
    if (level == IdLevel::Partial) {
        return itemTypeLabel(ctx, item);
    }
    Str out = itemBaseName(ctx, item);
    if (level == IdLevel::Mostly) {
        return out;
    }
    // level == IdLevel::All
    if (item.aligned) {
        switch (item.alignment) {
            case ItemAlign::Good:    out += Str(" (g)"); break;
            case ItemAlign::Neutral: out += Str(" (n)"); break;
            case ItemAlign::Evil:    out += Str(" (e)"); break;
            default: break;
        }
    }
    if (item.maxCharges > 0) {
        out += Str(" [") + Str(std::to_string(item.charges)) + Str("]");
    }
    if (item.cursed != CurseNone) {
        out += Str(" (cursed)");
    }
    return out;
}

i32 identifyChance(f64 skill, bool dark) {
    // R18/T-8, SRD ch13 Chances: identify = clamp(int((dark ? skill*0.75 : skill) + 20), 10, 90)
    // The reference truncates with (int); the clamp makes truncation and VbInt floor agree here.
    const f64 base = (dark ? skill * 0.75 : skill) + 20.0;
    i64 chance = static_cast<i64>(base);
    if (chance < 10) chance = 10;
    if (chance > 90) chance = 90;
    return static_cast<i32>(chance);
}

i32 recogniseChance(f64 skill, bool dark) {
    const f64 base = (dark ? skill : skill * 1.25) + 20.0;
    i64 chance = static_cast<i64>(vbInt(base));
    if (chance < 5) chance = 5;
    if (chance > 80) chance = 80;
    return static_cast<i32>(chance);
}

i32 renameChance(f64 skill, bool inFog) {
    const f64 base = (inFog ? skill * 0.75 : skill) + 20.0;
    i64 chance = static_cast<i64>(vbInt(base));
    if (chance < 10) chance = 10;
    if (chance > 90) chance = 90;
    return static_cast<i32>(chance);
}

u32 gearEffectBits(const Ctx& ctx, const Character& c, const Inventory& inv) {
    return gearEffects(ctx, c, inv);
}

Currency placeholderPrice() {
    return roundHalfEven(0.0);
}

Currency modItemCost(Ctx& ctx, const Item& item) {
    // Store-less default: one copy on the shelf. The game layer uses storeBuyPrice with the real shelf count.
    return storeBuyPrice(ctx.data, item, 1);
}

Currency identifyFee(Ctx& ctx, const Item& item) {
    return storeIdentifyFee(ctx.data, item, 1);   // store-less default; the game layer passes the shelf count
}

Currency sellPrice(Ctx& ctx, const Item& item) {
    return storeSellPrice(ctx.data, item, 1, true);   // store-less default; the game layer passes the shelf counts
}

Currency uncurseFee(Ctx& ctx, const Item& item) {
    // The reference has no uncurse fee. The SRD's R64 rule (uncurseFee(listPrice), items2b_2.cpp) applies to the list price.
    for (const ItemDef& d : ctx.data.items) {
        if (d.id == item.id) return uncurseFee(static_cast<Currency>(d.price) * 10000);
    }
    return 0;
}

Str trimEndName(const Str& s) {
    auto end = s.size();
    while (end > 0 && s[end - 1] == ' ') {
        --end;
    }
    return s.substr(0, end);
}

GiveOutcome giveFromPack(Ctx& ctx, const Character& giver, Inventory& giverInv,
                         Character& receiver, Inventory& receiverInv, i32 slot) {
    // R2: hands (slot 0) cannot be given; R1 item slots are 1..39.
    // ASSUMED: an out-of-range or empty slot is a silent no-op. GiveOutcome has no
    // "nothing" value, so Given is returned without any transfer. Callers must
    // check slotIsEmpty() first.
    if (slot < kFirstItemSlot || slot > kLastItemSlot) {
        return GiveOutcome::Given;
    }
    Item& item = giverInv.pack[static_cast<u32>(slot)];
    if (slotIsEmpty(item)) {
        return GiveOutcome::Given;  // ASSUMED: see above
    }

    // R47 (1): guild-issued items are refused first.
    // ASSUMED: guildIssued flag and the guild marker in ailments both identify guild-issued items.
    if (item.guildIssued || item.isGuildItem()) {
        ctx.say("items.give.guildIssued", "Cannot give Guild-Issued Items!",
                {slot}, {giver.name});
        return GiveOutcome::GuildIssued;
    }

    // R47 (2): equipped items are refused next.
    if (item.equipped) {
        ctx.say("items.give.equipped", "Cannot give equipped items!",
                {slot}, {giver.name});
        return GiveOutcome::Equipped;
    }

    // R47 (3): receiver must have a free slot. Scan starts at 1 (R3).
    // ASSUMED: firstFreePackSlot returns a value below kFirstItemSlot when no slot is free.
    const i32 freeSlot = firstFreePackSlot(receiverInv);
    if (freeSlot < kFirstItemSlot || freeSlot > kLastItemSlot) {
        // Name is quoted and TrimEnd'ed (Party.NoFreeSlots, Party.cs:467).
        ctx.say("items.give.receiverFull",
                Str("\"") + trimEndName(receiver.name) + "\" has no free slots!",
                {slot}, {receiver.name});
        return GiveOutcome::ReceiverFull;
    }

    // R48: the item moves, then the receiver reads it (Party.ReadGiven, R53).
    Item moved = item;
    item = Item{};  // empty slot
    // UNKNOWN: R76 buffer reset for the emptied giver slot is not applied here.
    // The giver is const in this signature, so resetEmptiedBuffers() cannot be called.
    receiverInv.pack[static_cast<u32>(freeSlot)] = moved;
    Item& placed = receiverInv.pack[static_cast<u32>(freeSlot)];
    giveRead(ctx, receiver, placed);

    // RESOLVED-BY-REFERENCE: the give line is
    // "Give of Item to \"<name>\" Completed!" (Party.GaveItem, Party.cs:502,
    // MAINMOD2.BAS:3004-3006), written after the read-again line.
    Str text = Str("Give of Item to \"") + trimEndName(receiver.name) + "\" Completed!";
    ctx.say("items.give.done", text, {slot, freeSlot}, {giver.name, receiver.name});
    return GiveOutcome::Given;
}

VaultGiveOutcome giveFromVault(Ctx& ctx, Inventory& giverInv, Character& receiver,
                               Inventory& receiverInv, i32 bankSlot) {
    // ASSUMED: an out-of-range bank index is treated as an empty vault slot.
    if (bankSlot < 0 || bankSlot >= kBankSlots) {
        return VaultGiveOutcome::Empty;
    }
    Item& item = giverInv.bank[static_cast<u32>(bankSlot)];

    // R49: an empty vault slot returns "" (no message).
    if (slotIsEmpty(item)) {
        return VaultGiveOutcome::Empty;
    }

    // R50: a guild-issued item is refused. No equipped test on this branch.
    // ASSUMED: the refusal text matches the pack refusal.
    if (item.guildIssued || item.isGuildItem()) {
        ctx.say("items.vault.guildIssued", "Cannot give Guild-Issued Items!",
                {bankSlot}, {receiver.name});
        return VaultGiveOutcome::GuildIssued;
    }

    // R51: receiver must have a free pack slot. Message is unquoted.
    const i32 freeSlot = firstFreePackSlot(receiverInv);
    if (freeSlot < kFirstItemSlot || freeSlot > kLastItemSlot) {
        ctx.say("items.vault.receiverFull", receiver.name + " has no free slots!",
                {bankSlot}, {receiver.name});
        return VaultGiveOutcome::ReceiverFull;
    }

    // R51: on success the vault slot empties.
    Item moved = item;
    item = Item{};
    receiverInv.pack[static_cast<u32>(freeSlot)] = moved;
    Item& placed = receiverInv.pack[static_cast<u32>(freeSlot)];
    // ASSUMED: the vault give takes the same reading path as a pack give (R53).
    giveRead(ctx, receiver, placed);

    // RESOLVED-BY-REFERENCE: the vault give line is the same
    // "Give of Item to \"<name>\" Completed!" as the pack give (Party.GaveItem,
    // Party.cs:502: "from the pack or from the vault alike").
    Str text = Str("Give of Item to \"") + trimEndName(receiver.name) + "\" Completed!";
    ctx.say("items.vault.done", text, {bankSlot, freeSlot}, {receiver.name});
    return VaultGiveOutcome::Given;
}

const ItemDef* defOf(const Ctx& ctx, i32 itemId) {
    if (itemId <= 0 || static_cast<u32>(itemId) >= ctx.data.items.size()) return nullptr;
    return &ctx.data.items[static_cast<u32>(itemId)];
}

const RaceDef* raceOf(const Ctx& ctx, const Character& c) {
    u32 r = static_cast<u32>(c.race);
    return r < ctx.data.races.size() ? &ctx.data.races[r] : nullptr;
}

Str itemNameOf(const Ctx& ctx, const Item& it) {
    const ItemDef* d = defOf(ctx, it.id);
    return d ? d->name : Str();
}

f64 guildUseFactor(i32 guildIdx) {
    if (guildIdx == static_cast<i32>(Guild::Nomad)) return kItemUseFactorNomad;
    if (guildIdx == static_cast<i32>(Guild::Healer)) return kItemUseFactorHealer;
    return 1.0;
}

bool guildAllowed(const ItemDef& d, i32 g) {
    // FIXED: ItemDef member guildMask does not exist; using guilds (the name the compiler suggested).
    return ((d.guilds >> static_cast<u32>(g)) & 1u) != 0u;
}

bool guildInScope(const Character& c, i32 g, bool classRestricted) {
    const GuildMembership& m = c.guilds[static_cast<u32>(g)];
    if (!m.joined || m.level <= 0) return false;
    if (classRestricted && g != static_cast<i32>(c.activeGuild)) return false;
    return true;
}

f64 requiredGuildLevel(const ItemDef& d, i32 g) {
    f64 f = guildUseFactor(g);
    f64 req = (f + f * 2.97) * d.levelScale;
    return req < 1.0 ? 1.0 : req;
}

bool canUseByGuilds(const Character& c, const ItemDef& d, bool classRestricted) {
    for (i32 g = 0; g < kGuildCount; ++g) {
        if (guildInScope(c, g, classRestricted) && guildAllowed(d, g)) return true;
    }
    return false;
}

bool meetsUseLevelFor(const Character& c, const ItemDef& d, bool classRestricted) {
    for (i32 g = 0; g < kGuildCount; ++g) {
        if (!guildInScope(c, g, classRestricted)) continue;
        if (static_cast<f64>(c.guilds[static_cast<u32>(g)].level) >= requiredGuildLevel(d, g)) return true;
    }
    return false;
}

Str swapMessage(SwapResult r) {
    switch (r) {
        case SwapResult::SourceGuildIssued: return Str("Source Item is a Guild-Issued Item!");
        case SwapResult::DestGuildIssued: return Str("Destination Item is a Guild-Issued Item!");
        case SwapResult::SourceEquippedOrBanked: return Str("Source Item is either Equipped or in the Bank!");
        case SwapResult::DestEquippedOrBanked: return Str("Destination Item is either Equipped or in the Bank!");
        default: return Str();
    }
}

Str alignTag(ItemAlign a) {
    switch (a) {
        case ItemAlign::Good: return Str(" (g)");
        case ItemAlign::Neutral: return Str(" (n)");
        case ItemAlign::Evil: return Str(" (e)");
        default: return Str();
    }
}

bool alignCompatible(ItemAlign a, ItemAlign b) {
    return a == b || a == ItemAlign::Unaligned || b == ItemAlign::Unaligned;
}

Str combineSuffix(CombineCheck r) {
    switch (r) {
        case CombineCheck::NotCompatibleClass: return Str(" is not compatible class");
        case CombineCheck::NotSameType: return Str(" is not of the same type");
        case CombineCheck::NotCompatibleAlignment: return Str(" is not compatible Alignment");
        default: return Str();
    }
}

void applyStatMods(Ctx& ctx, Character& c, const ItemDef& d, bool reversed) {
    for (i32 i = 0; i < kStatCount; ++i) {
        // FIXED: ItemDef member statMods does not exist; using statsMod (name suggested by compiler).
        applyStatMod(ctx, c, static_cast<StatIndex>(i), d.statsMod[i], reversed);
    }
}

bool slimeHits(i32 roll, i32 dungeonLevel) {
    return roll < kSlimeBaseRoll + dungeonLevel * kSlimeDungeonFactor;
}

bool slotEmpty(const Inventory& inv, i32 internalIndex) {
    if (!packIndexValid(internalIndex)) return false;
    return inv.pack[internalIndex].id == 0;
}

i32 firstFreeSlot(const Inventory& inv) {
    for (i32 i = 1; i < kPackSlots; ++i) {
        if (slotEmpty(inv, i)) return i;
    }
    return -1;
}

i32 handsUsed(const Ctx& ctx, const Inventory& inv) {
    i32 h = 0;
    for (i32 i = 1; i < kPackSlots; ++i) {
        const Item& it = inv.pack[i];
        if (!it.equipped) continue;
        const ItemDef* d = defOf(ctx, it.id);
        if (d) h += d->nHands;
    }
    return h;
}

EquipProblem equipProblem(const Ctx& ctx, const Character& c, const Inventory& inv, const Item& it) {
    const ItemDef* d = defOf(ctx, it.id);
    if (!d) return EquipProblem::None;  // UNKNOWN: empty or unknown item id
    if (handsUsed(ctx, inv) + d->nHands > kHandsCapacity) return EquipProblem::NoFreeHands;
    i32 cls = wearClassOf(ctx, it);
    i32 cap = maxWornOfClass(ctx, cls);
    if (cap > 0 && wornOfClass(ctx, inv, cls) >= cap) return EquipProblem::UsingTooMany;
    bool restricted = d->classRestricted;
    if (!canUseByGuilds(c, *d, restricted)) {
        return restricted ? EquipProblem::ClassRestricted : EquipProblem::GuildsCannotUse;
    }
    if (!meetsUseLevelFor(c, *d, restricted)) {
        return restricted ? EquipProblem::GuildLevelTooLow : EquipProblem::AllGuildLevelsTooLow;
    }
    // CONFLICT: engine text "One or more stats are too low!" [c2] vs FIDELITY
    // "You are too weak..." [c26]. Engine text used (StatsTooLow).
    for (i32 i = 0; i < kStatCount; ++i) {
        if (c.abilities.stats[i] < d->statsRequired[i]) return EquipProblem::StatsTooLow;
    }
    return EquipProblem::None;
}

Str equipProblemText(EquipProblem p) {
    switch (p) {
        case EquipProblem::NoFreeHands: return Str("No Free Hands!");
        case EquipProblem::UsingTooMany: return Str("Using too Many!");
        case EquipProblem::ClassRestricted: return Str("Your current guild cannot use this item!");
        case EquipProblem::GuildsCannotUse: return Str("Your currently joined guilds cannot use this item!");
        case EquipProblem::GuildLevelTooLow: return Str("Your guild level is too low to use item!");
        case EquipProblem::AllGuildLevelsTooLow: return Str("All guild levels too low to use item!");
        case EquipProblem::StatsTooLow: return Str("One or more stats are too low!");
        case EquipProblem::TooWeak: return Str("You are too weak to equip this item!");
        case EquipProblem::CursedStatsTooLow: return Str("Your stats are too low for the item to properly attach!");
        default: return Str();
    }
}

bool equipItem(Ctx& ctx, Character& c, Inventory& inv, i32 internalSlot) {
    if (!packIndexValid(internalSlot)) return false;
    Item& it = inv.pack[internalSlot];
    if (it.id <= 0 || !defOf(ctx, it.id)) return false;
    EquipProblem p = equipProblem(ctx, c, inv, it);
    if (p != EquipProblem::None) {
        ctx.say("items.equipRefused", equipProblemText(p), {}, {});
        return false;
    }
    it.equipped = true;
    applyEquipCurse(ctx, it, fitFor(it.alignment, c.alignment));
    return true;
}

i32 wearClassOf(const Ctx& ctx, const Item& it) {
    const ItemDef* d = defOf(ctx, it.id);
    if (!d) return 0;
    u32 t = static_cast<u32>(d->type);
    if (d->type < 0 || t >= ctx.data.itemTypes.size()) return 0;
    return ctx.data.itemTypes[t].index;
}

i32 maxWornOfClass(const Ctx& ctx, i32 wearClass) {
    if (wearClass < 0 || static_cast<u32>(wearClass) >= ctx.data.itemDescriptions.size()) return 0;
    return ctx.data.itemDescriptions[static_cast<u32>(wearClass)].index;
}

bool isWearable(const Ctx& ctx, const Item& it) {
    return maxWornOfClass(ctx, wearClassOf(ctx, it)) != 0;
}

i32 wornOfClass(const Ctx& ctx, const Inventory& inv, i32 wearClass) {
    i32 n = 0;
    for (i32 i = 1; i < kPackSlots; ++i) {
        const Item& it = inv.pack[i];
        if (it.equipped && it.id > 0 && wearClassOf(ctx, it) == wearClass) ++n;
    }
    return n;
}

void applyEquipCurse(Ctx& ctx, Item& slot, FitClass fit) {
    (void)ctx;
    if (slot.cursed != CurseNone) slot.slotCursed = true;
    if (fit == FitClass::Subtract) slot.slotCursed = true;
}

UncurseResult checkUncurse(const Item& slot) {
    if (!slot.slotCursed) return UncurseResult::NotCursed;
    if (!slot.equipped) return UncurseResult::NotEquipped;
    return UncurseResult::Ok;
}

UncurseResult uncurseSlot(Ctx& ctx, Item& slot) {
    UncurseResult r = checkUncurse(slot);
    if (r == UncurseResult::NotCursed) {
        ctx.say("items.uncurseNotCursed", "Item is not cursed!", {}, {});
        return r;
    }
    if (r == UncurseResult::NotEquipped) {
        ctx.say("items.uncurseNotEquipped", "Item isn't equipped!", {}, {});
        return r;
    }
    slot.slotCursed = false;
    return UncurseResult::Ok;
}

void forcedUnequipCheck(Ctx& ctx, const Character& c, const Inventory& inv, Item& slot) {
    if (equipProblem(ctx, c, inv, slot) != EquipProblem::None && !slot.slotCursed) {
        slot.equipped = false;
    }
}

GiveRefusal checkGive(const Item& slot, const Inventory& recipient) {
    if (isGuildIssuedItem(slot)) return GiveRefusal::GuildIssued;
    if (slot.equipped) return GiveRefusal::Equipped;
    if (firstFreeSlot(recipient) < 0) return GiveRefusal::NoFreeSlot;
    return GiveRefusal::None;
}

bool giveSlot(Ctx& ctx, Inventory& from, i32 fromSlot, Inventory& to) {
    if (!packIndexValid(fromSlot)) return false;
    Item& src = from.pack[fromSlot];
    if (src.id <= 0) return false;
    GiveRefusal r = checkGive(src, to);
    if (r != GiveRefusal::None) {
        Str name = itemNameOf(ctx, src);
        if (r == GiveRefusal::GuildIssued) {
            ctx.say("items.giveGuildIssued", "Cannot give Guild-Issued Items!", {}, {});
        } else if (r == GiveRefusal::Equipped) {
            ctx.say("items.giveEquipped", "Cannot give equipped items!", {}, {});
        } else {
            ctx.say("items.giveNoSlot", Str("\"") + name + Str("\" has no free slots!"), {}, {name});
        }
        return false;
    }
    i32 dest = firstFreeSlot(to);
    to.pack[dest] = src;
    src = Item{};
    return true;
}

BankResult depositGold(Ctx& ctx, Purse& purse, Currency amount) {
    (void)ctx;
    if (amount > purse.goldOnHand || amount <= 0) return BankResult::Beep;
    purse.goldInBank += amount;
    purse.goldOnHand -= amount;
    return BankResult::Ok;
}

BankResult withdrawGold(Ctx& ctx, Purse& purse, Currency amount) {
    (void)ctx;
    if (amount > purse.goldInBank || purse.goldInBank < 0) return BankResult::Beep;
    purse.goldOnHand += amount;
    purse.goldInBank -= amount;
    return BankResult::Ok;
}

void transferGold(Ctx& ctx, Character& from, Character& to, Currency amount) {
    (void)ctx;
    Currency want = amount < 0 ? 0 : amount;
    Currency moved = want < from.wallet.goldOnHand ? want : from.wallet.goldOnHand;
    // R24: receiver balance cap. Refuse the transfer rather than overflow the receiver.
    if (moved > kBalanceCap - to.wallet.goldOnHand) {
        return;
    }
    to.wallet.goldOnHand += moved;
    from.wallet.goldOnHand -= moved;
}

BuyResult buyItem(Ctx& ctx, Purse& purse, Inventory& inv, const Item& item, Currency price) {
    i32 slot = firstFreeSlot(inv);
    if (slot < 0) {
        ctx.say("items.buyNoSlot", "No free slots!", {}, {});
        return BuyResult::NoFreeSlot;
    }
    if (purse.goldOnHand < price) {
        ctx.say("items.buyNoGold", "Not enough gold!", {}, {});
        return BuyResult::NotEnoughGold;
    }
    purse.goldOnHand -= price;
    inv.pack[slot] = item;
    return BuyResult::Ok;
}

SwapResult checkSwap(const Inventory& from, i32 slotFrom, const Inventory& to, i32 slotTo) {
    if (!packIndexValid(slotFrom) || !packIndexValid(slotTo)) return SwapResult::OutOfRange;
    const Item& a = from.pack[slotFrom];
    const Item& b = to.pack[slotTo];
    if (isGuildIssuedItem(a)) return SwapResult::SourceGuildIssued;
    if (isGuildIssuedItem(b)) return SwapResult::DestGuildIssued;
    if (a.equipped) return SwapResult::SourceEquippedOrBanked;
    if (b.equipped) return SwapResult::DestEquippedOrBanked;
    return SwapResult::Ok;
}

bool swapPackSlots(Ctx& ctx, Inventory& from, i32 slotFrom, Inventory& to, i32 slotTo) {
    SwapResult r = checkSwap(from, slotFrom, to, slotTo);
    if (r == SwapResult::OutOfRange) return false;  // refused silently [R-swap]
    if (r != SwapResult::Ok) {
        ctx.say("items.swapRefused", swapMessage(r), {}, {});
        return false;
    }
    Item tmp = from.pack[slotFrom];
    from.pack[slotFrom] = to.pack[slotTo];
    to.pack[slotTo] = tmp;
    return true;
}

bool swapPlayerSlots(Ctx& ctx, Character& c, Inventory& inv, i32 playerA, i32 playerB, bool buffersFollow) {
    (void)ctx;
    if (!isValidPlayerSlot(playerA) || !isValidPlayerSlot(playerB)) return false;
    i32 a = playerA - 1;
    i32 b = playerB - 1;
    Item tmp = inv.pack[a];
    inv.pack[a] = inv.pack[b];
    inv.pack[b] = tmp;
    if (buffersFollow) {
        for (i32 k = 0; k < kSpellBuffers; ++k) {
            i32& v = c.order.spellBuffers[k];
            if (v == a) {
                v = b;
            } else if (v == b) {
                v = a;
            }
        }
    }
    return true;
}

bool slimeStrikes(Ctx& ctx, i32 dungeonLevel) {
    return slimeHits(slimeRollValue(ctx), dungeonLevel);
}

i32 destroyChance(i32 levelFound, i32 charDex, i32 monDex, bool paralysed) {
    i32 raw;
    if (!paralysed) {
        raw = (kDestroyBase - levelFound) + (charDex + charDex) * kDestroyDexFactor
            - monDex * kDestroyMonDexFactor;
    } else {
        double v = static_cast<double>(kDestroyBase - levelFound)
            + static_cast<double>(charDex + charDex) / 2.0
            - static_cast<double>(monDex * kDestroyMonDexFactor);
        raw = static_cast<i32>(vbInt(v));
    }
    return clampI(raw, kDestroyMin, kDestroyMax);
}

bool isDestructible(i32 specialType) {
    return specialType < kGuildMarkerBase || specialType > kGuildMarkerBase + kGuildCount - 1;
}

Currency slimeGold(Ctx& ctx, i32 dungeonLevel, i32 monAtt, i32 monLvl, i32 guildLevel) {
    f64 denom = static_cast<f64>(guildLevel < 1 ? 1 : guildLevel);
    f64 scale = (static_cast<f64>(dungeonLevel + monAtt) * (kSlimeGoldCoef * static_cast<f64>(monLvl))) / denom;
    return vbInt(ctx.rng.nextDouble() * scale);
}

TheftFlags theftFlags(i32 score, i32 monLvl) {
    i32 v = score - monLvl * kMonLvlScoreFactor;
    TheftFlags f;
    f.gold = v < kTheftScoreLimit;
    f.item = v <= kItemTheftScoreLimit;
    return f;
}

SlimeResult rollSlime(Ctx& ctx, Inventory& inv, const SlimeInput& in) {
    SlimeResult r;  // slot = -1 means no effect
    i32 roll = slimeRollValue(ctx);
    if (!slimeHits(roll, in.dungeonLevel)) return r;
    i32 slot = slimeSlot(ctx);
    if (slotEmpty(inv, slot) || inv.pack[slot].id <= 0) return r;
    r.slot = slot;
    Item& it = inv.pack[slot];
    const ItemDef* d = defOf(ctx, it.id);
    i32 special = d ? d->specialType : 0;
    if (isDestructible(special)) {
        i32 chance = destroyChance(it.level, in.charDex, in.monDex, in.paralysed);
        if (ctx.rng.percent(chance)) {
            r.destroyed = true;
            Str name = itemNameOf(ctx, it);
            ctx.say("items.slimeDestroyed", Str("SLIME: ") + name + Str(" Destroyed!"), {}, {name});
            it = Item{};
        }
    }
    r.theft = theftFlags(roll, in.monLvl);
    if (r.theft.gold) {
        r.goldTaken = slimeGold(ctx, in.dungeonLevel, in.monAtt, in.monLvl, in.guildLevel);
    }
    return r;
}

i32 attDefWorth(i32 raw, FitClass fit) {
    switch (fit) {
        case FitClass::Full: return raw;
        case FitClass::Half: return static_cast<i32>(roundHalfEven(static_cast<f64>(raw) / 2.0));
        case FitClass::Subtract: return -raw;
    }
    return raw;
}

i32 attackDefenceHalved(i32 x) {
    return static_cast<i32>(roundHalfEven(static_cast<f64>(x) / 2.0));
}

i32 statModHalved(i32 x) {
    return static_cast<i32>(vbInt(static_cast<f64>(x) / 2.0));
}

bool effectBitCounts(ItemAlign itemAlign, Align charAlign) {
    if (itemAlign == ItemAlign::Unaligned) return true;
    return static_cast<i32>(itemAlign) - 1 == static_cast<i32>(charAlign);
}

u32 gearEffects(const Ctx& ctx, const Character& c, const Inventory& inv) {
    u32 e = 0;
    for (i32 i = 1; i < kPackSlots; ++i) {
        const Item& it = inv.pack[i];
        if (!it.equipped || it.id <= 0) continue;
        if (!effectBitCounts(it.alignment, c.alignment)) continue;
        const ItemDef* d = defOf(ctx, it.id);
        if (d) e |= (d->abilities & kEffectMask);
    }
    return e & kEffectMask;
}

bool isCombinableType(i32 typeNumber) {
    return (typeNumber >= 23 && typeNumber <= 28) || typeNumber == 30 || typeNumber == 31;
}

CombineCheck checkCombine(const Ctx& ctx, const Item& first, const Item& next) {
    (void)ctx;
    // R54: the first item's type must be combinable; each later item is compared on type.
    // The item's own type field is used (no definition lookup by id).
    if (!isCombinableType(first.type) || !isCombinableType(next.type)) return CombineCheck::NotCompatibleClass;
    if (first.type != next.type) return CombineCheck::NotSameType;
    // GAP: R54 also requires IdLevel::All on both items and equal item ids. CombineCheck has no
    // NotIdentified / NotSameId value in the supplied headers, so those checks are not modelled.
    if (!alignCompatible(first.alignment, next.alignment)) return CombineCheck::NotCompatibleAlignment;
    const i64 sum = static_cast<i64>(first.charges) + static_cast<i64>(next.charges);
    if (sum > kChargesMax || sum < kChargesMin) return CombineCheck::Overflow;   // R56
    return CombineCheck::Ok;
}

CombineCheck combineCharges(Ctx& ctx, Item& first, Item& next) {
    CombineCheck r = checkCombine(ctx, first, next);
    if (r == CombineCheck::Ok) {
        first.charges = first.charges + next.charges;
        next.id = 0;
        return r;
    }
    if (r != CombineCheck::Overflow) {
        ctx.say("items.combineRefused", itemNameOf(ctx, next) + combineSuffix(r), {}, {});
    }
    return r;
}

bool mustBeEquipped(i32 typeNumber) {
    return (typeNumber >= kMustEquipTypeMin && typeNumber <= kMustEquipTypeMax)
        || typeNumber == 29 || typeNumber == 32 || typeNumber == 33 || typeNumber == 34;
}

bool isConsumedType(i32 typeNumber) {
    return (typeNumber >= kConsumedTypeMin && typeNumber <= kConsumedTypeMax)
        || typeNumber == 30 || typeNumber == 31;
}

UseCheck checkUse(const Ctx& ctx, const Character& c, const Inventory& inv, i32 internalSlot, bool inDungeon) {
    (void)c;
    if (!inDungeon) return UseCheck::NotInDungeon;
    if (!packIndexValid(internalSlot)) return UseCheck::NoEffect;
    const Item& it = inv.pack[internalSlot];
    const ItemDef* d = defOf(ctx, it.id);
    if (!d) return UseCheck::NoEffect;
    if (d->specialType == 0 && it.spellId == 0) return UseCheck::NoEffect;
    if (mustBeEquipped(d->type) && !it.equipped) return UseCheck::MustBeEquipped;
    if (isConsumedType(d->type) && it.charges <= 0) return UseCheck::OutOfCharges;
    return UseCheck::Ok;
}

void removeIfExhausted(Ctx& ctx, Inventory& inv, i32 internalSlot) {
    if (!packIndexValid(internalSlot)) return;
    Item& it = inv.pack[internalSlot];
    const ItemDef* d = defOf(ctx, it.id);
    if (d && isConsumedType(d->type) && it.charges <= 0) it = Item{};
}

void applySpecialType(Ctx& ctx, Character& c, const ItemDef& def, i32 specialType) {
    switch (static_cast<SpecialEffect>(specialType)) {
        case SpecialEffect::StatMods:
            applyStatMods(ctx, c, def, false);
            break;
        case SpecialEffect::SpellPoints50:
            c.vitals.curSpellPoints += 50;  // UNKNOWN: no cap applied
            break;
        case SpecialEffect::SpellPoints200:
            c.vitals.curSpellPoints += 200;  // UNKNOWN: no cap applied
            break;
        case SpecialEffect::PotionOfYouth:
            youngerBy(ctx, c, kYouthYears);
            applyStatMods(ctx, c, def, false);
            break;
        case SpecialEffect::DragonsBlood:
            youngerBy(ctx, c, kDragonsBloodYears);
            applyStatMods(ctx, c, def, false);
            break;
        default:
            break;
    }
}

void youngerBy(Ctx& ctx, Character& c, i32 years) {
    c.ageDays -= years * kYearDays;
    if (c.ageDays < kCharacterMinAge) {
        c.ageDays = kCharacterMinAge;
        ctx.say("items.cannotGetYounger", "You cannot get any younger.", {}, {});
    }
}

i32 applyStatMod(Ctx& ctx, Character& c, StatIndex stat, i32 mod, bool reversed) {
    i32 idx = static_cast<i32>(stat);
    i32 cur = c.abilities.stats[idx];
    const RaceDef* race = raceOf(ctx, c);
    if (!race) return cur;
    // R (ch13): ceiling = race.Max[i] + 5, taken from the race record (ItemUse.cs ApplyStatMods).
    // The cap is silent; a raise that reaches it is still applied.
    i32 ceiling = race->max[idx] + kStatCeilingBonus;
    i32 s = cur;
    if (reversed && mod > 0) {
        s -= mod;
    } else {
        s += mod;
    }
    if (s > ceiling) s = ceiling;
    // UNKNOWN: ch13 also has "if stat < race.Min[i] then stat = race.Min[i]". The RaceDef
    // minimum field name is not in the packet, so the floor is not applied here. See NEED.
    c.abilities.stats[idx] = s;
    return s;
}

bool rollIdentifyTick(Ctx& ctx, f64 skill, bool dark) {
