}

i32 seerTakeCount(Ctx& ctx, i32 n) {
    i64 take = roundHalfEven(static_cast<f64>(n) - ctx.rng.nextDouble() * static_cast<f64>(n));
    if (take > kSeerTakeMax) take = kSeerTakeMax;
    if (take > n) take = n;
    if (take < 1) take = 1;
    return static_cast<i32>(take);
}

