                             Inventory& to, i32 toSlot) {
    if (&from == &to && fromSlot == toSlot) return ExchangeOutcome::SameSlot;  // R75
    if (fromSlot < 0 || fromSlot > kLastPackIndex || toSlot < 0 || toSlot > kLastPackIndex) {
