bool parseJson(const Str& text, JsonValue& out, Str& err) {
  Parser p(text);
  out = JsonValue();
  if (!p.parseValue(out, 0)) { err = p.err; return false; }
  p.ws();
  if (p.i != text.size()) { err = "trailing characters at offset " + std::to_string(p.i); return false; }
  return true;
}

