        case RecordKind::Wealthiest: return "Wealthiest";
        case RecordKind::Fighting: return "Fighting";
        case RecordKind::Magic: return "Magic";
        case RecordKind::Thieving: return "Thieving";
    }
    return "Record";
}

i64 powerFromFields(i32 att, i32 strength, i32 hits, i32 dex, i32 guildLevel,
                    u32 specialFlags, u32 spellFlags) {
    // first = round_even(Att*2 + STR*10 + Hits/10.0)
    i64 first = roundHalfEven(static_cast<double>(att) * 2.0 +
                              static_cast<double>(strength) * 10.0 +
                              static_cast<double>(hits) / 10.0);
    // power = first + DEX*2 + GuildLevel + 75*count(special 0..13) + 100*count(spell 0..17)
    // UNKNOWN: Creature has no dedicated spell-bit field; specialBits is taken as the
    // special-attack bits and specialPropertyFlags as the spell bits.
    return first + static_cast<i64>(dex) * 2 + static_cast<i64>(guildLevel) +
           kPowerSpecialWeight * countLowBits(specialFlags, kPowerSpecialBits) +
           kPowerSpellWeight * countLowBits(spellFlags, kPowerSpellBits);
}

bool endsWith(const Str& s, const char* suffix) {
    i32 sl = 0;
    while (suffix[sl] != '\0') ++sl;
    i32 n = static_cast<i32>(s.size());
    if (n < sl) return false;
    for (i32 i = 0; i < sl; ++i) {
        if (s[static_cast<u32>(n - sl + i)] != suffix[i]) return false;
    }
    return true;
}

Str dropLast(const Str& s, i32 k) {
    return s.substr(0, static_cast<u32>(static_cast<i32>(s.size()) - k));
}

bool inPartyAtDefeat(const Party& party) {
    return party.size > 1;
}

void sayAsmodeusEnding(Ctx& ctx, bool inAParty) {
    ctx.say("asmodeus.ending",
            inAParty ? "Asmodeus is destroyed. Your party has won the day."
                     : "Asmodeus is destroyed. You stand alone in victory.",
            {inAParty ? 1 : 0}, {});
}

Str asmodeusLogLine(const Str& name, bool inAParty) {
    if (inAParty) return name + " was part of the party that defeated him.";
    return name + " single handedly defeated Asmodeus.";
}

void writeAsmodeusGuildLogs(Ctx& ctx, const Party& party, bool inAParty) {
    for (i32 i = 0; i < party.size; ++i) {
        const Character& ch = party.members[static_cast<u32>(i)];
        if (ch.isDead()) continue;  // survivors only
        Str line = asmodeusLogLine(ch.name, inAParty);
        ctx.say("guildlog.wrote", line, {}, {ch.name});
    }
}

bool isValidTeleportSquare(u32 wallWord) {
    return (wallWord & kWallMaskRock) == 0 && (wallWord & kWallMaskTeleporter) == 0;
}

TeleporterDestination findTeleporterDestination(Ctx& ctx, const FloorState& floor) {
    TeleporterDestination dest{};
    for (i32 tries = 0; tries < kTeleportMaxTries; ++tries) {
        i32 x = ctx.rng.below(kTeleportAxisMax) + kTeleportAxisMin;
        i32 y = ctx.rng.below(kTeleportAxisMax) + kTeleportAxisMin;
        if (isValidTeleportSquare(floorWallWord(floor, x, y))) {
            dest.found = true;  // R7
            dest.x = x;
            dest.y = y;
            return dest;
        }
    }
    return dest;  // R8: not found, TeleportTo stays null
}

TeleportTrapResult springTeleporterTrap(Ctx& ctx, Party& party, const FloorState& floor) {
    TeleportTrapResult result{};
    if (party.opener < 0 || party.opener >= party.size) return result;
    result.destination = findTeleporterDestination(ctx, floor);
    if (!result.destination.found) return result;  // R8
    Character& opener = party.members[static_cast<u32>(party.opener)];
    opener.location.x = result.destination.x;
    opener.location.y = result.destination.y;
    // UNKNOWN: opener.location.area is not recomputed on teleport (not stated in R7).
    result.teleported = true;
    ctx.say("trap.teleporter", opener.name + " is teleported!",
            {result.destination.x, result.destination.y}, {opener.name});
    return result;
}

bool pitStyleRoll(Ctx& ctx, i32 dungeonLevel) {
    double threshold = static_cast<double>(kPitRollBase) +
                       static_cast<double>(dungeonLevel) / kPitRollDepthDivisor;
    return threshold < ctx.rng.nextDouble() * kPitRollScale;
}

bool hoversOverPit(Ctx& ctx, i32 dungeonLevel) {
    return pitStyleRoll(ctx, dungeonLevel);
}

bool chuteMemberFalls(Ctx& ctx, const Character& ch, i32 dungeonLevel) {
    bool levitating = ch.ailments.levitating;
    bool hovers = hoversOverPit(ctx, dungeonLevel);
    return !(levitating && hovers);
}

i32 chuteDamage(Ctx& ctx, i32 landedLevel, i32 raceSize) {
    (void)ctx;
    (void)landedLevel;
    (void)raceSize;
    return 0;
}

i32 chuteLandingDamage(Ctx& ctx, const Character& ch, i32 landedLevel, i32 raceSize) {
    if (ch.ailments.levitating) return 0;
    return chuteDamage(ctx, landedLevel, raceSize);
}

i32 landedAreaId(const GameData& data, i32 landedLevel, i32 x, i32 y) {
    return floorAreaAt(data, landedLevel, x, y);
}

void moveFallenMember(Ctx& ctx, Character& ch, i32 landedLevel) {
    ch.location.dungeonLevel = landedLevel;
    ch.location.area = landedAreaId(ctx.data, landedLevel, ch.location.x, ch.location.y);
}

void announceChuteFall(Ctx& ctx, const Character& ch, i32 damage) {
    ctx.say("chute.fall", ch.name + " falls through the chute!", {}, {ch.name});
    ctx.say("chute.hit", ch.name + " is hurt by the landing.", {damage}, {ch.name});
}

void applyChuteFall(Ctx& ctx, Party& party, u32 idx, const FloorChute& chute,
                    i32 fromLevel, ChuteFallResult& out) {
    Character& ch = party.members[idx];
    // R12: the floor below by the chute record's depth.
    // UNKNOWN: FloorChute.depth field name assumed.
    i32 landed = fromLevel + chute.depth;
    moveFallenMember(ctx, ch, landed);                                   // R12
    i32 raceSize = raceSizeOf(ctx.data, ch.race);
    i32 dmg = chuteLandingDamage(ctx, ch, landed, raceSize);             // R13
    i32 hits = ch.vitals.curHits - dmg;
    ch.vitals.curHits = hits < 0 ? 0 : hits;  // UNKNOWN: death handling not in this part
    announceChuteFall(ctx, ch, dmg);                                     // R14
    out.fell[idx] = true;
    out.damage[idx] = dmg;
    out.fallCount += 1;
}

ChuteFallResult walkOntoChute(Ctx& ctx, Party& party, const FloorChute& chute,
                              i32 fromLevel, bool followAnswer) {
    ChuteFallResult out{};
    bool leaderFell = false;
    for (i32 i = 0; i < party.size; ++i) {
        u32 idx = static_cast<u32>(i);
        bool falls = false;
        if (i == 0) {
            falls = chuteMemberFalls(ctx, party.members[idx], fromLevel);  // R9
            leaderFell = falls;
        } else if (leaderFell && followAnswer) {
            falls = true;  // R11: follows without a roll
        } else {
            falls = chuteMemberFalls(ctx, party.members[idx], fromLevel);  // R9
        }
        if (falls) applyChuteFall(ctx, party, idx, chute, fromLevel, out);
    }
    return out;
}

ChuteFallResult takeChuteLanding(Ctx& ctx, Party& party, const FloorChute& chute,
                                 i32 fromLevel) {
    ChuteFallResult out{};
    for (i32 i = 0; i < party.size; ++i) {
        applyChuteFall(ctx, party, static_cast<u32>(i), chute, fromLevel, out);
    }
    return out;
}

void resolveChuteLeftBehind(Ctx& ctx, Party& party) {
    for (i32 i = 1; i < party.size; ++i) {
        Character& ch = party.members[static_cast<u32>(i)];
        bool sameSquare = ch.location.x == party.x && ch.location.y == party.y &&
                          ch.location.dungeonLevel == party.dungeonLevel;
        if (!sameSquare) continue;
        ch.visible = false;
        if (ch.vitals.curHits <= 0) ch.deathState = DeathState::Dead;
        ch.location.area = landedAreaId(ctx.data, party.dungeonLevel, ch.location.x, ch.location.y);
    }
}

bool hallRecordBeaten(const GameData& data, RecordKind kind, const HallRecord& stored, i64 value) {
    if (kind == RecordKind::Deadliest) {  // R17
        i64 candidatePower = monsterPowerById(data, static_cast<i32>(value));
        i64 storedPower = monsterPowerById(data, static_cast<i32>(stored.value));
        if (candidatePower <= storedPower) return false;
        return true;  // stored = -1; value <= -1 is false for monster ids
    }
    return value > stored.value;  // if value <= stored.Value: no change
}

bool checkAndLogHallRecord(Ctx& ctx, HallOfRecords& hall, RecordKind kind, i64 value,
                           const Str& holder, bool holderIsPlayer, i64 nowMs) {
    if (!hallRecordBeaten(ctx.data, kind, hallSlot(hall, kind), value)) return false;
    writeHallRecord(hall, kind, value, holder, holderIsPlayer, nowMs);  // R18
    if (!holderIsPlayer && kind != RecordKind::Deadliest) {             // R19
        announceHallRecord(ctx, kind, hallSlot(hall, kind));
    }
    return true;
}

void writeHallRecord(HallOfRecords& hall, RecordKind kind, i64 value, const Str& holder,
                     bool holderIsPlayer, i64 nowMs) {
    (void)holder;
    (void)holderIsPlayer;
    (void)nowMs;
    hall.records[static_cast<u32>(kind)] = static_cast<i32>(value);
}

void announceHallRecord(Ctx& ctx, RecordKind kind, const HallRecord& rec) {
    Str holder = rec.holder;
    ctx.say("hall.record", holder + " set the " + recordKindName(kind) + " record.",
            {rec.value}, {holder});
}

HallOfRecords defaultHallOfRecords() {
    HallOfRecords hall{};
    for (i32 i = 0; i < kRecordKindCount; ++i) {
        const HallSeed& seed = kHallSeeds[i];
        hall.records[static_cast<u32>(seed.kind)] = static_cast<i32>(seed.value);
    }
    return hall;
}

i32 countLowBits(u32 flags, i32 bitCount) {
    if (bitCount < 0) bitCount = 0;
    if (bitCount > 32) bitCount = 32;
    i32 n = 0;
    for (i32 b = 0; b < bitCount; ++b) {
        if ((flags & (u32{1} << static_cast<u32>(b))) != 0) ++n;
    }
    return n;
}

i64 monsterPower(const Creature& m) {
    return powerFromFields(m.att, m.str, m.hits, m.dex, m.guildLevel,
                           static_cast<u32>(m.specialBits),
                           m.specialPropertyFlags);
}

i64 monsterPowerById(const GameData& data, i32 monsterId) {
    const MonsterDef& def = monsterDefAt(data, monsterId);
    return powerFromFields(def.att, 0, def.hits, 0, def.guildLevel,
                           0u,
                           def.specialPropertyFlags);
}

i32 fightingSkillIndex(const Arr<f32, 6>& ratings) {
    double total = static_cast<double>(ratings[4]);
    const i32 order[3] = {2, 1, 3};
    for (i32 a : order) {
        total = static_cast<double>(
            roundHalfEven(total + static_cast<double>(ratings[static_cast<u32>(a)]) * kFightingWeight));
    }
    return static_cast<i32>(roundHalfEven(total / kFightingDivisor * kSkillPercent));
}

i32 thievingSkillIndex(f32 rating0, i32 effectiveDex) {
    double v = static_cast<double>(rating0) * static_cast<double>(effectiveDex);
    if (v < 1.0) v = 1.0;
    return static_cast<i32>(roundHalfEven(v / kThievingDivisor * kSkillPercent));
}

i32 magicSkillIndex(const GameData& data, i32 guildLevel) {
    i64 possible = 0;
    for (const auto& s : data.spells) {
        possible += static_cast<i64>(s.level) * kMagicLevelScale + kMagicCapPerSpell;
    }
    double have = 0.0;
    double half = static_cast<double>(guildLevel) / 2.0 + 0.5;
    for (const auto& s : data.spells) {
        for (const auto& g : data.guilds) {
            double rate = static_cast<double>(g.spellRate[static_cast<u32>(s.category)]);
            if (s.level > 0 && rate > 0.0 && static_cast<double>(s.level) * rate <= half) {
                have += static_cast<double>(s.level) * kMagicLevelScale;
                have = static_cast<double>(roundHalfEven(have + half));
                break;
            }
        }
    }
    if (possible == 0) return 0;
    return static_cast<i32>(
        roundHalfEven(have / static_cast<double>(possible) * kSkillPercent));
}

Str pluraliseName(const Str& name, i32 count) {
    if (count <= 1) return name;

    const char* const unchanged[] = {"sae", "lex", "ish", "asu", "shi",
                                     "toa", "ngi", "ubi", "kul"};
    for (const char* s : unchanged) {
        if (endsWith(name, s)) return name;
    }
    if (endsWith(name, "yr") || endsWith(name, "ee")) return name;
    if (endsWith(name, "man")) return dropLast(name, 3) + "men";
    if (endsWith(name, "bus") || endsWith(name, "gus") || endsWith(name, "eet")) {
        return dropLast(name, 2) + "i";
    }
    if (endsWith(name, "ry") || endsWith(name, "py")) return dropLast(name, 1) + "ies";
    if (endsWith(name, "ch")) {
        return name == "Leech" ? name + "es" : name + "s";
    }
    if (endsWith(name, "sus")) return dropLast(name, 1) + "mi";
    if (endsWith(name, "ief") || endsWith(name, "arf") || endsWith(name, "Elf") ||
        endsWith(name, "olf")) {
        return dropLast(name, 1) + "ves";
    }
    if (endsWith(name, "mmy")) return dropLast(name, 1) + "ies";
    if (endsWith(name, "s")) return name;
    return name + "s";
}

U128 u128Shl(U128 x, i32 n) {
    if (n <= 0) return x;
    if (n >= 128) return U128{0, 0};
    if (n >= 64) return U128{x.lo << (n - 64), 0};
    return U128{(x.hi << n) | (x.lo >> (64 - n)), x.lo << n};
}

U128 u128Shr(U128 x, i32 n) {
    if (n <= 0) return x;
    if (n >= 128) return U128{0, 0};
    if (n >= 64) return U128{0, x.hi >> (n - 64)};
    return U128{x.hi >> n, (x.lo >> n) | (x.hi << (64 - n))};
}

bool u128Add(U128 a, U128 b, U128& out) {
    u64 lo = a.lo + b.lo;
    u64 carryLo = lo < a.lo ? 1 : 0;
    u64 hi = a.hi + b.hi;
    bool over = hi < a.hi;
    u64 hi2 = hi + carryLo;
    if (hi2 < hi) over = true;
    out = U128{hi2, lo};
    return over;
}

U128 u128Sub(U128 a, U128 b) {
    u64 borrow = a.lo < b.lo ? 1 : 0;
    return U128{a.hi - b.hi - borrow, a.lo - b.lo};
}

i32 u128Cmp(U128 a, U128 b) {
    if (a.hi != b.hi) return a.hi < b.hi ? -1 : 1;
    if (a.lo != b.lo) return a.lo < b.lo ? -1 : 1;
    return 0;
}

i32 topBit(U128 x) {
    for (i32 i = 127; i >= 0; --i) {
        u64 w = i >= 64 ? x.hi : x.lo;
        i32 b = i >= 64 ? i - 64 : i;
        if (((w >> b) & 1u) != 0) return i;
    }
    return -1;
}

U128 mul64(u64 a, u64 b) {
    u64 aL = a & 0xffffffffu, aH = a >> 32;
    u64 bL = b & 0xffffffffu, bH = b >> 32;
    u64 ll = aL * bL;
    u64 lh = aL * bH;
    u64 hl = aH * bL;
    u64 hh = aH * bH;
    u64 mid = (ll >> 32) + (lh & 0xffffffffu) + (hl & 0xffffffffu);
    U128 r{0, 0};
    r.lo = (mid << 32) | (ll & 0xffffffffu);
    r.hi = hh + (lh >> 32) + (hl >> 32) + (mid >> 32);
    return r;
}

X87Value normalizeRound(bool negative, i64 exp, U128 r, bool sticky) {
    i32 p = topBit(r);
    if (p < 0) return X87Value{0, 0, false};
    i32 k = p - 63;
    if (k <= 0) {
        // Left shift is exact; sticky cannot be set on this path.
        U128 m = u128Shl(r, -k);
        return X87Value{m.lo, exp + k, negative};
    }
    U128 mant = u128Shr(r, k);
    U128 rem = u128Sub(r, u128Shl(mant, k));
    U128 half = u128Shl(U128{0, 1}, k - 1);
    i32 c = u128Cmp(rem, half);
    bool up = c > 0 || (c == 0 && (sticky || (mant.lo & 1u) != 0));
    i64 e = exp + k;
    if (up) {
        mant.lo += 1;
        if (mant.lo == 0) {  // carried out of 64 bits
            mant.lo = u64{1} << 63;
            e += 1;
        }
    }
    return X87Value{mant.lo, e, negative};
}

bool divStep(u64& r, u64 mb) {
    bool carry = (r >> 63) != 0;
    r <<= 1;
    if (carry || r >= mb) {
        r -= mb;  // wrapping subtraction is exact here
        return true;
    }
    return false;
}

i64 signedOrSaturate(u64 mag, bool negative) {
    const u64 kMaxMag = 9223372036854775807ULL;
    if (negative) {
        if (mag > kMaxMag) return -9223372036854775807LL - 1;
        return -static_cast<i64>(mag);
    }
    if (mag > kMaxMag) return 9223372036854775807LL;
    return static_cast<i64>(mag);
}

bool isAsciiAlnum(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
}

char lowerAscii(char c) {
    return (c >= 'A' && c <= 'Z') ? static_cast<char>(c - 'A' + 'a') : c;
}

u32 skipToAlnum(const Str& s, u32 i) {
    u32 n = static_cast<u32>(s.size());
    while (i < n && !isAsciiAlnum(s[i])) ++i;
    return i;
}

CurrencyFromDoubleResult currencyFromDoubleChecked(double value) {
    CurrencyFromDoubleResult res{};
    double d = value * 10000.0;
    const double two63 = 9223372036854775808.0;
    if (d != d || d >= two63 || d < -two63) {
        res.overflow = true;
        return res;
    }
    res.value = roundHalfEven(d);
    return res;
}

X87Value x87FromDouble(double value) {
    if (value == 0.0 || value != value || !(std::fabs(value) <= 1.7976931348623157e308)) {
        return X87Value{0, 0, false};
    }
    int e = 0;
    double f = std::frexp(std::fabs(value), &e);  // |value| = f * 2^e, f in [0.5, 1)
    u64 m = static_cast<u64>(std::ldexp(f, 64));  // exact: f has at most 53 bits
    return X87Value{m, static_cast<i64>(e) - 64, value < 0.0};
}

X87Value x87Add(const X87Value& a, const X87Value& b) {
    if (a.mantissa == 0) return b;
    if (b.mantissa == 0) return a;
    bool aBig = a.exponent > b.exponent ||
                (a.exponent == b.exponent && a.mantissa >= b.mantissa);
    const X87Value& big = aBig ? a : b;
    const X87Value& small = aBig ? b : a;
    i64 d = big.exponent - small.exponent;  // >= 0
    // Window unit is 2^(big.exponent - 64). Big mantissa sits in the high word.
    U128 bigW{big.mantissa, 0};
    U128 smallW{0, 0};
    bool sticky = false;
    if (d <= 64) {
        smallW = u128Shl(U128{0, small.mantissa}, static_cast<i32>(64 - d));
    } else {
        i64 t = d - 64;
        if (t >= 64) {
            sticky = small.mantissa != 0;
        } else {
            smallW = U128{0, small.mantissa >> t};
            sticky = (small.mantissa & ((u64{1} << t) - 1)) != 0;
        }
    }
    bool negative = big.negative;
    i64 exp = big.exponent - 64;
    U128 r{0, 0};
    if (big.negative == small.negative) {
        U128 sum{0, 0};
        bool carry = u128Add(bigW, smallW, sum);
        if (carry) {  // 129-bit result: shift right one, keep the lost bit as sticky
            sticky = sticky || ((sum.lo & 1u) != 0);
            r = U128{(u64{1} << 63) | (sum.hi >> 1), (sum.hi << 63) | (sum.lo >> 1)};
            exp += 1;
        } else {
            r = sum;
        }
    } else {
        U128 diff = u128Sub(bigW, smallW);
        if (sticky) diff = u128Sub(diff, U128{0, 1});  // B - (S + f) = (B - S - 1) + (1 - f)
        r = diff;
    }
    return normalizeRound(negative, exp, r, sticky);
}

X87Value x87Mul(const X87Value& a, const X87Value& b) {
    if (a.mantissa == 0 || b.mantissa == 0) return X87Value{0, 0, false};
    U128 p = mul64(a.mantissa, b.mantissa);
    return normalizeRound(a.negative != b.negative, a.exponent + b.exponent, p, false);
}

X87Value x87Div(const X87Value& a, const X87Value& b) {
    if (a.mantissa == 0 || b.mantissa == 0) return X87Value{0, 0, false};
    u64 ma = a.mantissa;
    u64 mb = b.mantissa;
    bool ip = ma >= mb;  // quotient in (0.5, 2)
    u64 r = ip ? ma - mb : ma;
    u64 q = ip ? 1 : 0;
    i32 fracBits = ip ? 63 : 64;
    for (i32 i = 0; i < fracBits; ++i) {
        q = (q << 1) | (divStep(r, mb) ? 1u : 0u);
    }
    bool guard = divStep(r, mb);
    bool sticky = r != 0;
    i64 exp = a.exponent - b.exponent - (ip ? 63 : 64);
    if (guard && (sticky || (q & 1u) != 0)) {
        q += 1;
        if (q == 0) {
            q = u64{1} << 63;
            exp += 1;
        }
    }
    return X87Value{q, exp, a.negative != b.negative};
}

i64 x87StoreToLong(const X87Value& v) {
    if (v.mantissa == 0) return 0;
    if (v.exponent >= 0) {
        if (v.exponent == 0) return signedOrSaturate(v.mantissa, v.negative);
        if (v.exponent >= 64 || (v.mantissa >> (63 - v.exponent)) != 0) {
            return signedOrSaturate(~u64{0}, v.negative);
        }
        return signedOrSaturate(v.mantissa << v.exponent, v.negative);
    }
    i64 shift = -v.exponent;
    if (shift > 64) return 0;  // magnitude below one half
    u64 ip = 0;
    u64 rem = v.mantissa;
    if (shift < 64) {
        ip = v.mantissa >> shift;
        rem = v.mantissa & ((u64{1} << shift) - 1);
    }
    u64 half = u64{1} << (shift - 1);
    bool up = rem > half || (rem == half && (ip & 1u) != 0);
    u64 mag = ip + (up ? 1u : 0u);
    return signedOrSaturate(mag, v.negative);
}

i32 wordSortCompare(const Str& a, const Str& b) {
    u32 i = 0;
    u32 j = 0;
    u32 na = static_cast<u32>(a.size());
    u32 nb = static_cast<u32>(b.size());
    while (true) {
        i = skipToAlnum(a, i);
        j = skipToAlnum(b, j);
        bool endA = i >= na;
        bool endB = j >= nb;
        if (endA || endB) {
            if (endA && endB) return 0;
            return endA ? -1 : 1;
        }
        char ca = lowerAscii(a[i]);
        char cb = lowerAscii(b[j]);
        if (ca != cb) return ca < cb ? -1 : 1;
        ++i;
        ++j;
    }
}

bool questKindEligible(QuestKind kind, i32 guildLevel) {
    if (kind == QuestKind::Defeat) return guildLevel >= kQuestMonsterMinGuildLevel;
    if (kind == QuestKind::Fetch) return guildLevel >= kQuestItemMinGuildLevel;
    return false;
}

i32 questMonsterLevelCap(i32 guildLevel) {
    i64 v = vbInt(static_cast<double>(guildLevel) / kQuestGuildLevelDivisor);
    return v < kQuestMonsterLevelCap ? static_cast<i32>(v) : kQuestMonsterLevelCap;
}

i32 questItemLevelCap(i32 guildLevel) {
    double base = static_cast<double>(questMonsterLevelCap(guildLevel));
    double v = base / 1.5 + 1.0;
    i64 f = vbInt(v);
    return f < kQuestItemLevelCap ? static_cast<i32>(f) : kQuestItemLevelCap;
}

i32 drawQuestLevel(Ctx& ctx, i32 levelCap) {
    if (levelCap < 1) return 1;
    return ctx.rng.below(levelCap) + 1;
}

bool isRareQuestMonster(i32 spawnWeight) {
    return spawnWeight <= kQuestRareMonsterMaxWeight;
}

bool isRareQuestItem(i32 spawnWeight) {
    return spawnWeight <= kQuestRareItemMaxWeight;
}

bool rareQuestReroll(Ctx& ctx) {
    return ctx.rng.percent(kQuestRareRerollPercent);
}

bool questItemExcluded(const Item& item, i32 itemLevel, Currency itemValue) {
    return item.cursed != CurseNone || itemLevel == 0 || itemValue < kQuestMinItemValue;
}

QuestKind rollQuestKind(Ctx& ctx, i32 guildLevel) {
    if (ctx.rng.percent(kQuestNoQuestPercent)) return QuestKind::None;
    if (guildLevel >= kQuestItemMinGuildLevel &&
        ctx.rng.percent(kQuestItemFrequencyPercent)) {
        return QuestKind::Fetch;
    }
    if (guildLevel >= kQuestMonsterMinGuildLevel) return QuestKind::Defeat;
    return QuestKind::None;
}

i32 countChars(const Str& s) {
    return static_cast<i32>(s.size());
}

template <typename T>
i32 countOf(const Vec<T>& v) {
    return static_cast<i32>(v.size());
}

bool validIndex(const ModHost& host, i32 idx) {
    return idx >= 0 && idx < countOf(host.mods);
}

char lowerAscii(char c) {
    if (c >= 'A' && c <= 'Z') {
        return static_cast<char>(c - 'A' + 'a');
    }
    return c;
}

bool isBlankChar(char c) {
    return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\v' || c == '\f';
}

Str trimText(const Str& s) {
    i32 begin = 0;
    i32 end = countChars(s);
    while (begin < end && isBlankChar(s[begin])) {
        ++begin;
    }
    while (end > begin && isBlankChar(s[end - 1])) {
        --end;
    }
    Str out;
    for (i32 i = begin; i < end; ++i) {
        out += s[i];
    }
    return out;
}

bool equalsCi(const Str& a, const Str& b) {
    const i32 n = countChars(a);
    if (n != countChars(b)) {
        return false;
    }
    for (i32 i = 0; i < n; ++i) {
        if (lowerAscii(a[i]) != lowerAscii(b[i])) {
            return false;
        }
    }
    return true;
}

bool equalsCiLiteral(const Str& a, const char* b) {
    i32 i = 0;
    while (b[i] != '\0') {
        if (i >= countChars(a)) {
            return false;
        }
        if (lowerAscii(a[i]) != lowerAscii(b[i])) {
            return false;
        }
        ++i;
    }
    return i == countChars(a);
}

bool lessCi(const Str& a, const Str& b) {
    const i32 na = countChars(a);
    const i32 nb = countChars(b);
    for (i32 i = 0; i < na && i < nb; ++i) {
        const char ca = lowerAscii(a[i]);
        const char cb = lowerAscii(b[i]);
        if (ca != cb) {
            return ca < cb;
        }
    }
    return na < nb;
}

bool containsAny(const Str& s, const char* set) {
    for (i32 i = 0; i < countChars(s); ++i) {
        for (i32 k = 0; set[k] != '\0'; ++k) {
            if (s[i] == set[k]) {
                return true;
            }
        }
    }
    return false;
}

i32 findStored(const ModSettingsStore& store, const Str& modId, const Str& key) {
    for (i32 i = 0; i < countOf(store.entries); ++i) {
        if (store.entries[i].modId == modId && store.entries[i].key == key) {
            return i;
        }
    }
    return -1;
}

void writeStoredText(ModSettingsStore& store, const Str& modId, const Str& key, const Str& value) {
    const i32 idx = findStored(store, modId, key);
    if (idx >= 0) {
        store.entries[idx].text = value;
        return;
    }
    ModSettingEntry entry;  // ModSettingEntry is the element type of ModSettingsStore::entries
    entry.modId = modId;
    entry.key = key;
    entry.text = value;
    store.entries.push_back(entry);
}

i32 findToggleIndexCi(const ModManifest& manifest, const Str& key) {
    for (i32 i = 0; i < countOf(manifest.settings); ++i) {
        if (equalsCi(manifest.settings[i].key, key)) {
            return i;
        }
    }
    return -1;
}

i32 matchOption(const Vec<Str>& options, const Str& x) {
    if (x.empty()) {
        return -1;
    }
    for (i32 i = 0; i < countOf(options); ++i) {
        if (equalsCi(options[i], x)) {
            return i;
        }
    }
    return -1;
}

bool isJsonWs(char c) {
    return c == ' ' || c == '\t' || c == '\r' || c == '\n';
}

void jsonSkipWs(const Str& t, i32& pos) {
    const i32 n = countChars(t);
    bool moved = true;
    while (moved) {
        moved = false;
        while (pos < n && isJsonWs(t[pos])) {
            ++pos;
            moved = true;
        }
        if (pos + 1 < n && t[pos] == '/' && t[pos + 1] == '/') {
            while (pos < n && t[pos] != '\n') {
                ++pos;
            }
            moved = true;
        } else if (pos + 1 < n && t[pos] == '/' && t[pos + 1] == '*') {
            pos += 2;
            while (pos + 1 < n && !(t[pos] == '*' && t[pos + 1] == '/')) {
                ++pos;
            }
            pos += 2;
            if (pos > n) {
                pos = n;
            }
            moved = true;
        }
    }
}

bool jsonParseString(const Str& t, i32& pos, Str& out) {
    const i32 n = countChars(t);
    out = Str();
    if (pos >= n || t[pos] != '"') {
        return false;
    }
    ++pos;
    while (pos < n) {
        const char c = t[pos];
        if (c == '"') {
            ++pos;
            return true;
        }
        if (c == '\\') {
            if (pos + 1 >= n) {
                return false;
            }
            const char e = t[pos + 1];
            pos += 2;
            if (e == 'n') {
                out += '\n';
            } else if (e == 't') {
                out += '\t';
            } else if (e == 'r') {
                out += '\r';
            } else if (e == 'b') {
                out += '\b';
            } else if (e == 'f') {
                out += '\f';
            } else if (e == 'u') {
                // UNKNOWN: \uXXXX escapes are replaced by '?'; the SRD does not say.
                if (pos + 4 > n) {
                    return false;
                }
                pos += 4;
                out += '?';
            } else {
                out += e;  // covers \" \\ and \/
            }
            continue;
        }
        out += c;
        ++pos;
    }
    return false;
}

bool jsonSkipValue(const Str& t, i32& pos) {
    const i32 n = countChars(t);
    if (pos >= n) {
        return false;
    }
    const char c = t[pos];
    if (c == '"') {
        Str discard;
        return jsonParseString(t, pos, discard);
    }
    if (c == '{' || c == '[') {
        i32 depth = 0;
        while (pos < n) {
            const char d = t[pos];
            if (d == '"') {
                Str discard;
                if (!jsonParseString(t, pos, discard)) {
                    return false;
                }
                continue;
            }
            if (d == '{' || d == '[') {
                ++depth;
            } else if (d == '}' || d == ']') {
                --depth;
                if (depth == 0) {
                    ++pos;
                    return true;
                }
            }
            ++pos;
        }
        return false;
    }
    // Bare token: number, true, false, null.
    const i32 start = pos;
    while (pos < n && !isJsonWs(t[pos]) && t[pos] != ',' && t[pos] != '}' && t[pos] != ']' &&
           t[pos] != ':') {
        ++pos;
    }
    return pos > start;
}

i32 manifestFieldIndex(const Str& key) {
    for (i32 i = 0; i < kManifestFieldCount; ++i) {
        if (equalsCiLiteral(key, kManifestFieldNames[i])) {
            return i;
        }
    }
    return -1;
}

void assignManifestField(ModManifest& m, i32 field, const Str& value) {
    switch (field) {
        case 0: m.id = value; break;
        case 1: m.name = value; break;
        case 2: m.version = value; break;
        case 3: m.author = value; break;
        case 4: m.gameVersion = value; break;
        case 5: m.assembly = value; break;
        case 6: m.entryType = value; break;
        case 7: m.description = value; break;
        default: break;
    }
}

bool manifestBad(Ctx& ctx) {
    ctx.say("mod.manifest_bad", "mod.json could not be parsed", {}, {});
    return false;
}

ModKind modKindOf(const LiveMod& mod) {
    (void)mod;
    return ModKind::Lifecycle;
}

i32 findPortRootIndex(const Vec<AncestorFolder>& chainNearestFirst) {
    // R1: PortTree.Root is the nearest ancestor folder that contains Mordor.sln.
    // UNKNOWN: no-match result is -1; the SRD does not say what the caller does then.
    for (i32 i = 0; i < countOf(chainNearestFirst); ++i) {
        if (chainNearestFirst[i].hasMordorSln) {
            return i;
        }
    }
    return -1;
}

Vec<Str> resolveModRoots(bool mordorModsSet,
                         const Str& mordorModsValue,
                         const Str& gameFolderModsDir,
                         const Str& programFolderModsDir) {
    Vec<Str> roots;
    if (mordorModsSet) {
        // R2.1: use the ';'-separated paths in MORDOR_MODS.
        // UNKNOWN: empty and blank segments are skipped and segments are trimmed; the SRD does
        //   not say. A blank MORDOR_MODS value therefore yields no roots.
        Str current;
        const i32 n = countChars(mordorModsValue);
        for (i32 i = 0; i <= n; ++i) {
            const bool atEnd = (i == n);
            if (atEnd || mordorModsValue[i] == kModsEnvSeparator) {
                const Str piece = trimText(current);
                if (!piece.empty()) {
                    roots.push_back(piece);
                }
                current.clear();
            } else {
                current += mordorModsValue[i];
            }
        }
        return roots;
    }
    // R2.2: mods folder beside the game folder, then beside the program.
    roots.push_back(gameFolderModsDir);
    roots.push_back(programFolderModsDir);
    return roots;
}

void discoverMods(Ctx& ctx, ModHost& host, const Vec<ModRootListing>& roots) {
    // R3: scan each root's subfolders in case-insensitive name order for mod.json.
    // UNKNOWN: ModRootListing carries only folder names and a hasManifest flag, not the text of
    //   mod.json. This function fixes the discovery order and reports each candidate. The host
    //   reads the file and then calls readManifestText, validateManifest and isDuplicateModId
    //   (R5) before adding the mod to host.mods.
    (void)host;
    for (i32 r = 0; r < countOf(roots); ++r) {
        // Copy, then insertion-sort the copy by case-insensitive name.
        Vec<ModFolderEntry> folders = roots[r].subfolders;
        const i32 n = countOf(folders);
        for (i32 i = 1; i < n; ++i) {
            ModFolderEntry key = folders[i];
            i32 j = i - 1;
            while (j >= 0 && lessCi(key.name, folders[j].name)) {
                folders[j + 1] = folders[j];
                --j;
            }
            folders[j + 1] = key;
        }
        for (i32 i = 0; i < n; ++i) {
            if (folders[i].hasManifest) {
                ctx.say("mod.discovered", "Mod folder with mod.json found",
                        {static_cast<i64>(r)}, {folders[i].name, roots[r].rootPath});
            }
        }
    }
}

bool readManifestText(Ctx& ctx, const Str& jsonText, ModManifest& out) {
    // R4: an empty file is an error. The SRD throws InvalidDataException; this port has no
    // exceptions, so it reports an event and returns false.
    if (countChars(jsonText) == 0) {
        ctx.say("mod.manifest_empty", "mod.json is empty", {}, {});
        return false;
    }
    const i32 n = countChars(jsonText);
    ModManifest parsed;
    i32 pos = 0;
    jsonSkipWs(jsonText, pos);
    if (pos >= n || jsonText[pos] != '{') {
        return manifestBad(ctx);
    }
    ++pos;
    while (true) {
        jsonSkipWs(jsonText, pos);
        if (pos < n && jsonText[pos] == '}') {  // also covers a trailing comma
            ++pos;
            break;
        }
        Str key;
        if (!jsonParseString(jsonText, pos, key)) {
            return manifestBad(ctx);
        }
        jsonSkipWs(jsonText, pos);
        if (pos >= n || jsonText[pos] != ':') {
            return manifestBad(ctx);
        }
        ++pos;
        jsonSkipWs(jsonText, pos);
        const i32 field = manifestFieldIndex(key);
        if (field >= 0 && pos < n && jsonText[pos] == '"') {
            Str value;
            if (!jsonParseString(jsonText, pos, value)) {
                return manifestBad(ctx);
            }
            assignManifestField(parsed, field, value);
        } else {
            if (!jsonSkipValue(jsonText, pos)) {
                return manifestBad(ctx);
            }
        }
        jsonSkipWs(jsonText, pos);
        if (pos < n && jsonText[pos] == ',') {
            ++pos;
            continue;
        }
        if (pos < n && jsonText[pos] == '}') {
            ++pos;
            break;
        }
        return manifestBad(ctx);
    }

ManifestProblem validateManifest(const ModManifest& manifest) {
    // F1, first failure wins.
    if (isBlankText(manifest.id)) {
        return ManifestProblem::NoId;
    }
    if (containsAny(manifest.id, "[]=\r\n")) {
        return ManifestProblem::IdBadChars;
    }
    if (isBlankText(manifest.assembly)) {
        return ManifestProblem::NoAssembly;
    }
    if (isBlankText(manifest.entryType)) {
        return ManifestProblem::NoEntryType;
    }
    return ManifestProblem::None;
}

Str manifestProblemText(ManifestProblem problem) {
    // F1 messages. UNKNOWN: None is the F1 null result; it is returned here as "".
    switch (problem) {
        case ManifestProblem::NoId: return Str("no id");
        case ManifestProblem::IdBadChars: return Str("the id may not contain [ ] or =");
        case ManifestProblem::NoAssembly: return Str("no assembly");
        case ManifestProblem::NoEntryType: return Str("no entryType");
        case ManifestProblem::None: return Str("");
    }
    return Str("");
}

bool isDuplicateModId(const ModHost& host, const Str& id) {
    // R5: a duplicate id is skipped and the first one found is kept.
    return findModIndexById(host, id) >= 0;
}

i32 findModIndexById(const ModHost& host, const Str& id) {
    // UNKNOWN: id comparison is exact (case-sensitive); the SRD does not say.
    for (i32 i = 0; i < countOf(host.mods); ++i) {
        if (host.mods[i].id == id) {
            return i;
        }
    }
    return -1;
}

Str modDisplayTitle(const ModManifest& manifest) {
    // F2: Title = (IsBlank(Name) ? Id : Name) + (Version == "" ? "" : " " + Version)
    Str title = isBlankText(manifest.name) ? manifest.id : manifest.name;
    if (!manifest.version.empty()) {
        title += " ";
        title += manifest.version;
    }
    return title;
}

bool isBlankText(const Str& text) {
    // F1/F2 IsBlank: empty or whitespace only.
    for (i32 i = 0; i < countChars(text); ++i) {
        if (!isBlankChar(text[i])) {
            return false;
        }
    }
    return true;
}

bool isModEnabled(const ModSettingsStore& store, const Str& modId) {
    // F4: IsEnabled(id) = ReadFlag(id, "Enabled", false)
    return readStoredFlag(store, modId, Str("Enabled"), false);
}

void setModEnabled(ModSettingsStore& store, const Str& modId, bool value) {
    // F4: SetEnabled writes "Enabled" as True or False.
    writeStoredFlag(store, modId, Str("Enabled"), value);
}

void loadEnabledMods(Ctx& ctx, ModHost& host) {
    // R6: only mods whose Enabled flag is true are loaded (opt-in).
    // R5: a mod with a validation problem is listed but not loaded.
    // R7: loaded in discovery order.
    // UNKNOWN: whether startup calls Load then OnEnable along the same path as a live switch-on.
    //   Chosen: yes, the same path as firstSwitchOn (R8).
    for (i32 i = 0; i < countOf(host.mods); ++i) {
        const LiveMod& mod = host.mods[i];
        if (!isModEnabled(host.settings, mod.id)) {
            continue;
        }
        if (validateManifest(mod.manifest) != ManifestProblem::None) {
            continue;
        }
        if (mod.faulted) {
            continue;
        }
        firstSwitchOn(ctx, host, i);
    }
}

void firstSwitchOn(Ctx& ctx, ModHost& host, i32 modIndex) {
    // R8: the host calls Load once, then OnEnable.
    // UNKNOWN: plain (non-lifecycle) mods have no Load or OnEnable hook in this port. Chosen: they
    //   only become active, and no hook is requested for them.
    if (!validIndex(host, modIndex)) {
        return;
    }
    LiveMod& mod = host.mods[modIndex];
    if (modKindOf(mod) == ModKind::Lifecycle) {
        if (!mod.loaded) {
            mod.loaded = true;
            ctx.say("mod.load", "Host calls Load", {}, {mod.id});
        }
        ctx.say("mod.on_enable", "Host calls OnEnable", {}, {mod.id});
    }
    mod.active = true;
}

void reactivateMod(Ctx& ctx, ModHost& host, i32 modIndex) {
    // R9: later activations call OnEnable and re-note patches.
    if (!validIndex(host, modIndex)) {
        return;
    }
    LiveMod& mod = host.mods[modIndex];
    if (modKindOf(mod) == ModKind::Lifecycle) {
        ctx.say("mod.on_enable", "Host calls OnEnable", {}, {mod.id});
        ctx.say("mod.repatch", "Host re-notes Harmony patches", {}, {mod.id});
    }
    mod.active = true;
}

void deactivateMod(Ctx& ctx, ModHost& host, i32 modIndex) {
    // R10: stop calls immediately, run OnDisable, then remove Harmony patches (Table 3).
    // UNKNOWN: UnpatchAll behaviour beyond removing the mod's patches is not stated.
    if (!validIndex(host, modIndex)) {
        return;
    }
    LiveMod& mod = host.mods[modIndex];
    mod.active = false;
    if (modKindOf(mod) == ModKind::Lifecycle) {
        ctx.say("mod.on_disable", "Host calls OnDisable", {}, {mod.id});
    }
    ctx.say("mod.unpatch", "Host removes Harmony patches", {}, {mod.id});
}

ModSwitchResult switchModLive(Ctx& ctx, ModHost& host, i32 modIndex, bool switchOn) {
    if (!validIndex(host, modIndex)) {
        return ModSwitchResult::Failed;
    }
    LiveMod& mod = host.mods[modIndex];
    // R11.4: settings are saved in every case.
    setModEnabled(host.settings, mod.id, switchOn);
    // R11.1 / R11.3: only lifecycle mods switch live. Faulted mods change at next start.
    if (modKindOf(mod) != ModKind::Lifecycle || mod.faulted) {
        ctx.say("mod.switch_deferred", "Change applies at next start", {}, {mod.id});
        return ModSwitchResult::DeferredToRestart;
    }
    if (switchOn) {
        // UNKNOWN: a switch-on of a mod with a manifest problem is refused as Failed. The SRD
        //   says such mods are not loaded but does not name the live-switch result.
        if (validateManifest(mod.manifest) != ManifestProblem::None) {
            return ModSwitchResult::Failed;
        }
        // R11.2: load if not yet loaded, otherwise reactivate.
        if (!mod.loaded) {
            firstSwitchOn(ctx, host, modIndex);
        } else {
            reactivateMod(ctx, host, modIndex);
        }
    } else {
        deactivateMod(ctx, host, modIndex);
    }
    return ModSwitchResult::Ok;
}

bool useOriginalAnswer(HookStatus status) {
    // R12.3: a null decision or a throw gives the original's answer. Only Ok uses the mod.
    return status != HookStatus::Ok;
}

bool applyHookReply(Ctx& ctx, LiveMod& mod, const ModHookReply& reply) {
    // R12.1-2: a throw disables the mod for the session and the original answer is used.
    if (reply.status == HookStatus::Threw) {
        faultMod(ctx, mod, Str("hook threw an exception"));
        return false;
    }
    // R12.3: a null decision gives the original's answer.
    if (reply.status == HookStatus::NullDecision) {
        return false;
    }
    return true;
}

void faultMod(Ctx& ctx, LiveMod& mod, const Str& reason) {
    // R12.1-2, R13: disable for the rest of the session, remove patches, log the reason.
    // UNKNOWN: whether the fault persists across sessions. Chosen: the enabled setting is left
    //   unchanged, so the mod is tried again at next start.
    mod.faulted = true;
    mod.faultReason = reason;
    mod.active = false;
    ctx.say("mod.unpatch", "Host removes Harmony patches of faulted mod", {}, {mod.id});
    ctx.say("mod.fault", "Mod disabled for this session; original rule answer used",
            {}, {mod.id, reason});
}

void raiseSettingChanged(Ctx& ctx, ModHost& host, const Str& modId, const Str& key) {
    // R14: the store raises one Changed(modId, key) event for all mods.
    ctx.say("mod.settings_changed", "Setting changed", {}, {modId, key});
    // ModSettings forwards only matching ids. Each forward is an independent call. Exceptions
    // cannot occur in this port, so the per-handler try block has no counterpart here.
    for (i32 i = 0; i < countOf(host.mods); ++i) {
        if (host.mods[i].id == modId) {
            ctx.say("mod.settings_forward", "Setting forwarded to mod", {}, {modId, key});
        }
    }
}

bool toggleValue(const ModHost& host, i32 modIndex, const Str& key) {
    // F5: Get(key) = ReadFlag(id, key, DefaultFor(key)).
    if (!validIndex(host, modIndex)) {
        return false;
    }
    const LiveMod& mod = host.mods[modIndex];
    return readStoredFlag(host.settings, mod.id, key,
                          declaredToggleDefault(mod.manifest, key));
}

bool declaredToggleDefault(const ModManifest& manifest, const Str& key) {
    // F5 DefaultFor: default of the toggle whose key matches case-insensitively, else false.
    const i32 idx = findToggleIndexCi(manifest, key);
    if (idx < 0) {
        return false;
    }
    return manifest.settings[idx].defaultValue;  // UNVERIFIED: ModToggleSpec::defaultValue not confirmed
}

Str resolveChoice(const ModChoiceSpec* spec, const Str& stored) {
    // F6: ChoiceOf(spec, stored).
    if (spec == nullptr || spec->options.empty()) {
        // stored ?? "": stored is never null in this port.
        return stored;
    }
    i32 idx = matchOption(spec->options, trimText(stored));
    if (idx < 0) {
        idx = matchOption(spec->options, spec->defaultOption);
    }
    if (idx < 0) {
        // Options[0]: the first declared option is the fallback.
        idx = 0;
    }
    return spec->options[idx];
}

bool readStoredFlag(const ModSettingsStore& store, const Str& modId, const Str& key, bool defaultValue) {
    // F4 ReadFlag: the stored boolean, or defaultValue when none is stored.
    const i32 idx = findStored(store, modId, key);
    if (idx < 0) {
        return defaultValue;
    }
    const Str text = trimText(store.entries[idx].text);
    if (equalsCiLiteral(text, "True")) {
        return true;
    }
    if (equalsCiLiteral(text, "False")) {
        return false;
    }
    // UNKNOWN: an unparsable stored flag gives defaultValue; the SRD does not say.
    return defaultValue;
}

void writeStoredFlag(ModSettingsStore& store, const Str& modId, const Str& key, bool value) {
    // F4: written as True or False.
    writeStoredText(store, modId, key, value ? Str("True") : Str("False"));
}

Str readStoredText(const ModSettingsStore& store, const Str& modId, const Str& key) {
    // Stored text, or "" when none is stored.
    const i32 idx = findStored(store, modId, key);
    if (idx < 0) {
        return Str("");
    }
    return store.entries[idx].text;
}

bool declareToggle(ModManifest& manifest, const ModToggleSpec& spec) {
    // R17 quirk (manifest wins): DeclareToggle does not replace an existing toggle with the same
    // key. The existing (manifest) toggle stays and the code default is silently ignored.
    // UNKNOWN: key match here is case-insensitive, following F5; the SRD does not say.
    if (findToggleIndexCi(manifest, spec.key) >= 0) {
        return false;
    }
    manifest.settings.push_back(spec);
    return true;
}

