    // UNKNOWN: out-of-range members return -1; the SRD does not say.
    const i32 count = static_cast<i32>(sizeof(kApiMemberVersion) / sizeof(kApiMemberVersion[0]));
    if (member < 0 || member >= count) {
        return -1;
    }
    return kApiMemberVersion[member];
}

