    const i32 swing = static_cast<i32>(vbInt(ctx.rng.nextDouble() * (static_cast<f64>(baseHits) * 0.5) / 2.0)) + 1;
    RolledHits out{};
    out.hits = (sign == 0) ? baseHits - swing : baseHits + swing;
    out.maxHits = out.hits;
    return out;
}

