}

i32 rollDice(Ctx& ctx, i32 n, i32 sides, i32 plus) {
    i32 total = plus;
    for (i32 k = 0; k < n; ++k) {
        total += static_cast<i32>(ctx.rng.below(sides)) + 1;
    }
    return total;
}

bool hasFlagBit(u32 flags, u32 bit) {
