bool floorBitPresent(u32 floorMask, i32 n) {
    if (n < 1 || n > 32) {
        return false;
    }
    return ((floorMask >> static_cast<u32>(n - 1)) & 1u) == 1u;
}

i32 atOr(const Vec<i32>& v, i32 index) {
