bool parseI32(const Str& text, i32& out) {
    const i64 n = static_cast<i64>(text.size());
    i64 p = 0;
    while (p < n && text[p] == ' ') {
        ++p;
    }
    i64 e = n;
    while (e > p && text[e - 1] == ' ') {
        --e;
    }
    bool negative = false;
    if (p < e && (text[p] == '-' || text[p] == '+')) {
        negative = (text[p] == '-');
        ++p;
    }
    if (p >= e) {
        return false;
    }
    i64 value = 0;
    for (i64 i = p; i < e; ++i) {
        const char c = text[i];
        if (c < '0' || c > '9') {
            return false;
        }
        value = value * 10 + (c - '0');
        if (value > 2147483648LL) {
            return false;
        }
    }
    if (negative) {
        value = -value;
    }
    if (value < -2147483648LL || value > 2147483647LL) {
        return false;
    }
    out = static_cast<i32>(value);
    return true;
}

bool parseFlagText(const Str& text) {
    if (equalsIgnoreCase(text, Str(kTextTrue))) {
        return true;
    }
    if (equalsIgnoreCase(text, Str("1")) || equalsIgnoreCase(text, Str("-1"))) {
        return true;
    }
    return false;
}

bool flagGet(const OptionFlags& f, i32 idx) {
    switch (idx) {
        case 0: return f.noStretch;
        case 1: return f.soundCanvas;
        case 2: return f.noPartyFx;
        case 3: return f.noAutoSave;
        case 4: return f.noLoadAutomap;
        case 5: return f.noBlinkCursor;
        case 6: return f.noDing;
        case 7: return f.noToolbar;
        default: return false;
    }
}

void flagSet(OptionFlags& f, i32 idx, bool value) {
    switch (idx) {
        case 0: f.noStretch = value; break;
        case 1: f.soundCanvas = value; break;
        case 2: f.noPartyFx = value; break;
        case 3: f.noAutoSave = value; break;
        case 4: f.noLoadAutomap = value; break;
        case 5: f.noBlinkCursor = value; break;
        case 6: f.noDing = value; break;
        case 7: f.noToolbar = value; break;
        default: break;
    }
}

i32 readIntOr(const IniDocument& ini, const char* key, i32 fallback) {
    const Str* text = iniFind(ini, Str(kOptionsSection), Str(key));
    i32 value = 0;
    if (text != nullptr && parseI32(*text, value)) {
        return value;
    }
    return fallback;
}

void readOneFont(const IniDocument& ini,
                 const char* faceKey,
                 const char* sizeKey,
                 const char* defaultFace,
                 i32 defaultSize,
                 FontSetting& out) {
    const Str* face = iniFind(ini, Str(kOptionsSection), Str(faceKey));
    if (face != nullptr && !face->empty()) {
        out.face = *face;
    } else {
        out.face = Str(defaultFace);  // R4.1
    }

    i32 size = defaultSize;
    const Str* sizeText = iniFind(ini, Str(kOptionsSection), Str(sizeKey));
    if (sizeText != nullptr) {
        i32 parsed = 0;
        if (parseI32(*sizeText, parsed)) {
            size = parsed;  // R4.2
        }
    }
    out.size = size;
}

const Str* iniFind(const IniDocument& ini, const Str& section, const Str& key) {
    const i64 s = findSectionIndex(ini, section);
    if (s < 0) {
        return nullptr;
    }
    const IniSection& sec = ini.sections[s];
    const i64 e = findEntryIndex(sec, key);
    if (e < 0) {
        return nullptr;
    }
    return &sec.entries[e].value;
}

bool iniFlagValue(const IniDocument& ini, const Str& section, const Str& key) {
    const Str* text = iniFind(ini, section, key);
    if (text == nullptr) {
        return false;
    }
    return parseFlagText(*text);
}

void iniSet(IniDocument& ini, const Str& section, const Str& key, const Str& value) {
    i64 s = findSectionIndex(ini, section);
    if (s < 0) {
        IniSection created;
        created.name = section;
        ini.sections.push_back(created);
        s = static_cast<i64>(ini.sections.size()) - 1;
    }
    IniSection& sec = ini.sections[s];
    const i64 e = findEntryIndex(sec, key);
    if (e >= 0) {
        sec.entries[e].key = key;
        sec.entries[e].value = value;
        return;
    }
    IniEntry entry;
    entry.key = key;
    entry.value = value;
    sec.entries.push_back(entry);
}

void loadOptions(Ctx& ctx, const IniDocument& ini, GameOptions& opts) {
    // R3.2: flags read as False when absent.
    for (i32 i = 0; i < kNamedOptionFlagCount; ++i) {
        flagSet(opts.flags, i, iniFlagValue(ini, Str(kOptionsSection), Str(kNamedFlagKeys[i])));
    }
    // UNKNOWN: the four unnamed flags have no known key names, so they read as False (R2).
    for (i32 i = 0; i < kUnnamedOptionFlagCount; ++i) {
        opts.flags.unnamed[i] = false;
    }
    // R3.3: MusicVolume defaults to 0.
    opts.musicVolume = readIntOr(ini, kKeyMusicVolume, kMusicVolumeDefault);
    // R3.4: FXVolume defaults to WaveVolume.Default.
    opts.fxVolume = readIntOr(ini, kKeyFxVolume, kWaveVolumeDefault);
    // R3.5: Brightness defaults to 0.
    opts.brightness = readIntOr(ini, kKeyBrightness, kBrightnessDefault);
    // R3.6: fonts via ReadFonts.
    // UNKNOWN: whether Load runs before or after ReadFonts. The SRD listing order is used.
    readFonts(ctx, ini, opts);
}

void readFonts(Ctx& /*ctx*/, const IniDocument& ini, GameOptions& opts) {
    readOneFont(ini, kKeyProFace, kKeyProSize, kProFontDefaultFace, kProFontDefaultSize, opts.proFont);
    readOneFont(ini, kKeyNonProFace, kKeyNonProSize, kNonProFontDefaultFace, kNonProFontDefaultSize,
                opts.nonProFont);
}

void saveOptions(Ctx& /*ctx*/, const GameOptions& opts, IniDocument& ini) {
    for (i32 i = 0; i < kNamedOptionFlagCount; ++i) {
        const bool on = flagGet(opts.flags, i);
        Str key;
        if (i == kNoToolbarFlagIndex) {
            // R5.2 QUIRK (kept by the port): True writes "NoToolBar", False writes "NoToolbar".
            // Keys are case-insensitive, so both refer to the same entry.
            key = on ? Str(kNoToolbarKeyWhenTrue) : Str(kNoToolbarKeyWhenFalse);
        } else {
            key = Str(kNamedFlagKeys[i]);
        }
        iniSet(ini, Str(kOptionsSection), key, Str(on ? kTextTrue : kTextFalse));
    }
}

void restoreOptionDefaults(Ctx& /*ctx*/, GameOptions& opts) {
    opts.musicVolume = kMusicVolumeDefault;
    opts.fxVolume = kWaveVolumeDefault;
    opts.brightness = kBrightnessDefault;
    opts.proFont.face = Str(kProFontDefaultFace);
    opts.proFont.size = kProFontDefaultSize;
    opts.nonProFont.face = Str(kNonProFontDefaultFace);
    opts.nonProFont.size = kNonProFontDefaultSize;
}

i32 exploredIndex(i32 x, i32 y, i32 width) {
    return y * width + x;
}

void mergeSharedMap(Ctx& /*ctx*/, SharedMap& target, const SharedMap& incoming) {
    const i64 count = static_cast<i64>(incoming.levels.size());
    for (i64 lv = 0; lv < count; ++lv) {
        const AutomapLevel& src = incoming.levels[lv];
        if (src.width <= 0 || src.height <= 0) {
            continue;  // nothing to merge for this level
        }
        while (static_cast<i64>(target.levels.size()) <= lv) {
            target.levels.push_back(AutomapLevel{});
        }
        AutomapLevel& dst = target.levels[lv];
        if (dst.width <= 0 || dst.height <= 0) {
            dst.width = src.width;
            dst.height = src.height;
            dst.explored.resize(src.explored.size(), false);
        }
        if (dst.width != src.width || dst.height != src.height) {
            continue;  // UNKNOWN: differing level shapes are not merged
        }
        const i64 dstCells = static_cast<i64>(dst.explored.size());
        const i64 srcCells = static_cast<i64>(src.explored.size());
        const i64 cells = dstCells < srcCells ? dstCells : srcCells;
        for (i64 i = 0; i < cells; ++i) {
            if (src.explored[i]) {
                dst.explored[i] = true;  // R9.1: only grow
            }
        }
    }
}

void absorbLegacyExplored(Ctx& ctx,
                          SharedMap& map,
                          const Vec<Vec<bool>>& legacyExplored,
                          const Vec<i32>& legacyLevelWidths) {
    SharedMap incoming;
    const i64 levelCount = static_cast<i64>(legacyExplored.size());
    const i64 widthCount = static_cast<i64>(legacyLevelWidths.size());
    const i64 count = levelCount < widthCount ? levelCount : widthCount;
    for (i64 lv = 0; lv < count; ++lv) {
        const i32 width = legacyLevelWidths[lv];
        if (width <= 0) {
            continue;
        }
        const Vec<bool>& cells = legacyExplored[lv];
        const i64 cellCount = static_cast<i64>(cells.size());
        AutomapLevel level;
        level.width = width;
        level.height = static_cast<i32>((cellCount + width - 1) / width);
        level.explored = cells;
        while (static_cast<i64>(incoming.levels.size()) <= lv) {
            incoming.levels.push_back(AutomapLevel{});
        }
        incoming.levels[lv] = level;
    }
    mergeSharedMap(ctx, map, incoming);  // R9.1 rule applies
}

bool levelShownOnAutomap(Ctx& /*ctx*/, const SharedMap& map, i32 level) {
    if (level < 0 || static_cast<i64>(level) >= static_cast<i64>(map.levels.size())) {
        return false;
    }
    const AutomapLevel& lv = map.levels[level];
    const i64 cells = static_cast<i64>(lv.explored.size());
    for (i64 i = 0; i < cells; ++i) {
        if (lv.explored[i]) {
            return true;
        }
    }
    return false;
}

i32 deepestVisited(Ctx& ctx, const SharedMap& map) {
    for (i64 level = static_cast<i64>(map.levels.size()) - 1; level >= 0; --level) {
        if (levelShownOnAutomap(ctx, map, static_cast<i32>(level))) {
            return static_cast<i32>(level);
        }
    }
    return -1;
}

SaveFolderChoice resolveSaveFolder(Ctx& ctx, const SaveFolderProbe& probe) {
    SaveFolderChoice choice;
    if (probe.overrideSet) {  // R11.1
        choice.source = SaveFolderSource::Override;
        choice.path = probe.overridePath;
    } else if (probe.legacyNonEmpty) {  // R11.2
        choice.source = SaveFolderSource::Legacy;
        choice.path = probe.legacyPath;
    } else {  // R11.3
        choice.source = SaveFolderSource::AppData;
        choice.path = probe.appDataPath;
    }
    ctx.say("options.save_folder", "Save folder in use", {}, {choice.path});
    return choice;
}

bool importAllowed(Ctx& ctx, const Vec<Str>& stamps) {
    const Str required(kImportVersion);
    const i64 count = static_cast<i64>(stamps.size());
    for (i64 i = 0; i < count; ++i) {
        if (!(stamps[i] == required)) {
            ctx.say("options.import_refused", "Import refused: version stamp is not 1.1", {}, {stamps[i]});
            return false;
        }
    }
    return true;
}

BuildSwitches buildSwitchesFor(BuildVariant variant) {
    BuildSwitches sw;
    if (variant == BuildVariant::Full) {
        sw.goodbyeBox = true;          // m009C = 0: goodbye box asking to pass on shareware
        sw.limitedTitle = false;
        sw.takeDenied = false;
        sw.deadChuteLines = false;
        sw.aboutOrderingInfo = false;
        sw.aboutOrdering = false;
        sw.limitationNotice = false;   // gv0180 never set in the full build
        sw.limitedSplashPrefix = false;  // m002E never set in the full build
        sw.writesLimitedFlag = false;  // gv0180 never set in the full build
    } else {
        sw.goodbyeBox = false;         // m009C True: goodbox box shown only when False
        sw.limitedTitle = true;        // m009C True: title " (Limited Version)"
        sw.takeDenied = true;          // m0622 True
        sw.deadChuteLines = true;      // m02A6 True
        sw.aboutOrderingInfo = true;   // m0032 True
        sw.aboutOrdering = true;       // m00A8 True
        sw.limitationNotice = true;    // gv0180 set
        sw.limitedSplashPrefix = true; // m002E: "Limited " prefix on splash
        sw.writesLimitedFlag = true;   // gv0180 writes Limited=True
    }
    return sw;
}

bool limitedSplashShown(Ctx& /*ctx*/, BuildVariant variant, const IniDocument& ini) {
    if (!buildSwitchesFor(variant).limitedSplashPrefix) {
        return false;
    }
    return iniFlagValue(ini, Str(kLimitedFlagSection), Str(kLimitedFlagKey));
}

i32 limitationNoticeLevels(Ctx& /*ctx*/, BuildVariant /*variant*/) {
    return kFullBuildLevelCap;
}

void showLimitationNotice(Ctx& ctx, BuildVariant variant, IniDocument& ini) {
    const BuildSwitches sw = buildSwitchesFor(variant);
    if (!sw.limitationNotice) {
        return;
    }
    const i32 levels = limitationNoticeLevels(ctx, variant);
    // Assumes ctx.say's nums parameter is a Vec<i64>.
    ctx.say("options.limitation_notice",
            "PUBLIC BETA ... only n dungeon levels, where n is nums[0]",
            {static_cast<i64>(levels)},
            {});
    if (sw.writesLimitedFlag) {
        iniSet(ini, Str(kLimitedFlagSection), Str(kLimitedFlagKey), Str(kTextTrue));
    }
}

bool isMemberOf(const Party& party, const Character& c) {
    for (i32 i = 0; i < party.size; ++i) {
        if (memberAt(party, i).name == c.name) return true;
    }
    return false;
}

void eraseMember(Party& party, i32 index) {
    if (party.size <= 0) return;
    for (i32 j = index; j + 1 < party.size; ++j) {
        memberAt(party, j) = memberAt(party, j + 1);
        party.combatOrders[static_cast<u32>(j)] = party.combatOrders[static_cast<u32>(j + 1)];
        party.itemOrders[static_cast<u32>(j)] = party.itemOrders[static_cast<u32>(j + 1)];
    }
    const u32 last = static_cast<u32>(party.size - 1);
    party.combatOrders[last] = CombatOrder{};
    party.itemOrders[last] = ItemOrder{};
    party.size -= 1;
}

void appendMember(Party& party, const Character& c) {
    if (party.size >= kPartyMaxSize) return;
    memberAt(party, party.size) = c;
    party.combatOrders[static_cast<u32>(party.size)] = CombatOrder{};
    party.itemOrders[static_cast<u32>(party.size)] = ItemOrder{};
    party.size += 1;
}

bool pruneMemberAt(Ctx& ctx, Party& party, i32 index, bool announce) {
    if (party.size <= 1) return false;                                   // R11: lone member kept
    if (index < 0 || index >= party.size) return false;
    {
        const Character& m = memberAt(party, index);
        const bool alive = !m.isDead();
        if (alive && m.vitals.curHits > 0 && m.deathState != DeathState::Stoned) {
            return false;                                                // R12.1: stays
        }
    }
    Character& m = memberAt(party, index);
    m.vitals.curHits = 0;                                                // R12.2
    // UNKNOWN: "level" in R12.2 is read as the dungeon level the member stands on.
    if (announce && m.location.dungeonLevel == memberAt(party, 0).location.dungeonLevel) {
        ctx.say("party.member.died", "\"" + m.name + "\" has died!", {}, {});  // R12.2
    }
    if (!m.isDead()) m.deathState = DeathState::Dead;                    // R12.2
    m.saved = true;                                                      // R12.2: saved
    eraseMember(party, index);                                           // R12.2: removed
    if (party.size > 0) {
        // R12.2: remaining members move to the leader's level, X and Y.
        const Location lead = memberAt(party, 0).location;
        for (i32 j = 0; j < party.size; ++j) {
            Location& l = memberAt(party, j).location;
            l.dungeonLevel = lead.dungeonLevel;
            l.x = lead.x;
            l.y = lead.y;
        }
        party.dungeonLevel = lead.dungeonLevel;
        party.x = lead.x;
        party.y = lead.y;
    }
    return true;
}

void pruneTheDeadLoop(Ctx& ctx, Party& party, bool announce) {
    i32 i = 0;
    while (i < party.size) {
        if (!pruneMemberAt(ctx, party, i, announce)) ++i;
    }
}

void dropOwnedCompanions(Vec<Companion>& companions, i32 partySize) {
    const i32 n = static_cast<i32>(companions.size());
    for (i32 i = 0; i < n; ++i) {
        Companion& c = companions[static_cast<u32>(i)];
        if (c.occupied && c.owner >= 0 && c.owner < partySize) {
            c.occupied = false;
            c.owner = -1;
        }
    }
}

void distributeOnHand(Party& party, i32 remainderIndex) {
    const i32 n = party.size;
    if (n <= 0) return;
    Currency total = 0;
    for (i32 i = 0; i < n; ++i) total += memberAt(party, i).wallet.goldOnHand;
    const Currency share = total / n;
    const Currency rem = total % n;
    for (i32 i = 0; i < n; ++i) memberAt(party, i).wallet.goldOnHand = share;
    const i32 r = (remainderIndex >= 0 && remainderIndex < n) ? remainderIndex : 0;
    memberAt(party, r).wallet.goldOnHand += rem;
}

void depositAll(Party& party) {
    for (i32 i = 0; i < party.size; ++i) {
        Purse& w = memberAt(party, i).wallet;
        w.goldInBank += w.goldOnHand;
        w.goldOnHand = 0;
    }
}

void drawExchangeGold(Character& who, Currency amount) {
    who.wallet.goldOnHand -= amount;
    if (who.wallet.goldOnHand < 0) {
        who.wallet.goldInBank += who.wallet.goldOnHand;
        who.wallet.goldOnHand = 0;
    }
}

bool parseSignedInt(const Str& text, i32 from, i32 to, i32& out) {
    i32 i = from;
    i32 end = to;
    while (i < end && text[static_cast<u32>(i)] == ' ') ++i;
    while (end > i && text[static_cast<u32>(end - 1)] == ' ') --end;
    bool neg = false;
    if (i < end && text[static_cast<u32>(i)] == '-') {
        neg = true;
        ++i;
    }
    if (i >= end) return false;
    i64 v = 0;
    for (; i < end; ++i) {
        const char ch = text[static_cast<u32>(i)];
        if (ch < '0' || ch > '9') return false;
        v = v * 10 + (ch - '0');
    }
    out = static_cast<i32>(neg ? -v : v);
    return true;
}

bool oppositelyAligned(Align a, Align b) {
    return (a == Align::Good && b == Align::Evil) || (a == Align::Evil && b == Align::Good);
}

bool isPartyFull(const Party& party) {
    return party.size >= kPartyMaxSize;
}

JoinCheck checkJoin(Ctx& ctx, const Party& party, const Character& joiner,
                    bool inDungeon, bool inCombat, bool passwordMatches) {
    JoinCheck out;
    const bool joinerDead = joiner.isDead();
    if (party.size > 0 && memberAt(party, 0).isDead()) {                 // R4.1 silent
        out.refusal = JoinRefusal::LeaderDead;
        return out;
    }
    if (inDungeon && inCombat && joinerDead) {                           // R4.2
        out.refusal = JoinRefusal::DeadInCombat;
        ctx.say("party.join.combat", "Cannot raise character in Combat!", {}, {});
        return out;
    }
    if (isPartyFull(party)) {                                            // R4.3
        out.refusal = JoinRefusal::PartyFull;
        ctx.say("party.join.full", "Your party is too full!", {}, {});
        return out;
    }
    if (!joiner.password.empty() && !passwordMatches) {                  // R6
        out.refusal = JoinRefusal::WrongPassword;
        ctx.say("party.join.password", "Incorrect Password!", {}, {});
        return out;
    }
    if (hasOppositeMember(party, joiner.alignment)) {                    // R7 (no message in SRD)
        out.refusal = JoinRefusal::OppositeAlignment;
        return out;
    }
    if (joinerDead && !joiner.pendingRaise) {                            // R8
        out.refusal = JoinRefusal::DeadNoPendingRaise;
        // UNKNOWN: the SRD text ends in "..."; the tail is not given.
        ctx.say("party.join.dead", "\"" + joiner.name + "\" is Dead! ...", {}, {});
        return out;
    }
    out.runSub0BDE = inDungeon && inCombat && !joinerDead;               // R4.2 living joiner
    return out;
}

bool isJoinCandidate(const Party& party, const Character& c, bool inCity) {
    return !isMemberOf(party, c) && samePlace(party, c, inCity);
}

bool samePlace(const Party& party, const Character& c, bool bothInCity) {
    if (bothInCity) return true;
    if (party.size <= 0) return false;
    const Location& l = memberAt(party, 0).location;
    return c.location.x == l.x && c.location.y == l.y &&
           c.location.dungeonLevel == l.dungeonLevel && c.location.area == l.area;
}

bool isOnJoinList(const Party& party, const Character& c, i32 currentArea) {
    if (isMemberOf(party, c)) return false;
    if (party.size <= 0) return false;
    return c.location.dungeonLevel == party.dungeonLevel && c.location.area == currentArea;
}

bool hasOppositeMember(const Party& party, Align joinerAlignment) {
    for (i32 i = 0; i < party.size; ++i) {
        if (oppositelyAligned(memberAt(party, i).alignment, joinerAlignment)) return true;
    }
    return false;
}

void performJoin(Ctx& ctx, Party& party, Vec<Companion>& companions, Character& joiner) {
    if (party.size <= 0 || isPartyFull(party)) return;
    const Character& leader = memberAt(party, 0);
    joiner.location.x = leader.location.x;                               // R9 square
    joiner.location.y = leader.location.y;
    joiner.location.dungeonLevel = leader.location.dungeonLevel;
    joiner.location.area = leader.location.area;
    joiner.lost.level = leader.lost.level;                               // R9 lost flags
    joiner.lost.position = leader.lost.position;
    joiner.lost.facing = leader.lost.facing;
    joiner.vitals.curHits = joiner.vitals.maxHits;                       // R9 full HP
    joiner.vitals.curSpellPoints = joiner.vitals.maxSpellPoints;         // R9 full SP
    // UNKNOWN: a dead joiner with a pending raise is pruned here (R12.1 treats isDead as
    // not alive); the raise is assumed to have been applied before the join.
    appendMember(party, joiner);
    companionCarryRun(ctx, party, companions);                           // R13: prune after carry
    pruneTheDeadLoop(ctx, party, true);                                  // R9, R14
}

LeaveResult leaveParty(Ctx& ctx, Party& party, i32 slot,
                       bool inDungeon, bool monstersPresent, bool confirmed) {
    LeaveResult r;
    if (slot < 0 || slot >= party.size) {                                // UNKNOWN: bad slot, no effect
        r.outcome = LeaveOutcome::NotConfirmed;
        return r;
    }
    const Character& who = memberAt(party, slot);
    if (inDungeon && monstersPresent) {                                  // R10.1
        r.outcome = LeaveOutcome::RefusedMonstersPresent;
        ctx.say("party.leave.monsters",
                "\"" + who.name + "\" cannot leave while monsters are in the area!", {}, {});
        return r;
    }
    if (slot == kLeaderIndex) {                                          // R10.2
        r.outcome = LeaveOutcome::RefusedLeader;
        ctx.say("party.leave.leader", "Leader cannot leave Party!", {}, {});
        return r;
    }
    if (!confirmed) {                                                    // R10.3
        r.outcome = LeaveOutcome::NotConfirmed;
        return r;
    }
    Character leaver = who;
    leaver.saved = true;                                                 // R10.3 saved at current level and square
    leaver.location.x = party.x;                                         // R10.3 current square
    leaver.location.y = party.y;                                         // R10.3
    leaver.location.dungeonLevel = party.dungeonLevel;                   // R10.3 current level
    eraseMember(party, slot);
    // UNKNOWN: selected index is reset to the first member when it falls off the end.
    if (party.selectedIndex >= party.size) party.selectedIndex = 0;
    pruneTheDeadLoop(ctx, party, true);                                  // R10.3, R13
    r.outcome = LeaveOutcome::Left;
    r.leaver = leaver;
    return r;
}

bool pruneOneMember(Ctx& ctx, Party& party, i32 index) {
    return pruneMemberAt(ctx, party, index, true);
}

bool pruneOnSizeDrop(i32 sizeBefore, i32 sizeAfter) {
    return sizeAfter < sizeBefore;
}

bool firePartyUpdateIfDead(Ctx& ctx, Party& party) {
    bool anyDead = false;
    for (i32 i = 0; i < party.size; ++i) {
        if (memberAt(party, i).isDead()) anyDead = true;
    }
    if (!anyDead) return false;
    pruneTheDeadLoop(ctx, party, true);
    return true;
}

void handleWipedParty(Ctx& ctx, Party& party, Vec<Companion>& companions) {
    party.wiped = true;
    if (party.size > 1) {
        pruneTheDeadLoop(ctx, party, true);                              // R15.1
    } else if (party.size == 1) {
        dropOwnedCompanions(companions, party.size);                     // R15.2
    }
}

i32 pickMonsterTarget(Ctx& ctx, const Party& party) {
    i32 n = party.size;
    if (n <= 0) return kLeaderIndex;
    if (n > kTargetWeightCount) n = kTargetWeightCount;
    i32 total = 0;
    for (i32 i = 0; i < n; ++i) total += kTargetWeights[i];
    if (total <= 0) return kLeaderIndex;
    const i32 roll = static_cast<i32>(ctx.rng.below(total));
    i32 acc = 0;
    for (i32 i = 0; i < n; ++i) {
        acc += kTargetWeights[i];
        if (roll < acc) return i;
    }
    return kLeaderIndex;
}

GroupTurnStep afterTargetKnockedOut(Ctx& ctx, Party& party, Vec<Companion>& companions,
                                    i32 targetIndex) {
    if (targetIndex < 0 || targetIndex >= party.size) return GroupTurnStep::Continue;
    if (memberAt(party, targetIndex).vitals.curHits > 0) return GroupTurnStep::Continue;
    const i32 before = party.size;
    dropOwnedCompanions(companions, party.size);                         // R17 sub0930
    pruneTheDeadLoop(ctx, party, true);                                  // R17 prune
    if (before == 1) return GroupTurnStep::MonsterTurnEnds;              // R17 lone death
    if (party.size == 1) return GroupTurnStep::GroupStops;               // R17 one left
    return GroupTurnStep::Continue;
}

DisbandPlan planDisband(Ctx& ctx, const Party& party, bool monstersStanding) {
    (void)ctx;
    DisbandPlan plan;
    const bool leaderDead = party.size > 0 && memberAt(party, 0).isDead();
    plan.leaderDead = leaderDead;                                        // R18.5
    if (monstersStanding && !leaderDead) {
        plan.refused = true;
        return plan;
    }
    plan.askReload = party.size > 1;                                     // R18.1
    return plan;
}

RecordAction resolveDisband(const Party& party, bool reloadWhenLoaded) {
    if (party.size > 0 && memberAt(party, 0).isDead()) return RecordAction::None;   // R18.5
    if (party.size <= 1) return RecordAction::BlankRecord;                           // R18.3
    return reloadWhenLoaded ? RecordAction::WriteRecord : RecordAction::DeleteRecord; // R18.2
}

AutoloadResult autoloadParty(Ctx& ctx, Party& party, Vec<Companion>& companions,
                             const Vec<RememberedMember>& remembered) {
    AutoloadResult result;
    // UNKNOWN: with no leader loaded, the party is treated as leader dead.
    if (party.size <= 0 || memberAt(party, 0).isDead()) {                // R19.1
        result.leaderDead = true;
        return result;
    }
    const i32 n = static_cast<i32>(remembered.size());
    for (i32 k = 0; k < n; ++k) {
        const RememberedMember& rm = remembered[static_cast<u32>(k)];
        const Character& c = rm.character;
        if (c.name == memberAt(party, 0).name) continue;                 // R19: other than the leader
        if (!rm.loadOk) {                                                // R19.2
            result.outcomes.push_back(AutoloadMemberOutcome::LoadFailed);
            ctx.say("party.autoload.error",
                    "AUTOLOAD PARTY: An error occurred auto-loading \"" + c.name + "\".", {}, {});
            continue;
        }
        const Location& leaderLoc = memberAt(party, 0).location;
        if (c.location.area != leaderLoc.area || c.location.dungeonLevel != leaderLoc.dungeonLevel) {
            result.outcomes.push_back(AutoloadMemberOutcome::NotHere);   // R19.3
            ctx.say("party.autoload.nothere",
                    "AUTOLOAD PARTY: \"" + c.name + "\" is not here anymore!", {}, {});
            continue;
        }
        if (c.isDead()) {                                                // R19.4
            result.outcomes.push_back(AutoloadMemberOutcome::Dead);
            ctx.say("party.autoload.dead",
                    "AUTOLOAD PARTY: \"" + c.name + "\" is dead!  Can't join!", {}, {});
            continue;
        }
        if (hasOppositeMember(party, c.alignment)) {                     // R19.5
            result.outcomes.push_back(AutoloadMemberOutcome::Opposite);
            ctx.say("party.autoload.opposite",
                    "AUTOLOAD PARTY: \"" + c.name +
                    "\" is oppositely aligned to one or more members of the party!", {}, {});
            continue;
        }
        if (isPartyFull(party)) break;                                   // UNKNOWN: full party not in R19; stop
        appendMember(party, c);                                          // R19.6 join
        ctx.say("party.autoload.joined",
                "AUTOLOAD PARTY: \"" + c.name + "\" is now a member of your party.", {}, {});
        companionCarryRun(ctx, party, companions);                       // R19.6
        result.outcomes.push_back(AutoloadMemberOutcome::Joined);
        result.joined += 1;
    }
    pruneTheDeadLoop(ctx, party, false);                                 // R13: town autoload prunes quietly
    return result;
}

bool giveAvailable(Ctx& ctx, const Party& party) {
    if (party.size <= 1) {
        ctx.say("party.give.alone", "Nobody in party to give to!", {}, {});
        return false;
    }
    return true;
}

GiveGoldOutcome giveGoldTransfer(Ctx& ctx, Character& giver, Character& receiver, Currency amount) {
    if (currencyWhole(amount) < 1) return GiveGoldOutcome::ZeroNoOp;
    if (amount > giver.wallet.goldOnHand) {
        ctx.say("party.give.notenough", "Not enough gold!", {}, {});
        return GiveGoldOutcome::NotEnoughGold;
    }
    // R24: receiver balance cap. Refuse the whole give; giver keeps the gold.
    // RESOLVED-BY-REFERENCE: GiveCommand.cs Give() (sub14B5 has no handler): an overflow "goes to
    // fn1521's trap ... writes to the error file only and ends the command ... no line, no item".
    // So the receiver-full refusal is silent.
    // UNKNOWN: GiveGoldOutcome has no receiver-full value as provided; NotEnoughGold is a stand-in.
    if (amount > kBalanceCap - receiver.wallet.goldOnHand) {
        return GiveGoldOutcome::NotEnoughGold;
    }
    giver.wallet.goldOnHand -= amount;
    receiver.wallet.goldOnHand += amount;
    ctx.say("party.give.gold",
            "Give of " + numText(currencyWhole(amount)) + " gold to \"" + receiver.name + "\" Completed!",
            {}, {});
    return GiveGoldOutcome::Done;
}

PoolOutcome poolGold(Ctx& ctx, Party& party, i32 selectedIndex, bool inCombat) {
    if (party.size <= 1) {                                               // R22.1
        ctx.say("party.pool.alone", "Nobody else in party to Pool to!", {}, {});
        return PoolOutcome::RefusedAlone;
    }
    if (inCombat) {                                                      // R22.2
        ctx.say("party.pool.combat", "Cannot pool gold while in combat!", {}, {});
        return PoolOutcome::RefusedInCombat;
    }
    distributeOnHand(party, selectedIndex);                              // R22.3
    if (party.size >= 2) ctx.say("party.pool.done", "Pool completed", {}, {});
    checkWealthiest(ctx, party);                                         // R22.4
    // R22.5: a mod may replace this pool with Bank Party Pool & Deposit; mods are not modelled here.
    return PoolOutcome::Pooled;
}

Currency exchangeAvailable(const Character& c, bool inDungeon) {
    return inDungeon ? c.wallet.goldOnHand : c.wallet.goldOnHand + c.wallet.goldInBank;
}

GoldTransferOutcome transferExchangeGold(Ctx& ctx, Character& from, Character& to,
                                         Currency amount, bool inDungeon) {
    if (amount == 0) return GoldTransferOutcome::ZeroNoOp;               // R23.1
    if (amount > exchangeAvailable(from, inDungeon)) {                   // R23.3
        ctx.say("party.exchange.toomuch", "Too Much!", {}, {});
        return GoldTransferOutcome::TooMuch;
    }
    drawExchangeGold(from, amount);                                      // R23.4
    to.wallet.goldOnHand += amount;
    return GoldTransferOutcome::Done;
}

BankPartyOutcome bankPartyOption(Ctx& ctx, Party& party, BankPartyOption option) {
    (void)ctx;
    const bool pool = option == BankPartyOption::PartyPool || option == BankPartyOption::PartyPoolAndDeposit;
    const bool deposit = option == BankPartyOption::PartyDeposit || option == BankPartyOption::PartyPoolAndDeposit;

    // R24: decide overflow on projected balances BEFORE touching any wallet, so a refused
    // operation leaves the party exactly as it was (no snapshot/rollback needed).
    // UNKNOWN: assumes distributeOnHand pools all on-hand gold into the selected member and
    // depositAll moves each member's on-hand gold into their bank.
    bool overflow = false;
    Currency pooled = 0;
    if (pool) {
        for (i32 i = 0; i < party.size && !overflow; ++i) {
            const Currency g = memberAt(party, i).wallet.goldOnHand;
            if (g > 0) {
                if (g > kBalanceCap - pooled) {
                    overflow = true;
                } else {
                    pooled += g;
                }
            }
        }
    }
    for (i32 i = 0; i < party.size && !overflow; ++i) {
        const Purse& w = memberAt(party, i).wallet;
        const Currency onHand = pool ? (i == party.selectedIndex ? pooled : Currency(0)) : w.goldOnHand;
        if (deposit && onHand > 0 && onHand > kBalanceCap - w.goldInBank) {
            overflow = true;
        }
    }
    if (overflow) {                                                      // R24 roll back (nothing changed yet)
        return BankPartyOutcome::RolledBack;
    }
    if (pool) {
        distributeOnHand(party, party.selectedIndex);
    }
    if (deposit) {
        depositAll(party);
    }
    return BankPartyOutcome::Done;
}

SwapInputResult parseSwapInput(const Str& text) {
    SwapInputResult r;
    if (text.size() > 5) return r;
    const i32 n = static_cast<i32>(text.size());
    i32 comma = -1;
    i32 commas = 0;
    for (i32 i = 0; i < n; ++i) {
        if (text[static_cast<u32>(i)] == ',') {
            comma = i;
            ++commas;
        }
    }
    if (commas != 1) return r;
    i32 a = 0;
    i32 b = 0;
    if (!parseSignedInt(text, 0, comma, a)) return r;
    if (!parseSignedInt(text, comma + 1, n, b)) return r;
    r.ok = true;
    r.first = a;
    r.second = b;
    return r;
}

bool runItemSwap(Ctx& ctx, Character& c, Inventory& inv, const Str& text, bool buffersFollow) {
    const SwapInputResult in = parseSwapInput(text);
    if (!in.ok) return false;                                            // R25.1 silent refusal
    // UNKNOWN: slot 1 (hands) is refused here; the SRD also says SwapSlots checks the range.
    if (in.first == 1 || in.second == 1) return false;                   // R25.2
    const SwapResult r = swapSlots(ctx, c, inv, in.first, in.second, buffersFollow);
    // UNKNOWN: SwapResult enumerator names are truncated in the API index; value 0 is assumed success.
    if (static_cast<i32>(r) != 0) return false;
    ctx.say("party.swap.done", "Item swap completed!", {}, {});          // R25.3
    return true;
}

PartySwapOutcome swapPartyPositions(Ctx& ctx, Party& party, i32 a, i32 b,
                                    bool inDungeon, bool inCombat) {
    if (a < 0 || b < 0 || a >= party.size || b >= party.size) return PartySwapOutcome::InvalidIndex;
    if (inDungeon && inCombat) {                                         // R26.4
        ctx.say("party.swap.combat", "You cannot rearrange the party during combat!", {}, {});
        return PartySwapOutcome::RefusedInCombat;
    }
    if (a == b) return PartySwapOutcome::Swapped;
    const u32 ua = static_cast<u32>(a);
    const u32 ub = static_cast<u32>(b);
    Character tmpC = memberAt(party, a);                                 // R26.1
    memberAt(party, a) = memberAt(party, b);
    memberAt(party, b) = tmpC;
    CombatOrder tmpO = party.combatOrders[ua];                           // R26.1 standing orders
    party.combatOrders[ua] = party.combatOrders[ub];
    party.combatOrders[ub] = tmpO;
    if (party.selectedIndex == a) {                                      // R26.2
        party.selectedIndex = b;
    } else if (party.selectedIndex == b) {
        party.selectedIndex = a;
    }
    if (a == kLeaderIndex || b == kLeaderIndex) {                        // R26.3
        // UNKNOWN: the NowLeader text is not given in the SRD; wording assumed.
        ctx.say("party.swap.leader", "\"" + memberAt(party, 0).name + "\" is now the party leader.", {}, {});
    }
    return PartySwapOutcome::Swapped;
}

i32 nextCommandIndex(const Party& party) {
    if (party.size <= 0) return 0;
    return (party.selectedIndex + 1) % party.size;
}

SwitchResult switchCommandedCharacter(Ctx& ctx, Party& party, i32 targetIndex,
                                      SwitchKind kind, bool inTown) {
    (void)ctx;
    (void)kind;
    SwitchResult r;
    if (targetIndex < 0 || targetIndex >= party.size) return r;
    if (targetIndex == party.selectedIndex) return r;                    // R27.4 nothing to do
    party.selectedIndex = targetIndex;
    r.changed = true;
    r.resetSpellType = true;                                             // R27.4
    // R27.4: in town (leader alive, level 0) Store, Confinement, Morgue, Guild and Bank update.
    // RESOLVED-BY-REFERENCE: R6 (ch16): "If the leader is not in the dungeon (`DungeonLevel <= 0`)
    // and not dead, UPDATE goes to Store, Confinement, Morgue, Guild, Bank, in that order."
    // The level test is <= 0, not == 0. The Seer receives nothing (R6.2), so it is not refreshed.
    r.townRefresh = inTown && party.size > 0 && !memberAt(party, 0).isDead() && party.dungeonLevel <= 0;
    return r;
}

bool altDigitSwitchesCommand(const Party& party, i32 digit) {
    return party.size > 1 && digit >= 1 && digit <= kCommandKeySlots && digit <= party.size;
}

void applyRoomEntryCombatSettings(Ctx& ctx, Party& party, bool hostileEngaged) {
    (void)ctx;
    if (!hostileEngaged) return;                                         // R29.2
    for (i32 i = 0; i < party.size; ++i) {
        CombatOrder& slot = party.combatOrders[static_cast<u32>(i)];
        if (slot.kind == CombatOrderKind::None) {
            slot = memberAt(party, i).order;                             // R29.1
        }
    }
}

PickupOutcome pickUpBody(Ctx& ctx, Party& party, Character& carrier, Character& target,
                         bool targetHidden) {
    if (carrier.isDead() || carrier.ailments.paralysed) return PickupOutcome::RefusedSilent;
    if (targetHidden) {                                                  // refused before any put-down
        ctx.say("party.pickup.hidden", "\"" + target.name + "\" is hidden!", {}, {});
        return PickupOutcome::RefusedHidden;
    }
    const bool wasCarrying = !carrier.carryingCharacterName.empty();
    if (wasCarrying) {                                                   // R30.1 put down first
        ctx.say("party.pickup.putdown",
                "Put down \"" + carrier.carryingCharacterName + "\".", {}, {});
    }
    carrier.carryingCharacterName = target.name;
    party.carryingSlot = CarryingSlot::DeadCharacter;
    return wasCarrying ? PickupOutcome::PutDownThenPicked : PickupOutcome::Picked;
}

BodyDropOutcome dropBody(Ctx& ctx, Character& carrier) {
    (void)ctx;
    if (carrier.carryingCharacterName.empty()) return BodyDropOutcome::NothingCarried;
    if (carrier.ailments.paralysed) return BodyDropOutcome::RefusedSilent;
    carrier.carryingCharacterName = Str{};
    return BodyDropOutcome::Dropped;
}

bool morgueGrabBody(Ctx& ctx, Party& party, Character& target) {
    (void)ctx;
    if (party.size <= 0) return false;
    i32 idx = party.selectedIndex;
    if (idx < 0 || idx >= party.size) idx = 0;
    Character& carrier = memberAt(party, idx);
    carrier.carryingCharacterName = target.name;
    party.carryingSlot = CarryingSlot::DeadCharacter;
    return true;
}

void companionCarryRun(Ctx& ctx, Party& party, Vec<Companion>& companions) {
    (void)ctx;
    (void)party;
    (void)companions;
}

bool helpCryNeeded(const Vitals& v) {
    // SRD ch17 [c11]: CurHits <= MaxHits * 0.1 (inclusive, as in the reference HelpCry.cs:31)
    return v.curHits < kHelpCryHitsBelow ||
           static_cast<double>(v.curHits) <= kHelpCryFraction * static_cast<double>(v.maxHits);
}

bool addCurrencyChecked(Currency a, Currency b, Currency& out) {
    if (b > 0 && a > kCurrencyMax - b) return false;
    if (b < 0 && a < kCurrencyMin - b) return false;
    out = a + b;
    return true;
}

i32 findMemberIndex(const Party& party, const Str& name) {
    for (i32 i = 0; i < party.size; ++i) {
        if (party.members[i].name == name) return i;
    }
    return -1;
}

void clampSelected(Party& party) {
    if (party.size <= 0) {
        party.selectedIndex = 0;
        return;
    }
    if (party.selectedIndex < 0) party.selectedIndex = 0;
    if (party.selectedIndex > party.size - 1) party.selectedIndex = party.size - 1;
}

bool selectSlot(Party& party, i32 slot) {
    if (slot < 0 || slot >= party.size) return false;
    party.selectedIndex = slot;
    return true;
}

void appendMember(Party& party, const Character& c) {
    if (party.size >= kPartyMaxSize) return;
    party.members[party.size] = c;
    party.size += 1;
}

void removeAt(Party& party, i32 index) {
    for (i32 j = index; j + 1 < party.size; ++j) {
        party.members[j] = party.members[j + 1];
    }
    party.size -= 1;
    party.members[party.size] = Character{};
}

i32 savedArea(const Character& c) {
    return c.location.dungeonLevel == 0 ? -1 : c.location.area;
}

void applyDefaultOrder(Character& c) {
    if (c.order.kind == CombatOrderKind::None) {
        c.order.kind = CombatOrderKind::Fight;
    }
}

void pruneTheDead(Ctx& ctx, Party& party) {
    if (party.size <= 1) return;

    const i32 leaderLevel = party.members[0].location.dungeonLevel;
    i32 i = 0;
    while (i < party.size && party.size > 1) {
        Character& m = party.members[i];
        const bool able = !m.isDead() && m.vitals.curHits > 0 &&
                          m.deathState != DeathState::Stoned;
        if (able) {
            i += 1;
            continue;
        }

        m.vitals.curHits = 0;
        if (m.location.dungeonLevel == leaderLevel) {
            ctx.say("party.member.died", "\"<name>\" has died!", {}, {m.name});
        }
        if (!m.isDead()) {
            m.deathState = DeathState::Dead;
        }
        // save(member): writing the character file is the caller's job; the core
        // has no file access.

        const bool removedBeforeSelected = i < party.selectedIndex;
        removeAt(party, i);
        // UNKNOWN: the SRD text reads "SelectedIndex--? if i < SelectedIndex".
        // Simplest sensible rule: decrement when the removed slot was before the selection.
        if (removedBeforeSelected) party.selectedIndex -= 1;
        clampSelected(party);

        // All remaining members move to the current leader's level, X and Y.
        const Location lead = party.members[0].location;
        for (i32 k = 0; k < party.size; ++k) {
            party.members[k].location.dungeonLevel = lead.dungeonLevel;
            party.members[k].location.x = lead.x;
            party.members[k].location.y = lead.y;
        }
        // Index i is not advanced (original quirk, c16).
    }
}

bool helpCryNeeded(const Character& c) {
    // Needed = CurHits < 10 OR CurHits <= MaxHits * 0.1
    const i32 cur = c.vitals.curHits;
    if (cur < kHelpCryHitsAbsolute) return true;
    return static_cast<double>(cur) <=
           static_cast<double>(c.vitals.maxHits) * kHelpCryHitsFraction;
}

i32 monsterTargetWeight(i32 position) {
    // Table is integer-halving: 100,50,25,12,6,3,1,0. Positions past the table
    // (and the last entry, 0) weigh 0.
    if (position < 0) return 0;
    const i32 last = kMonsterTargetWeightCount - 1;
    if (position >= kMonsterTargetWeightCount) return kMonsterTargetWeights[last];
    return kMonsterTargetWeights[position];
}

i32 monsterTargetTotal(i32 partySize) {
    // total = sum of the weight for each party position
    i32 total = 0;
    for (i32 i = 0; i < partySize; ++i) {
        total += monsterTargetWeight(i);
    }
    return total;
}

i32 pickMonsterTarget(Ctx& ctx, i32 partySize) {
    // total = sum of weights; roll = Rnd(100) + 1
    // target = 0; acc = 100; step = 100
    // while (acc / total * 100 < roll): target++; step /= 2; acc += step
    // target = min(target, last)
    const i32 total = monsterTargetTotal(partySize);
    if (total <= 0) return 0;  // UNKNOWN: empty party; not reachable from the SRD text.

    const i32 roll = static_cast<i32>(ctx.rng.below(kMonsterTargetRollSides)) + 1;

    i32 target = 0;
    i32 acc = 100;
    i32 step = 100;
    // UNKNOWN: "acc / total * 100" is taken as floating point. Integer division
    // would give 0 and never terminate. The bound on target is a safety guard only;
    // the accumulated total can never reach the roll before position 8.
    while (static_cast<double>(acc) / static_cast<double>(total) * 100.0 <
               static_cast<double>(roll) &&
           target < kMonsterTargetWeightCount) {
        target += 1;
        step /= 2;
        acc += step;
    }

    const i32 last = kMonsterTargetWeightCount - 1;
    if (target > last) target = last;
    return target;
}

PartyJoinOutcome joinParty(Ctx& ctx, Party& party, Character& newcomer, bool inCombat) {
    // if Members.Count == 0: join
    if (party.size == 0) {
        appendMember(party, newcomer);
        return PartyJoinOutcome::Joined;
    }
    // UNKNOWN: message for a dead first member (SRD "Chars(0).DeathState: refuse").
    if (party.members[0].isDead()) {
        return PartyJoinOutcome::LeaderDead;
    }
    // if Members.Count >= 4: refuse "Your party is too full!"
    if (party.size >= kPartyMaxSize) {
        ctx.say("party.join.full", "Your party is too full!", {}, {});
        return PartyJoinOutcome::Full;
    }
    // if any member.Name == c.Name: refuse AlreadyInParty
    if (findMemberIndex(party, newcomer.name) >= 0) {
        ctx.say("party.join.already", "Character is already in Party!", {}, {});
        return PartyJoinOutcome::AlreadyInParty;
    }
    // Combat check (c59): "if fn0EEF() > 0 and joiner dead: Cannot raise character in Combat!"
    if (inCombat && newcomer.isDead()) {
        ctx.say("party.join.deadInCombat", "Cannot raise character in Combat!", {}, {});
        return PartyJoinOutcome::DeadInCombat;
    }
    // if c.IsDead: refuse IsDead
    if (newcomer.isDead()) {
        ctx.say("party.join.dead", "Character is Dead!", {}, {});
        return PartyJoinOutcome::Dead;
    }
    // if not SamePlace(Leader, c): refuse NotHere
    if (!samePlace(party.leader(), newcomer)) {
        ctx.say("party.join.notHere", "Character is not here!", {}, {});  // UNKNOWN: exact box
        return PartyJoinOutcome::NotHere;
    }
    // if any Opposed(member.Alignment, c.Alignment): refuse oppositely aligned
    for (i32 i = 0; i < party.size; ++i) {
        if (opposedAlignment(party.members[i].alignment, newcomer.alignment)) {
            ctx.say("party.join.opposed",
                    "\"<name>\" is oppositely aligned to one or more members of the party!",
                    {}, {newcomer.name});
            return PartyJoinOutcome::Opposed;
        }
    }
    // Mid-fight setup for living joiners only (c59, sub0BDE).
    if (inCombat) {
        setupJoinerInCombat(ctx, party, newcomer);
    }
    // sub0848 True: newcomer lost flags = Chars(0) lost flags (c16)
    inheritLostFlags(ctx, party.members[0], newcomer);
    appendMember(party, newcomer);
    return PartyJoinOutcome::Joined;
}

bool opposedAlignment(Align a, Align b) {
    // Opposed(a, b) = (a==Good and b==Evil) or (a==Evil and b==Good)
    return (a == Align::Good && b == Align::Evil) || (a == Align::Evil && b == Align::Good);
}

bool samePlace(const Character& a, const Character& b) {
    // (a.DungeonLevel==0 and b.DungeonLevel==0) or
    // (same level and same X and Y)
    if (a.location.dungeonLevel == 0 && b.location.dungeonLevel == 0) return true;
    return a.location.dungeonLevel == b.location.dungeonLevel &&
           a.location.x == b.location.x && a.location.y == b.location.y;
}

Vec<i32> hereToJoinCandidates(const Party& party,
                              const Vec<Character>& roster,
                              i32 partyLevel,
                              i32 floorCount,
                              i32 area) {
    // HereToJoin = everyone where not in party
    //              and DungeonLevel == level
    //              and 1 <= DungeonLevel <= floors
    //              and savedArea(c) == area
    Vec<i32> out;
    if (partyLevel < 1 || partyLevel > floorCount) return out;
    const i32 count = static_cast<i32>(roster.size());
    for (i32 r = 0; r < count; ++r) {
        const Character& c = roster[r];
        if (findMemberIndex(party, c.name) >= 0) continue;
        if (c.location.dungeonLevel != partyLevel) continue;
        if (savedArea(c) != area) continue;
        out.push_back(r);
    }
    return out;
}

void inheritLostFlags(Ctx& ctx, const Character& first, Character& newcomer) {
    // newcomer.LostLevel = first.LostLevel; LostPosition; LostFacing (c16)
    static_cast<void>(ctx);
    newcomer.lost.level = first.lost.level;
    newcomer.lost.position = first.lost.position;
    newcomer.lost.facing = first.lost.facing;
}

bool poolGoldToSelected(Ctx& ctx, Party& party) {
    (void)ctx;
    // R24: pool each other member's on-hand gold, in index order, into the selected member.
    // Stop at the first member whose full amount would overflow the selected member's cap;
    // that member and all later members keep their gold.
    // UNKNOWN: SRD does not say whether a partial amount is moved before stopping; whole-member only.
    // FIXED: memberAt is not declared anywhere; use direct member indexing.
    Character& sel = party.members[party.selectedIndex];
    for (i32 i = 0; i < party.size; ++i) {
        if (i == party.selectedIndex) continue;
        Character& m = party.members[i];
        const Currency g = m.wallet.goldOnHand;
        if (g <= 0) continue;
        // FIXED: kBalanceCap is not declared anywhere; use the local kCurrencyMax cap.
        if (g > kCurrencyMax - sel.wallet.goldOnHand) {
            return false;  // overflow: stop pooling
        }
        sel.wallet.goldOnHand += g;
        m.wallet.goldOnHand -= g;
    }
    return true;
}

bool poolGoldToBank(Ctx& ctx, Party& party) {
    // PoolToBank: to.GoldInBank += m.GoldOnHand; m.GoldOnHand = 0 (all members, to included)
    static_cast<void>(ctx);
    const i32 to = party.selectedIndex;
    if (to < 0 || to >= party.size) return true;
    Character& dest = party.members[to];
    for (i32 i = 0; i < party.size; ++i) {
        Character& m = party.members[i];
        Currency sum = 0;
        if (!addCurrencyChecked(dest.wallet.goldInBank, m.wallet.goldOnHand, sum)) {
            return false;
        }
        dest.wallet.goldInBank = sum;
        m.wallet.goldOnHand = 0;
    }
    return true;
}

bool partyDepositGold(Ctx& ctx, Party& party) {
    // PartyDeposit: m.GoldInBank += m.GoldOnHand; m.GoldOnHand = 0 (each member)
    // UNKNOWN: overflow handling for this step is not stated; stop on overflow like the pools.
    static_cast<void>(ctx);
    for (i32 i = 0; i < party.size; ++i) {
        Character& m = party.members[i];
        Currency sum = 0;
        if (!addCurrencyChecked(m.wallet.goldInBank, m.wallet.goldOnHand, sum)) {
            return false;
        }
        m.wallet.goldInBank = sum;
        m.wallet.goldOnHand = 0;
    }
    return true;
}

bool poolAndDepositGold(Ctx& ctx, Party& party) {
    // PoolAndDeposit:
    //   for m != to: to.GoldInBank += m.GoldInBank; to.GoldInBank += m.GoldOnHand;
    //                m.GoldInBank = m.GoldOnHand = 0
    //   to.GoldInBank += to.GoldOnHand; to.GoldOnHand = 0
    // Port deviation (c16): on overflow every balance is rolled back to its
    // starting value. The original has no error handler.
    static_cast<void>(ctx);
    const i32 to = party.selectedIndex;
    if (to < 0 || to >= party.size) return true;

    Arr<Purse, kPartyMaxSize> snapshot{};
    for (i32 i = 0; i < party.size; ++i) {
        snapshot[i] = party.members[i].wallet;
    }

    Character& dest = party.members[to];
    bool ok = true;
    for (i32 i = 0; i < party.size && ok; ++i) {
        if (i == to) continue;
        Character& m = party.members[i];
        Currency afterBank = 0;
        if (!addCurrencyChecked(dest.wallet.goldInBank, m.wallet.goldInBank, afterBank)) {
            ok = false;
            break;
        }
        Currency afterOnHand = 0;
        if (!addCurrencyChecked(afterBank, m.wallet.goldOnHand, afterOnHand)) {
            ok = false;
            break;
        }
        dest.wallet.goldInBank = afterOnHand;
        m.wallet.goldInBank = 0;
        m.wallet.goldOnHand = 0;
    }
    if (ok) {
        Currency finalBank = 0;
        if (!addCurrencyChecked(dest.wallet.goldInBank, dest.wallet.goldOnHand, finalBank)) {
            ok = false;
        } else {
            dest.wallet.goldInBank = finalBank;
            dest.wallet.goldOnHand = 0;
        }
    }

    if (!ok) {
        for (i32 i = 0; i < party.size; ++i) {
            party.members[i].wallet = snapshot[i];
        }
        return false;
    }
    return true;
}

PartyPoolOutcome poolPartyGold(Ctx& ctx, Party& party, PartyPoolKind kind, bool inCombat) {
    // Order confirmed by reference (Party.cs fn1521 case 80): combat is refused first,
    // then the lone member: "If fn0EEF() > 0 And Foes(0).Engaged Then ... Else If UBound(Chars) > m00A6 ...".
    if (inCombat) {
        ctx.say("party.pool.inCombat", "Cannot pool gold while in combat!", {}, {});
        return PartyPoolOutcome::InCombat;
    }
    // if Party.Size == 1: refuse(NobodyToPoolTo)
    if (party.size <= 1) {
        ctx.say("party.pool.alone", "Nobody else in party to Pool to!", {}, {});
        return PartyPoolOutcome::NobodyToPoolTo;
    }
    bool ok = true;
    switch (kind) {
        case PartyPoolKind::ToSelected:
            ok = poolGoldToSelected(ctx, party);
            break;
        case PartyPoolKind::ToBank:
            ok = poolGoldToBank(ctx, party);
            break;
        case PartyPoolKind::PartyDeposit:
            ok = partyDepositGold(ctx, party);
            break;
        case PartyPoolKind::PoolAndDeposit:
            ok = poolAndDepositGold(ctx, party);
            break;
    }
    // Completion line. Reference PoolCompleted(to) for ALT-p (ToSelected):
    // "Pool of party's on-hand gold to \"<name>\" completed!". Other kinds keep "Pool completed".
    // Printed whenever the party has two or more members, without checking whether gold moved (c16, c43).
    if (kind == PartyPoolKind::ToSelected) {
        ctx.say("party.pool.completed",
                "Pool of party's on-hand gold to \"<name>\" completed!", {},
                {party.members[party.selectedIndex].name});
    } else {
        ctx.say("party.pool.completed", "Pool completed", {}, {});
    }
    checkWealthiest(ctx, party);
    return ok ? PartyPoolOutcome::Completed : PartyPoolOutcome::OverflowStopped;
}

void checkWealthiest(Ctx& ctx, Party& party) {
    // UNKNOWN: CheckWealthiest body is not in the source chunks (c48).
    // Simplest sensible rule: the richest member (purse, ties to the earliest index)
    // becomes the gold leader.
    static_cast<void>(ctx);
    if (party.size <= 0) return;
    i32 best = 0;
    Currency bestPurse = party.members[0].purse();
    for (i32 i = 1; i < party.size; ++i) {
        const Currency p = party.members[i].purse();
        if (p > bestPurse) {
            bestPurse = p;
            best = i;
        }
    }
    party.goldLeaderIndex = best;
}

bool removeMember(Ctx& ctx, Party& party, const Str& name) {
    // if character not in party or Members.Count == 1: false
    // remove; SelectedIndex clamped to [0, Count-1]
    static_cast<void>(ctx);
    if (party.size <= 1) return false;
    const i32 idx = findMemberIndex(party, name);
    if (idx < 0) return false;
    removeAt(party, idx);
    clampSelected(party);
    return true;
}

RearrangeOutcome rearrangeParty(Ctx& ctx, Party& party, i32 a, i32 b, bool inCombat) {
    // CONFLICT R16: the combat guard applies in the dungeon only (port comment, c43);
    // the city never refuses. The original's behaviour is not stated.
    if (inCombat && party.inDungeon) {
        ctx.say("party.rearrange.combat", "You cannot rearrange the party during combat!", {}, {});
        return RearrangeOutcome::InCombat;
    }
    if (a < 0 || a >= party.size || b < 0 || b >= party.size) {
        return RearrangeOutcome::OutOfRange;
    }
    if (a == b) {
        return RearrangeOutcome::SameSlot;
    }

    // swap(Members[a], Members[b]) (port fix: a true swap, not a rotation, c16)
    const Character tmp = party.members[a];
    party.members[a] = party.members[b];
    party.members[b] = tmp;

    // if SelectedIndex == a: SelectedIndex = b; elif == b: SelectedIndex = a
    if (party.selectedIndex == a) {
        party.selectedIndex = b;
    } else if (party.selectedIndex == b) {
        party.selectedIndex = a;
    }

    // announce NowLeader if a == 0 or b == 0
    if (a == 0 || b == 0) {
        ctx.say("party.leader.changed", "\"<name>\" is now party leader!", {},
                {party.members[0].name});
    }
    return RearrangeOutcome::Swapped;
}

bool selectMember(Ctx& ctx, Party& party, i32 slot) {
    // if slot == SelectedIndex or !Select(slot): return
    if (slot == party.selectedIndex) return false;
    if (!selectSlot(party, slot)) return false;

    // if leader.DungeonLevel <= 0 and !leader.IsDead: refresh the town screens
    const Character& leader = party.leader();
    if (leader.location.dungeonLevel <= 0 && !leader.isDead()) {
        // UI refresh of Store, Confinement, Morgue, Guild, Bank (c16).
        ctx.say("party.town.refresh", "Town screens refreshed", {}, {});
    }
    return true;
}

bool selectNextAble(Ctx& ctx, Party& party) {
    // Able = not IsDead and not Stoned and CurHits > 0
    // for step 1..Count: i = (SelectedIndex + step) % Count; if able(i): select i
    static_cast<void>(ctx);
    if (party.size <= 0) return false;
    for (i32 step = 1; step <= party.size; ++step) {
        const i32 i = (party.selectedIndex + step) % party.size;
        const Character& c = party.members[i];
        const bool able = !c.isDead() && c.deathState != DeathState::Stoned &&
                          c.vitals.curHits > 0;
        if (able) {
            party.selectedIndex = i;
            return true;
        }
    }
    return false;
}

void cycleSelectedMember(Ctx& ctx, Party& party) {
    // if Size > 1: Select((SelectedIndex + 1) % Size)  (silent, no UI refresh; c42, c48)
    static_cast<void>(ctx);
    if (party.size > 1) {
        selectSlot(party, (party.selectedIndex + 1) % party.size);
    }
}

void ensureDefaultCombatOrders(Ctx& ctx, Party& party) {
    // for c in Members: if order.Kind == None: order.ApplyDefault(c); keep order.Target
    static_cast<void>(ctx);
    for (i32 i = 0; i < party.size; ++i) {
        applyDefaultOrder(party.members[i]);
    }
}

CombatOrderKind combatSettingKind(i32 setting) {
    // 0 = Nothing, 1 = Fight, 2 = Defend, 3 + k = Buffer k
    if (setting <= kCombatSettingNothing) return CombatOrderKind::None;
    if (setting == kCombatSettingFight) return CombatOrderKind::Fight;
    if (setting == kCombatSettingDefend) return CombatOrderKind::Defend;
    return CombatOrderKind::Buffer;
}

i32 combatSettingBufferIndex(i32 setting) {
    // 3 + k -> k (0-based index into SpellBuffers); otherwise -1
    if (setting < kCombatSettingBufferBase) return -1;
    return setting - kCombatSettingBufferBase;
}

i32 combatSettingFromKind(CombatOrderKind kind, i32 bufferIndex) {
    switch (kind) {
        case CombatOrderKind::None:
            return kCombatSettingNothing;
        case CombatOrderKind::Fight:
            return kCombatSettingFight;
        case CombatOrderKind::Defend:
            return kCombatSettingDefend;
        case CombatOrderKind::Buffer:
            return kCombatSettingBufferBase + bufferIndex;
    }
    return kCombatSettingNothing;
}

Str partyStatusCode(const Character& c) {
    // s = ("Po" if poisoned) + ("Di" if diseased) + ("Pa" if paralysed)
    // return s == "" ? "OK" : s
    // UNKNOWN: "poisoned" and "diseased" are taken as level > 0.
    Str s;
    if (c.ailments.poisonLevel > 0) s += kStatusPoisoned;
    if (c.ailments.diseaseLevel > 0) s += kStatusDiseased;
    if (c.ailments.paralysed) s += kStatusParalysed;
    if (s.empty()) return Str(kStatusOk);
    return s;
}

AutoloadOutcome autoloadMember(Ctx& ctx, Party& party, Character& candidate, bool stillHere) {
    // UNKNOWN: check order here is not stated in the SRD; the order used is
    // not here, dead, full, leader dead, opposed, then join.
    if (!stillHere) {
        ctx.say("party.autoload.notHere",
                "AUTOLOAD PARTY: \"<name>\" is not here anymore!", {}, {candidate.name});
        return AutoloadOutcome::NotHere;
    }
    if (candidate.isDead()) {
        ctx.say("party.autoload.dead",
                "AUTOLOAD PARTY: \"<name>\" is dead!  Can't join!", {}, {candidate.name});
        return AutoloadOutcome::Dead;
    }
    if (party.size >= kPartyMaxSize) {
        ctx.say("party.autoload.full", "AUTOLOAD PARTY: Your party is too full!", {}, {});
        return AutoloadOutcome::Full;
    }
    if (party.size >= 1 && party.members[0].isDead()) {
        return AutoloadOutcome::LeaderDead;  // UNKNOWN: message not in the chunks
    }
    for (i32 i = 0; i < party.size; ++i) {
        if (autoloadAlignmentClash(party.members[i].alignment, candidate.alignment)) {
            ctx.say("party.autoload.opposed",
                    "AUTOLOAD PARTY: \"<name>\" is oppositely aligned to one or more members of the party!",
                    {}, {candidate.name});
            return AutoloadOutcome::Opposed;
        }
    }
    appendMember(party, candidate);
    ctx.say("party.autoload.joined",
            "AUTOLOAD PARTY: \"<name>\" is now a member of your party.", {}, {candidate.name});
    return AutoloadOutcome::Joined;
}

bool autoloadAlignmentClash(Align a, Align b) {
    // |member.Alignment - them.Alignment| > 1 (integer difference), c16.
    // CONFLICT: this matches opposedAlignment only when the enum is ordered
    // Good=0, Neutral=1, Evil=2, which is the order used by Align here.
    const i32 diff = static_cast<i32>(a) - static_cast<i32>(b);
    const i32 gap = diff < 0 ? -diff : diff;
    return gap > kAutoloadAlignGap;
}

CityJoinOutcome joinFromCity(Ctx& ctx, Party& party, Character& who, const Str& said) {
    // if Members[0].IsDead: return
    if (party.size >= 1 && party.members[0].isDead()) {
        return CityJoinOutcome::LeaderDead;
    }
    // if Size >= Party.MaxSize: "Your party is too full!"
    if (party.size >= kPartyMaxSize) {
        ctx.say("party.join.full", "Your party is too full!", {}, {});
        return CityJoinOutcome::Full;
    }
    // UNKNOWN: placement of the AlreadyInParty and NotHere checks; they are
    // implied by the candidate list (SamePlace with the Leader, not in party).
    if (findMemberIndex(party, who.name) >= 0) {
        return CityJoinOutcome::AlreadyInParty;
    }
    // UNKNOWN: with an empty party there is no leader to compare with.
    if (party.size > 0 && !samePlace(party.leader(), who)) {
        ctx.say("party.join.notHere", "Character is not here!", {}, {});
        return CityJoinOutcome::NotHere;
    }
    // if HasPassword and not PasswordMatches(said): "Incorrect Password!"
    if (!passwordMatches(who, said)) {
        ctx.say("party.join.password", "Incorrect Password!", {}, {});
        return CityJoinOutcome::WrongPassword;
    }
    // if any member Opposed(member.Alignment, who.Alignment): refuse
    for (i32 i = 0; i < party.size; ++i) {
        if (opposedAlignment(party.members[i].alignment, who.alignment)) {
            ctx.say("party.join.opposed",
                    "\"<name>\" is oppositely aligned to one or more members of the party!",
                    {}, {who.name});
            return CityJoinOutcome::Opposed;
        }
    }
    // if who.IsDead and not PendingRaise.IsPending(who): "X is Dead! ..."
    // CONFLICT: the port admits dead joiners with a pending raise (CityWindow, c48);
    // the engine (Party.cs) refuses all dead joiners. The port rule is used here.
    if (who.isDead() && !who.pendingRaise) {
        ctx.say("party.join.deadNotPending", "\"<name>\" is Dead! ...", {}, {who.name});
        return CityJoinOutcome::DeadNotPending;
    }
    // who.CurHits = MaxHits; who.CurSpellPoints = MaxSpellPoints
    who.vitals.curHits = who.vitals.maxHits;
    who.vitals.curSpellPoints = who.vitals.maxSpellPoints;

    // UNKNOWN: the SRD omits the add itself; the join is placed before PruneTheDead.
    appendMember(party, who);
    // PruneTheDead(): a dead joiner with a pending raise is pruned here when more
    // than one member is listed. This follows the SRD order.
    pruneTheDead(ctx, party);
    return CityJoinOutcome::Joined;
}

bool passwordMatches(const Character& who, const Str& said) {
    // No password set: always matches. Otherwise compared as typed.
    // Passwords are stored in plain text (original quirk, c31).
    // UNKNOWN: case sensitivity is not stated; exact match is used.
    if (who.password.empty()) return true;
    return who.password == said;
}

bool isBodyInCity(const Character& body, const Character& self, const Party& party) {
    // BodiesInTheCity = dead && Name != self && DungeonLevel == 0 && no party member carries them
    if (!body.isDead()) return false;
    if (body.name == self.name) return false;
    if (body.location.dungeonLevel != 0) return false;
    for (i32 i = 0; i < party.size; ++i) {
        if (party.members[i].carryingCharacterName == body.name) return false;
    }
    return true;
}

PartyGiveGoldOutcome giveGoldToMember(Ctx& ctx,
                                      Party& party,
                                      Character& giver,
                                      i32 receiverIndex,
                                      Currency amount) {
    // Nobody in party to give to (c10)
    if (party.size <= 1 || receiverIndex < 0 || receiverIndex >= party.size) {
        ctx.say("party.give.nobody", "Nobody in party to give to!", {}, {});
        return PartyGiveGoldOutcome::NobodyToGiveTo;
    }
    // Gold "" or Val < 1 -> 0 (c10). UNKNOWN: the 1-gold floor is taken as
    // currencyFromWhole(1) in Currency units.
    if (amount < currencyFromWhole(1)) {
        return PartyGiveGoldOutcome::NothingToGive;
    }
    // Val > gold on hand -> "Not enough gold!" (c10)
    if (amount > giver.wallet.goldOnHand) {
        ctx.say("party.give.notEnough", "Not enough gold!", {}, {});
        return PartyGiveGoldOutcome::NotEnoughGold;
    }
    Character& receiver = party.members[receiverIndex];
    giver.wallet.goldOnHand -= amount;
    receiver.wallet.goldOnHand += amount;
    // Give of N gold to "X" Completed! (nums[0] = N, strs[0] = receiver name)
    ctx.say("party.give.goldDone", "Give of gold to \"<name>\" Completed!",
            {static_cast<i64>(currencyWhole(amount))}, {receiver.name});
    return PartyGiveGoldOutcome::Given;
}

i32 itemSlotIndex(i32 n) {
    // slot = (n > 1) ? n - 1 : 0
    return (n > 1) ? n - 1 : 0;
}

PartyGiveItemOutcome giveItemToMember(Ctx& ctx,
                                      Party& party,
                                      Character& giver,
                                      i32 receiverIndex,
                                      i32 packSlot) {
    // Nobody in party to give to (c10)
    if (party.size <= 1 || receiverIndex < 0 || receiverIndex >= party.size) {
        ctx.say("party.give.nobody", "Nobody in party to give to!", {}, {});
        return PartyGiveItemOutcome::NobodyToGiveTo;
    }
    const i32 slot = itemSlotIndex(packSlot);
    // Item "" or "0" and slot 1 (Hands) -> "No Item to give!" (c10)
    if (slot == kGiveHandsSlot || slot < 0 || slot >= kPackSlots) {
        ctx.say("party.give.noItem", "No Item to give!", {}, {});
        return PartyGiveItemOutcome::NoItemToGive;
    }
    // Locate the giver's member index by address identity (no RTTI).
    i32 giverIndex = -1;
    for (i32 i = 0; i < party.size; ++i) {
        if (&party.members[i] == &giver) {
            giverIndex = i;
            break;
        }
    }
    if (giverIndex < 0) {
        ctx.say("party.give.nobody", "Nobody in party to give to!", {}, {});
        return PartyGiveItemOutcome::NobodyToGiveTo;
    }
    Inventory& from = party.inventories[giverIndex];
    Inventory& to = party.inventories[receiverIndex];
    // Item "" or "0" -> "No Item to give!" (c10)
    if (from.pack[slot].id == 0) {
        ctx.say("party.give.noItem", "No Item to give!", {}, {});
        return PartyGiveItemOutcome::NoItemToGive;
    }
    // UNKNOWN: the Equipped check and the receiver placement rule (first empty
    // slot, Hands excluded or not) are not given in the SRD text provided.
    // Here the item goes to the receiver's first empty pack slot.
    i32 dest = -1;
    for (i32 s = 0; s < kPackSlots; ++s) {
        if (to.pack[s].id == 0) {
            dest = s;
            break;
        }
    }
    if (dest < 0) {
        // UNKNOWN: no SRD message for a full pack. Reuses the no-item outcome.
        ctx.say("party.give.packFull", "Pack is full!", {}, {});
        return PartyGiveItemOutcome::NoItemToGive;
    }
    to.pack[dest] = from.pack[slot];
    from.pack[slot] = Item{};
    // RESOLVED-BY-REFERENCE: the completion line reads "Give of Item to "X" Completed!"
    // (GiveCommand.cs:172, sub14B5 3004-3006), with a capital I. Strs[0] = receiver name.
    ctx.say("party.give.itemDone", "Give of Item to \"<name>\" Completed!", {},
            {party.members[receiverIndex].name});
    return PartyGiveItemOutcome::Given;
}

PartyLeaveOutcome leaveParty(Ctx& ctx, Party& party, bool confirmed, bool monstersInArea) {
    // if SelectedIndex == 0: "Leader cannot leave Party!"
    if (party.selectedIndex == 0) {
        ctx.say("party.leave.leader", "Leader cannot leave Party!", {}, {});
        return PartyLeaveOutcome::LeaderCannotLeave;
    }
    // UNKNOWN: order of the monsters check and the confirm check.
    if (monstersInArea) {
        ctx.say("party.leave.monsters",
                "\"<name>\" cannot leave while monsters are in the area!", {},
                {party.members[party.selectedIndex].name});
        return PartyLeaveOutcome::MonstersInArea;
    }
    if (!confirmed) {
        return PartyLeaveOutcome::NotConfirmed;
    }
    // if confirmed: party.Remove(who); PruneTheDead()
    removeAt(party, party.selectedIndex);
    clampSelected(party);
    pruneTheDead(ctx, party);
    return PartyLeaveOutcome::Left;
}

void setupJoinerInCombat(Ctx& ctx, Party& party, Character& newcomer) {
    // UNKNOWN: sub0BDE body is not in the source chunks (c59).
    // Minimal setup for a living joiner: default combat order if none is set.
    // Dead joiners are refused before this is reached (c59).
    static_cast<void>(ctx);
    static_cast<void>(party);
    if (newcomer.isDead()) return;
    applyDefaultOrder(newcomer);
}

DefaultOptionsOutcome setDefaultCombatOptions(Ctx& ctx,
                                              Party& party,
                                              bool inCombat,
                                              bool monstersInArea) {
    // Refusals in combat and with monsters present (c43).
    if (inCombat) {
        ctx.say("party.options.inCombat",
                "Cannot set default options while in Combat!", {}, {});
        return DefaultOptionsOutcome::InCombat;
    }
    if (monstersInArea) {
        // UNKNOWN: exact wording; the source gives "...monsters are in the area!".
        ctx.say("party.options.monsters",
                "Cannot set default options while monsters are in the area!", {}, {});
        return DefaultOptionsOutcome::MonstersInArea;
    }
    // UNKNOWN: the apply step is not in the chunks; fill empty orders with the default.
    ensureDefaultCombatOrders(ctx, party);
    return DefaultOptionsOutcome::Applied;
}

PartySaveAction disbandParty(Ctx& ctx, Party& party, bool rememberForReload) {
    // Save only at disband, with remember = (answer == Yes). Not remembered: the
    // saved party file is deleted (c16).
    // UNKNOWN: the caller clears the party after writing or deleting the file, so the
    // members are not cleared here. Disband behaviour varies by version (c91).
    static_cast<void>(party);
    ctx.say("party.disband.start", "Disbanding Party...", {}, {});
    return rememberForReload ? PartySaveAction::SaveParty : PartySaveAction::DeleteSavedParty;
}

i32 townGoldLeaderIndex(const Party& party) {
    // First living member in the city (dungeon level 0), in party order (c36).
    // Returns -1 when nobody qualifies. UNKNOWN: the -1 result is not in the SRD.
    for (i32 i = 0; i < party.size; ++i) {
        const Character& m = party.members[i];
        if (!m.isDead() && m.location.dungeonLevel == 0) return i;
    }
    return -1;
}

bool commandSwitchSlotValid(i32 slot, i32 partySize, bool inDungeon) {
    // CONFLICT: Dungeon uses 1-based Alt+1..4 keys (slot exists when slot <= partySize,
    // size > 1). City accepts slot 0 or higher (c43, c48). The index base in the two
    // places differs and is not confirmed. UNKNOWN: whether Alt+0 in the city does nothing.
    if (inDungeon) {
        return partySize > 1 && slot >= 1 && slot <= partySize &&
               slot <= kCommandSwitchSlotsMax;
    }
    return slot >= 0;
}

i32 transferGold(Ctx& ctx,
                 Character& from,
                 Character& to,
                 Currency amount,
                 bool inDungeon) {
    // FIXED: kBalanceCap is not declared in any header. Defined locally as the
    // 32-bit signed maximum (ASSUMED value; the reference cap is not in the index).
    constexpr Currency kBalanceCap = static_cast<Currency>(2147483647);

    // if amount == 0: return
    if (amount == 0) {
        return 0;
    }

    // purse = onhand + bank
    // available = (dungeon ? onhand : purse)
    Currency purse = from.purse();
    Currency available = inDungeon ? from.wallet.goldOnHand : purse;

    // if amount > available: "Too Much!"
    if (amount > available) {
        ctx.say("partyb.gold.tooMuch", "Too Much!", {}, {});
        return -1;
    }

    // R24 / R64: receiver balance cap. The reference does `to.GoldOnHand += amount` first;
    // on overflow the trap resumes silently with nothing moved on either side.
    // Checked before the sender is touched, so no partial transfer.
    // CONFLICT-free for Give (R64); for Exchange the SRD is silent, see erratum ch14.
    if (amount > 0 && to.wallet.goldOnHand > kBalanceCap - amount) {
        return 0;
    }

    // to.GoldOnHand += amount
    // from.GoldOnHand -= amount
    // QUIRK (kept on purpose): a negative amount skips the check above, so the
    // recipient pays and may go below zero, and the sender gains gold. Only the
    // sender is clamped below.
    to.wallet.goldOnHand += amount;
    from.wallet.goldOnHand -= amount;

    // if from.GoldOnHand < 0: from.GoldInBank += from.GoldOnHand; from.GoldOnHand = 0
    if (from.wallet.goldOnHand < 0) {
        from.wallet.goldInBank += from.wallet.goldOnHand;
        from.wallet.goldOnHand = 0;
    }

    return 1;
}

