bool raceMayJoinGuild(Race race, Guild g) {
    switch (g) {
        case Guild::Warrior:
            return race != Race::Elf && race != Race::Osiri && race != Race::Gnome;
        case Guild::Wizard:
            return race != Race::Giant && race != Race::Morloch && race != Race::Gnome;
        default:
            return true;
    }
