void appendDigits(Str& out, i64 v) {
    char buf[24];
    int n = 0;
    do {
        buf[n++] = static_cast<char>('0' + v % 10);
        v /= 10;
    } while (v > 0);
    while (n > 0) {
        out.push_back(buf[--n]);
    }
}

Str bankalltext(Currency balance) {
    Str out;
    if (balance < 0) {
        out.push_back('-');
    }
    i64 a = balance < 0 ? -balance : balance;
    i64 whole = a / 10000;
    i64 frac = a % 10000;
    if (frac == 0) {
        appendDigits(out, whole);
        return out;
    }
    if (whole > 0) {
        appendDigits(out, whole);
    }
    out.push_back('.');
    char d[4];
    for (int i = 3; i >= 0; --i) {
        d[i] = static_cast<char>('0' + frac % 10);
        frac /= 10;
    }
    int len = 4;
    while (len > 0 && d[len - 1] == '0') {
        --len;
    }
    for (int i = 0; i < len; ++i) {
        out.push_back(d[i]);
    }
    return out;
}

bool addFits(Currency a, Currency b) {
    if (b > 0) return a <= kCurrencyMax - b;
    return a >= kCurrencyMin - b;
}

bool subFits(Currency a, Currency b) {
    if (b > 0) return a >= kCurrencyMin + b;
    return a <= kCurrencyMax + b;
}

bool isDigit(char c) {
    return c >= '0' && c <= '9';
}

bool parseCurrency(const Str& s, Currency& out) {
    const size_t n = s.size();
    size_t i = 0;
    bool neg = false;
    if (i < n && (s[i] == '-' || s[i] == '+')) {
        neg = (s[i] == '-');
        ++i;
    }

    const Currency wholeLimit = kCurrencyMax / kUnitsPerGold;
    Currency whole = 0;
    bool anyDigit = false;
    while (i < n && isDigit(s[i])) {
        const Currency d = s[i] - '0';
        if (whole > (wholeLimit * 10 + 9 - d) / 10 + 1) return false;  // guard before multiplying
        if (whole * 10 + d > wholeLimit) {
            // Only allowed if the final magnitude still fits; checked below via frac budget.
            return false;
        }
        whole = whole * 10 + d;
        anyDigit = true;
        ++i;
    }

    Currency frac = 0;
    int placed = 0;          // fractional digits stored in frac (max 4)
    int nextDigit = -1;      // first digit beyond 4 places, or -1 if none
    bool sticky = false;     // any non-zero digit beyond that
    int count = 0;           // fractional digits seen
    if (i < n && s[i] == '.') {
        ++i;
        while (i < n && isDigit(s[i])) {
            const int d = s[i] - '0';
            if (count < 4) {
                frac = frac * 10 + d;
                ++placed;
            } else if (count == 4) {
                nextDigit = d;
            } else if (d != 0) {
                sticky = true;
            }
            if (count >= 0) anyDigit = true;
            ++count;
            ++i;
        }
    }
    if (i != n || !anyDigit) return false;
    for (int k = placed; k < 4; ++k) frac *= 10;

    // Round half to even on the 5th decimal and beyond.
    bool up = false;
    if (nextDigit > 5) {
        up = true;
    } else if (nextDigit == 5) {
        up = sticky ? true : (frac % 2 == 1);
    }

    // Magnitude = whole*10000 + frac + up, must not exceed kCurrencyMax.
    const Currency rem = kCurrencyMax - whole * kUnitsPerGold;  // >= 0 since whole <= wholeLimit
    const Currency fracPart = frac + (up ? 1 : 0);
    if (fracPart > rem) return false;
    const Currency magnitude = whole * kUnitsPerGold + fracPart;
    out = neg ? -magnitude : magnitude;
    return true;
}

BankAnswer bankTyped(Character& ch, const Str& text, bool deposit) {
    Currency amount = 0;
    if (!parseCurrency(text, amount) || amount == 0) return BankAnswer::Ignored;

    Purse& w = ch.wallet;
    if (deposit) {
        if (amount > w.goldOnHand || amount <= 0) return BankAnswer::Beep;
        if (addFits(w.goldInBank, amount)) w.goldInBank += amount;      // 315
        if (subFits(w.goldOnHand, amount)) w.goldOnHand -= amount;      // 316
    } else {
        if (amount > w.goldInBank || w.goldInBank < 0) return BankAnswer::Beep;
        if (addFits(w.goldOnHand, amount)) w.goldOnHand += amount;      // 323
        if (subFits(w.goldInBank, amount)) w.goldInBank -= amount;      // 324
    }
    return BankAnswer::Moved;
}

i64 roundHalfEvenLocal(double x) {
    double f = std::floor(x);
    double d = x - f;
    i64 fi = static_cast<i64>(f);
    if (d > 0.5) return fi + 1;
    if (d < 0.5) return fi;
    return (fi % 2 == 0) ? fi : fi + 1;
}

i64 pow2(i32 k) {
    return static_cast<i64>(1) << k;
}

i32 fn1485Price(i32 level, i32 u4, f32 rate, i32 sl, i32& rated) {
    f32 r = (rate == 0.0f) ? 1.0f : rate;                               // 2886-2889
    double prod = static_cast<double>(level) * static_cast<double>(r);  // exact in double
    i64 ratedL = roundHalfEvenLocal(prod);                              // 2890
    rated = static_cast<i32>(ratedL);

    // The Single rate as mant * 2^exp, exactly.
    u32 bits = 0;
    std::memcpy(&bits, &r, sizeof bits);
    i32 e = static_cast<i32>((bits >> 23) & 0xFFu);
    i64 mant = static_cast<i64>(bits & 0x7FFFFFu);
    if (e != 0) {
        mant |= 0x800000;
    } else {
        e = 1;  // denormal
    }
    bool negative = (bits >> 31) != 0;
    i32 exp = e - 127 - 23;

    // Strip trailing zero bits: same value, smaller operands.
    while (mant != 0 && (mant & 1) == 0) {
        mant >>= 1;
        exp += 1;
    }
    if (negative) mant = -mant;

    i64 num = ratedL * static_cast<i64>(u4) * mant * 19;
    i64 den = 10 * static_cast<i64>(sl < 1 ? 1 : sl);
    if (exp >= 0) {
        num *= pow2(exp);
    } else {
        den *= pow2(-exp);
    }

    // C++ integer division truncates toward zero, as BigInteger.DivRem does.
    i64 q = num / den;
    i64 rem = num % den;
    if (rem < 0) {
        q -= 1;  // a floor, not a truncation
    } else if (rem == 0 && num > 0) {
        // Whole: the true product is just under it, so the page floors one lower.
        q -= 1;
    }
    return static_cast<i32>(q);
}

char lowerAscii(char c) {
    return (c >= 'A' && c <= 'Z') ? static_cast<char>(c - 'A' + 'a') : c;
}

int digitValue(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 99;
}

bool goldFromTag(const Str& tag, i64& out) {
    // Trim blanks (' ' and '\t') from both ends.
    size_t b = 0;
    size_t e = tag.size();
    while (b < e && isBlank(tag[b])) ++b;
    while (e > b && isBlank(tag[e - 1])) --e;

    // &H (radix 16) or &O (radix 8) prefix, case-insensitive.
    if (e - b >= 2 && tag[b] == '&' &&
        (lowerAscii(tag[b + 1]) == 'h' || lowerAscii(tag[b + 1]) == 'o')) {
        const int radix = (lowerAscii(tag[b + 1]) == 'h') ? 16 : 8;
        size_t p = b + 2;
        bool any = false;
        i64 acc = 0;
        for (; p < e; ++p) {
            const int d = digitValue(tag[p]);
            if (d >= radix) break;
            any = true;
            acc = acc * radix + d;
            if (acc > (static_cast<i64>(1) << 40)) return false;  // far past Long
        }
        if (!any || p != e) return false;
        if (acc > 2147483647LL) return false;  // Overflow (UNKNOWN: VB wrap)
        out = acc;
        return true;
    }

    // Decimal: optional sign, digits with thousands commas, optional
    // fraction, optional E/D exponent. The whole trimmed string must match.
    std::string s;
    size_t p = b;
    if (p < e && (tag[p] == '+' || tag[p] == '-')) {
        s.push_back(tag[p]);
        ++p;
    }

    size_t intDigits = 0;
    while (p < e) {
        if (isDigit(tag[p])) {
            s.push_back(tag[p]);
            ++intDigits;
            ++p;
        } else if (tag[p] == ',' && intDigits > 0) {
            ++p;  // thousands separator: dropped from the value
        } else {
            break;
        }
    }

    size_t fracDigits = 0;
    if (p < e && tag[p] == '.') {
        s.push_back('.');
        ++p;
        while (p < e && isDigit(tag[p])) {
            s.push_back(tag[p]);
            ++fracDigits;
            ++p;
        }
    }
    if (intDigits + fracDigits == 0) return false;  // not a number

    // VB takes D as well as E for the exponent.
    if (p < e && (lowerAscii(tag[p]) == 'e' || lowerAscii(tag[p]) == 'd')) {
        s.push_back('e');
        ++p;
        if (p < e && (tag[p] == '+' || tag[p] == '-')) {
            s.push_back(tag[p]);
            ++p;
        }
        size_t expDigits = 0;
        while (p < e && isDigit(tag[p])) {
            s.push_back(tag[p]);
            ++expDigits;
            ++p;
        }
        if (expDigits == 0) return false;
    }

    if (p != e) return false;  // trailing junk: Type mismatch

    const double v = std::strtod(s.c_str(), nullptr);
    if (!std::isfinite(v)) return false;  // past a Double

    const double r = std::nearbyint(v);  // half to even (default rounding mode)
    if (!fitsLong(r)) return false;      // Overflow
    out = static_cast<i64>(r);
    return true;
}

Currency saturateGold(i64 gold) {
    const Currency hi = std::numeric_limits<Currency>::max();
    const Currency lo = std::numeric_limits<Currency>::min();
    if (gold > hi / kCurrencyPerGold) return hi;
    if (gold < lo / kCurrencyPerGold) return lo;
    return gold * kCurrencyPerGold;
}

i64 roundCurrencyToGold(Currency c) {
    i64 whole = c / kCurrencyPerGold;
    i64 rem = c % kCurrencyPerGold;
    if (rem < 0) {  // floor division, so the remainder is in [0, 10000)
        whole -= 1;
        rem += kCurrencyPerGold;
    }
    const i64 half = kCurrencyPerGold / 2;
    if (rem > half) return whole + 1;
    if (rem < half) return whole;
    return (whole % 2 == 0) ? whole : whole + 1;  // exactly .5: to even
}

bool goldToSteal(Currency onHand, i64 rolled, i64& taken) {
    // R-less: MONSMOD thief take. Left = onHand - Saturate(rolled); overflow means null.
    const Currency sub = saturateGold(rolled);
    const Currency lo = std::numeric_limits<Currency>::min();
    const Currency hi = std::numeric_limits<Currency>::max();

    // VbCurrency.TrySubtract(onHand, sub): fail when the difference leaves the range.
    if (sub >= 0 ? onHand < lo + sub : onHand > hi + sub) return false;

    const Currency left = onHand - sub;
    if (left < 0) {
        // Purse runs out: the thief takes the whole purse, rounded to whole gold.
        taken = roundCurrencyToGold(onHand);
    } else {
        taken = rolled;
    }
    return true;
}

void appendInt(Str& out, i32 v) {
    if (v < 0) {
        out += '-';
        v = -v;
    }
    char buf[12];
    int n = 0;
    do {
        buf[n++] = static_cast<char>('0' + v % 10);
        v /= 10;
    } while (v > 0);
    while (n > 0) {
        out += buf[--n];
    }
}

bool placeOf(bool lostLevel, bool lostPosition, i32 level, i32 x, i32 y, Str& out) {
    // Live square is passed in by the caller (dungeon's current square), not the saved record.
    if (lostLevel || lostPosition || level <= 0) {
        return false;
    }
    out = Str();
    appendInt(out, x + 1);
    out += ',';
    appendInt(out, y + 1);
    out += ',';
    appendInt(out, level);
    return true;
}

i32 questItemBand(i32 tier) {
