SanctuaryPoint castSetSanctuary(Ctx& ctx, const Party& party) {
    const SanctuaryPoint p = sanctuaryPointFor(party);
    ctx.say("spell.sanctuary.set", "Sanctuary is set here.",
            {static_cast<i64>(p.x), static_cast<i64>(p.y), static_cast<i64>(p.dungeonLevel)}, {});
    return p;
}

SanctuaryOutcome castSanctuaryReturn(Ctx& ctx, Character& caster, const SanctuaryPoint& stored) {
    if (stored.isNever()) {
        ctx.say("spell.sanctuary.never", "No sanctuary has been set.", {}, {});
        return SanctuaryOutcome::NeverCast;
    }
    addAgeDays(caster, kSanctuaryDays);
    ctx.say("spell.sanctuary.returned", "{0} is returned to sanctuary.",
            {static_cast<i64>(kSanctuaryDays)}, {caster.name});
    return SanctuaryOutcome::Returned;
}

void addAgeDays(Character& who, i32 days) {
    who.ageDays += days;
}

void clearPartyLost(Ctx& ctx, Party& party) {
    party.lost = false;
    party.lostFacing = false;
    party.lostLevel = false;
    party.lostPosition = false;
    for (i32 i = 0; i < party.size && i < kPartyMaxSize; ++i) {
        party.members[static_cast<u32>(i)].lost = LostState{};
    }
    // UNKNOWN: message text is not given in the SRD.
    ctx.say("spell.lost.ended", "You are no longer lost.", {}, {});
}

void castUtilityEffect(Ctx& ctx, Party& party, FloorState& floor, UtilityEffect effect) {
    // UNKNOWN: Detect Rock's effect on FloorState is not in the chunks. The floor is not
    // modified here, and only the event is emitted.
    (void)floor;
    switch (effect) {
        case UtilityEffect::DetectRock:
            ctx.say("spell.utility.detectRock", "You sense the rock around you.", {}, {});
            break;
        case UtilityEffect::DepthPerception:
            ctx.say("spell.utility.depthPerception", "You perceive your depth.", {}, {});
            clearPartyLost(ctx, party);
            break;
        case UtilityEffect::FindDirection:
            ctx.say("spell.utility.findDirection", "You find your direction.", {}, {});
            clearPartyLost(ctx, party);
            break;
        default:
            break;
    }
}

SpellSheet sheetOf(const SpellDef& s) {
  SpellSheet r;
  r.numM = s.affectMonster;
  r.numG = s.affectGroup;
  r.base = s.damage1;
  r.power = s.damage2;
  r.baseBlank = (s.damage1 == 0 && s.damage2 == 0);
  r.verbIndex = s.killEffect < 0 ? 0 : (s.killEffect > 8 ? 8 : s.killEffect);
  r.type = (s.damage1 > 0 || s.damage2 > 0) ? (s.effect == 0 ? "Detrimental" : "Beneficial") : "";
  return r;
}

double lnOf(double x) {
    return x > 0.0 ? std::log(x) : 0.0;
}

i64 truncToI64(double x) {
    return static_cast<i64>(std::trunc(x));
}

const SpellDef* spellAt(const Ctx& ctx, i32 index) {
    if (index < 0 || index >= static_cast<i32>(ctx.data.spells.size())) {
        return nullptr;
    }
    return &ctx.data.spells[static_cast<u32>(index)];
}

double scaledMagnitude(double g, double h, double s, double logBase, double logShift = 0.0) {
    // Spreadsheet shape (ch10 R2): G + G*LN(SL)/LN(base) + Int((SL/10)*(H-1)). The engine's damage
    // formula (Rules.SpellDamage, ch10 R6) takes the log of SL+1: pass logShift = 1 for damage.
    return g + g * lnOf(s + logShift) / std::log(logBase)
           + static_cast<double>(vbInt((s / 10.0) * (h - 1.0)));
}

double archiveMinimum(i64 base, i64 power, i64 sl, double divisor) {
    const double g = static_cast<double>(base);
    const double s = static_cast<double>(sl);
    const double term1 = g * lnOf(s) / divisor;
    const double term2 = static_cast<double>(vbInt(s * (static_cast<double>(power) - 1.0) / 10.0));
    return (g + term1 + term2) / 2.0;
}

i64 rollAboveMinimum(Ctx& ctx, double minimum) {
    i64 span = vbInt(minimum);
    if (span < 1) {
        span = 1;
    }
    const i64 roll = static_cast<i64>(ctx.rng.below(static_cast<i32>(span))) + 1;
    return vbInt(minimum) + roll;
}

FacingVectors facingVectors(Facing f) {
    switch (f) {
        case Facing::N:
            return FacingVectors{0, -1, 1, 0};
        case Facing::E:
            return FacingVectors{1, 0, 0, 1};
        case Facing::S:
            return FacingVectors{0, 1, -1, 0};
        case Facing::W:
        default:
            return FacingVectors{-1, 0, 0, -1};
    }
}

SpellRow spellRowByName(const Ctx& ctx, const Str& spellName) {
    SpellRow row{};
    row.index = -1;
    row.type = SpellEffectType::BLANK;
    row.baseBlank = true;
    row.base = 0;
    row.power = 0;
    row.hpFlag = false;
    const i32 count = static_cast<i32>(ctx.data.spells.size());
    for (i32 i = 0; i < count; ++i) {
        const SpellDef& s = ctx.data.spells[static_cast<u32>(i)];
        if (!(s.name == spellName)) {
            continue;
        }
        row.index = i;
        if (sheetOf(s).type == "Detrimental") {
            row.type = SpellEffectType::DETRIMENTAL;
        } else if (sheetOf(s).type == "Beneficial") {
            row.type = SpellEffectType::BENEFICIAL;
        }
        row.baseBlank = sheetOf(s).baseBlank;
        row.base = sheetOf(s).base;
        row.power = sheetOf(s).power;
        row.hpFlag = (sheetOf(s).hpFlag == "Y");
        break;  // VLOOKUP returns the first match.
    }
    return row;
}

double damageMod(i64 base, i64 power, i64 sl) {
    // Engine damage (Rules.SpellDamage): the log term is LN(SL+1).
    return scaledMagnitude(static_cast<double>(base), static_cast<double>(power),
                           static_cast<double>(sl), kLnDamageBase, 1.0);
}

double healMod(i64 base, i64 power, i64 sl) {
    return scaledMagnitude(static_cast<double>(base), static_cast<double>(power),
                           static_cast<double>(sl), kLnHealBase);
}

MagnitudeResult spellMagnitude(const SpellRow& row, i64 sl) {
    MagnitudeResult r{};
    if (row.baseBlank) {
        r.blank = true;
        r.dmgMod = 0.0;
        r.healMod = 0.0;
        return r;
    }
    r.blank = false;
    r.dmgMod = damageMod(row.base, row.power, sl);
    r.healMod = healMod(row.base, row.power, sl);
    return r;
}

ValueRange damageRange(SpellEffectType type, const MagnitudeResult& mag) {
    ValueRange v{false, 0, 0};
    if (mag.blank || type != SpellEffectType::DETRIMENTAL) {
        return v;
    }
    v.present = true;
    v.min = truncToI64(mag.dmgMod * 0.5 - 1.0);
    v.max = truncToI64(mag.dmgMod * 1.0 - 1.0);
    return v;
}

ValueRange healRange(SpellEffectType type, const MagnitudeResult& mag) {
    ValueRange v{false, 0, 0};
    if (mag.blank || type != SpellEffectType::BENEFICIAL) {
        return v;
    }
    v.present = true;
    v.min = truncToI64(mag.healMod * 0.5 - 1.0);
    v.max = truncToI64(mag.healMod * 1.0 - 1.0);
    return v;
}

bool hpNoteShown(const ValueRange& dmgRange, const SpellRow& row) {
    return dmgRange.present && row.hpFlag;
}

i64 sheetBaseValue(double q, double r) {
    return vbInt(q * r * kSheetFactor - kSheetEpsilon);
}

i64 sheetScaledBase(double c, double q, double r, i64 sl) {
    const i64 cInt = static_cast<i64>(c);
    if (sl <= 0) {
        return cInt;
    }
    const double x = c * q * r * kSheetFactor / static_cast<double>(sl) - kSheetEpsilon;
    const i64 X = vbInt(x);
    return (static_cast<double>(X) < c) ? cInt : X;
}

i64 sheetColumnK(double c, double q, double r) {
    const double x = c * q * r * kSheetFactor / (c + 1.0);
    return static_cast<i64>(std::ceil(x)) * 2 - 1;
}

SpellTargetCaps spellTargetCaps(const Ctx& ctx, i32 spellIndex) {
    SpellTargetCaps caps{0, 0};
    const SpellDef* s = spellAt(ctx, spellIndex);
    if (s == nullptr) {
        return caps;
    }
    caps.numM = sheetOf(*s).numM;
    caps.numG = sheetOf(*s).numG;
    return caps;
}

SpellReach spellReach(const Ctx& ctx, i32 spellIndex) {
    const SpellDef* s = spellAt(ctx, spellIndex);
    if (s == nullptr) {
        return SpellReach::CASTER_ONLY;
    }
    const i32 e = s->effect;
    if (e >= 200) {
        return SpellReach::WHOLE_PARTY;
    }
    if (e >= 75 && e <= 99) {
        return SpellReach::CHARM_FILTER;
    }
    if (e == 0 || e == 100) {
        return SpellReach::COMBAT_MONSTERS;
    }
    return SpellReach::CASTER_ONLY;
}

SpellVerb spellVerb(const Ctx& ctx, i32 spellIndex) {
    const SpellDef* s = spellAt(ctx, spellIndex);
    if (s == nullptr) {
        return SpellVerb::NONE;
    }
    if (s->effect == 100) {
        return SpellVerb::KILLED;
    }
    // CONFLICT: Part A puts charm at 80-99 while 75 is class-gated damage. Charm uses 80-99 here.
    if (s->effect >= 80 && s->effect <= 99) {
        return SpellVerb::CHARMED;
    }
    if (sheetOf(*s).verbIndex < 0 || sheetOf(*s).verbIndex > 8) {
        return SpellVerb::NONE;
    }
    return kVerbByIndex[sheetOf(*s).verbIndex];
}

SpellUse spellUse(const Ctx& ctx, i32 spellIndex) {
    const SpellDef* s = spellAt(ctx, spellIndex);
    if (s == nullptr) {
        return SpellUse::NonCombat;
    }
    const i32 e = s->effect;
    if (e == 10) {
        return SpellUse::Combat;                 // R14 Cure Paralysis
    }
    if (e == 0) {
        return (sheetOf(*s).type == "Detrimental") ? SpellUse::Combat : SpellUse::NonCombat;
    }
    if (e == 1 || e == 2 || e == 18) {
        return SpellUse::NonCombat;              // R14 heal family
    }
    if (e >= 50 && e <= 74) {
        return SpellUse::NonCombat;              // R21 resist spells
    }
    if (e >= 75 && e <= 100) {
        return SpellUse::Combat;                 // charm, class-gated damage, kill
    }
    return SpellUse::NonCombat;
}

double archiveDamageMinimum(i64 base, i64 power, i64 sl) {
    return archiveMinimum(base, power, sl, kArchiveDamageDivisor);
}

i64 archiveDamageRoll(Ctx& ctx, double minimum) {
    return rollAboveMinimum(ctx, minimum);
}

i64 resistedDamage(i64 damage, i32 resistancePct) {
    const double factor = 1.0 - static_cast<double>(resistancePct) / 100.0;
    return roundHalfEven(static_cast<double>(damage) * factor);
}

bool killSpellSucceeds(i64 rolledDamage, i64 monsterHits) {
    return rolledDamage >= monsterHits;
}

double archiveHealMinimum(i64 base, i64 power, i64 sl) {
    return archiveMinimum(base, power, sl, kArchiveHealDivisor);
}

i64 archiveHealRoll(Ctx& ctx, double minimum) {
    return rollAboveMinimum(ctx, minimum);
}

double itemProtectionDefence(i64 sl) {
    const double l = lnOf(static_cast<double>(sl));
    return 3.0 * l * l;
}

double guildSpellProtectionDefence(i64 sl) {
    const double half = static_cast<double>(vbInt(static_cast<double>(sl) / 2.0));
    const double l = lnOf(half + 1.0);
    return 3.0 * l * l;
}

i32 charmMonsters(Ctx& ctx, Party& party, Encounter& enc, i32 monsterClassFilter) {
    if (party.size <= 0) {
        return 0;
    }
    i32 charmed = 0;
    i32 groupsTouched = 0;
    for (i32 g = 0; g < kMaxGroups && charmed < kCharmTargets && groupsTouched < kCharmGroups; ++g) {
        MonsterGroup& grp = enc.groups[static_cast<u32>(g)];
        Creature& front = grp.front;
        if (front.monsterClass != monsterClassFilter || !front.alive || front.charmed) {
            continue;
        }
        front.charmed = true;
        front.hostile = false;
        grp.state = GroupState::Peaced;
        ++charmed;
        ++groupsTouched;
        ctx.say("spell.charm.success", "You charmed One!", {}, {});
    }
    if (charmed == 0) {
        ctx.say("spell.charm.failed", "Failed", {}, {});
    }
    return charmed;
}

bool bindCompanion(Ctx& ctx, Companion& companion, i32 bindLevelGain) {
    if (companion.joinedFreely) {
        ctx.say("spell.bind.refused", "Bind has no effect on this companion.", {}, {});
        return false;
    }
    const i32 before = companion.bindingLevel;
    i32 next = before + bindLevelGain;
    if (next > kBindingMax) {
        next = kBindingMax;
    }
    companion.bindingLevel = next;
    ctx.say("spell.bind.raised", "Bind level raised.", {}, {});
    return next > before;
}

void controlDragonFailed(Ctx& ctx, Encounter& enc, i32 groupIndex) {
    if (groupIndex < 0 || groupIndex >= kMaxGroups) {
        return;
    }
    MonsterGroup& grp = enc.groups[static_cast<u32>(groupIndex)];
    grp.state = GroupState::Hostile;
    grp.front.hostile = true;
    grp.front.charmed = false;
    ctx.say("spell.control.adverse", "The targets respond adversely.", {}, {});
}

void setSanctuary(Ctx& ctx, SanctuaryStore& store, const Location& at) {
    store.x = at.x;
    store.y = at.y;
    store.dungeonLevel = at.dungeonLevel;
    ctx.say("spell.sanctuary.set", "Sanctuary location set.", {}, {});
}

bool castSanctuary(Ctx& ctx, Party& party, i32 casterIndex, const SanctuaryStore& store) {
    if (store.dungeonLevel == kSanctuaryUnsetLevel) {
        ctx.say("spell.sanctuary.none", "Nothing happens.", {}, {});
        return false;
    }
    if (casterIndex < 0 || casterIndex >= party.size) {
        return false;
    }
    party.x = store.x;
    party.y = store.y;
    party.dungeonLevel = store.dungeonLevel;
    Character& caster = party.members[static_cast<u32>(casterIndex)];
    caster.ageDays += kSanctuaryAgeDays;
    ctx.say("spell.sanctuary.cast", "Sanctuary returns the party.", {}, {});
    return true;
}

DisplaceOutcome displaceWithin(Ctx& ctx, Party& party, i32 casterIndex, i32 offsetRight, i32 offsetForward) {
    static_cast<void>(casterIndex);
    if (!party.inDungeon) {
        for (i32 i = 0; i < party.size; ++i) {
            party.members[static_cast<u32>(i)].deathState = DeathState::Dead;
        }
        ctx.say("spell.displace.outside", "The party is destroyed.", {}, {});
        return DisplaceOutcome::OUTSIDE_DUNGEON;
    }
    const FacingVectors v = facingVectors(party.facing);
    party.x += offsetRight * v.rx + offsetForward * v.fx;
    party.y += offsetRight * v.ry + offsetForward * v.fy;
    ctx.say("spell.displace.moved", "The party is displaced.", {}, {});
    return DisplaceOutcome::MOVED;
}

DisplaceOutcome etherealPortal(Ctx& ctx, Party& party, i32 casterIndex) {
    return displaceWithin(ctx, party, casterIndex, 0, 2);
}

void castResistSpell(Ctx& ctx, Resistances& resistances, SpellResistKind kind) {
    const i32 idx = static_cast<i32>(kind);
    if (idx < 0 || idx >= kResistKinds) {
        return;
    }
    i32& slot = resistances.resist[static_cast<u32>(idx)];
    if (slot < kResistGrantPercent) {
        slot = kResistGrantPercent;
    }
    ctx.say("spell.resist.granted", "Resistance raised.", {}, {});
}

const MovementSpellRow* findMovementRow(MovementSpell spell) {
    for (const MovementSpellRow& row : kMovementSpellRows) {
        if (row.spell == spell) {
            return &row;
        }
    }
    return nullptr;
}

MovementScope movementScopeOf(MovementSpell spell) {
    const MovementSpellRow* row = findMovementRow(spell);
    if (row == nullptr) {
        return MovementScope::NonCombat;
    }
    return row->combatMarked ? MovementScope::CombatAndNonCombat
                             : MovementScope::NonCombat;
}

i32 movementSpellBase(MovementSpell spell) {
    const MovementSpellRow* row = findMovementRow(spell);
    if (row == nullptr) {
        return 0;
    }
    return row->base;
}

bool meetsMovementStatRequirements(const Character& caster, MovementSpell spell) {
    if (spell != MovementSpell::Sanctuary) {
        return true;
    }
    const i32 intel = caster.abilities.stats[static_cast<u32>(StatIndex::Int)];
    const i32 wis = caster.abilities.stats[static_cast<u32>(StatIndex::Wis)];
    const i32 con = caster.abilities.stats[static_cast<u32>(StatIndex::Con)];
    return intel >= kSanctuaryReqInt
        && wis >= kSanctuaryReqWis
        && con >= kSanctuaryReqCon;
}

i32 teleportImpalePercent(i32 creatureMagicResistance) {
    return clampv(100 - creatureMagicResistance, 0, 100);
}

TeleportCombatResult teleportCombatSendAway(Ctx& ctx, Encounter& encounter) {
    TeleportCombatResult result;

    const i32 groupLimit = minv(kTeleportCombatMaxGroups, kMaxGroups);

    for (i32 g = 0; g < groupLimit; ++g) {
        if (result.sentAway >= kTeleportCombatMaxMonsters) {
            break;
        }
        MonsterGroup& grp = encounter.groups[static_cast<u32>(g)];
        if (grp.livingCount <= 0) {
            continue;
        }

        const i32 pct = teleportImpalePercent(grp.front.magicResistance);
        bool hit = false;

        while (grp.livingCount > 0 && result.sentAway < kTeleportCombatMaxMonsters) {
            grp.livingCount -= 1;
            grp.count = maxv(0, grp.count - 1);
            result.sentAway += 1;
            hit = true;

            if (ctx.rng.percent(pct)) {
                result.impaled += 1;
            }
        }

        if (hit) {
            result.groupsHit += 1;
        }
    }

    ctx.say("spells3.teleport.combat",
            "Teleport in combat: monsters sent away, monsters impaled, groups hit",
            {result.sentAway, result.impaled, result.groupsHit},
            {});

    return result;
}

double damageModifier1(i32 base, i32 sl, i32 power) {
    // R6 step 1 (ch10): Modifier1 = Base + Base*LN(SL+1)/LN(5) + power term.
    // CONFLICT: SRD writes the power term as Int(...) (floor). Reference Rules.SpellDamage
    // (Rules.cs:628) uses the C# (int) cast, which truncates toward zero. Reference preferred.
    // The two differ only when (SL/10)*(power-1) is negative (power 0).
    // RESOLVED-BY-REFERENCE: Rules.SpellDamage (Rules.cs:624-628) runs `sl = Math.Max(1, sl);`
    // before Modifier1, so SL below 1 is treated as 1 in both the log term and the power term.
    // The SRD is silent on SL < 1.
    const i32 level = sl < 1 ? 1 : sl;
    const double b = static_cast<double>(base);
    const double slD = static_cast<double>(level);

    const double logTerm = b * std::log(slD + 1.0) / std::log(5.0);

    // Truncation toward zero, matching the reference (int) cast.
    const double powerRaw = (slD / 10.0) * static_cast<double>(power - 1);
    const double powerTerm = static_cast<double>(static_cast<i64>(powerRaw));
    return b + logTerm + powerTerm;
}

i32 effectiveSpellLevel(i32 sl) {
    // CONFLICT: reference SpellDamage uses sl = Math.Max(1, sl) (Rules.cs:631); SRD R8 says SL 0
    // is UNKNOWN. Reference preferred: floor at 1. Upper bound 255 kept from the existing code.
    return clampv(sl, 1, 255);
}

i32 spellModifier2(Ctx& ctx, double modifier1, i32 sl) {
    // UNKNOWN: behaviour at SL 0, where (SL-1)/SL^2 is undefined (R8, c107).
    // Chosen: the term is taken as 0 at SL 0 so no division by zero occurs.
    const double slD = static_cast<double>(sl);
    const double term = (sl == 0) ? 0.0 : (slD - 1.0) / (slD * slD);

    // UNKNOWN: range of Rnd (R6, c107). Uses VB Rnd via ctx.rng.
    const double rnd = ctx.rng.nextDouble();

    // RESOLVED-BY-REFERENCE: legend says Int(x) is truncation (c107). Reference SpellHeal
    // (Rules.cs:646) uses a C# (int) cast: `(int)(rng.NextDouble() * (mod1 - ((sl - 1) / (double)(sl * sl))) / 2) + 1`.
    // Truncation toward zero is used, not vbInt (floor). The two differ only for negative arguments.
    const i64 truncated = static_cast<i64>(rnd * (modifier1 - term) / 2.0);
    return static_cast<i32>(truncated) + 1;
}

i32 spellDamage(Ctx& ctx, i32 base, i32 sl, i32 power, i32 targetResistance) {
    const i32 level = effectiveSpellLevel(sl);

    // Step 1
    const double m1 = damageModifier1(base, level, power);

    // Step 2
    const i32 m2 = spellModifier2(ctx, m1, level);

    // Step 3: Damage = Int(Modifier1 - Modifier2)
    const i64 damage = vbInt(m1 - static_cast<double>(m2));

    // Step 4: resistance scaling (R6 step 4). Reference Rules.SpellDamage: the resistance is clamped to
    // 0..100, the result rounds half to even (the running damage is an Integer variable, so the
    // multiplication rounds on the way back in) and is never below 0.
    const i32 resistance = targetResistance < 0 ? 0 : (targetResistance > 100 ? 100 : targetResistance);
    const double scaled = static_cast<double>(damage) * (1.0 - static_cast<double>(resistance) / 100.0);
    const i64 rounded = roundHalfEven(scaled);
    return static_cast<i32>(rounded < 0 ? 0 : rounded);
}

double healingModifier1(i32 base, i32 sl, i32 power) {
    const double b = static_cast<double>(base);

    // UNKNOWN: LN(0) is undefined (R8, c107). Chosen: log term is 0 when SL < 1.
    double logTerm = 0.0;
    if (sl >= 1) {
        logTerm = b * std::log(static_cast<double>(sl)) / std::log(10.0);
    }

    // Reference SpellHeal (Rules.cs:646) uses `+ (int)((sl / 10.0) * (power - 1))`, a C# cast
    // that truncates toward zero, so truncation is used here rather than vbInt (floor).
    // This term is outside the marker list; it is changed for consistency with the reference.
    const double powerTerm =
        static_cast<double>(static_cast<i64>((static_cast<double>(sl) / 10.0) * static_cast<double>(power - 1)));

    return b + logTerm + powerTerm;
}

i32 spellHealing(Ctx& ctx, i32 base, i32 sl, i32 power) {
    const i32 level = effectiveSpellLevel(sl);

    // Step 1
    const double m1 = healingModifier1(base, level, power);

    // Step 2
    const i32 m2 = spellModifier2(ctx, m1, level);

    // Step 3 (no resistance step for healing).
    return static_cast<i32>(vbInt(m1 - static_cast<double>(m2)));
}

CrestGrantRow crestGrantFor(Guild crest) {
    for (const CrestGrantRow& row : kCrestGrants) {
        if (row.crest == crest) {
            return row;
        }
    }
    return CrestGrantRow{crest, CrestSpell::None, 0};
}

CrestCastResult castCrestSpell(Ctx& ctx, const Character& caster, Guild crest) {
    CrestCastResult result{};

    const CrestGrantRow row = crestGrantFor(crest);
    if (row.spell == CrestSpell::None) {
        // Journeyman, Warrior, Ninja and any crest outside the table: no spell granted.
        return result;
    }

    result.cast = true;
    result.spell = row.spell;
    result.charges = row.charges;
    result.spellLevel = caster.spellLevel;

    ctx.say("spells3.crestSpellGranted", "Crest grants a spell", {}, {});
    return result;
}

MovementCastResult castMovementSpell(Ctx& ctx,
                                     Party& party,
                                     FloorState& floor,
                                     const MovementRequest& req,
                                     MovementSpell spell,
                                     const Location& sanctuary,
                                     bool sanctuarySet) {
    MovementCastResult result{};

    // UNKNOWN: FloorState query API (rock behind wall, square bounds) is not in the provided
    // headers. Placeholder: no square is rock and every square is in bounds until wired in.
    (void)floor;
    auto squareIsRock = [](i32 x, i32 y) -> bool {
        (void)x;
        (void)y;
        return false;  // UNKNOWN: FloorState rock query
    };

    // Caster must be a valid, living party member. ASSUMED: dead casters cannot cast.
    if (req.casterIndex < 0 || req.casterIndex >= party.size) {
        result.outcome = MovementOutcome::NoEffect;
        return result;
    }
    Character& caster = party.members[static_cast<u32>(req.casterIndex)];
    if (caster.isDead()) {
        result.outcome = MovementOutcome::NoEffect;
        return result;
    }

    // ASSUMED: "in front" uses N=(0,-1), E=(1,0), S=(0,1), W=(-1,0). The SRD gives no grid orientation.
    i32 fx = 0;
    i32 fy = 0;
    switch (party.facing) {
        case Facing::N: fy = -1; break;
        case Facing::E: fx = 1; break;
        case Facing::S: fy = 1; break;
        case Facing::W: fx = -1; break;
    }

    // Shared kill routine for PartyKilled (R2 Ethereal Portal, Displacement).
    // ASSUMED: rock death uses DeathState::Rock.
    auto killParty = [&party]() {
        for (i32 i = 0; i < party.size; ++i) {
            Character& c = party.members[static_cast<u32>(i)];
            if (!c.isDead()) {
                c.deathState = DeathState::Rock;
            }
        }
        party.wiped = true;
    };

    switch (spell) {
        case MovementSpell::DetectRock: {
            // R2 Detect Rock: reports only the wall in front of the caster (c106).
            const i32 wx = party.x + fx;
            const i32 wy = party.y + fy;
            result.rockBehind = squareIsRock(wx, wy);  // UNKNOWN: always false until query wired
            ctx.say("spell.movement.detect_rock",
                    "The caster senses whether rock lies behind the wall ahead.",
                    {static_cast<i64>(result.rockBehind ? 1 : 0)},
                    {caster.name});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        case MovementSpell::FeatherEssence: {
            // R2 Feather Essence: levitates one recipient.
            // UNKNOWN: failure condition and chance (R2 says it can fail). No roll is made.
            if (req.targetIndex < 0 || req.targetIndex >= party.size) {
                result.outcome = MovementOutcome::NoEffect;
                break;
            }
            Character& target = party.members[static_cast<u32>(req.targetIndex)];
            if (target.isDead()) {
                result.outcome = MovementOutcome::NoEffect;
                break;
            }
            target.ailments.levitating = true;
            result.levitated = true;
            ctx.say("spell.movement.feather_essence",
                    "The recipient floats above pits, chutes and water.",
                    {static_cast<i64>(req.targetIndex)},
                    {target.name});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        case MovementSpell::EtherealPortal: {
            // R2 Ethereal Portal: moves caster and party through the wall in front.
            // ASSUMED: the destination is two squares ahead (wall square, then landing square).
            // R2: if the square behind the wall is rock, the whole party dies.
            const i32 dx2 = party.x + 2 * fx;
            const i32 dy2 = party.y + 2 * fy;
            if (squareIsRock(dx2, dy2)) {
                killParty();
                result.outcome = MovementOutcome::PartyKilled;
                ctx.say("spell.movement.ethereal_portal_rock",
                        "The party steps into solid rock and is lost.",
                        {}, {});
                break;
            }
            party.x = dx2;
            party.y = dy2;
            ctx.say("spell.movement.ethereal_portal",
                    "The party passes through the wall.",
                    {static_cast<i64>(party.x), static_cast<i64>(party.y)},
                    {});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        case MovementSpell::Displacement: {
            // R2 Displacement: teleports within the current level by the requested offset.
            // R2: outside the dungeon or into rock kills caster and party.
            // UNKNOWN: dungeon bounds are not available; only rock is checked.
            const i32 nx = party.x + req.dx;
            const i32 ny = party.y + req.dy;
            if (squareIsRock(nx, ny)) {
                killParty();
                result.outcome = MovementOutcome::PartyKilled;
                ctx.say("spell.movement.displacement_rock",
                        "The party is displaced into rock and is lost.",
                        {}, {});
                break;
            }
            party.x = nx;
            party.y = ny;
            ctx.say("spell.movement.displacement",
                    "The party is displaced on this level.",
                    {static_cast<i64>(nx), static_cast<i64>(ny)},
                    {});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        case MovementSpell::MassLevitate: {
            // R2 Mass Levitate: Feather Essence for the whole party (c106).
            // UNKNOWN: failure chance is not applied (see Feather Essence).
            i32 count = 0;
            for (i32 i = 0; i < party.size; ++i) {
                Character& c = party.members[static_cast<u32>(i)];
                if (!c.isDead()) {
                    c.ailments.levitating = true;
                    ++count;
                }
            }
            result.levitated = true;
            ctx.say("spell.movement.mass_levitate",
                    "The whole party floats.",
                    {static_cast<i64>(count)},
                    {});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        case MovementSpell::Teleport: {
            // R2 Teleport, non-combat: moves caster and party up to 3 levels (c106).
            // Combat Teleport (R5) is teleportCombatSendAway, not this function.
            // ASSUMED: engaged party routes to the combat path, so no effect here.
            if (party.engaged) {
                result.outcome = MovementOutcome::NoEffect;
                break;
            }
            // Clamp to +/- kTeleportMaxLevels (MovementRequest comment).
            i32 delta = req.levelDelta;
            if (delta > kTeleportMaxLevels) {
                delta = kTeleportMaxLevels;
            }
            if (delta < -kTeleportMaxLevels) {
                delta = -kTeleportMaxLevels;
            }
            // UNKNOWN: floor count bounds for the destination level are not checked.
            party.dungeonLevel += delta;
            result.levelsMoved = delta;
            ctx.say("spell.movement.teleport",
                    "The party is moved between levels.",
                    {static_cast<i64>(delta), static_cast<i64>(party.dungeonLevel)},
                    {});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        case MovementSpell::Sanctuary: {
            // R2 Sanctuary: returns caster and party to the set location.
            // R2: no effect if never set. Ages caster about one year.
            // CONFLICT: manual says caster and party return [c83]; archive says caster returns
            // to "that exact spot" [c105]. Implemented as party return (manual).
            if (!sanctuarySet) {
                result.outcome = MovementOutcome::NoEffect;
                break;
            }
            party.x = sanctuary.x;
            party.y = sanctuary.y;
            party.dungeonLevel = sanctuary.dungeonLevel;
            // ASSUMED: Location.facing 0..3 maps to N, E, S, W.
            switch (sanctuary.facing) {
                case 1: party.facing = Facing::E; break;
                case 2: party.facing = Facing::S; break;
                case 3: party.facing = Facing::W; break;
                default: party.facing = Facing::N; break;
            }
            // ASSUMED: "about one year" = 365 days of aging for the caster.
            constexpr i32 kSanctuaryAgingDays = 365;
            caster.ageDays += kSanctuaryAgingDays;
            result.agedDays = kSanctuaryAgingDays;
            result.sanctuaryReturned = true;
            ctx.say("spell.movement.sanctuary",
                    "The party is returned to the sanctuary.",
                    {static_cast<i64>(kSanctuaryAgingDays)},
                    {caster.name});
            result.outcome = MovementOutcome::Applied;
            break;
        }

        default:
            result.outcome = MovementOutcome::NoEffect;
            break;
    }

    return result;
}

i32 baseCon(const Character& c) {
    return c.abilities.stats[static_cast<u32>(StatIndex::Con)];
}

i32 effectiveCon(const Character& c) {
    return baseCon(c) + c.abilities.gearCon;
}

i32 statAt(const Character& c, StatIndex s) {
    return c.abilities.stats[static_cast<u32>(s)];
}

i32 resistAt(const Character& c, i32 idx) {
    return c.resistances.resist[static_cast<u32>(idx)];
}

bool hasBit(u32 flags, i32 bit) {
    return ((flags >> static_cast<u32>(bit)) & 1u) != 0u;
}

i32 highestGuildLevel(const Character& c) {
    i32 best = 0;
    for (u32 i = 0; i < static_cast<u32>(kGuildCount); ++i) {
        best = maxI(best, c.guilds[i].level);
    }
    return best;
}

void note(Ctx& ctx, const char* code, const char* text) {
    ctx.say(code, text, {}, {});
}

void paralyse(Ctx& ctx, Character& c, i32 level) {
    if (c.ailments.paralysisLevel != 0) return;          // R13.1
    c.combat.adShift = storedADShift(c) - statsADNow(c); // R13.2
    c.ailments.paralysisLevel = level;
    note(ctx, "status1a.paralysed", "Paralysed");
}

void unparalyse(Ctx& ctx, Character& c) {
    if (c.ailments.paralysisLevel == 0) return;          // R14.1
    c.combat.adShift = storedADShift(c) + statsADNow(c); // R14.2
    c.ailments.paralysisLevel = 0;
    note(ctx, "status1a.unparalysed", "Paralysis ends");
}

void inflictPoison(Ctx& ctx, Character& victim, i32 attackerLevel) {
    const bool failed = d100(ctx) > resistAt(victim, kResPoison);
    if (failed && victim.ailments.poisonLevel == 0) {
        // CONFLICT: R28 level conflict; LevelFound is taken as the attacker level passed in.
        victim.ailments.poisonLevel = attackerLevel;
        note(ctx, "status1a.poisoned", "Poisoned");
    }
}

void inflictDisease(Ctx& ctx, Character& victim, i32 attackerLevel) {
    const bool failed = d100(ctx) > resistAt(victim, kResDisease);
    if (failed && victim.ailments.diseaseLevel == 0) {
        // CONFLICT: R28 level conflict; LevelFound is taken as the attacker level passed in.
        victim.ailments.diseaseLevel = attackerLevel;
        note(ctx, "status1a.diseased", "Diseased");
    }
}

bool isHeld(const Character& c) {
    return c.ailments.paralysisLevel > 0;
}

bool canActOnOwnTurn(const Character& c) {
    return !isHeld(c);
}

bool heldActionRefused(const Character& c, HeldAction action) {
    if (!isHeld(c)) return false;
    switch (action) {
        case HeldAction::StairsDown:  // R18
        case HeldAction::Chute:       // R18
            return false;
        default:                      // R17
            return true;
    }
}

i32 ailmentRollOffset(i32 effCon, i32 level) {
    return (effCon - kAilmentConBase) * kConWeight - level * kAilmentLevelWeight;
}

AilmentTickResult poisonDiseaseTick(Ctx& ctx, Character& c) {
    AilmentTickResult r;
    const i32 con = effectiveCon(c);

    if (c.ailments.poisonLevel > 0) {
        const i32 roll = static_cast<i32>(ctx.rng.below(kAilmentRollRange))
                       + ailmentRollOffset(con, c.ailments.poisonLevel);
        if (roll > kPoisonCureAbove) {
            curePoison(ctx, c);
            r.poisonCured = true;
        } else {
            c.vitals.curHits -= kPoisonTickHits;
            r.hitsLost += kPoisonTickHits;
        }
    }

    if (c.ailments.diseaseLevel > 0) {
        // R7: disease roll subtracts poisonLevel*2 unless poison was cured this tick.
        const i32 poisonTerm = r.poisonCured ? 0 : c.ailments.poisonLevel;
        const i32 roll = static_cast<i32>(ctx.rng.below(kAilmentRollRange))
                       + ailmentRollOffset(con, poisonTerm);
        if (roll > kDiseaseCureAbove) {
            cureDisease(ctx, c);
            r.diseaseCured = true;
        } else {
            c.vitals.curHits -= kDiseaseTickHits;
            r.hitsLost += kDiseaseTickHits;
        }
    }
    return r;
}

void inflictPoisonAndDisease(Ctx& ctx, Character& victim, i32 attackerLevel) {
    inflictPoison(ctx, victim, attackerLevel);
    inflictDisease(ctx, victim, attackerLevel);
}

void curePoison(Ctx& ctx, Character& c) {
    c.ailments.poisonLevel = 0;
    note(ctx, "status1a.poison_cured", "Poison cured");
}

void cureDisease(Ctx& ctx, Character& c) {
    c.ailments.diseaseLevel = 0;
    note(ctx, "status1a.disease_cured", "Disease cured");
}

i32 healingWhileDiseased(const Character& c, i32 healing) {
    if (c.ailments.diseaseLevel <= 0) return healing;
    return static_cast<i32>(vbInt(static_cast<double>(healing) / 2.0));
}

void townRestCuresPoison(Ctx& ctx, Character& c) {
    if (c.ailments.poisonLevel > 0) {
        curePoison(ctx, c);
    }
}

i32 meleeParalysisChance(const Character& c) {
    const i32 v = resistAt(c, kResParalysis) + baseCon(c);
    return v > kParalysisCap ? kParalysisCap : v;
}

bool meleeParalysisCheck(Ctx& ctx, Character& c, i32 monsterLevel) {
    const i32 chance = meleeParalysisChance(c);
    const bool failed = d100(ctx) > chance;
    if (failed && c.ailments.paralyzedRounds == 0) {
        paralyse(ctx, c, monsterLevel);
        return true;
    }
    return false;
}

double paralysisWearOffChance(const Character& c, i32 monsterGuildLevel) {
    const i32 pLevel = c.ailments.paralysisLevel < 1 ? 1 : c.ailments.paralysisLevel;
    const double p = static_cast<double>(pLevel);
    const double hold = std::log(p / 2.0 + p / 10.0) / std::log(1.02);

    const i32 lvlInt = monsterGuildLevel < 1 ? 1 : monsterGuildLevel;
    const double lvl = static_cast<double>(lvlInt);
    const double fight =
        ((std::log(lvl) + lvl / 10.0) / std::log(1.05) / 10.0 + baseCon(c) * 1.5)
        + resistAt(c, kResParalysis);

    return clampD(hold - fight, 5.0, 90.0);
}

bool paralysisWearOffTick(Ctx& ctx, Character& c, i32 monsterGuildLevel) {
    if (!isHeld(c)) return false;
    const double chance = paralysisWearOffChance(c, monsterGuildLevel);
    const i32 roll = d100(ctx);
    if (static_cast<double>(roll) > chance) {
        unparalyse(ctx, c);
        return true;
    }
    return false;
}

bool paralysisNoMonsterClear(Ctx& ctx, Character& c, bool monsterOnSquare) {
    if (monsterOnSquare || !isHeld(c)) return false;
    unparalyse(ctx, c);
    return true;
}

void monsterGroupSpecialTurn(Ctx& ctx, Party& party, Creature& attacker, i32 victimIndex) {
    if (victimIndex < 0 || victimIndex >= party.size) return;
    Character& v = party.members[static_cast<u32>(victimIndex)];
    if (v.isDead()) return;

    const u32 flags = attacker.specialPropertyFlags;
    const i32 monsterLevel = attacker.guildLevel;  // M in R27/R28/R32
    const i32 victimLevel = v.activeLevel();

    // Step 1: breath, bits 3 and 4 (R22.1, R24, R28).
    const bool fire = hasBit(flags, kBitBreathFire);
    const bool cold = hasBit(flags, kBitBreathCold);
    if (fire || cold) {
        // CONFIRMED-BY-REFERENCE: MonsterAttack.cs breath gate `_rng.Next(100) < chance`
        // is Int(Rnd*100) < chance, i.e. d100 <= threshold. Threshold table (50/80/20) is in breathThresholdPercent.
        if (d100(ctx) <= breathThresholdPercent(highestGuildLevel(v), monsterLevel)) {
            // RESOLVED-BY-REFERENCE: MonsterAttack.cs (MONSMOD.BAS:2692-2757):
            // "int l046C = VbInt(monLvl * Math.Log(monLvl + 1));" then "if (l046C <= 0) yield break;".
            // Log(0) raises an error that ends the whole group turn, so acid, specials and the rest
            // of the turn are skipped. Level 0, and level 1 (VbInt(0.69) = 0), take this path.
            const double bm = static_cast<double>(monsterLevel);
            if (vbInt(bm * std::log(bm + 1.0)) <= 0) return;
            i32 dmg = rollBreathDamage(ctx, monsterLevel, victimLevel);
            dmg = applySpecialResistance(dmg, resistAt(v, fire ? kResFire : kResCold));  // R24
            v.vitals.curHits -= dmg;
            note(ctx, "status1a.breath", "Breath strikes");
        }
    }

    // Step 1b: acid spit, bit 5 (R27 spit thresholds on active level, R28).
    if (hasBit(flags, kBitSpit)) {
        // CONFIRMED-BY-REFERENCE: MonsterAttack.cs acid gate `_rng.Next(100) < chance` (50/90/10 by level)
        // is the same roll form as d100 <= threshold. Threshold body is not in this input.
        if (d100(ctx) <= spitThresholdPercent(v.activeLevel(), monsterLevel)) {
            i32 dmg = rollSpitDamage(ctx, monsterLevel, victimLevel);
            // FIXED: header declares an i32 named specialResistIndex; function renamed.
            dmg = applySpecialResistance(
                dmg, resistAt(v, specialResistIndexOf(SpecialAttackKind::AcidSpit)));
            v.vitals.curHits -= dmg;
            note(ctx, "status1a.spit", "Acid spits");
        }
    }

    // Step 3: electrocution, bit 6, checked against the hit target (R29).
    // UNKNOWN: electrocution damage formula is not in the input; only the chance
    // is rolled and reported.
    if (hasBit(flags, kBitElectrocution)) {
        if (d100(ctx) <= electrocutionChancePercent(v.level, monsterLevel)) {
            note(ctx, "status1a.electrocuted", "Electrocution");
        }
    }

    // Step 4: melee side effects (R22.4), list order.
    if (hasBit(flags, kBitPoison)) {
        inflictPoison(ctx, v, attacker.levelFound);
    }
    if (hasBit(flags, kBitDisease)) {
        inflictDisease(ctx, v, attacker.levelFound);
    }
    if (hasBit(flags, kBitParalysis)) {
        meleeParalysisCheck(ctx, v, monsterLevel);
    }
    if (hasBit(flags, kBitStone)) {
        stoneCheck(ctx, v, attacker.levelFound);  // engine form (R30) preferred
    }
    if (hasBit(flags, kBitDrain)) {
        const DrainOutcome out = drainCharacter(ctx, v, attacker.levelFound);
        for (i32 pick : out.picks) {
            applyDrainPick(ctx, v, pick);
        }
    }
    if (hasBit(flags, kBitAging)) {
        rollAgingDays(ctx, v, monsterLevel, attacker.floor);
    }
    // UNKNOWN: destruction (bit 12) needs an Inventory, not reachable here.
    // UNKNOWN: theft (bit 13) needs the thief coefficient, not supplied.
    // Step 5 (companion stoning of the monster) is not applied here; see companionBlowStones.
}

i32 applySpecialResistance(i32 damage, i32 resistPercent) {
    if (resistPercent <= 0) return damage;
    const double d = static_cast<double>(damage);
    return static_cast<i32>(vbInt(d - d * ((resistPercent / 2.0) * 0.01)));
}

static i32 specialResistIndexOf(SpecialAttackKind kind) {
    switch (kind) {
        case SpecialAttackKind::Breath:     return kResFire;
        case SpecialAttackKind::AcidSpit:   return 2;  // UNKNOWN
        case SpecialAttackKind::Electrocute: return 3;  // UNKNOWN
    }
    return kResFire;
}

RatioBand ratioBand(i32 characterLevel, i32 monsterLevel) {
    const double c = static_cast<double>(characterLevel);
    const double m = static_cast<double>(monsterLevel);
    if (c > 1.25 * m) return RatioBand::High;
    if (c < 0.75 * m) return RatioBand::Low;
    return RatioBand::Even;
}

i32 breathThresholdPercent(i32 highestGuildLevel, i32 monsterLevel) {
    return kBreathThresholdPct[static_cast<u32>(ratioBand(highestGuildLevel, monsterLevel))];
}

i32 spitThresholdPercent(i32 activeLevel, i32 monsterLevel) {
    return kSpitThresholdPct[static_cast<u32>(ratioBand(activeLevel, monsterLevel))];
}

i32 rollBreathDamage(Ctx& ctx, i32 monsterGuildLevel, i32 victimActiveLevel) {
    const double m = static_cast<double>(monsterGuildLevel);
    // RESOLVED-BY-REFERENCE: MonsterAttack.cs: "int l046C = VbInt(monLvl * Math.Log(monLvl + 1));".
    // This is a floor (VbInt), not round-half-even.
    const double x = static_cast<double>(vbInt(m * std::log(m + 1.0)));
    // RESOLVED-BY-REFERENCE: MonsterAttack.cs: "if (l046C <= 0) yield break;". The group turn ends there.
    // monsterGroupSpecialTurn takes that exit before calling this function; the return below is only a guard.
    if (x <= 0.0) return 0;
    const double q = static_cast<double>(vbInt(
        (std::log(x) + x / 15.0) / std::log(1.08)
        - static_cast<double>(victimActiveLevel) / 20.0 + 1.0));
    const double u = ctx.rng.nextDouble();
    const double inner = static_cast<double>(vbInt((u * q + 1.0) / 2.0));
    const double raw = (inner + q / 4.0) * 0.7 / 2.0;
    // RESOLVED-BY-REFERENCE: "int dmg = VbInt(((Floor(...) + range / 4.0) * 0.7) / 2);" - VbInt, not round-half-even.
    const i64 dmg = vbInt(raw);
    return dmg < 0 ? 0 : static_cast<i32>(dmg);
}

i32 rollSpitDamage(Ctx& ctx, i32 monsterGuildLevel, i32 victimActiveLevel) {
    const double x = static_cast<double>(monsterGuildLevel) + 1.0;
    const double q = static_cast<double>(vbInt(
        (std::log(x) + x / 15.0) / std::log(1.08)
        - static_cast<double>(victimActiveLevel) / 10.0 + 1.0));
    const double u = ctx.rng.nextDouble();
    const double inner = static_cast<double>(vbInt((u * q + 1.0) / 2.0));
    const double raw = (inner + q / 2.0) * 0.7;
    const i64 dmg = roundHalfEven(raw);
    return dmg < 0 ? 0 : static_cast<i32>(dmg);
}

i32 electrocutionChancePercent(i32 characterLevel, i32 monsterLevel) {
    return kElectrocutionThresholdPct[static_cast<u32>(ratioBand(characterLevel, monsterLevel))];
}

double stoneChance(const Character& target, i32 attackerLevel) {
    const i32 con = baseCon(target);
    const double tCon = static_cast<double>(con);
    const double lg = std::log(static_cast<double>(maxI(1, con))) / std::log(2.5);
    const double value = tCon * lg - static_cast<double>(attackerLevel);
    return minD(value, static_cast<double>(kStoneCap));
}

bool stoneCheck(Ctx& ctx, Character& target, i32 attackerLevel) {
    const double chance = stoneChance(target, attackerLevel);
    if (static_cast<double>(d100(ctx)) > chance) {
        target.deathState = DeathState::Stoned;  // R3
        note(ctx, "status1a.stoned", "Stoned");
        return true;
    }
    return false;
}

double companionStoneValue(i32 companionCon, i32 stoneFloor) {
    const double con = static_cast<double>(companionCon);
    const double lg = std::log(maxD(1.0, con)) / std::log(2.5);
    return con * lg - static_cast<double>(stoneFloor);
}

bool companionBlowStones(Ctx& ctx, Creature& target, i32 companionCon, i32 stoneFloor) {
    const double value = companionStoneValue(companionCon, stoneFloor);
    if (ctx.rng.nextDouble() * 100.0 > value) {
        target.stoned = true;
        target.hits = 0;
        note(ctx, "status1a.monster_stoned", "Stoned one!");
        return true;
    }
    return false;
}

DrainOutcome drainCharacter(Ctx& ctx, Character& target, i32 attackerLevel) {
    DrainOutcome out;
    const i32 n = static_cast<i32>(vbInt(static_cast<double>(attackerLevel) / 2.0 + 0.5));
    out.trials = static_cast<i32>(ctx.rng.below(n)) + 1;
    const double conSave = static_cast<double>(baseCon(target)) * 2.5
                         - static_cast<double>(attackerLevel) * 2.0;
    for (i32 t = 0; t < out.trials; ++t) {
        const i32 roll = d100(ctx);
        if (roll <= resistAt(target, kResDrain) || static_cast<double>(roll) <= conSave) {
            continue;
        }
        out.picks.push_back(static_cast<i32>(ctx.rng.below(kDrainPickSides)) + 1);
    }
    return out;
}

void applyDrainPick(Ctx& ctx, Character& c, i32 pick) {
    if (pick >= 1 && pick <= kDrainStatPickMax) {
        c.abilities.stats[static_cast<u32>(pick)] -= 1;
        note(ctx, "status1a.stat_drained", "Stat drained");
    } else if (pick == kDrainMaxHitsPick) {
        c.vitals.maxHits -= kDrainMaxHitsLoss;
        note(ctx, "status1a.maxhits_drained", "Maximum hits drained");
    }
}

double agingSaveChance(const Character& c, i32 monsterFloor) {
    return static_cast<double>(baseCon(c)) * 2.5
         - static_cast<double>(monsterFloor) * 2.0;
}

i32 rollAgingDays(Ctx& ctx, Character& c, i32 monsterGuildLevel, i32 monsterFloor) {
    const i32 roll = d100(ctx);
    if (static_cast<double>(roll) <= agingSaveChance(c, monsterFloor)) return 0;

    const i32 die = static_cast<i32>(ctx.rng.below(kAgingDaysCap)) + 1;
    const double unitRaw = static_cast<double>(monsterGuildLevel) / kAgingUnitDivisor;
    const i32 units = clampI(static_cast<i32>(roundHalfEven(unitRaw)),
                             kAgingUnitMin, kAgingUnitMax);
    const i32 cap = kAgingDaysPerUnit * units;
    const i32 days = die < cap ? die : cap;
    c.ageDays += days;
    note(ctx, "status1a.aged", "Aged");
    return days;
}

bool petrifyCheck(Ctx& ctx, Character& target, i32 monsterFloor) {
    const i32 r1 = d100(ctx);
    if (r1 <= resistAt(target, kResStone)) return false;  // first save held

    const i32 con = baseCon(target);
    const double lg = std::log(static_cast<double>(maxI(1, con))) / std::log(2.5);
    const double chance2 = minD(static_cast<double>(con) * lg - static_cast<double>(monsterFloor),
                                static_cast<double>(kParalysisCap));
    const i32 r2 = d100(ctx);
    if (static_cast<double>(r2) <= chance2) return false;  // second save held

    target.deathState = DeathState::Stoned;  // R3
    note(ctx, "status1a.petrified", "Petrified");
    return true;
}

i32 destructionSaveChance(const Character& c, i32 monsterFloor, i32 monsterDex) {
    const i32 v = kDestructionSaveBase - monsterFloor
                + 4 * statAt(c, StatIndex::Dex) - 2 * monsterDex;
    return clampI(v, kDestructionSaveMin, kDestructionSaveMax);
}

bool destructionCheck(Ctx& ctx, Character& c, Inventory& inv, i32 monsterFloor, i32 monsterDex) {
    const i32 slotCount = kDestructionSlotMax - kDestructionSlotMin + 1;
    const i32 slot = static_cast<i32>(ctx.rng.below(slotCount)) + kDestructionSlotMin;
    const i32 chance = destructionSaveChance(c, monsterFloor, monsterDex);
    if (d100(ctx) <= chance) return false;  // saved
    Item& it = inv.pack[static_cast<u32>(slot)];
    if (it.id == 0) return false;           // empty slot
    it = Item{};
    note(ctx, "status1a.item_destroyed", "Item destroyed");
    return true;
}

i32 theftScore(Ctx& ctx, i32 thiefLevel, i32 thiefCoefficient, bool defending) {
    const i32 base = static_cast<i32>(ctx.rng.below(kTheftScoreRange));
    const double u = ctx.rng.nextDouble();
    const double tl = static_cast<double>(thiefLevel);
    const i32 extra = static_cast<i32>(vbInt(u * (tl * static_cast<double>(thiefCoefficient))
                                             + 0.75 * tl));
    i32 score = base + extra;
    if (defending) score += score / 2;
    return score;
}

bool theftGoldAttempted(i32 score, i32 monsterGuildLevel) {
    return score - kTheftGoldMonsterWeight * monsterGuildLevel < kTheftGoldThreshold;
}

i32 theftItemSlot(Ctx& ctx) {
    return static_cast<i32>(ctx.rng.below(kTheftSlotCount)) + kTheftSlotMin;
}

i32 archiveSpecialDamage(Ctx& ctx, i32 monsterGuildLevel, i32 characterLevel, i32 resistPercent) {
    if (monsterGuildLevel <= 0) return 0;  // UNKNOWN: log of zero aborts
    const double m = static_cast<double>(monsterGuildLevel);
    const double minimum = (std::log(m) + m / 15.0) * 4.55;
    const double base = minimum + ctx.rng.nextDouble() * minimum;
    const double levelAdjusted = base - 0.7 * static_cast<double>(characterLevel / 10);
    const double fin = levelAdjusted * (1.0 - (resistPercent / 2.0) * 0.01);
    const i64 dmg = vbInt(fin < 0.0 ? 0.0 : fin);
    return static_cast<i32>(dmg);
}

i32 archiveBreathDamage(Ctx& ctx, i32 monsterGuildLevel, i32 resistPercent) {
    const double m = static_cast<double>(monsterGuildLevel);
    const double levelMod = m * std::log(m);
    if (levelMod <= 0.0) return 0;  // UNKNOWN: log of zero aborts
    const double minimumD = vbInt((std::log(levelMod) + levelMod / 15.0) * 1.1375) >= 0
                          ? static_cast<double>(vbInt((std::log(levelMod) + levelMod / 15.0) * 1.1375))
                          : 0.0;
    const i32 minimum = static_cast<i32>(minimumD);
    const i32 base = minimum + static_cast<i32>(ctx.rng.below(minimum * 2 + 1));
    const double fin = static_cast<double>(base) * (1.0 - (resistPercent / 2.0) * 0.01);
    const i64 dmg = vbInt(fin < 0.0 ? 0.0 : fin);
    return static_cast<i32>(dmg);
}

i32 archiveStoneChance(i32 spawnLevel, i32 con) {
    const double c = static_cast<double>(con);
    const double v = (100.0 + static_cast<double>(spawnLevel))
                   - c * std::log(maxD(1.0, c)) * 1.09;
    return maxI(kArchiveChanceFloor, static_cast<i32>(vbInt(v)));
}

i32 archiveParalysisChance(i32 resistPercent, i32 con) {
    return maxI(kArchiveChanceFloor, 100 - (resistPercent + con));
}

i32 archiveAgeChance(i32 spawnLevel, i32 con) {
    const double v = (100.0 + static_cast<double>(spawnLevel) * 2.0)
                   - static_cast<double>(con) * 2.5;
    return static_cast<i32>(vbInt(v));
}

i32 specialResistIndex(SpecialAttackKind kind) {
    constexpr i32 kFireIndex = 0;          // R26 index 0: Fire (breath)
    constexpr i32 kAcidIndexAssumed = 2;   // UNKNOWN: acid index not given in SRD (R26); ASSUMED 2
    constexpr i32 kElectricalIndexAssumed = 3; // UNKNOWN: electrical index not given in SRD (R26); ASSUMED 3

    switch (kind) {
        case SpecialAttackKind::Breath:
            // R24: fire breath is resisted by Fire (0), cold breath by Cold (1).
            // ASSUMED: the signature carries no BreathType, so Fire (0) is returned.
            // A cold-breathing monster must use index 1 at the call site.
            return kFireIndex;
        case SpecialAttackKind::AcidSpit:
            // R24: acid spit is resisted by Acid. UNKNOWN index (R26); ASSUMED 2.
            return kAcidIndexAssumed;
        case SpecialAttackKind::Electrocute:
            // R24: electrocution is resisted by Electrical. UNKNOWN index (R26); ASSUMED 3.
            return kElectricalIndexAssumed;
    }
    return kFireIndex;
}

