    c.ailments.poisonLevel = 0;          // CurePoison
    c.ailments.diseaseLevel = 0;         // CureDisease
    for (i32 r = 0; r < kResistKinds; ++r) {
        c.resistances.resist[ix(r)] = 0; // SpellResist[all] = 0
    }
}

